INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36625, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事が起こる、または新たに作り出される。", "primary_collocate": null, "pronunciation": "しょうずる", "ipa": "ɕoːzɯɾɯ", "syllable_count": 4, "sentences": [{"text": "工事の遅れにより、予定の変更が生ずることもある。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "工事[こうじ]の遅[おく]れにより、予定[よてい]の変更[へんこう]が生[しょう]ずることもある。", "sentence_source": "generated"}, {"text": "説明が足りないと、誤解が生ずる。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "説明[せつめい]が足[た]りないと、誤解[ごかい]が生[しょう]ずる。", "sentence_source": "generated"}, {"text": "機械に故障が生ずると、工場の作業を止めなければならない。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "機械[きかい]に故障[こしょう]が生[しょう]ずると、工場[こうじょう]の作業[さぎょう]を止[と]めなければならない。", "sentence_source": "generated"}, {"text": "冷たい空気と暖かい空気がぶつかると、霧が生ずる。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "冷[つめ]たい空気[くうき]と暖[あたた]かい空気[くうき]がぶつかると、霧[きり]が生[しょう]ずる。", "sentence_source": "generated"}, {"text": "地震のあとには、町にさまざまな変化が生ずる。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "地震[じしん]のあとには、町[まち]にさまざまな変化[へんか]が生[しょう]ずる。", "sentence_source": "generated"}, {"text": "試合中に思わぬトラブルが生ずる場合に備え、全員で準備していた。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "試合中[じあいちゅう]に思[おも]わぬトラブルが生[しょう]ずる場合[ばあい]に備[そな]え、全員[ぜんいん]で準備[じゅんび]していた。", "sentence_source": "generated"}, {"text": "二つの物をこすり合わせると、熱が生ずる。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "二[ふた]つの物[もの]をこすり合[あ]わせると、熱[ねつ]が生[しょう]ずる。", "sentence_source": "generated"}, {"text": "台風の影響で、農作物に大きな被害が生ずる。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で、農作物[のうさくもつ]に大[おお]きな被害[ひがい]が生[しょう]ずる。", "sentence_source": "generated"}, {"text": "新しい制度を始めると、不公平が生ずることがないか調べている。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]を始[はじ]めると、不公平[ふこうへい]が生[しょう]ずることがないか調[しら]べている。", "sentence_source": "generated"}, {"text": "川の水が増えると、あちこちに小さな渦が生ずる。", "target_word": "生ずる", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が増[ふ]えると、あちこちに小[ちい]さな渦[うず]が生[しょう]ずる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生ずる", "label": "終止形・連体形"}, {"form": "生じる", "label": "終止形(同義の形)"}, {"form": "生じた", "label": "過去形"}, {"form": "生じて", "label": "て形"}, {"form": "生じない", "label": "否定形"}, {"form": "生ずれば", "label": "仮定形"}], "register": "書き言葉・硬い", "sense_fingerprint": "問題・変化・現象などが起こる、または熱や霧などが発生する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36625, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生ずる", "is_correct": true, "explanation": "「物事が起こる」意味。工事の遅れを原因として予定の変更が起こる文に合う。"}, {"text": "命ずる", "is_correct": false, "explanation": "命令する意味で、人が主語になる語。「予定の変更が命ずる」とは言えない。"}, {"text": "演ずる", "is_correct": false, "explanation": "役を演じる意味。「予定の変更が演ずる」は成り立たない。"}, {"text": "感ずる", "is_correct": false, "explanation": "感覚として受け取る意味で、感じる主体が必要。「予定の変更が感ずる」は合わない。"}], "explanations": {"生ずる": "「物事が起こる」意味。工事の遅れを原因として予定の変更が起こる文に合う。", "命ずる": "命令する意味で、人が主語になる語。「予定の変更が命ずる」とは言えない。", "演ずる": "役を演じる意味。「予定の変更が演ずる」は成り立たない。", "感ずる": "感覚として受け取る意味で、感じる主体が必要。「予定の変更が感ずる」は合わない。"}, "sentence_index": 0, "correct_answer": "生ずる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私はこの町で生ずる。", "explanation": "ここは〈生まれる〉の意味。生ずるは物事や現象が起こる意味で、人の誕生には使わない。"}, {"text": "彼は舞台で王様を生ずる。", "explanation": "ここは〈演じる〉の意味。生ずるは役を演じる意味にはならない。"}, {"text": "お湯が生ずると、火を止める。", "explanation": "ここは〈沸く〉の意味。生ずるは問題や現象の発生を表し、湯が沸く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36625, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生ずる", "is_correct": true, "explanation": "「物事が起こる」意味。摩擦によって熱が発生する文に合う。"}, {"text": "論ずる", "is_correct": false, "explanation": "議論する意味で、物を主語にして「熱が論ずる」とは言えない。"}, {"text": "禁ずる", "is_correct": false, "explanation": "禁止する意味で、「熱が禁ずる」は成り立たない。"}, {"text": "報ずる", "is_correct": false, "explanation": "知らせる・報告する意味で、「熱が報ずる」は不自然。"}], "explanations": {"生ずる": "「物事が起こる」意味。摩擦によって熱が発生する文に合う。", "論ずる": "議論する意味で、物を主語にして「熱が論ずる」とは言えない。", "禁ずる": "禁止する意味で、「熱が禁ずる」は成り立たない。", "報ずる": "知らせる・報告する意味で、「熱が報ずる」は不自然。"}, "sentence_index": 6, "correct_answer": "生ずる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "授業では、その問題を一時間かけて生ずる。", "explanation": "ここは〈論ずる〉（論じる）の意味。生ずるは物事が起こる意味で、議論の場面には使わない。"}, {"text": "会社は新しい製品を生ずることに成功した。", "explanation": "ここは他動詞の〈作る〉の用法。生ずるは自動詞で、人が製品を作る文には使わない。"}, {"text": "困っている友達に、私はお金を生ずることにした。", "explanation": "ここは〈貸す〉の意味。生ずるは物事が起こる意味で、お金を人に渡すことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36625, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が続くと、道路に水たまりが生ずて、交通が乱れる。", "corrected_sentence": "雨が続くと、道路に水たまりが生じて、交通が乱れる。", "error_description": "「生ずる」のて形は「生じて」。「生ずて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生ずる", "is_correct": true, "explanation": "終止形。一般的な因果を述べる文の文末に使う形。"}, {"text": "生じさせる", "is_correct": false, "explanation": "使役形。「誤解を生じさせる」の形で「を」が必要で、「誤解が生じさせる」は成り立たない。"}, {"text": "生じて", "is_correct": false, "explanation": "て形は文末に置けないので、この文は終わらない。"}, {"text": "生ずれば", "is_correct": false, "explanation": "仮定形。「と」の条件文と重なって二重の条件になり、不自然。"}], "correct_form": "生ずる", "base_form": "生ずる", "form_label": "終止形", "sentence_index": 1, "explanations": {"生ずる": "終止形。一般的な因果を述べる文の文末に使う形。", "生じさせる": "使役形。「誤解を生じさせる」の形で「を」が必要で、「誤解が生じさせる」は成り立たない。", "生じて": "て形は文末に置けないので、この文は終わらない。", "生ずれば": "仮定形。「と」の条件文と重なって二重の条件になり、不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36625, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湯を沸かすと、鍋の底に小さな泡が生ずれる。", "corrected_sentence": "湯を沸かすと、鍋の底に小さな泡が生ずる。", "error_description": "「生ずれる」は正しい活用ではない。終止形は「生ずる」、仮定形は「生ずれば」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生ずる", "is_correct": true, "explanation": "終止形。「被害が生ずる」と文末で言い切る形で、この文に合う。"}, {"text": "生じながら", "is_correct": false, "explanation": "「ながら」は別の動作と並行する形で、続く文が必要。この文は「生じながら。」で終わらない。"}, {"text": "生じたら", "is_correct": false, "explanation": "「たら」の条件節になるため、文末に置くと続きが必要になる。この文は成り立たない。"}, {"text": "生じるために", "is_correct": false, "explanation": "「ために」は目的を表す形で、後に主節が必要。この文は「生じるために。」で言い切れない。"}], "correct_form": "生ずる", "base_form": "生ずる", "form_label": "終止形", "sentence_index": 7, "explanations": {"生ずる": "終止形。「被害が生ずる」と文末で言い切る形で、この文に合う。", "生じながら": "「ながら」は別の動作と並行する形で、続く文が必要。この文は「生じながら。」で終わらない。", "生じたら": "「たら」の条件節になるため、文末に置くと続きが必要になる。この文は成り立たない。", "生じるために": "「ために」は目的を表す形で、後に主節が必要。この文は「生じるために。」で言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36626, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「呼吸をする」の「を」。呼吸が「する」の対象になる。"}, {"text": "に", "is_correct": false, "explanation": "「呼吸にする」は何かを変化させる言い方になり、この文の意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「呼吸がする」は成り立たず、「する」の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「呼吸へする」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「呼吸をする」の「を」。呼吸が「する」の対象になる。", "に": "「呼吸にする」は何かを変化させる言い方になり、この文の意味が通らない。", "が": "「呼吸がする」は成り立たず、「する」の対象を示せない。", "へ": "「へ」は方向を示すので、「呼吸へする」は文が成り立たない。"}, "error_tags": {"に": "変化先", "が": "主格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
