INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36626, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "空気を体の中に入れたり、外に出したりすること。", "primary_collocate": null, "pronunciation": "こきゅう", "ipa": "kokʲɯː", "syllable_count": 3, "sentences": [{"text": "走ったあとで、呼吸が苦しくなった。", "target_word": "呼吸", "complexity_tier": "T2", "furigana": "走[はし]ったあとで、呼吸[こきゅう]が苦[くる]しくなった。", "sentence_source": "generated"}, {"text": "深く呼吸をすると、心が落ち着く。", "target_word": "呼吸", "complexity_tier": "T2", "furigana": "深[ふか]く呼吸[こきゅう]をすると、心[こころ]が落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "医者は患者の呼吸を確かめた。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]の呼吸[こきゅう]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "水に潜るときは、呼吸を止める。", "target_word": "呼吸", "complexity_tier": "T2", "furigana": "水[みず]に潜[もぐ]るときは、呼吸[こきゅう]を止[と]める。", "sentence_source": "generated"}, {"text": "魚はえらで呼吸している。", "target_word": "呼吸", "complexity_tier": "T2", "furigana": "魚[さかな]はえらで呼吸[こきゅう]している。", "sentence_source": "generated"}, {"text": "寝ているとき、赤ちゃんの呼吸は静かだった。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "寝[ね]ているとき、赤[あか]ちゃんの呼吸[こきゅう]は静[しず]かだった。", "sentence_source": "generated"}, {"text": "山の高いところでは空気がうすく、呼吸が速くなる。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "山[やま]の高[たか]いところでは空気[くうき]がうすく、呼吸[こきゅう]が速[はや]くなる。", "sentence_source": "generated"}, {"text": "歌を歌う前に、呼吸を整えた。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "歌[うた]を歌[うた]う前[まえ]に、呼吸[こきゅう]を整[ととの]えた。", "sentence_source": "generated"}, {"text": "煙の中では呼吸ができなくなるので、口をハンカチでおおう。", "target_word": "呼吸", "complexity_tier": "T4", "furigana": "煙[けむり]の中[なか]では呼吸[こきゅう]ができなくなるので、口[くち]をハンカチでおおう。", "sentence_source": "generated"}, {"text": "プールで泳ぐときは、顔を上げて呼吸をする。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "プールで泳[およ]ぐときは、顔[かお]を上[あ]げて呼吸[こきゅう]をする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼吸", "label": "基本形"}, {"form": "呼吸する", "label": "する動詞"}, {"form": "呼吸した", "label": "過去形"}, {"form": "呼吸を", "label": "目的語(を)"}], "register": "中立", "sense_fingerprint": "息を吸ったり吐いたりする体の働き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: うすく (Zipf 2.37)']::text[], '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36626, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼吸", "is_correct": true, "explanation": "体が空気を出し入れする働きで、走ったあとに苦しくなる主語になる。"}, {"text": "体温", "is_correct": false, "explanation": "体温は高い・低いで表すもので、「体温が苦しくなった」とは言わない。"}, {"text": "食欲", "is_correct": false, "explanation": "食欲は苦しくなるものではなく、この文の主語にならない。"}, {"text": "姿勢", "is_correct": false, "explanation": "姿勢は苦しくなるものではなく、この文の主語にならない。"}], "explanations": {"呼吸": "体が空気を出し入れする働きで、走ったあとに苦しくなる主語になる。", "体温": "体温は高い・低いで表すもので、「体温が苦しくなった」とは言わない。", "食欲": "食欲は苦しくなるものではなく、この文の主語にならない。", "姿勢": "姿勢は苦しくなるものではなく、この文の主語にならない。"}, "sentence_index": 0, "correct_answer": "呼吸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "検査では、呼吸に含まれる二酸化炭素の量を測った。", "explanation": "ここは〈呼気〉（吐き出した空気）の意味。呼吸は吸ったり吐いたりする働きで、中に含まれるものとしては言わない。呼気に含まれる、と言う。"}, {"text": "おいしいスープを飲んで、思わず呼吸をついた。", "explanation": "ここは〈息〉の意味。息をつく（安堵や満足の息）は呼吸では言わない。"}, {"text": "赤ちゃんは、安らかな呼吸をたてて眠っている。", "explanation": "ここは〈寝息〉の意味。寝息をたてるとは言うが、呼吸をたてるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36626, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼吸", "is_correct": true, "explanation": "空気の出し入れの働きで、空気がうすくなると速くなる主語になる。"}, {"text": "視力", "is_correct": false, "explanation": "視力は速くなるものではなく、この文の主語にならない。"}, {"text": "血圧", "is_correct": false, "explanation": "血圧は高い・低いで表すもので、速くなるとは言わない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は増減で表すもので、速くなるとは言わない。"}], "explanations": {"呼吸": "空気の出し入れの働きで、空気がうすくなると速くなる主語になる。", "視力": "視力は速くなるものではなく、この文の主語にならない。", "血圧": "血圧は高い・低いで表すもので、速くなるとは言わない。", "体重": "体重は増減で表すもので、速くなるとは言わない。"}, "sentence_index": 6, "correct_answer": "呼吸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議が終わって、ほっと呼吸をもらした。", "explanation": "ここは〈ため息〉の意味。ため息をもらすは安堵や疲れを表す息で、体の呼吸とは言い換えられない。"}, {"text": "暑い日は、たくさん呼吸をかくので水を飲もう。", "explanation": "ここは〈汗〉の意味。汗をかくとは言うが、呼吸は空気の出し入れで、かく対象にはならない。"}, {"text": "台所から、いい呼吸が漂ってきた。", "explanation": "ここは〈におい〉の意味。香りが広がる意味で、体の働きの呼吸は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36626, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゆっくり呼吸にすると、体の力が抜ける。", "corrected_sentence": "ゆっくり呼吸をすると、体の力が抜ける。", "error_description": "「呼吸をする」の「を」が正しい。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36626, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝る前に、ゆっくり呼吸を閉めよう。", "corrected_sentence": "寝る前に、ゆっくり呼吸を整えよう。", "error_description": "「呼吸を整える」が正しい。「閉める」は呼吸には使わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
