INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36627, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生物が肺などで、空気を吸ったり吐いたりする現象。", "primary_collocate": null, "pronunciation": "こきゅう", "ipa": "kokʲɯː", "syllable_count": 3, "sentences": [{"text": "運動のあとは、呼吸が速くなります。", "target_word": "呼吸", "complexity_tier": "T2", "furigana": "運動[うんどう]のあとは、呼吸[こきゅう]が速[はや]くなります。", "sentence_source": "generated"}, {"text": "深く呼吸をすると、気持ちが落ち着きます。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "深[ふか]く呼吸[こきゅう]をすると、気持[きも]ちが落[お]ち着[つ]きます。", "sentence_source": "generated"}, {"text": "水の中では、魚はえらで呼吸をしている。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]では、魚[さかな]はえらで呼吸[こきゅう]をしている。", "sentence_source": "generated"}, {"text": "緊張したときは、ゆっくり呼吸を整えましょう。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "緊張[きんちょう]したときは、ゆっくり呼吸[こきゅう]を整[ととの]えましょう。", "sentence_source": "generated"}, {"text": "赤ちゃんは静かな呼吸をして眠っていた。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは静[しず]かな呼吸[こきゅう]をして眠[ねむ]っていた。", "sentence_source": "generated"}, {"text": "山の上は空気がうすく、呼吸が苦しくなった。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は空気[くうき]がうすく、呼吸[こきゅう]が苦[くる]しくなった。", "sentence_source": "generated"}, {"text": "医者は患者の呼吸と脈をていねいに調べた。", "target_word": "呼吸", "complexity_tier": "T4", "furigana": "医者[いしゃ]は患者[かんじゃ]の呼吸[こきゅう]と脈[みゃく]をていねいに調[しら]べた。", "sentence_source": "generated"}, {"text": "呼吸が止まったので、すぐに救急車を呼んだ。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "呼吸[こきゅう]が止[と]まったので、すぐに救急車[きゅうきゅうしゃ]を呼[よ]んだ。", "sentence_source": "generated"}, {"text": "泳ぐときは、息つぎのタイミングに合わせて呼吸する。", "target_word": "呼吸", "complexity_tier": "T4", "furigana": "泳[およ]ぐときは、息[いき]つぎのタイミングに合[あ]わせて呼吸[こきゅう]する。", "sentence_source": "generated"}, {"text": "鼻から吸って口から吐く呼吸の練習をした。", "target_word": "呼吸", "complexity_tier": "T3", "furigana": "鼻[はな]から吸[す]って口[くち]から吐[は]く呼吸[こきゅう]の練習[れんしゅう]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼吸", "label": "基本形"}, {"form": "呼吸する", "label": "する動詞形"}, {"form": "呼吸した", "label": "過去形"}, {"form": "呼吸が", "label": "主格"}], "register": "neutral", "sense_fingerprint": "生物が空気を吸って吐く、息をする働き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: うすく (Zipf 2.37)']::text[], '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36627, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼吸", "is_correct": true, "explanation": "空気の出し入れの働きで、運動のあとに速くなる主語になる。"}, {"text": "体重", "is_correct": false, "explanation": "体重は増減で表すもので、速くなるとは言わない。"}, {"text": "視力", "is_correct": false, "explanation": "視力は速くなるものではなく、この文の主語にならない。"}, {"text": "食欲", "is_correct": false, "explanation": "食欲は速くなるものではなく、運動のあとの主語にならない。"}], "explanations": {"呼吸": "空気の出し入れの働きで、運動のあとに速くなる主語になる。", "体重": "体重は増減で表すもので、速くなるとは言わない。", "視力": "視力は速くなるものではなく、この文の主語にならない。", "食欲": "食欲は速くなるものではなく、運動のあとの主語にならない。"}, "sentence_index": 0, "correct_answer": "呼吸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宿題が終わって、ほっと呼吸をついた。", "explanation": "ここは〈息〉の意味。息をつくは安堵の息を吐くことで、呼吸をつくとは言わない。"}, {"text": "緊張すると、心臓の呼吸が速くなる。", "explanation": "ここは〈鼓動〉の意味。心臓の拍動を指す語で、空気の出し入れには使わない。"}, {"text": "教室に子どもたちの呼吸が広がった。", "explanation": "ここは〈笑い声〉の意味。笑い声が広がるという意味で、体の呼吸は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36627, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼吸", "is_correct": true, "explanation": "体の空気の出し入れの働きで、患者の状態を調べる対象として脈と並ぶ。"}, {"text": "足音", "is_correct": false, "explanation": "足音は脈と並べて調べるものではなく、患者の状態を調べる対象にならない。"}, {"text": "笑顔", "is_correct": false, "explanation": "笑顔は脈と並べて調べるものではなく、この文では不自然。"}, {"text": "財布", "is_correct": false, "explanation": "財布は体の状態を調べる対象ではなく、脈と並べて調べる文として成り立たない。"}], "explanations": {"呼吸": "体の空気の出し入れの働きで、患者の状態を調べる対象として脈と並ぶ。", "足音": "足音は脈と並べて調べるものではなく、患者の状態を調べる対象にならない。", "笑顔": "笑顔は脈と並べて調べるものではなく、この文では不自然。", "財布": "財布は体の状態を調べる対象ではなく、脈と並べて調べる文として成り立たない。"}, "sentence_index": 6, "correct_answer": "呼吸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中なので、呼吸を立てないように、そっと歩いた。", "explanation": "ここは〈足音〉の意味。足音を立てるとは言うが、呼吸を立てるとは言わない。"}, {"text": "会議が退屈で、大きな呼吸をかみ殺した。", "explanation": "ここは〈あくび〉の意味。あくびをかみ殺すとは言えるが、呼吸をかみ殺すとは言わない。"}, {"text": "遠くから太鼓の呼吸が聞こえた。", "explanation": "ここは〈音〉の意味。太鼓の音が聞こえるという意味で、体の呼吸は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36627, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝ているあいだも、呼吸を続いている。", "corrected_sentence": "寝ているあいだも、呼吸が続いている。", "error_description": "「続いている」は自動詞なので主語に「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36627, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の上では、呼吸を苦しくなりやすい。", "corrected_sentence": "山の上では、呼吸が苦しくなりやすい。", "error_description": "「苦しくなる」は主語に「が」を使う。「呼吸を」は誤りで、正しくは「呼吸が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
