INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36628, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す「で」。「この周辺で、おいしいパン屋を知りませんか」と探す場所を表し、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語にすると「周辺が知る」となり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語にすると「周辺を知る」となり、場所の文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「知る」という動作と合わない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す「で」。「この周辺で、おいしいパン屋を知りませんか」と探す場所を表し、文に合う。", "が": "主語にすると「周辺が知る」となり、文が成り立たない。", "を": "目的語にすると「周辺を知る」となり、場所の文として不自然。", "へ": "方向を表す助詞で、「知る」という動作と合わない。"}, "error_tags": {"が": "主語にすると「周辺が知る」となり文が成り立たない", "を": "目的語にすると「周辺を知る」となり場所の文として不自然", "へ": "方向を表す助詞で、「知る」という動作と合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36628, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かのまわりにあるところ。", "primary_collocate": null, "pronunciation": "しゅうへん", "ipa": "ɕɯːheɴ", "syllable_count": 4, "sentences": [{"text": "駅の周辺には、安いレストランがたくさんあります。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "駅[えき]の周辺[しゅうへん]には、安[やす]いレストランがたくさんあります。", "sentence_source": "generated"}, {"text": "学校の周辺は静かなので、勉強しやすいです。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "学校[がっこう]の周辺[しゅうへん]は静[しず]かなので、勉強[べんきょう]しやすいです。", "sentence_source": "generated"}, {"text": "家の周辺を散歩すると、いい運動になります。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "家[いえ]の周辺[しゅうへん]を散歩[さんぽ]すると、いい運動[うんどう]になります。", "sentence_source": "generated"}, {"text": "空港の周辺はホテルが多く、泊まる場所に困りません。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "空港[くうこう]の周辺[しゅうへん]はホテルが多[おお]く、泊[と]まる場所[ばしょ]に困[こま]りません。", "sentence_source": "generated"}, {"text": "事故があったため、現場の周辺は通れませんでした。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "事故[じこ]があったため、現場[げんば]の周辺[しゅうへん]は通[とお]れませんでした。", "sentence_source": "generated"}, {"text": "公園の周辺に、新しい図書館ができました。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "公園[こうえん]の周辺[しゅうへん]に、新[あたら]しい図書館[としょかん]ができました。", "sentence_source": "generated"}, {"text": "湖の周辺には、きれいな花が咲いています。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "湖[みずうみ]の周辺[しゅうへん]には、きれいな花[はな]が咲[さ]いています。", "sentence_source": "generated"}, {"text": "この周辺で、おいしいパン屋を知りませんか。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "この周辺[しゅうへん]で、おいしいパン屋[や]を知[し]りませんか。", "sentence_source": "generated"}, {"text": "大学の周辺は学生が多いので、いつもにぎやかです。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "大学[だいがく]の周辺[しゅうへん]は学生[がくせい]が多[おお]いので、いつもにぎやかです。", "sentence_source": "generated"}, {"text": "病院の周辺には薬局が三つあります。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "病院[びょういん]の周辺[しゅうへん]には薬局[やっきょく]が三[みっ]つあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "周辺", "label": "基本形"}, {"form": "周辺の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "ある場所や建物のまわりの地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36628, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時刻", "is_correct": false, "explanation": "時間を表す語なので、駅の周辺に店があるかを述べる文には合わない。"}, {"text": "周辺", "is_correct": true, "explanation": "駅のまわりの地域を表し、その周辺に安い店が多いという文に合う。"}, {"text": "運賃", "is_correct": false, "explanation": "乗車の料金の意味で、店の所在を述べる文には合わない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券の意味で、駅の場所にレストランがあるという文脈には合わない。"}], "explanations": {"時刻": "時間を表す語なので、駅の周辺に店があるかを述べる文には合わない。", "周辺": "駅のまわりの地域を表し、その周辺に安い店が多いという文に合う。", "運賃": "乗車の料金の意味で、店の所在を述べる文には合わない。", "切符": "乗車券の意味で、駅の場所にレストランがあるという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "周辺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械は周辺が短いので、回転が速すぎて危ない。", "explanation": "ここは〈周期〉の意味。一定の間隔で繰り返す周期を使い、まわりの場所を指す周辺は合わない。"}, {"text": "彼女は周辺の視線が気になって、ずっと下を向いていた。", "explanation": "ここは〈周囲〉の意味。人の視線には周囲を使い、周辺は場所を指すので合わない。"}, {"text": "この大会では周辺遅れの選手が多かった。", "explanation": "ここは〈周回遅れ〉の意味。周回は一周ずつ数える語で、まわりの場所を指す周辺は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36628, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水位", "is_correct": false, "explanation": "水面の高さを表す語で、花が咲いている場所を述べる文には合わない。"}, {"text": "周辺", "is_correct": true, "explanation": "湖のまわりの地域を表し、その周辺にきれいな花が咲くという文に合う。"}, {"text": "水質", "is_correct": false, "explanation": "水の性質の意味で、花が咲く場所を示す文には合わない。"}, {"text": "深さ", "is_correct": false, "explanation": "水の深さを表す語で、花が咲いている場所の文脈には合わない。"}], "explanations": {"水位": "水面の高さを表す語で、花が咲いている場所を述べる文には合わない。", "周辺": "湖のまわりの地域を表し、その周辺にきれいな花が咲くという文に合う。", "水質": "水の性質の意味で、花が咲く場所を示す文には合わない。", "深さ": "水の深さを表す語で、花が咲いている場所の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "周辺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は周辺に準備を進めて、当日も慌てなかった。", "explanation": "ここは〈周到〉の意味。準備に抜かりがないことを表す周到を使い、まわりの場所を指す周辺は合わない。"}, {"text": "来年は会社の周辺にあたるので、盛大に祝います。", "explanation": "ここは〈周年〉の意味。創立からの年数を数える周年を使い、まわりの場所を指す周辺は合わない。"}, {"text": "京都の周辺券を買って、バスで回りました。", "explanation": "ここは〈周遊券〉の意味。決まった区間を何度も乗れる周遊券を使い、まわりの場所を指す周辺は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36628, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方、家の周辺に歩くと、気分がすっきりします。", "corrected_sentence": "夕方、家の周辺を歩くと、気分がすっきりします。", "error_description": "「周辺」の直後の助詞「を」を「に」にした誤り。「歩く」は「〜を歩く」と目的語に「を」を取るので、正しくは「周辺を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36628, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "港の周辺が歩くと、潮の香りがします。", "corrected_sentence": "港の周辺を歩くと、潮の香りがします。", "error_description": "「周辺」の直後の助詞「が」を「を」に直す誤り。「歩く」は目的語に「を」を取るので、主語の「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36629, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す「で」。「工場の周辺で、機械の音が聞こえる」と音が聞こえる場所を表し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語にすると「周辺を聞こえる」となり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「聞こえる」という動きと合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語にすると「周辺が聞こえる」となり意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す「で」。「工場の周辺で、機械の音が聞こえる」と音が聞こえる場所を表し、文に合う。", "を": "目的語にすると「周辺を聞こえる」となり不自然。", "へ": "方向を表す助詞で、「聞こえる」という動きと合わない。", "が": "主語にすると「周辺が聞こえる」となり意味が通らない。"}, "error_tags": {"を": "目的語にすると「周辺を聞こえる」となり不自然", "へ": "方向を表す助詞で、「聞こえる」という動きと合わない", "が": "主語にすると「周辺が聞こえる」となり意味が通らない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
