INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36629, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物や場所のすぐ外側の部分。また、そのあたり。", "primary_collocate": null, "pronunciation": "しゅうへん", "ipa": "ɕɯːheɴ", "syllable_count": 4, "sentences": [{"text": "城の周辺には、古い堀が残っています。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "城[しろ]の周辺[しゅうへん]には、古[ふる]い堀[ほり]が残[のこ]っています。", "sentence_source": "generated"}, {"text": "工場の周辺では、夜も機械の音が聞こえます。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "工場[こうじょう]の周辺[しゅうへん]では、夜[よる]も機械[きかい]の音[おと]が聞[き]こえます。", "sentence_source": "generated"}, {"text": "池の周辺を一周すると、三十分かかります。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "池[いけ]の周辺[しゅうへん]を一周[いっしゅう]すると、三十分[さんじゅっぷん]かかります。", "sentence_source": "generated"}, {"text": "町の周辺は、田んぼと畑ばかりです。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "町[まち]の周辺[しゅうへん]は、田[た]んぼと畑[はたけ]ばかりです。", "sentence_source": "generated"}, {"text": "火山の周辺には、温泉がいくつもあります。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "火山[かざん]の周辺[しゅうへん]には、温泉[おんせん]がいくつもあります。", "sentence_source": "generated"}, {"text": "神社の周辺に、お祭りの店が並びました。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "神社[じんじゃ]の周辺[しゅうへん]に、お祭[まつ]りの店[みせ]が並[なら]びました。", "sentence_source": "generated"}, {"text": "東京の周辺の県から、通勤する人が多いです。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "東京[とうきょう]の周辺[しゅうへん]の県[けん]から、通勤[つうきん]する人[ひと]が多[おお]いです。", "sentence_source": "generated"}, {"text": "ビルの周辺は風が強いので、帽子に気をつけてください。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "ビルの周辺[しゅうへん]は風[かぜ]が強[つよ]いので、帽子[ぼうし]に気[き]をつけてください。", "sentence_source": "generated"}, {"text": "台風のため、海の周辺には近づかないでください。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "台風[たいふう]のため、海[うみ]の周辺[しゅうへん]には近[ちか]づかないでください。", "sentence_source": "generated"}, {"text": "彼は会社の周辺に住んでいるので、通勤が楽です。", "target_word": "周辺", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]の周辺[しゅうへん]に住[す]んでいるので、通勤[つうきん]が楽[らく]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "周辺", "label": "基本形"}, {"form": "周辺の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "物や場所のすぐ外側のあたり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36629, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屋根", "is_correct": false, "explanation": "建物の上の覆いで、堀が残っているという文の場所としては合わない。"}, {"text": "周辺", "is_correct": true, "explanation": "城のすぐ外側のあたりを表し、古い堀が残っている場所として自然。"}, {"text": "天井", "is_correct": false, "explanation": "室内の上部を指すので、城の堀の所在を述べる文には合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "時間を表す語で、堀が残っている場所を示す文には合わない。"}], "explanations": {"屋根": "建物の上の覆いで、堀が残っているという文の場所としては合わない。", "周辺": "城のすぐ外側のあたりを表し、古い堀が残っている場所として自然。", "天井": "室内の上部を指すので、城の堀の所在を述べる文には合わない。", "時刻": "時間を表す語で、堀が残っている場所を示す文には合わない。"}, "sentence_index": 0, "correct_answer": "周辺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この電球は周辺が短いので、すぐ切れてしまう。", "explanation": "ここは〈周期〉の意味。繰り返す間隔を指す周期を使い、物のすぐ外側を指す周辺は合わない。"}, {"text": "周辺の目が気になって、話しかけられなかった。", "explanation": "ここは〈周囲〉の意味。人の目には周囲を使い、周辺は物や場所の外側を指すので合わない。"}, {"text": "彼はレースで周辺遅れになった。", "explanation": "ここは〈周回遅れ〉の意味。周回は一周ずつ数える語で、物の外側を指す周辺は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36629, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "駅", "is_correct": false, "explanation": "乗り物の拠点を指し、県の位置を示す文には合わない。"}, {"text": "周辺", "is_correct": true, "explanation": "東京のまわりの地域を表し、近隣の県から通勤する人が多いという文に合う。"}, {"text": "海岸", "is_correct": false, "explanation": "海沿いの場所を指すので、県の位置関係を述べる文には合わない。"}, {"text": "山地", "is_correct": false, "explanation": "山々が連なる地域を指すので、通勤する人の多い県の文には合わない。"}], "explanations": {"駅": "乗り物の拠点を指し、県の位置を示す文には合わない。", "周辺": "東京のまわりの地域を表し、近隣の県から通勤する人が多いという文に合う。", "海岸": "海沿いの場所を指すので、県の位置関係を述べる文には合わない。", "山地": "山々が連なる地域を指すので、通勤する人の多い県の文には合わない。"}, "sentence_index": 6, "correct_answer": "周辺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は周辺に計画を立てて、失敗を防いだ。", "explanation": "ここは〈周到〉の意味。抜かりのない様子を表す周到を使い、物の外側を指す周辺は合わない。"}, {"text": "今年で店が十周辺を迎えるので、感謝の催しをします。", "explanation": "ここは〈周年〉の意味。創立からの年数を数える周年を使い、物の外側を指す周辺は合わない。"}, {"text": "京都の周辺券で、一日じゅう電車に乗りました。", "explanation": "ここは〈周遊券〉の意味。区間内を自由に乗れる周遊券を使い、物の外側を指す周辺は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
