INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36630, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「血管が細くなる」の「が」。細くなる主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「細くなる」は自動詞なので、目的語の「を」は取らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や到達点を示すので、血管が細くなる主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「血管へ細くなる」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「血管が細くなる」の「が」。細くなる主体を示す。", "を": "「細くなる」は自動詞なので、目的語の「を」は取らない。", "に": "「に」は場所や到達点を示すので、血管が細くなる主語にならない。", "へ": "「へ」は方向を示すので、「血管へ細くなる」は成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所・到達点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
