INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36630, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体の中にあって、血が通う管のことです。", "primary_collocate": null, "pronunciation": "けっかん", "ipa": "kekkaɴ", "syllable_count": 4, "sentences": [{"text": "血管の中を血が流れています。", "target_word": "血管", "complexity_tier": "T2", "furigana": "血管[けっかん]の中[なか]を血[ち]が流[なが]れています。", "sentence_source": "generated"}, {"text": "寒いと、手の血管が細くなります。", "target_word": "血管", "complexity_tier": "T2", "furigana": "寒[さむ]いと、手[て]の血管[けっかん]が細[ほそ]くなります。", "sentence_source": "generated"}, {"text": "注射のために腕の血管を探した。", "target_word": "血管", "complexity_tier": "T3", "furigana": "注射[ちゅうしゃ]のために腕[うで]の血管[けっかん]を探[さが]した。", "sentence_source": "generated"}, {"text": "この病気は血管がつまることで起こる。", "target_word": "血管", "complexity_tier": "T3", "furigana": "この病気[びょうき]は血管[けっかん]がつまることで起[お]こる。", "sentence_source": "generated"}, {"text": "おふろに入ると血管が広がって、体が温まる。", "target_word": "血管", "complexity_tier": "T3", "furigana": "おふろに入[はい]ると血管[けっかん]が広[ひろ]がって、体[からだ]が温[あたた]まる。", "sentence_source": "generated"}, {"text": "年をとると、血管がかたくなりやすい。", "target_word": "血管", "complexity_tier": "T3", "furigana": "年[とし]をとると、血管[けっかん]がかたくなりやすい。", "sentence_source": "generated"}, {"text": "看護師は細い血管にもうまく針を入れた。", "target_word": "血管", "complexity_tier": "T3", "furigana": "看護師[かんごし]は細[ほそ]い血管[けっかん]にもうまく針[はり]を入[い]れた。", "sentence_source": "generated"}, {"text": "顔が赤いのは、血管が広がっているからだ。", "target_word": "血管", "complexity_tier": "T3", "furigana": "顔[かお]が赤[あか]いのは、血管[けっかん]が広[ひろ]がっているからだ。", "sentence_source": "generated"}, {"text": "血管が切れて、血がたくさん出た。", "target_word": "血管", "complexity_tier": "T2", "furigana": "血管[けっかん]が切[き]れて、血[ち]がたくさん出[で]た。", "sentence_source": "generated"}, {"text": "医者は足の血管の検査をすすめた。", "target_word": "血管", "complexity_tier": "T3", "furigana": "医者[いしゃ]は足[あし]の血管[けっかん]の検査[けんさ]をすすめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "血管", "label": "基本形"}, {"form": "血管が", "label": "主格"}, {"form": "血管を", "label": "目的格"}, {"form": "血管の", "label": "連体格"}], "register": "neutral", "sense_fingerprint": "体の中で血が通る管", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36630, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "血管", "is_correct": true, "explanation": "血が通る管のことで、血が流れる場所として文に合う。"}, {"text": "神経", "is_correct": false, "explanation": "神経は信号を伝える組織で、血が流れる場所ではない。"}, {"text": "爪", "is_correct": false, "explanation": "爪は角質でできた部分で、血が流れる管ではない。"}, {"text": "涙", "is_correct": false, "explanation": "涙は目から出る液体で、血が流れる場所ではない。"}], "explanations": {"血管": "血が通る管のことで、血が流れる場所として文に合う。", "神経": "神経は信号を伝える組織で、血が流れる場所ではない。", "爪": "爪は角質でできた部分で、血が流れる管ではない。", "涙": "涙は目から出る液体で、血が流れる場所ではない。"}, "sentence_index": 0, "correct_answer": "血管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "血管が不足すると、めまいがする。", "explanation": "ここは〈血液〉の意味。不足するのは血液で、血管が足りないとは言わない。"}, {"text": "台所の血管が詰まって、水が流れない。", "explanation": "ここは〈排水管〉の意味。台所の水が流れない場面で、体の血管は使わない。"}, {"text": "血管を開けて、部屋に光を入れた。", "explanation": "ここは〈カーテン〉の意味。開けるのは窓やカーテンで、血管は開けるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36630, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血管", "is_correct": true, "explanation": "細い血管に針を入れる文で、針を刺す対象になる。"}, {"text": "眉毛", "is_correct": false, "explanation": "眉毛は針を入れる対象として不自然で、この文には合わない。"}, {"text": "髪", "is_correct": false, "explanation": "髪は針を入れる対象として不自然で、この文には合わない。"}, {"text": "まつ毛", "is_correct": false, "explanation": "まつ毛は針を入れる対象として不自然で、この文には合わない。"}], "explanations": {"血管": "細い血管に針を入れる文で、針を刺す対象になる。", "眉毛": "眉毛は針を入れる対象として不自然で、この文には合わない。", "髪": "髪は針を入れる対象として不自然で、この文には合わない。", "まつ毛": "まつ毛は針を入れる対象として不自然で、この文には合わない。"}, "sentence_index": 6, "correct_answer": "血管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "転んで、足の血管が折れた。", "explanation": "ここは〈骨〉の意味。折れるのは骨で、血管は切れる・破れると言う。"}, {"text": "血管を削って、先をとがらせた。", "explanation": "ここは〈鉛筆〉の意味。先を削るのは鉛筆で、血管は削るものではない。"}, {"text": "血管を編んで、マフラーを作った。", "explanation": "ここは〈毛糸〉の意味。編んで作るのは毛糸で、血管は編むものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36630, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "運動をすると、腕の血管を太くなる。", "corrected_sentence": "運動をすると、腕の血管が太くなる。", "error_description": "「太くなる」は自動詞なので主語に「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36630, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い夜は、手の血管をちぢまりやすい。", "corrected_sentence": "寒い夜は、手の血管がちぢまりやすい。", "error_description": "「ちぢまる」は自動詞なので主語に「が」を使う。「血管を」は誤りで、「血管が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
