INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36631, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「血管をつなげる」の「を」。つなげる対象の血管を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す格で、「つなげる」の対象を取る形に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す助詞で、「つなげる」の直接の対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示し、「つなげる」の対象としては成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「血管をつなげる」の「を」。つなげる対象の血管を示す。", "が": "主語を示す格で、「つなげる」の対象を取る形に合わない。", "の": "連体修飾を示す助詞で、「つなげる」の直接の対象にならない。", "より": "比較の基準を示し、「つなげる」の対象としては成り立たない。"}, "error_tags": {"が": "主語を示す格で、「つなげる」の対象を取る形に合わない", "の": "連体修飾を示す助詞で、「つなげる」の直接の対象にならない", "より": "比較の基準を示し、「つなげる」の対象としては成り立たない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36631, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "血液が流れる管。全身に酸素や栄養を運び、二酸化炭素や老廃物を回収する。", "primary_collocate": null, "pronunciation": "けっかん", "ipa": "kekkaɴ", "syllable_count": 4, "sentences": [{"text": "血管は全身に酸素や栄養を運んでいる。", "target_word": "血管", "complexity_tier": "T3", "furigana": "血管[けっかん]は全身[ぜんしん]に酸素[さんそ]や栄養[えいよう]を運[はこ]んでいる。", "sentence_source": "generated"}, {"text": "動脈は心臓から出る血管で、壁が厚い。", "target_word": "血管", "complexity_tier": "T4", "furigana": "動脈[どうみゃく]は心臓[しんぞう]から出[で]る血管[けっかん]で、壁[かべ]が厚[あつ]い。", "sentence_source": "generated"}, {"text": "細い血管が網の目のように体中に広がっている。", "target_word": "血管", "complexity_tier": "T4", "furigana": "細[ほそ]い血管[けっかん]が網[あみ]の目[め]のように体中[からだじゅう]に広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "運動を続けると、血管の働きがよくなる。", "target_word": "血管", "complexity_tier": "T3", "furigana": "運動[うんどう]を続[つづ]けると、血管[けっかん]の働[はたら]きがよくなる。", "sentence_source": "generated"}, {"text": "血管は二酸化炭素や老廃物も回収して、肺や腎臓へ運ぶ。", "target_word": "血管", "complexity_tier": "T4", "furigana": "血管[けっかん]は二酸化炭素[にさんかたんそ]や老廃物[ろうはいぶつ]も回収[かいしゅう]して、肺[はい]や腎臓[じんぞう]へ運[はこ]ぶ。", "sentence_source": "generated"}, {"text": "塩分をとりすぎると、血管に負担がかかる。", "target_word": "血管", "complexity_tier": "T3", "furigana": "塩分[えんぶん]をとりすぎると、血管[けっかん]に負担[ふたん]がかかる。", "sentence_source": "generated"}, {"text": "血管が詰まると、酸素が届かなくなって細胞が弱る。", "target_word": "血管", "complexity_tier": "T4", "furigana": "血管[けっかん]が詰[つ]まると、酸素[さんそ]が届[とど]かなくなって細胞[さいぼう]が弱[よわ]る。", "sentence_source": "generated"}, {"text": "体じゅうの血管をつなげると、地球を二周する長さになるそうだ。", "target_word": "血管", "complexity_tier": "T4", "furigana": "体[からだ]じゅうの血管[けっかん]をつなげると、地球[ちきゅう]を二周[にしゅう]する長[なが]さになるそうだ。", "sentence_source": "generated"}, {"text": "医師はカメラで心臓の血管の中を観察した。", "target_word": "血管", "complexity_tier": "T4", "furigana": "医師[いし]はカメラで心臓[しんぞう]の血管[けっかん]の中[なか]を観察[かんさつ]した。", "sentence_source": "generated"}, {"text": "血管の壁がやわらかいと、血液がスムーズに流れる。", "target_word": "血管", "complexity_tier": "T4", "furigana": "血管[けっかん]の壁[かべ]がやわらかいと、血液[けつえき]がスムーズに流[なが]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "血管", "label": "基本形"}, {"form": "血管が", "label": "主格"}, {"form": "血管に", "label": "与格・位格"}, {"form": "血管の", "label": "連体格"}], "register": "neutral", "sense_fingerprint": "血液を流し、酸素や栄養を運び老廃物を回収する管", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36631, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "血管", "is_correct": true, "explanation": "血液を全身へ運ぶ管を指し、酸素や栄養を運ぶ主語として文が成り立つ。"}, {"text": "神経", "is_correct": false, "explanation": "神経は感覚や命令を伝える組織で、酸素や栄養を運ぶ役目ではないため合わない。"}, {"text": "骨", "is_correct": false, "explanation": "骨は体を支える組織で、血液や栄養を運ぶ働きがないため合わない。"}, {"text": "筋肉", "is_correct": false, "explanation": "筋肉は体を動かす組織で、酸素や栄養を運ぶのは血管の役割のため合わない。"}], "explanations": {"血管": "血液を全身へ運ぶ管を指し、酸素や栄養を運ぶ主語として文が成り立つ。", "神経": "神経は感覚や命令を伝える組織で、酸素や栄養を運ぶ役目ではないため合わない。", "骨": "骨は体を支える組織で、血液や栄養を運ぶ働きがないため合わない。", "筋肉": "筋肉は体を動かす組織で、酸素や栄養を運ぶのは血管の役割のため合わない。"}, "sentence_index": 0, "correct_answer": "血管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "運動を続けると、血管の流れがよくなる。", "explanation": "ここは〈血液〉の意味。流れるのは血液で、血管は血液が通る管なので「血管の流れ」とは言わない。"}, {"text": "感覚を脳へ伝えるのは血管だ。", "explanation": "ここは〈神経〉の意味。感覚を伝えるのは神経で、血管は血液を運ぶ管なので合わない。"}, {"text": "運動のあとは、血管が速くなる。", "explanation": "ここは〈脈〉の意味。鼓動の速さを表すのは脈で、血管が速くなるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36631, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "血管", "is_correct": true, "explanation": "詰まると酸素が届かなくなる管を指し、「血管が詰まる」として文が成り立つ。"}, {"text": "爪", "is_correct": false, "explanation": "爪は指先の固い部分で、詰まって酸素の流れを止める組織ではないため合わない。"}, {"text": "髪", "is_correct": false, "explanation": "髪は頭に生える毛で、詰まって細胞に酸素を届けなくする器官ではないため合わない。"}, {"text": "唇", "is_correct": false, "explanation": "唇は口の周りの部位で、詰まって酸素が届かなくなる場所ではないため合わない。"}], "explanations": {"血管": "詰まると酸素が届かなくなる管を指し、「血管が詰まる」として文が成り立つ。", "爪": "爪は指先の固い部分で、詰まって酸素の流れを止める組織ではないため合わない。", "髪": "髪は頭に生える毛で、詰まって細胞に酸素を届けなくする器官ではないため合わない。", "唇": "唇は口の周りの部位で、詰まって酸素が届かなくなる場所ではないため合わない。"}, "sentence_index": 6, "correct_answer": "血管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い血管がさびて、水が漏れている。", "explanation": "ここは〈配管〉の意味。さびるのは金属の配管で、血管は血が通る体の管なので合わない。"}, {"text": "血管が一分間に七十回打って、全身へ血を送る。", "explanation": "ここは〈心臓〉の意味。規則的に打って血を送り出すのは心臓で、血管は打たないので合わない。"}, {"text": "血管が膨らんで、空気を取り込む。", "explanation": "ここは〈肺〉の意味。空気を取り込むのは肺で、血管は血液が通る管なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36631, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "血管を詰まると、足がしびれることがある。", "corrected_sentence": "血管が詰まると、足がしびれることがある。", "error_description": "助詞の誤り。「詰まる」は自動詞なので主語には「血管が」を使う。「血管を」は他動詞の目的語の形で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36631, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "運動で血管が広げると、血圧が下がる。", "corrected_sentence": "運動で血管が広がると、血圧が下がる。", "error_description": "自動詞と他動詞の取り違え。主語は「血管が」なので自動詞「広がる」が正しく、他動詞「広げる」は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36632, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "通過する場所（ゴール地点）を示す目的語の「を」。"}, {"text": "が", "is_correct": false, "explanation": "「地点が通過した」では地点が動く主語になり、不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では地点と何かを並べる意味になり、通過の文には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる文脈が必要で、ここでは成り立たない。"}], "correct_answer": "を", "explanations": {"を": "通過する場所（ゴール地点）を示す目的語の「を」。", "が": "「地点が通過した」では地点が動く主語になり、不自然。", "と": "並列の「と」では地点と何かを並べる意味になり、通過の文には合わない。", "より": "比較の「より」は比べる文脈が必要で、ここでは成り立たない。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36632, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語（特急）を示す格助詞の「が」。特急が通過する意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「特急を通過する」だと特急が通り抜けられる対象になり、通過する主体がなく不自然。"}, {"text": "に", "is_correct": false, "explanation": "「特急に通過する」は帰着点の関係にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は行き先に付くもので、特急の動きを示さない。"}], "correct_answer": "が", "explanations": {"が": "主語（特急）を示す格助詞の「が」。特急が通過する意味になる。", "を": "「特急を通過する」だと特急が通り抜けられる対象になり、通過する主体がなく不自然。", "に": "「特急に通過する」は帰着点の関係にならず、不自然。", "へ": "方向の「へ」は行き先に付くもので、特急の動きを示さない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36632, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが一方の側からもう一方の側へと動いて通ること。", "primary_collocate": null, "pronunciation": "つうか", "ipa": "tsɯːka", "syllable_count": 3, "sentences": [{"text": "彗星が地球の近くを通過する様子を、望遠鏡で観察した。", "target_word": "通過", "complexity_tier": "T3", "furigana": "彗星[すいせい]が地球[ちきゅう]の近[ちか]くを通過[つうか]する様子[ようす]を、望遠鏡[ぼうえんきょう]で観察[かんさつ]した。", "sentence_source": "generated"}, {"text": "先頭の走者がゴール地点を通過した瞬間、大きな歓声が上がった。", "target_word": "通過", "complexity_tier": "T3", "furigana": "先頭[せんとう]の走者[そうしゃ]がゴール地点[ちてん]を通過[つうか]した瞬間[しゅんかん]、大[おお]きな歓声[かんせい]が上[あ]がった。", "sentence_source": "generated"}, {"text": "低気圧が通過すると、空気が一気に冷たくなった。", "target_word": "通過", "complexity_tier": "T3", "furigana": "低気圧[ていきあつ]が通過[つうか]すると、空気[くうき]が一気[いっき]に冷[つめ]たくなった。", "sentence_source": "generated"}, {"text": "電車が踏切を通過するのを待って、道を渡った。", "target_word": "通過", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が踏切[ふみきり]を通過[つうか]するのを待[ま]って、道[みち]を渡[わた]った。", "sentence_source": "generated"}, {"text": "船は夜のうちに海峡を通過し、朝には外海に出ていた。", "target_word": "通過", "complexity_tier": "T3", "furigana": "船[ふね]は夜[よる]のうちに海峡[かいきょう]を通過[つうか]し、朝[あさ]には外海[そとうみ]に出[で]ていた。", "sentence_source": "generated"}, {"text": "光がガラスを通過するとき、少し曲がって進む。", "target_word": "通過", "complexity_tier": "T3", "furigana": "光[ひかり]がガラスを通過[つうか]するとき、少[すこ]し曲[ま]がって進[すす]む。", "sentence_source": "generated"}, {"text": "台風の通過後、川の水かさが急に増えた。", "target_word": "通過", "complexity_tier": "T3", "furigana": "台風[たいふう]の通過後[つうかご]、川[かわ]の水[みず]かさが急[きゅう]に増[ふ]えた。", "sentence_source": "generated"}, {"text": "特急が通過する間、ホームの黄色い線の内側で待った。", "target_word": "通過", "complexity_tier": "T3", "furigana": "特急[とっきゅう]が通過[つうか]する間[あいだ]、ホームの黄色[きいろ]い線[せん]の内側[うちがわ]で待[ま]った。", "sentence_source": "generated"}, {"text": "マラソンの先頭集団が十キロ地点を通過した。", "target_word": "通過", "complexity_tier": "T3", "furigana": "マラソンの先頭[せんとう]集団[しゅうだん]が十[じゅっ]キロ地点[ちてん]を通過[つうか]した。", "sentence_source": "generated"}, {"text": "人工衛星は毎日同じ時刻に空を通過する。", "target_word": "通過", "complexity_tier": "T3", "furigana": "人工[じんこう]衛星[えいせい]は毎日[まいにち]同[おな]じ時刻[じこく]に空[そら]を通過[つうか]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通過", "label": "基本形（名詞）"}, {"form": "通過する", "label": "辞書形"}, {"form": "通過し", "label": "連用形"}, {"form": "通過した", "label": "過去形"}], "register": "標準（中立）", "sense_fingerprint": "何かが一方から他方へ動いて通ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 外海 (Zipf 2.11)','sentence 6 above tier T2: contains vocabulary far above tier T2: 水かさ (Zipf 1.84)']::text[], '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36632, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消滅", "is_correct": false, "explanation": "消えてなくなる意味で、彗星が地球の近くを通る様子には合わない。"}, {"text": "誕生", "is_correct": false, "explanation": "生まれる意味で、ここでは文が成り立たない。"}, {"text": "通過", "is_correct": true, "explanation": "何かが一方の側から他方へ通ることを表し、彗星の動きに合う。"}, {"text": "膨張", "is_correct": false, "explanation": "大きくなる意味で、地球の近くを対象にできない。"}], "explanations": {"消滅": "消えてなくなる意味で、彗星が地球の近くを通る様子には合わない。", "誕生": "生まれる意味で、ここでは文が成り立たない。", "通過": "何かが一方の側から他方へ通ることを表し、彗星の動きに合う。", "膨張": "大きくなる意味で、地球の近くを対象にできない。"}, "sentence_index": 0, "correct_answer": "通過"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生に挨拶を通過してから、教室に入った。", "explanation": "ここは〈会釈する〉の意味。礼をして頭を下げることは会釈で、通過は通り抜けを表すので合わない。"}, {"text": "母は毎晩、鍋で料理を通過している。", "explanation": "ここは〈調理する〉の意味。食材に火を通して作ることは調理で、通過は通り抜けを表すので合わない。"}, {"text": "出席の点呼を通過してから、席についた。", "explanation": "ここは〈名簿を確かめる〉の意味。名前を呼んで確認する作業は、通り抜ける意味の通過には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36632, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停車", "is_correct": false, "explanation": "止まる意味で、台風の後の文には合わない。"}, {"text": "乗車", "is_correct": false, "explanation": "乗り込む意味で、台風を対象にできない。"}, {"text": "通過", "is_correct": true, "explanation": "台風が通り過ぎたことを表し、「通過後」の文に合う。"}, {"text": "出版", "is_correct": false, "explanation": "本を世に出す意味で、台風には使えない。"}], "explanations": {"停車": "止まる意味で、台風の後の文には合わない。", "乗車": "乗り込む意味で、台風を対象にできない。", "通過": "台風が通り過ぎたことを表し、「通過後」の文に合う。", "出版": "本を世に出す意味で、台風には使えない。"}, "sentence_index": 6, "correct_answer": "通過"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美術館で絵画を通過して、しばらく見入った。", "explanation": "ここは〈鑑賞〉の意味。絵画は味わうもので、通過は通り抜けを表すので合わない。"}, {"text": "バイオリンを通過して、曲を仕上げた。", "explanation": "ここは〈演奏〉の意味。楽器は弾くもので、通過は通り抜けを表すので合わない。"}, {"text": "ろうそくを通過して、部屋を明るくした。", "explanation": "ここは〈点火〉の意味。火をつけるのは点火で、通過は通り抜けを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36632, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボールがネットが通過した瞬間、会場がどよめいた。", "corrected_sentence": "ボールがネットを通過した瞬間、会場がどよめいた。", "error_description": "通過の対象（場所）は「を」で示す。「が」はネットを動く主語にしてしまい、ネットが通過するという不自然な意味になる。正しくは「ネットを通過した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36632, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ロケットは大気圏を通過されて、宇宙へ向かった。", "corrected_sentence": "ロケットは大気圏を通過して、宇宙へ向かった。", "error_description": "「通過される」は受身形で、動作を行うロケット自身が通り抜ける意味に合わない。能動の「通過して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36633, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "通り抜ける場所（駅）を示す目的語の「を」。"}, {"text": "が", "is_correct": false, "explanation": "「駅が通過して」では駅が動く主語になり、文の意味が合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では駅と何かを並べる意味になり、通り抜ける動作と合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象が必要で、ここでは成り立たない。"}], "correct_answer": "を", "explanations": {"を": "通り抜ける場所（駅）を示す目的語の「を」。", "が": "「駅が通過して」では駅が動く主語になり、文の意味が合わない。", "と": "並列の「と」では駅と何かを並べる意味になり、通り抜ける動作と合わない。", "より": "比較の「より」は比べる対象が必要で、ここでは成り立たない。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36633, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「通過には〜が必要」の形で、通過という事柄に対する条件を示す。"}, {"text": "を", "is_correct": false, "explanation": "「通過を」は目的語になり、必要な条件を示す文の形には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「通過で」は手段の意味になり、必要条件の文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は行き先に付くもので、必要条件の文には合わない。"}], "correct_answer": "に", "explanations": {"に": "「通過には〜が必要」の形で、通過という事柄に対する条件を示す。", "を": "「通過を」は目的語になり、必要な条件を示す文の形には合わない。", "で": "「通過で」は手段の意味になり、必要条件の文に合わない。", "へ": "方向の「へ」は行き先に付くもので、必要条件の文には合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36633, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある場所や物の中を通り抜けて向こう側へ行くこと。", "primary_collocate": null, "pronunciation": "つうか", "ipa": "tsɯːka", "syllable_count": 3, "sentences": [{"text": "その峠道の通過は、雪のため一時間遅れた。", "target_word": "通過", "complexity_tier": "T3", "furigana": "その峠道[とうげみち]の通過[つうか]は、雪[ゆき]のため一時間[いちじかん]遅[おく]れた。", "sentence_source": "generated"}, {"text": "特急列車は小さな駅を通過して、そのまま次の町へ向かった。", "target_word": "通過", "complexity_tier": "T3", "furigana": "特急[とっきゅう]列車[れっしゃ]は小[ちい]さな駅[えき]を通過[つうか]して、そのまま次[つぎ]の町[まち]へ向[む]かった。", "sentence_source": "generated"}, {"text": "台風は夕方に関東地方を通過し、夜には雨も弱まった。", "target_word": "通過", "complexity_tier": "T3", "furigana": "台風[たいふう]は夕方[ゆうがた]に関東[かんとう]地方[ちほう]を通過[つうか]し、夜[よる]には雨[あめ]も弱[よわ]まった。", "sentence_source": "generated"}, {"text": "荷物検査を通過してから、搭乗口へ急いだ。", "target_word": "通過", "complexity_tier": "T3", "furigana": "荷物[にもつ]検査[けんさ]を通過[つうか]してから、搭乗口[とうじょうぐち]へ急[いそ]いだ。", "sentence_source": "generated"}, {"text": "トラックがトンネルを通過するとき、大きな音が響いた。", "target_word": "通過", "complexity_tier": "T3", "furigana": "トラックがトンネルを通過[つうか]するとき、大[おお]きな音[おと]が響[ひび]いた。", "sentence_source": "generated"}, {"text": "この急行は各駅を通過するので、小さな駅では停まらない。", "target_word": "通過", "complexity_tier": "T3", "furigana": "この急行[きゅうこう]は各駅[かくえき]を通過[つうか]するので、小[ちい]さな駅[えき]では停[と]まらない。", "sentence_source": "generated"}, {"text": "高さ制限があるため、大型バスはこの橋の下を通過できない。", "target_word": "通過", "complexity_tier": "T3", "furigana": "高[たか]さ制限[せいげん]があるため、大型[おおがた]バスはこの橋[はし]の下[した]を通過[つうか]できない。", "sentence_source": "generated"}, {"text": "改札の通過には、切符かカードが必要だ。", "target_word": "通過", "complexity_tier": "T3", "furigana": "改札[かいさつ]の通過[つうか]には、切符[きっぷ]かカードが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "飛行機が上空を通過した直後、窓がかすかに震えた。", "target_word": "通過", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が上空[じょうくう]を通過[つうか]した直後[ちょくご]、窓[まど]がかすかに震[ふる]えた。", "sentence_source": "generated"}, {"text": "工事のため、この道路は車の通過が禁止されている。", "target_word": "通過", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、この道路[どうろ]は車[くるま]の通過[つうか]が禁止[きんし]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通過", "label": "基本形（名詞）"}, {"form": "通過する", "label": "辞書形"}, {"form": "通過し", "label": "連用形"}, {"form": "通過した", "label": "過去形"}], "register": "標準（中立）", "sense_fingerprint": "場所や物の中を通り抜けて向こうへ行くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34bf2d29-c04c-4dd8-9a30-a2a912b51307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36633, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消滅", "is_correct": false, "explanation": "消えてなくなる意味で、峠道の通過が遅れたという文には合わない。"}, {"text": "通過", "is_correct": true, "explanation": "峠道を通り抜けることを表し、雪で遅れたという文に合う。"}, {"text": "誕生", "is_correct": false, "explanation": "生まれる意味で、峠道の通過には合わない。"}, {"text": "膨張", "is_correct": false, "explanation": "大きくなる意味で、峠道の通過が遅れた文には合わない。"}], "explanations": {"消滅": "消えてなくなる意味で、峠道の通過が遅れたという文には合わない。", "通過": "峠道を通り抜けることを表し、雪で遅れたという文に合う。", "誕生": "生まれる意味で、峠道の通過には合わない。", "膨張": "大きくなる意味で、峠道の通過が遅れた文には合わない。"}, "sentence_index": 0, "correct_answer": "通過"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "注文した本を通過して、夕方に玄関まで届けた。", "explanation": "ここは〈配達〉の意味。届けるのは配達で、通過は通り抜けることなので合わない。"}, {"text": "代金を通過して、商品を受け取った。", "explanation": "ここは〈支払い〉の意味。代金は払うもので、通過は通り抜けを表すので合わない。"}, {"text": "手紙を通過してから、駅へ向かった。", "explanation": "ここは〈投函〉の意味。手紙は郵便箱に入れるもので、通過しても投函にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36633, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乗車", "is_correct": false, "explanation": "乗り込む動作で、橋の下を通り抜ける意味にはならない。"}, {"text": "発車", "is_correct": false, "explanation": "出発する動作で、橋の下を通り抜ける文には合わない。"}, {"text": "通過", "is_correct": true, "explanation": "橋の下を通り抜けることを表す。大型バスが通れないという文に合う。"}, {"text": "加速", "is_correct": false, "explanation": "速さを増す動作で、橋の下を通り抜ける意味にはならない。"}], "explanations": {"乗車": "乗り込む動作で、橋の下を通り抜ける意味にはならない。", "発車": "出発する動作で、橋の下を通り抜ける文には合わない。", "通過": "橋の下を通り抜けることを表す。大型バスが通れないという文に合う。", "加速": "速さを増す動作で、橋の下を通り抜ける意味にはならない。"}, "sentence_index": 6, "correct_answer": "通過"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓から海の景色を通過して、しばらく過ごした。", "explanation": "ここは〈眺める〉の意味。景色は見るもので、通過は通り抜けることなので合わない。"}, {"text": "ピアノを通過して、曲を仕上げた。", "explanation": "ここは〈演奏〉の意味。楽器は弾くもので、通過は通り抜けを表すので合わない。"}, {"text": "答案を通過して、結果を配った。", "explanation": "ここは〈採点〉の意味。答案に点をつけるのは採点で、通過は通り抜けを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36633, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風は夜のうちに四国を通過する、朝には晴れた。", "corrected_sentence": "台風は夜のうちに四国を通過し、朝には晴れた。", "error_description": "文を続けるには連用形「通過し」が要る。終止形「通過する」で読点を打つと文が切れ、後ろの「晴れた」とつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36633, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜行列車は深夜の小さな駅に通過する。", "corrected_sentence": "夜行列車は深夜の小さな駅を通過する。", "error_description": "通過の対象（場所）は「を」で示す。「に」は帰着点を表すので、通過する場所を示す文には合わない。正しくは「駅を通過する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f8b8280-f29e-4f7e-b2fc-ea52ff4ea335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36634, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "「過剰」の対義語。必要な量を超える過剰に対し、必要量に届かない状態を表す。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深い性質を表し、量の多さの反対とは言えないため合わない。"}, {"text": "冷静", "is_correct": false, "explanation": "感情の落ち着きを表し、量の多さの反対にはならないため合わない。"}, {"text": "平凡", "is_correct": false, "explanation": "特色がないことを表し、量の多さの対義語にはならないため合わない。"}], "correct_answer": "不足", "explanations": {"不足": "「過剰」の対義語。必要な量を超える過剰に対し、必要量に届かない状態を表す。", "慎重": "注意深い性質を表し、量の多さの反対とは言えないため合わない。", "冷静": "感情の落ち着きを表し、量の多さの反対にはならないため合わない。", "平凡": "特色がないことを表し、量の多さの対義語にはならないため合わない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36634, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "「過剰」の対義語。必要量より少ない状態を表し、期待が多すぎることの反対にもなる。"}, {"text": "誠実", "is_correct": false, "explanation": "人柄を表す語で、量の多さの反対とは言えないため合わない。"}, {"text": "頑固", "is_correct": false, "explanation": "考えを曲げない性質を表し、量の反対にはならないため合わない。"}, {"text": "愉快", "is_correct": false, "explanation": "気分の良さを表し、量の多さの対義語にはならないため合わない。"}], "correct_answer": "不足", "explanations": {"不足": "「過剰」の対義語。必要量より少ない状態を表し、期待が多すぎることの反対にもなる。", "誠実": "人柄を表す語で、量の多さの反対とは言えないため合わない。", "頑固": "考えを曲げない性質を表し、量の反対にはならないため合わない。", "愉快": "気分の良さを表し、量の多さの対義語にはならないため合わない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36634, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "「過剰」は、必要な量よりも多いことです。", "primary_collocate": null, "pronunciation": "かじょう", "ipa": "kaʑoː", "syllable_count": 3, "sentences": [{"text": "薬の過剰な服用は、体に害を与えます。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "薬[くすり]の過剰[かじょう]な服用[ふくよう]は、体[からだ]に害[がい]を与[あた]えます。", "sentence_source": "generated"}, {"text": "彼は小さな失敗を過剰に心配して、みんなに笑われた。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "彼は小さな失敗を過剰[かじょう]に心配して、みんなに笑われた。", "sentence_source": "generated"}, {"text": "この店は商品が過剰で、売れ残りが多い。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "この店[みせ]は商品[しょうひん]が過剰[かじょう]で、売[う]れ残[のこ]りが多[おお]い。", "sentence_source": "generated"}, {"text": "自信が過剰だと、失敗に気づきにくい。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "自信[じしん]が過剰[かじょう]だと、失敗[しっぱい]に気[き]づきにくい。", "sentence_source": "generated"}, {"text": "塩分の過剰がさまざまな病気の原因になる。", "target_word": "過剰", "complexity_tier": "T4", "furigana": "塩分[えんぶん]の過剰[かじょう]がさまざまな病気[びょうき]の原因[げんいん]になる。", "sentence_source": "generated"}, {"text": "過剰な包装を減らすことが、ごみ対策になる。", "target_word": "過剰", "complexity_tier": "T4", "furigana": "過剰[かじょう]な包装[ほうそう]を減[へ]らすことが、ごみ対策[たいさく]になる。", "sentence_source": "generated"}, {"text": "水をやりすぎると、過剰な水分で根がくさる。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "水[みず]をやりすぎると、過剰[かじょう]な水分[すいぶん]で根[ね]がくさる。", "sentence_source": "generated"}, {"text": "彼女の心配は過剰で、毎日何度も電話してくる。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の心配[しんぱい]は過剰[かじょう]で、毎日[まいにち]何度[なんど]も電話[でんわ]してくる。", "sentence_source": "generated"}, {"text": "生産が過剰になり、値段が大きく下がった。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "生産[せいさん]が過剰[かじょう]になり、値段[ねだん]が大[おお]きく下[さ]がった。", "sentence_source": "generated"}, {"text": "過剰な期待をかけられて、新人はつらそうだった。", "target_word": "過剰", "complexity_tier": "T3", "furigana": "過剰[かじょう]な期待[きたい]をかけられて、新人[しんじん]はつらそうだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過剰", "label": "基本形"}, {"form": "過剰な", "label": "連体形"}, {"form": "過剰に", "label": "連用形"}, {"form": "過剰だ", "label": "終止形"}], "register": "neutral", "sense_fingerprint": "必要な量や程度を超えて多すぎること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: くさる (Zipf 1.54)']::text[], '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36634, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過剰", "is_correct": true, "explanation": "必要な量を超えることを表し、「薬の〜な服用」で害が出る意味に合う。"}, {"text": "不安", "is_correct": false, "explanation": "気持ちの落ち着かなさを表し、薬の服用の量を表さないため合わない。"}, {"text": "欠乏", "is_correct": false, "explanation": "足りないことを表す名詞で、「欠乏な服用」とは言えず量の多さとも合わない。"}, {"text": "過去", "is_correct": false, "explanation": "時間の前を指す語で、薬の服用の量を表さないため合わない。"}], "explanations": {"過剰": "必要な量を超えることを表し、「薬の〜な服用」で害が出る意味に合う。", "不安": "気持ちの落ち着かなさを表し、薬の服用の量を表さないため合わない。", "欠乏": "足りないことを表す名詞で、「欠乏な服用」とは言えず量の多さとも合わない。", "過去": "時間の前を指す語で、薬の服用の量を表さないため合わない。"}, "sentence_index": 0, "correct_answer": "過剰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の過剰が原因で、荷物が届かなかった。", "explanation": "ここは〈過失〉の意味。不注意による誤りは過失で、多すぎることを表す過剰とは合わない。"}, {"text": "彼は過剰で入院した。", "explanation": "ここは〈過労〉の意味。働きすぎで体を壊すことは過労で、物の量が多い過剰とは言わない。"}, {"text": "ゴールまで過剰を残しておく。", "explanation": "ここは〈余力〉の意味。残しておく力は余力で、量が多すぎることを表す過剰とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36634, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過剰", "is_correct": true, "explanation": "必要量を超えることを表し、水のやりすぎで根がくさる原因に合う。"}, {"text": "過少", "is_correct": false, "explanation": "量が少なすぎることを表し、「やりすぎ」の流れに逆らうため合わない。"}, {"text": "微量", "is_correct": false, "explanation": "ごくわずかな量を表し、やりすぎの結果として根がくさることとは噛み合わない。"}, {"text": "軽度", "is_correct": false, "explanation": "程度が軽いことを表し、根をくさらせるほどの水分とは噛み合わない。"}], "explanations": {"過剰": "必要量を超えることを表し、水のやりすぎで根がくさる原因に合う。", "過少": "量が少なすぎることを表し、「やりすぎ」の流れに逆らうため合わない。", "微量": "ごくわずかな量を表し、やりすぎの結果として根がくさることとは噛み合わない。", "軽度": "程度が軽いことを表し、根をくさらせるほどの水分とは噛み合わない。"}, "sentence_index": 6, "correct_answer": "過剰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "違反者には過剰が科される。", "explanation": "ここは〈過料〉の意味。違反者に科される金銭罰は過料で、「過剰が科される」とは言わない。"}, {"text": "今はもう過剰のことだ。", "explanation": "ここは〈過去〉の意味。時間の前を指す過去とは違い、過剰は量の多さを表すので合わない。"}, {"text": "この村は過剰が進み、若い人が減っている。", "explanation": "ここは〈過疎〉の意味。人が少なくなって寂れることは過疎で、数や量が多すぎることを表す過剰とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36634, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "包装が過剰に来ると、ごみの量が増える。", "corrected_sentence": "包装が過剰になると、ごみの量が増える。", "error_description": "述語の誤り。「過剰に」は「なる」と組んで「過剰になる」の形で使う。「来る」は意味が通らず、不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36634, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水分を過剰になると、体のバランスが崩れることがある。", "corrected_sentence": "水分が過剰になると、体のバランスが崩れることがある。", "error_description": "助詞の誤り。「過剰になる」の主語は「水分が」で、「水分を」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
