INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36636, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「放散が悪い」の「が」。悪い状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す格で、「悪い」の主語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "帰着を示す格で、「放散」が主語になる位置に合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す格で、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「放散が悪い」の「が」。悪い状態の主語を示す。", "を": "対象を示す格で、「悪い」の主語にはならない。", "に": "帰着を示す格で、「放散」が主語になる位置に合わない。", "で": "手段を示す格で、主語にはならない。"}, "error_tags": {"を": "対象を示す格で、「悪い」の主語にはならない", "に": "帰着を示す格で、「放散」が主語になる位置に合わない", "で": "手段を示す格で、主語にはならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36636, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "熱を外に出すこと。", "primary_collocate": null, "pronunciation": "ほうさん", "ipa": "hoːsaɴ", "syllable_count": 4, "sentences": [{"text": "このパソコンは熱の放散がよく、長く使っても熱くならない。", "target_word": "放散", "complexity_tier": "T4", "furigana": "このパソコンは熱[ねつ]の放散[ほうさん]がよく、長[なが]く使[つか]っても熱[あつ]くならない。", "sentence_source": "generated"}, {"text": "金属の板は、熱を放散するために取り付けてある。", "target_word": "放散", "complexity_tier": "T4", "furigana": "金属[きんぞく]の板[いた]は、熱[ねつ]を放散[ほうさん]するために取[と]り付[つ]けてある。", "sentence_source": "generated"}, {"text": "夏は、汗をかくことで体の熱が放散される。", "target_word": "放散", "complexity_tier": "T4", "furigana": "夏[なつ]は、汗[あせ]をかくことで体[からだ]の熱[ねつ]が放散[ほうさん]される。", "sentence_source": "generated"}, {"text": "犬は舌を出して熱を放散する。", "target_word": "放散", "complexity_tier": "T3", "furigana": "犬[いぬ]は舌[した]を出[だ]して熱[ねつ]を放散[ほうさん]する。", "sentence_source": "generated"}, {"text": "部品が小さいと、熱が放散しにくい。", "target_word": "放散", "complexity_tier": "T3", "furigana": "部品[ぶひん]が小[ちい]さいと、熱[ねつ]が放散[ほうさん]しにくい。", "sentence_source": "generated"}, {"text": "冷却ファンは、機械の熱を外へ放散する役目がある。", "target_word": "放散", "complexity_tier": "T4", "furigana": "冷却[れいきゃく]ファンは、機械[きかい]の熱[ねつ]を外[そと]へ放散[ほうさん]する役目[やくめ]がある。", "sentence_source": "generated"}, {"text": "窓を開けると、部屋にこもった熱が放散される。", "target_word": "放散", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けると、部屋[へや]にこもった熱[ねつ]が放散[ほうさん]される。", "sentence_source": "generated"}, {"text": "熱の放散が悪いと、機械が故障しやすい。", "target_word": "放散", "complexity_tier": "T3", "furigana": "熱[ねつ]の放散[ほうさん]が悪[わる]いと、機械[きかい]が故障[こしょう]しやすい。", "sentence_source": "generated"}, {"text": "熱は、金属の管から外へ放散される。", "target_word": "放散", "complexity_tier": "T3", "furigana": "熱[ねつ]は、金属[きんぞく]の管[くだ]から外[そと]へ放散[ほうさん]される。", "sentence_source": "generated"}, {"text": "象は大きな耳から熱を放散して、体を冷やす。", "target_word": "放散", "complexity_tier": "T3", "furigana": "象[ぞう]は大[おお]きな耳[みみ]から熱[ねつ]を放散[ほうさん]して、体[からだ]を冷[ひ]やす。", "sentence_source": "generated"}], "morphological_forms": [{"form": "放散", "label": "基本形"}, {"form": "放散する", "label": "する動詞形"}, {"form": "放散される", "label": "受身形"}, {"form": "放散しにくい", "label": "難易形"}], "register": "formal", "sense_fingerprint": "体や機械にたまった熱を外へ逃がすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36636, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放散", "is_correct": true, "explanation": "熱を外へ逃がす意味を表し、「熱の〜がよい」という文に合う。"}, {"text": "振動", "is_correct": false, "explanation": "揺れを表す語で、熱の逃がし方を表さないため合わない。"}, {"text": "発光", "is_correct": false, "explanation": "光を出すことで、熱の放出の話には当てはまらないため合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "色の性質を表し、熱の性能とは結びつかないため合わない。"}], "explanations": {"放散": "熱を外へ逃がす意味を表し、「熱の〜がよい」という文に合う。", "振動": "揺れを表す語で、熱の逃がし方を表さないため合わない。", "発光": "光を出すことで、熱の放出の話には当てはまらないため合わない。", "色彩": "色の性質を表し、熱の性能とは結びつかないため合わない。"}, "sentence_index": 0, "correct_answer": "放散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大声で叫んで、気持ちを放散した。", "explanation": "ここは〈発散〉の意味。気持ちをはらすことは発散で、熱を外へ逃がす放散とは言わない。"}, {"text": "ダムの水を放散する。", "explanation": "ここは〈放出〉の意味。水を一気に流し出すのは放出で、熱を外へ逃がす放散とは合わない。"}, {"text": "荷物の重さを放散する。", "explanation": "ここは〈分散〉の意味。重さや仕事を分けるのは分散で、熱を外へ逃がす放散とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36636, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放散", "is_correct": true, "explanation": "熱を外へ逃がす意味を表し、「熱が〜される」という文に合う。"}, {"text": "凍結", "is_correct": false, "explanation": "液体が固まることを表し、熱を逃がす意味とは合わないため合わない。"}, {"text": "反転", "is_correct": false, "explanation": "向きが逆になることを表し、熱の行き先の話には合わないため合わない。"}, {"text": "粉砕", "is_correct": false, "explanation": "細かく砕くことを表し、熱には当てはまらないため合わない。"}], "explanations": {"放散": "熱を外へ逃がす意味を表し、「熱が〜される」という文に合う。", "凍結": "液体が固まることを表し、熱を逃がす意味とは合わないため合わない。", "反転": "向きが逆になることを表し、熱の行き先の話には合わないため合わない。", "粉砕": "細かく砕くことを表し、熱には当てはまらないため合わない。"}, "sentence_index": 6, "correct_answer": "放散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "そのニュースは一晩でネットに放散した。", "explanation": "ここは〈拡散〉の意味。情報が広く行き渡ることは拡散で、熱を外へ出す放散とは合わない。"}, {"text": "会社は放散した。", "explanation": "ここは〈解散〉の意味。組織をやめることは解散で、熱を外へ出す放散とは全く違う。"}, {"text": "休日は公園を放散して過ごす。", "explanation": "ここは〈散策〉の意味。ぶらぶら歩くことは散策で、熱を外へ逃がす放散とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36636, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熱の放散を受けるため、ファンで空気を回す。", "corrected_sentence": "熱の放散を促すため、ファンで空気を回す。", "error_description": "動詞の選択の誤り。「放散を促す」が正しく、「放散を受ける」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36636, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熱の放散を時間がかかる。", "corrected_sentence": "熱の放散に時間がかかる。", "error_description": "助詞の誤り。「〜に時間がかかる」の「に」が正しく、「を」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
