INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36637, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "熱やエネルギーなどを、周りに広く散らすこと。", "primary_collocate": null, "pronunciation": "ほうさん", "ipa": "hoːsaɴ", "syllable_count": 4, "sentences": [{"text": "太陽は、光と熱を宇宙へ放散している。", "target_word": "放散", "complexity_tier": "T4", "furigana": "太陽[たいよう]は、光[ひかり]と熱[ねつ]を宇宙[うちゅう]へ放散[ほうさん]している。", "sentence_source": "generated"}, {"text": "たき火は、周りに熱を放散して人々を温める。", "target_word": "放散", "complexity_tier": "T3", "furigana": "たき火[び]は、周[まわ]りに熱[ねつ]を放散[ほうさん]して人々[ひとびと]を温[あたた]める。", "sentence_source": "generated"}, {"text": "星は長い間、エネルギーを放散し続ける。", "target_word": "放散", "complexity_tier": "T4", "furigana": "星[ほし]は長[なが]い間[あいだ]、エネルギーを放散[ほうさん]し続[つづ]ける。", "sentence_source": "generated"}, {"text": "電球は電気の一部を光として放散する。", "target_word": "放散", "complexity_tier": "T4", "furigana": "電球[でんきゅう]は電気[でんき]の一部[いちぶ]を光[ひかり]として放散[ほうさん]する。", "sentence_source": "generated"}, {"text": "部屋の中心にあるストーブが熱を四方に放散した。", "target_word": "放散", "complexity_tier": "T4", "furigana": "部屋[へや]の中心[ちゅうしん]にあるストーブが熱[ねつ]を四方[しほう]に放散[ほうさん]した。", "sentence_source": "generated"}, {"text": "火山は、地下のエネルギーを煙や熱として放散する。", "target_word": "放散", "complexity_tier": "T4", "furigana": "火山[かざん]は、地下[ちか]のエネルギーを煙[けむり]や熱[ねつ]として放散[ほうさん]する。", "sentence_source": "generated"}, {"text": "この装置は、余ったエネルギーを周囲へ放散する仕組みになっている。", "target_word": "放散", "complexity_tier": "T3", "furigana": "この装置は、余[あま]ったエネルギーを周囲[しゅうい]へ放散[ほうさん]する仕組み[しくみ]になっている。", "sentence_source": "generated"}, {"text": "湯気とともに熱が空中に放散されていった。", "target_word": "放散", "complexity_tier": "T3", "furigana": "湯気[ゆげ]とともに熱[ねつ]が空中[くうちゅう]に放散[ほうさん]されていった。", "sentence_source": "generated"}, {"text": "花火は、一瞬で大きなエネルギーを夜空に放散する。", "target_word": "放散", "complexity_tier": "T4", "furigana": "花火[はなび]は、一瞬[いっしゅん]で大[おお]きなエネルギーを夜空[よぞら]に放散[ほうさん]する。", "sentence_source": "generated"}, {"text": "太陽の熱は地面にたまらず、空気中に放散される。", "target_word": "放散", "complexity_tier": "T4", "furigana": "太陽[たいよう]の熱[ねつ]は地面[じめん]にたまらず、空気中[くうきちゅう]に放散[ほうさん]される。", "sentence_source": "generated"}], "morphological_forms": [{"form": "放散", "label": "基本形"}, {"form": "放散する", "label": "する動詞形"}, {"form": "放散される", "label": "受身形"}, {"form": "放散させる", "label": "使役形"}], "register": "formal", "sense_fingerprint": "熱やエネルギーを周囲に広く散らすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36637, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放散", "is_correct": true, "explanation": "熱やエネルギーを周囲へ散らす意味を表し、太陽が宇宙へ放つ文に合う。"}, {"text": "凝縮", "is_correct": false, "explanation": "一か所に集まる意味で、宇宙へ広く散らす太陽の働きには合わない。"}, {"text": "固定", "is_correct": false, "explanation": "動かないように止める意味で、光や熱を広げる働きとは合わない。"}, {"text": "集合", "is_correct": false, "explanation": "集まる意味で、宇宙へ散らす動きとは合わない。"}], "explanations": {"放散": "熱やエネルギーを周囲へ散らす意味を表し、太陽が宇宙へ放つ文に合う。", "凝縮": "一か所に集まる意味で、宇宙へ広く散らす太陽の働きには合わない。", "固定": "動かないように止める意味で、光や熱を広げる働きとは合わない。", "集合": "集まる意味で、宇宙へ散らす動きとは合わない。"}, "sentence_index": 0, "correct_answer": "放散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "休日は公園をゆっくり放散して過ごす。", "explanation": "ここは〈散策〉の意味。ぶらぶら歩くことは散策で、熱やエネルギーを周囲へ散らす放散とは合わない。"}, {"text": "荷物の重さを放散して、負担を減らす。", "explanation": "ここは〈分散〉の意味。重さや仕事を分けることは分散で、エネルギーを外へ広く出す放散とは違う。"}, {"text": "会議が終わり、参加者は放散した。", "explanation": "ここは〈解散〉の意味。集まりをやめることは解散で、熱やエネルギーを出す放散とは全く違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36637, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放散", "is_correct": true, "explanation": "余ったエネルギーを周囲へ散らす意味を表し、「仕組み」の説明に合う。"}, {"text": "圧縮", "is_correct": false, "explanation": "体積を小さくする意味で、エネルギーを周囲へ出す仕組みとは合わない。"}, {"text": "点検", "is_correct": false, "explanation": "調べることを表し、エネルギーを出す仕組みには当てはまらない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける意味で、エネルギーの仕組みとは合わない。"}], "explanations": {"放散": "余ったエネルギーを周囲へ散らす意味を表し、「仕組み」の説明に合う。", "圧縮": "体積を小さくする意味で、エネルギーを周囲へ出す仕組みとは合わない。", "点検": "調べることを表し、エネルギーを出す仕組みには当てはまらない。", "施錠": "鍵をかける意味で、エネルギーの仕組みとは合わない。"}, "sentence_index": 6, "correct_answer": "放散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "うわさが町じゅうに放散した。", "explanation": "ここは〈拡散〉の意味。うわさや情報が広まることは拡散で、熱やエネルギーを外へ出す放散とは合わない。"}, {"text": "ストレスを放散して、気分を晴らす。", "explanation": "ここは〈発散〉の意味。不満や感情を外へ出して晴らすことは発散で、熱やエネルギーを周囲に散らす放散とは違う。"}, {"text": "戦争で家族が放散した。", "explanation": "ここは〈離散〉の意味。散り散りになることは離散で、エネルギーを出す放散とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36637, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ストーブは熱を四方へ放散される。", "corrected_sentence": "ストーブは熱を四方へ放散する。", "error_description": "態（voice）の誤り。主語「ストーブ」が熱を放つので能動の「放散する」が正しく、「放散される」は受身で不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36637, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "断熱材は熱の放散を勧める。", "corrected_sentence": "断熱材は熱の放散を防ぐ。", "error_description": "動詞の選択の誤り。断熱材は熱を外へ出さないよう「防ぐ」ので、「勧める」は意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36638, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「冷却に時間がかかる」の「に」で、時間がかかる対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の目的語に付く。「時間がかかる」には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表す。時間のかかる対象を示す文脈では使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す。「時間がかかる」とは結びつかない。"}], "correct_answer": "に", "explanations": {"に": "「冷却に時間がかかる」の「に」で、時間がかかる対象を示す。", "を": "「を」は動作の目的語に付く。「時間がかかる」には合わない。", "で": "「で」は手段や場所を表す。時間のかかる対象を示す文脈では使えない。", "へ": "「へ」は方向を表す。「時間がかかる」とは結びつかない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加熱", "is_correct": true, "explanation": "熱を加えて温度を上げること。冷却の対義語にあたる。"}, {"text": "包装", "is_correct": false, "explanation": "包んで整える作業で、温度の上げ下げに関わる対義語ではない。"}, {"text": "検査", "is_correct": false, "explanation": "品質を調べる作業で、温度の対義語ではない。"}, {"text": "販売", "is_correct": false, "explanation": "商品を売ること。冷却と対になる関係ではない。"}], "correct_answer": "加熱", "explanations": {"加熱": "熱を加えて温度を上げること。冷却の対義語にあたる。", "包装": "包んで整える作業で、温度の上げ下げに関わる対義語ではない。", "検査": "品質を調べる作業で、温度の対義語ではない。", "販売": "商品を売ること。冷却と対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36638, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「冷却すると」の「と」で、冷やした結果として新鮮なまま保てることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語に付く。「冷却する」の後の条件を示す位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や対象を示す。条件の意味にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。条件を表す位置には合わない。"}], "correct_answer": "と", "explanations": {"と": "「冷却すると」の「と」で、冷やした結果として新鮮なまま保てることを示す。", "を": "「を」は目的語に付く。「冷却する」の後の条件を示す位置には入らない。", "に": "「に」は方向や対象を示す。条件の意味にはならない。", "で": "「で」は手段や場所を示す。条件を表す位置には合わない。"}, "error_tags": {"を": "目的語", "に": "対象・方向", "で": "手段・場所"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加熱", "is_correct": true, "explanation": "熱を加えて温度を上げること。冷却の対義語にあたる。"}, {"text": "運搬", "is_correct": false, "explanation": "物を運ぶこと。温度の対義語ではない。"}, {"text": "放置", "is_correct": false, "explanation": "そのままにしておくこと。冷却と対になる関係ではない。"}, {"text": "出荷", "is_correct": false, "explanation": "商品を送り出すこと。温度の対義語ではない。"}], "correct_answer": "加熱", "explanations": {"加熱": "熱を加えて温度を上げること。冷却の対義語にあたる。", "運搬": "物を運ぶこと。温度の対義語ではない。", "放置": "そのままにしておくこと。冷却と対になる関係ではない。", "出荷": "商品を送り出すこと。温度の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36638, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "熱いものを冷やして温度を下げる行為のことです。", "primary_collocate": null, "pronunciation": "れいきゃく", "ipa": "reːkʲaku", "syllable_count": 4, "sentences": [{"text": "焼いたパンは、冷却してから袋に入れます。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "焼(や)いたパンは、冷却(れいきゃく)してから袋(ふくろ)に入(い)れます。", "sentence_source": "generated"}, {"text": "熱いスープは冷却に時間がかかるので、早めに作っておきます。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "熱(あつ)いスープは冷却(れいきゃく)に時間(じかん)がかかるので、早(はや)めに作(つく)っておきます。", "sentence_source": "generated"}, {"text": "急いでいるので、氷水でジュースを冷却しました。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "急(いそ)いでいるので、氷水(こおりみず)でジュースを冷却(れいきゃく)しました。", "sentence_source": "generated"}, {"text": "工場では、焼き上がったお菓子を冷却してから箱に詰めます。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "工場(こうじょう)では、焼(や)き上(あ)がったお菓子(かし)を冷却(れいきゃく)してから箱(はこ)に詰(つ)めます。", "sentence_source": "generated"}, {"text": "冷却が足りなかったため、ゼリーはうまく固まりませんでした。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "冷却(れいきゃく)が足(た)りなかったため、ゼリーはうまく固(かた)まりませんでした。", "sentence_source": "generated"}, {"text": "夏は、飲み物の冷却に冷凍庫をよく使います。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "夏(なつ)は、飲(の)み物(もの)の冷却(れいきゃく)に冷凍庫(れいとうこ)をよく使(つか)います。", "sentence_source": "generated"}, {"text": "実験のあと、熱い金属をゆっくり冷却しました。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "実験(じっけん)のあと、熱(あつ)い金属(きんぞく)をゆっくり冷却(れいきゃく)しました。", "sentence_source": "generated"}, {"text": "魚は急速に冷却すると、新鮮なまま保てます。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "魚(さかな)は急速(きゅうそく)に冷却(れいきゃく)すると、新鮮(しんせん)なまま保(たも)てます。", "sentence_source": "generated"}, {"text": "冷却の時間が短すぎて、中までは冷えていませんでした。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "冷却(れいきゃく)の時間(じかん)が短(みじか)すぎて、中(なか)までは冷(ひ)えていませんでした。", "sentence_source": "generated"}, {"text": "母は炊きたてのご飯を冷却してから、冷凍庫に入れました。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "母(はは)は炊(た)きたてのご飯(はん)を冷却(れいきゃく)してから、冷凍庫(れいとうこ)に入(い)れました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷却", "label": "基本形"}, {"form": "冷却する", "label": "サ変動詞形"}, {"form": "冷却した", "label": "過去形"}], "register": "中立（丁寧体）", "sense_fingerprint": "熱いものを冷やして温度を下げる行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36638, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "袋に入れる前に熱を取る作業という文脈で、熱いものの温度を下げる意味になる。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味。焼き上がったパンに火をつける工程は不自然で、冷ます文脈に合わない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつける意味。パンの扱いとしては成り立たない。"}, {"text": "解体", "is_correct": false, "explanation": "分解する意味。焼いたパンを分解してから袋に入れるとは言わない。"}], "explanations": {"冷却": "袋に入れる前に熱を取る作業という文脈で、熱いものの温度を下げる意味になる。", "点火": "火をつける意味。焼き上がったパンに火をつける工程は不自然で、冷ます文脈に合わない。", "点灯": "明かりをつける意味。パンの扱いとしては成り立たない。", "解体": "分解する意味。焼いたパンを分解してから袋に入れるとは言わない。"}, "sentence_index": 0, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達の失敗を見て、みんなで冷却しました。", "explanation": "〈冷やかす〉の場面です。人をからかうのは「冷やかす」と言い、「冷却」は物の温度を下げる行為に使うので、人をからかう意味では使えない。"}, {"text": "怒っている友達の頭を冷却するため、少し時間を置いた。", "explanation": "〈冷やす〉の場面です。人の頭や気持ちには「冷やす」を使い、「冷却」は機械や物を冷やす行為に使うので不自然。"}, {"text": "熱いスープをふうふう冷却して、ゆっくり飲んだ。", "explanation": "〈冷ます〉の場面です。息を吹きかけて食べ物の熱を逃がす動作には「冷ます」を使い、「冷却」は工業的な冷やし方に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36638, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "実験のあとに熱い金属の温度を下げる意味で、文脈に合う。"}, {"text": "点滅", "is_correct": false, "explanation": "光がついたり消えたりすること。金属には使えない。"}, {"text": "吸音", "is_correct": false, "explanation": "音を吸い込むこと。熱い金属の処理としては成り立たない。"}, {"text": "採光", "is_correct": false, "explanation": "光を取り入れること。金属を採光するとは言わない。"}], "explanations": {"冷却": "実験のあとに熱い金属の温度を下げる意味で、文脈に合う。", "点滅": "光がついたり消えたりすること。金属には使えない。", "吸音": "音を吸い込むこと。熱い金属の処理としては成り立たない。", "採光": "光を取り入れること。金属を採光するとは言わない。"}, "sentence_index": 6, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏は冷却をつけて、部屋を涼しくしています。", "explanation": "〈冷房〉の場面です。空調で部屋の空気を冷やすのは「冷房」で、「冷却」は物を冷やす行為を指すので電源を入れるものとしては使えない。"}, {"text": "スープが冷却してしまったので、温め直しました。", "explanation": "〈冷める〉の場面です。食べ物が自然に温度を下げるのは「冷める」で、「冷却」は人や機械が意図して冷やす行為に使う。"}, {"text": "原子炉では、水を冷却として使っています。", "explanation": "〈冷却材〉の場面です。冷却に使う物質は「冷却材」と言い、「冷却」は冷やす行為そのものを指すので物質には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36638, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな鍋は冷却を時間がかかるので、昼前に火を止めておきます。", "corrected_sentence": "大きな鍋は冷却に時間がかかるので、昼前に火を止めておきます。", "error_description": "誤: 冷却を時間がかかる / 正: 冷却に時間がかかる。「時間がかかる」は「〜に時間がかかる」の形で、対象には「に」を付ける。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36638, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熱くなった機械を冷却てから、電源を切ります。", "corrected_sentence": "熱くなった機械を冷却してから、電源を切ります。", "error_description": "誤: 冷却てから / 正: 冷却してから。「冷却する」は動詞で、「てから」の前は「冷却して」の形になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
