INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36639, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "function", "definition": "物の温度を下げるための機能や作用。", "primary_collocate": null, "pronunciation": "れいきゃく", "ipa": "reːkʲaku", "syllable_count": 4, "sentences": [{"text": "このパソコンは冷却の性能が高く、長く使っても熱くなりません。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "このパソコンは冷却(れいきゃく)の性能(せいのう)が高(たか)く、長(なが)く使(つか)っても熱(あつ)くなりません。", "sentence_source": "generated"}, {"text": "車のエンジンは、冷却がうまく働かないと止まってしまいます。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "車(くるま)のエンジンは、冷却(れいきゃく)がうまく働(はたら)かないと止(と)まってしまいます。", "sentence_source": "generated"}, {"text": "冷却の機能が壊れたため、機械が自動で止まりました。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "冷却(れいきゃく)の機能(きのう)が壊(こわ)れたため、機械(きかい)が自動(じどう)で止(と)まりました。", "sentence_source": "generated"}, {"text": "夏は冷却の効きが悪くなり、冷蔵庫の中がぬるくなりました。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "夏(なつ)は冷却(れいきゃく)の効(き)きが悪(わる)くなり、冷蔵庫(れいぞうこ)の中(なか)がぬるくなりました。", "sentence_source": "generated"}, {"text": "このゲーム機は冷却が弱くて、すぐに熱くなります。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "このゲーム機(き)は冷却(れいきゃく)が弱(よわ)くて、すぐに熱(あつ)くなります。", "sentence_source": "generated"}, {"text": "新しい型では、冷却の働きがさらに強くなりました。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "新(あたら)しい型(かた)では、冷却(れいきゃく)の働(はたら)きがさらに強(つよ)くなりました。", "sentence_source": "generated"}, {"text": "冷却が働いているあいだは、ファンの音が大きくなります。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "冷却(れいきゃく)が働(はたら)いているあいだは、ファンの音(おと)が大(おお)きくなります。", "sentence_source": "generated"}, {"text": "工場の機械には、冷却の仕組みが欠かせません。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "工場(こうじょう)の機械(きかい)には、冷却(れいきゃく)の仕組(しく)みが欠(か)かせません。", "sentence_source": "generated"}, {"text": "冷却に問題があったので、サーバーを一度止めました。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "冷却(れいきゃく)に問題(もんだい)があったので、サーバーを一度(いちど)止(と)めました。", "sentence_source": "generated"}, {"text": "熱を逃がす冷却のおかげで、部品が長持ちします。", "target_word": "冷却", "complexity_tier": "T3", "furigana": "熱(ねつ)を逃(に)がす冷却(れいきゃく)のおかげで、部品(ぶひん)が長持(ながも)ちします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷却", "label": "基本形"}, {"form": "冷却する", "label": "サ変動詞形"}, {"form": "冷却した", "label": "過去形"}], "register": "中立（丁寧体）", "sense_fingerprint": "機械などが熱を下げる機能・仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36639, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "機械が熱を下げる仕組みを指し、性能が高いという文脈に合う。"}, {"text": "点滅", "is_correct": false, "explanation": "光がついたり消えたりすること。パソコンの性能には合わない。"}, {"text": "解体", "is_correct": false, "explanation": "分解すること。性能の話には当てはまらない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつけること。熱を下げる性能を表す語ではない。"}], "explanations": {"冷却": "機械が熱を下げる仕組みを指し、性能が高いという文脈に合う。", "点滅": "光がついたり消えたりすること。パソコンの性能には合わない。", "解体": "分解すること。性能の話には当てはまらない。", "点火": "火をつけること。熱を下げる性能を表す語ではない。"}, "sentence_index": 0, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓を開けて冷却すると、部屋の空気が入れ替わります。", "explanation": "〈換気〉の場面です。空気を入れ替えるのは「換気」で、「冷却」は温度を下げる機能を指すので空気の入れ替えには使えない。"}, {"text": "彼の冷却した態度に、みんな戸惑いました。", "explanation": "〈冷ややか〉の場面です。人の態度を冷たく感じさせるのは「冷ややか」と言い、「冷却」は物の温度を下げる機能や作用を指すので態度には使えない。"}, {"text": "彼は冷却があり、怒りにくい人です。", "explanation": "〈落ち着き〉の場面です。人の性格には「落ち着き」を使い、「冷却」は機械や物の温度を下げる機能に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36639, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷却", "is_correct": true, "explanation": "冷却の働きが続くあいだファンの音が大きくなるという文脈に合う。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつけること。機械の働きとしては当てはまらない。"}, {"text": "解凍", "is_correct": false, "explanation": "凍ったものを溶かすこと。機械の働きには合わない。"}, {"text": "採光", "is_correct": false, "explanation": "光を取り入れること。ファンの音とは結びつかない。"}], "explanations": {"冷却": "冷却の働きが続くあいだファンの音が大きくなるという文脈に合う。", "点灯": "明かりをつけること。機械の働きとしては当てはまらない。", "解凍": "凍ったものを溶かすこと。機械の働きには合わない。", "採光": "光を取り入れること。ファンの音とは結びつかない。"}, "sentence_index": 6, "correct_answer": "冷却"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "換気扇は煙を外へ冷却します。", "explanation": "〈排気〉の場面です。煙を外へ出すのは「排気」で、「冷却」は温度を下げる機能に使うので煙を移す意味には合わない。"}, {"text": "扇風機から冷却が出てきて、部屋が涼しくなりました。", "explanation": "〈冷風〉の場面です。扇風機から出る涼しい風は「冷風」で、「冷却」は風のように出てくるものではない。"}, {"text": "この牛乳は冷却の機能で保存してください。", "explanation": "〈冷蔵〉の場面です。食品を冷やして保存するのは「冷蔵」と言い、「冷却」は温度を下げる機能や作用を指すので、保存の方法としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36639, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この機械は冷却を仕組みが強く、長時間の運転に向いています。", "corrected_sentence": "この機械は冷却の仕組みが強く、長時間の運転に向いています。", "error_description": "誤: 冷却を仕組み / 正: 冷却の仕組み。「仕組み」は名詞なので、「冷却」との関係は「の」で示す。「を」は動詞の目的語に使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36639, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この機械は冷却を弱いので、よく止まります。", "corrected_sentence": "この機械は冷却が弱いので、よく止まります。", "error_description": "誤: 冷却を弱い / 正: 冷却が弱い。「弱い」は冷却の状態を表すので、主語に「が」を付ける。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36640, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「雨音で覚醒した」の「で」。雨音がきっかけであることを示し、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「雨音が覚醒した」では雨音が目覚める主体になり、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "覚醒は目的語を取らないので、「雨音を覚醒した」は成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「雨音と覚醒した」は雨音も一緒に目覚めたという不自然な内容になる。"}], "correct_answer": "で", "explanations": {"で": "「雨音で覚醒した」の「で」。雨音がきっかけであることを示し、文に合う。", "が": "「雨音が覚醒した」では雨音が目覚める主体になり、意味が通らない。", "を": "覚醒は目的語を取らないので、「雨音を覚醒した」は成立しない。", "と": "「雨音と覚醒した」は雨音も一緒に目覚めたという不自然な内容になる。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36640, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36640, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ねむりからさめて、しっかりと目をさますこと。", "primary_collocate": null, "pronunciation": "かくせい", "ipa": "kakɯseː", "syllable_count": 4, "sentences": [{"text": "目覚まし時計が鳴っても、なかなか覚醒できなかった。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "目覚[めざ]まし時計[どけい]が鳴[な]っても、なかなか覚醒[かくせい]できなかった。", "sentence_source": "generated"}, {"text": "ぐっすり眠っていたが、窓を叩く雨音で覚醒した。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "ぐっすり眠[ねむ]っていたが、窓[まど]を叩[たた]く雨音[あまおと]で覚醒[かくせい]した。", "sentence_source": "generated"}, {"text": "麻酔から覚醒した患者は、すぐに家族の名前を呼んだ。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "麻酔[ますい]から覚醒[かくせい]した患者[かんじゃ]は、すぐに家族[かぞく]の名前[なまえ]を呼[よ]んだ。", "sentence_source": "generated"}, {"text": "朝のコーヒーを飲んでも、完全に覚醒するまで三十分かかる。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "朝[あさ]のコーヒーを飲[の]んでも、完全[かんぜん]に覚醒[かくせい]するまで三十分[さんじっぷん]かかる。", "sentence_source": "generated"}, {"text": "彼は深い眠りから覚醒し、ゆっくりと目を開けた。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "彼[かれ]は深[ふか]い眠[ねむ]りから覚醒[かくせい]し、ゆっくりと目[め]を開[あ]けた。", "sentence_source": "generated"}, {"text": "大きな物音で、私はベッドの中で突然覚醒した。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "大[おお]きな物音[ものおと]で、私[わたし]はベッドの中[なか]で突然[とつぜん]覚醒[かくせい]した。", "sentence_source": "generated"}, {"text": "覚醒したばかりの子どもは、まだ状況がわからず泣いていた。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "覚醒[かくせい]したばかりの子[こ]どもは、まだ状況[じょうきょう]がわからず泣[な]いていた。", "sentence_source": "generated"}, {"text": "夜中に何度も覚醒するので、朝になっても疲れが取れない。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "夜中[よなか]に何度[なんど]も覚醒[かくせい]するので、朝[あさ]になっても疲[つか]れが取[と]れない。", "sentence_source": "generated"}, {"text": "手術後、患者の覚醒を待ってから医師が説明した。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "手術後[しゅじゅつご]、患者[かんじゃ]の覚醒[かくせい]を待[ま]ってから医師[いし]が説明[せつめい]した。", "sentence_source": "generated"}, {"text": "窓から入る朝日を浴びると、体が自然に覚醒する。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "窓[まど]から入[はい]る朝日[あさひ]を浴[あ]びると、体[からだ]が自然[しぜん]に覚醒[かくせい]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覚醒する", "label": "辞書形"}, {"form": "覚醒した", "label": "過去形"}, {"form": "覚醒して", "label": "て形"}, {"form": "覚醒しない", "label": "否定形"}], "register": "neutral (plain form)", "sense_fingerprint": "眠りから完全に目を覚ます動作・変化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36640, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覚醒", "is_correct": true, "explanation": "「なかなか〜できなかった」に入り、目が覚めない状態を表す。ここでの正解。"}, {"text": "睡眠", "is_correct": false, "explanation": "睡眠は眠ること自体なので、「なかなか睡眠できなかった」では文が成り立たない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている時の呼吸音で、「寝息できなかった」は意味が通らない。"}, {"text": "夢見", "is_correct": false, "explanation": "夢見は夢を見ることを指し、「夢見できなかった」は文に合わない。"}], "explanations": {"覚醒": "「なかなか〜できなかった」に入り、目が覚めない状態を表す。ここでの正解。", "睡眠": "睡眠は眠ること自体なので、「なかなか睡眠できなかった」では文が成り立たない。", "寝息": "寝息は眠っている時の呼吸音で、「寝息できなかった」は意味が通らない。", "夢見": "夢見は夢を見ることを指し、「夢見できなかった」は文に合わない。"}, "sentence_index": 0, "correct_answer": "覚醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ベッドに入ると、彼はすぐに覚醒した。", "explanation": "ここは〈寝つく〉（眠りに入る）の意味。覚醒は眠りから目が覚めることなので、寝入る場面では使えない。"}, {"text": "社会の不正に覚醒し、彼は運動に加わった。", "explanation": "ここは〈悟る〉（真実に気づくこと）の意味。眠りから目を覚ます語義とは別で、この問題の正解の用法ではない。"}, {"text": "夜は、ぐっすり覚醒して朝まで休んだ。", "explanation": "ここは〈ぐっすり眠る〉（熟睡する）の意味。覚醒は眠りから目が覚めることなので、熟睡して休む状態とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36640, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覚醒", "is_correct": true, "explanation": "「覚醒したばかり」で目覚めた直後を表す。ここでの正解。"}, {"text": "寝床", "is_correct": false, "explanation": "寝床は寝るための場所で、「寝床したばかり」は文に合わない。"}, {"text": "寝相", "is_correct": false, "explanation": "寝相は寝ている時の姿勢で、「寝相したばかり」は成り立たない。"}, {"text": "目覚まし", "is_correct": false, "explanation": "目覚ましは目を覚まさせる道具や音で、「目覚ましたばかり」の形では使えない。"}], "explanations": {"覚醒": "「覚醒したばかり」で目覚めた直後を表す。ここでの正解。", "寝床": "寝床は寝るための場所で、「寝床したばかり」は文に合わない。", "寝相": "寝相は寝ている時の姿勢で、「寝相したばかり」は成り立たない。", "目覚まし": "目覚ましは目を覚まさせる道具や音で、「目覚ましたばかり」の形では使えない。"}, "sentence_index": 6, "correct_answer": "覚醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝ている間も、脳は覚醒して休まず働いている。", "explanation": "ここは眠っている間の場面に使っているが、覚醒は目が覚めている状態を指すので、睡眠中の脳の様子とは両立しない。"}, {"text": "雨の中でも試合をやり抜くと、彼は覚醒を決めた。", "explanation": "ここは〈覚悟〉（心を決めること）の意味。覚醒は目が覚めている状態で、決心を『決める』とは結べない。"}, {"text": "コーヒーで眠気を覚醒した。", "explanation": "ここは〈眠気を覚ます〉の意味。覚醒は自分が目覚める状態を指し、眠気を払う相手には他動詞の『覚ます』を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36640, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "麻酔に覚醒した患者は、すぐに水を求めた。", "corrected_sentence": "麻酔から覚醒した患者は、すぐに水を求めた。", "error_description": "麻酔からの覚醒（起点）は「から」で示す。「に」では覚醒の起点を表せず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36640, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は深い眠りに覚醒し、そっと目を開けた。", "corrected_sentence": "彼は深い眠りから覚醒し、そっと目を開けた。", "error_description": "眠りからの覚醒（起点）は「から」で示す。「に」では起点を表せず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36641, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「覚醒の度合い」の「の」。覚醒と度合いを結ぶ正しい形。"}, {"text": "が", "is_correct": false, "explanation": "「覚醒が度合い」では二つの名詞がつながらず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「覚醒を度合い」は目的語の形として成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「覚醒に度合い」は名詞同士の結び付けとして不自然。"}], "correct_answer": "の", "explanations": {"の": "「覚醒の度合い」の「の」。覚醒と度合いを結ぶ正しい形。", "が": "「覚醒が度合い」では二つの名詞がつながらず、文が成り立たない。", "を": "「覚醒を度合い」は目的語の形として成立しない。", "に": "「覚醒に度合い」は名詞同士の結び付けとして不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
