INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36641, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "意識がはっきりとしている状態になること。また、その状態。", "primary_collocate": null, "pronunciation": "かくせい", "ipa": "kakɯseː", "syllable_count": 4, "sentences": [{"text": "運転中は、意識が覚醒した状態を保つことが大切だ。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "運転中[うんてんちゅう]は、意識[いしき]が覚醒[かくせい]した状態[じょうたい]を保[たも]つことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "昼食後は眠くなりやすく、覚醒の度合いが下がる。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "昼食後[ちゅうしょくご]は眠[ねむ]くなりやすく、覚醒[かくせい]の度合[どあ]いが下[さ]がる。", "sentence_source": "generated"}, {"text": "脳波を調べると、被験者が覚醒しているかどうかがわかる。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "脳波[のうは]を調[しら]べると、被験者[ひけんしゃ]が覚醒[かくせい]しているかどうかがわかる。", "sentence_source": "generated"}, {"text": "緊張すると交感神経が働き、覚醒の水準が高まる。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "緊張[きんちょう]すると交感神経[こうかんしんけい]が働[はたら]き、覚醒[かくせい]の水準[すいじゅん]が高[たか]まる。", "sentence_source": "generated"}, {"text": "薬の影響で、覚醒が不十分なまま会議に出た。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "薬[くすり]の影響[えいきょう]で、覚醒[かくせい]が不十分[ふじゅうぶん]なまま会議[かいぎ]に出[で]た。", "sentence_source": "generated"}, {"text": "夜勤では、覚醒を保つために短い休憩を取る。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "夜勤[やきん]では、覚醒[かくせい]を保[たも]つために短[みじか]い休憩[きゅうけい]を取[と]る。", "sentence_source": "generated"}, {"text": "強い光は脳を刺激し、覚醒を促す。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "強[つよ]い光[ひかり]は脳[のう]を刺激[しげき]し、覚醒[かくせい]を促[うなが]す。", "sentence_source": "generated"}, {"text": "十分に覚醒していないと、危険な作業はできない。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]に覚醒[かくせい]していないと、危険[きけん]な作業[さぎょう]はできない。", "sentence_source": "generated"}, {"text": "試験前に覚醒が高まり、夜になっても眠れなかった。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "試験前[しけんまえ]に覚醒[かくせい]が高[たか]まり、夜[よる]になっても眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "医師は、患者の覚醒が続いていることを確認した。", "target_word": "覚醒", "complexity_tier": "T3", "furigana": "医師[いし]は、患者[かんじゃ]の覚醒[かくせい]が続[つづ]いていることを確認[かくにん]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覚醒する", "label": "辞書形"}, {"form": "覚醒した", "label": "過去形"}, {"form": "覚醒している", "label": "状態を表す形"}, {"form": "覚醒しない", "label": "否定形"}], "register": "neutral (plain form)", "sense_fingerprint": "意識が冴えてはっきりしている状態、またはその状態になること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36641, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覚醒", "is_correct": true, "explanation": "「意識が覚醒した状態」で、意識がはっきりした状態を表す。ここでの正解。"}, {"text": "睡眠", "is_correct": false, "explanation": "睡眠は眠ることなので、「意識が睡眠した」では意識の状態として成り立たない。"}, {"text": "熟睡", "is_correct": false, "explanation": "熟睡は深く眠ることで、「意識が熟睡した」は意味が通らない。"}, {"text": "仮眠", "is_correct": false, "explanation": "仮眠は短い睡眠を指し、「意識が仮眠した」は文に合わない。"}], "explanations": {"覚醒": "「意識が覚醒した状態」で、意識がはっきりした状態を表す。ここでの正解。", "睡眠": "睡眠は眠ることなので、「意識が睡眠した」では意識の状態として成り立たない。", "熟睡": "熟睡は深く眠ることで、「意識が熟睡した」は意味が通らない。", "仮眠": "仮眠は短い睡眠を指し、「意識が仮眠した」は文に合わない。"}, "sentence_index": 0, "correct_answer": "覚醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の説明は覚醒で、誰にでもわかりやすかった。", "explanation": "ここは〈明晰〉（筋道が通ってはっきりしていること）の意味。覚醒は人の意識の状態を指すので、説明の明快さには使わない。"}, {"text": "強い覚醒が襲ってきて、会議中に頭がぼんやりした。", "explanation": "覚醒は頭が冴えた状態を指すので、それが原因で頭がぼんやりするという内容は矛盾しており、眠気の意味ではない。"}, {"text": "試験中、彼は問題に覚醒して時間を忘れた。", "explanation": "ここは〈集中〉（一つのことに心を向けること）の意味。覚醒は意識が冴えた状態を指し、問題という対象に向ける働きは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36641, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覚醒", "is_correct": true, "explanation": "「覚醒を促す」で、意識を冴えさせることを表す。ここでの正解。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている時の呼吸音で、「寝息を促す」は意味が通らない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝床は寝る場所で、「寝床を促す」は文に合わない。"}, {"text": "熟睡", "is_correct": false, "explanation": "熟睡は深く眠ることで、強い光が促すものではないので、「熟睡を促す」は文に合わない。"}], "explanations": {"覚醒": "「覚醒を促す」で、意識を冴えさせることを表す。ここでの正解。", "寝息": "寝息は眠っている時の呼吸音で、「寝息を促す」は意味が通らない。", "寝床": "寝床は寝る場所で、「寝床を促す」は文に合わない。", "熟睡": "熟睡は深く眠ることで、強い光が促すものではないので、「熟睡を促す」は文に合わない。"}, "sentence_index": 6, "correct_answer": "覚醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疲れた彼は、ソファで覚醒に落ちた。", "explanation": "ここは〈眠りに落ちる〉の意味。覚醒は目が覚めている状態を指すので、眠りに落ちる場面には使わない。"}, {"text": "その景色の美しさは、彼の覚醒を一瞬で奪った。", "explanation": "ここは〈注意〉（気を向けること）の意味。覚醒は意識がはっきりした状態で、奪われるものとして注意の代わりには使わない。"}, {"text": "彼は、昼食後の覚醒に負けて、ぐっすり眠った。", "explanation": "覚醒は頭が冴えた状態で、それに負けて眠るという内容は矛盾する。眠気の意味で使っているわけではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36641, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昼寝の後は、覚醒に度合いが下がる。", "corrected_sentence": "昼寝の後は、覚醒の度合いが下がる。", "error_description": "「覚醒」と「度合い」は「の」で結ぶ。「に」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36641, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看護師は、患者の覚醒を続いていると報告した。", "corrected_sentence": "看護師は、患者の覚醒が続いていると報告した。", "error_description": "「覚醒が続く」の主語は「が」で示す。「を」では続く動作の主語にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36642, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「部屋の状態が悪かった」で、「状態」は「悪い」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「状態を悪かった」と目的語にすると、形容詞「悪い」の主語が成立せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「状態に悪かった」は、「に」を必要とする述語がなく文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「状態と悪かった」は並列の相手を表すが、主語の形にならず文意が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「部屋の状態が悪かった」で、「状態」は「悪い」の主語になる。", "を": "「状態を悪かった」と目的語にすると、形容詞「悪い」の主語が成立せず不自然。", "に": "「状態に悪かった」は、「に」を必要とする述語がなく文が成り立たない。", "と": "「状態と悪かった」は並列の相手を表すが、主語の形にならず文意が通らない。"}, "error_tags": {"を": "対象", "に": "場所・結果", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36642, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「疲れた状態で会議に出た」は、ある状態のもとでの行動を表す。"}, {"text": "が", "is_correct": false, "explanation": "「状態が会議に出た」では状態が出席の主体になり、文意が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「状態へ会議に出た」は方向を表すが、「状態」は行き先になる場所ではないので不自然。"}, {"text": "より", "is_correct": false, "explanation": "「状態より会議に出た」は比べる意味にならず、文意が通らない。"}], "correct_answer": "で", "explanations": {"で": "正解。「疲れた状態で会議に出た」は、ある状態のもとでの行動を表す。", "が": "「状態が会議に出た」では状態が出席の主体になり、文意が成り立たない。", "へ": "「状態へ会議に出た」は方向を表すが、「状態」は行き先になる場所ではないので不自然。", "より": "「状態より会議に出た」は比べる意味にならず、文意が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36642, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事のありさまや様子のことです。", "primary_collocate": null, "pronunciation": "じょうたい", "ipa": "dʑoːtai", "syllable_count": 4, "sentences": [{"text": "病人の状態が少しずつ良くなってきた。", "target_word": "状態", "complexity_tier": "T3", "furigana": "病人[びょうにん]の状態[じょうたい]が少[すこ]しずつ良[よ]くなってきた。", "sentence_source": "generated"}, {"text": "部屋の状態が悪かったので、すぐに掃除を始めた。", "target_word": "状態", "complexity_tier": "T3", "furigana": "部屋[へや]の状態[じょうたい]が悪[わる]かったので、すぐに掃除[そうじ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "雪のせいで、道路は走れない状態になった。", "target_word": "状態", "complexity_tier": "T3", "furigana": "雪[ゆき]のせいで、道路[どうろ]は走[はし]れない状態[じょうたい]になった。", "sentence_source": "generated"}, {"text": "この車は古いが、状態はとてもいい。", "target_word": "状態", "complexity_tier": "T3", "furigana": "この車[くるま]は古[ふる]いが、状態[じょうたい]はとてもいい。", "sentence_source": "generated"}, {"text": "試合の前に、体の状態をよく確かめた。", "target_word": "状態", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、体[からだ]の状態[じょうたい]をよく確[たし]かめた。", "sentence_source": "generated"}, {"text": "川の水が汚れた状態では、魚は住めない。", "target_word": "状態", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が汚[よご]れた状態[じょうたい]では、魚[さかな]は住[す]めない。", "sentence_source": "generated"}, {"text": "話し合いは、まだ決まらない状態が続いている。", "target_word": "状態", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いは、まだ決[き]まらない状態[じょうたい]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "彼は疲れた状態で会議に出たので、話をよく聞いていなかった。", "target_word": "状態", "complexity_tier": "T3", "furigana": "彼[かれ]は疲[つか]れた状態[じょうたい]で会議[かいぎ]に出[で]たので、話[はなし]をよく聞[き]いていなかった。", "sentence_source": "generated"}, {"text": "本は新品に近い状態で、傷はほとんどなかった。", "target_word": "状態", "complexity_tier": "T3", "furigana": "本[ほん]は新品[しんぴん]に近[ちか]い状態[じょうたい]で、傷[きず]はほとんどなかった。", "sentence_source": "generated"}, {"text": "畑の土の状態を見て、種をまく日を決めた。", "target_word": "状態", "complexity_tier": "T3", "furigana": "畑[はたけ]の土[つち]の状態[じょうたい]を見[み]て、種[たね]をまく日[ひ]を決[き]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "状態", "label": "基本形"}, {"form": "状態の", "label": "連体形"}, {"form": "状態で", "label": "で格"}, {"form": "状態に", "label": "に格"}], "register": "neutral", "sense_fingerprint": "物や人の、その時のありさま・様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36642, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "状態", "is_correct": true, "explanation": "正解。「病人の状態」は体調や病気の進みぐあいを表し、「良くなる」の主語として自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を指すので、病人の体調の変化には使えない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の区分で、病人が良くなる主語にはならない。"}, {"text": "理由", "is_correct": false, "explanation": "理由は原因を表すので、「良くなってきた」の主語にはならない。"}], "explanations": {"状態": "正解。「病人の状態」は体調や病気の進みぐあいを表し、「良くなる」の主語として自然。", "天気": "天気は空模様を指すので、病人の体調の変化には使えない。", "季節": "季節は一年の区分で、病人が良くなる主語にはならない。", "理由": "理由は原因を表すので、「良くなってきた」の主語にはならない。"}, "sentence_index": 0, "correct_answer": "状態"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布は色の状態が鮮やかで、夏に人気がある。", "explanation": "ここは〈色合い〉の意味。色の具合は色合いで、〈状態〉では色の出来ばえを表せないので合わない。"}, {"text": "彼女は状態が明るくて、みんなに好かれる。", "explanation": "ここは〈性格〉の意味。明るい人柄は性格で、〈状態〉は物事の今のありさまを指すので人の性格には合わない。"}, {"text": "今年の目標は、英語の状態を上げることだ。", "explanation": "ここは〈能力〉の意味。英語の力を上げるなら〈能力〉か〈力〉を使い、〈状態〉では英語の出来ばえを表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36642, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "状態", "is_correct": true, "explanation": "正解。「決まらない状態」は進まない話し合いのありさまを表し、「続いている」ともなじむ。"}, {"text": "声", "is_correct": false, "explanation": "声は音を指すので、「決まらない」と結びつかず、話し合いの様子としても成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "色は物の見た目で、話し合いの進まない様子は表せない。"}, {"text": "味", "is_correct": false, "explanation": "味は食べ物の性質で、話し合いの様子には使えない。"}], "explanations": {"状態": "正解。「決まらない状態」は進まない話し合いのありさまを表し、「続いている」ともなじむ。", "声": "声は音を指すので、「決まらない」と結びつかず、話し合いの様子としても成り立たない。", "色": "色は物の見た目で、話し合いの進まない様子は表せない。", "味": "味は食べ物の性質で、話し合いの様子には使えない。"}, "sentence_index": 6, "correct_answer": "状態"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "料理は三つの状態に分けて、順番に作ると失敗しにくい。", "explanation": "ここは〈段階〉の意味。作業を区切る順序は段階で、物事のありさまを指す〈状態〉では表せない。"}, {"text": "彼は試験の状態が高くて、クラスで一番だった。", "explanation": "ここは〈点数〉の意味。試験の出来は点数で表すので、〈状態〉を当てると不自然。"}, {"text": "この箱は四角い状態をしていて、棚にぴったり入る。", "explanation": "ここは〈形〉の意味。四角い輪郭は形で、〈状態〉は今のありさまを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36642, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の状態を整っていたので、水やりを休んだ。", "corrected_sentence": "庭の状態が整っていたので、水やりを休んだ。", "error_description": "「状態」に続く格助詞の誤り。「整う」は自動詞で、その主語には「が」を使う。「を」は誤りで、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36642, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "結論が出ない状態が続けている。", "corrected_sentence": "結論が出ない状態が続いている。", "error_description": "「状態」に係る動詞の誤り。「続く」は自動詞なので「続いている」が正しく、他動詞の「続けている」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36643, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「電源を切った状態で」は、部品を取り替える際の条件を表す。"}, {"text": "に", "is_correct": false, "explanation": "「電源を切った状態に部品を取り替える」は条件の格助詞として合わず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「状態と部品を取り替える」は並列にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「状態より部品を取り替える」は比較の意味にならず、不自然。"}], "correct_answer": "で", "explanations": {"で": "正解。「電源を切った状態で」は、部品を取り替える際の条件を表す。", "に": "「電源を切った状態に部品を取り替える」は条件の格助詞として合わず、不自然。", "と": "「状態と部品を取り替える」は並列にならず、文が成り立たない。", "より": "「状態より部品を取り替える」は比較の意味にならず、不自然。"}, "error_tags": {"に": "場所・結果", "と": "相手・並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36643, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「水が出ない状態が二日間続いた」で、「状態」が続く主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「状態を二日間続いた」は、「続く」が目的語を取らないので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「状態の二日間続いた」では、続く主語が成立せず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「状態へ二日間続いた」は方向を表すが、「続く」と結びつかず不自然。"}], "correct_answer": "が", "explanations": {"が": "正解。「水が出ない状態が二日間続いた」で、「状態」が続く主語になる。", "を": "「状態を二日間続いた」は、「続く」が目的語を取らないので不自然。", "の": "「状態の二日間続いた」では、続く主語が成立せず文が成り立たない。", "へ": "「状態へ二日間続いた」は方向を表すが、「続く」と結びつかず不自然。"}, "error_tags": {"を": "対象", "の": "所属・修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36643, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の状態や状況を指す言葉。ある時点での様子や、どのような条件にあるかを表す。", "primary_collocate": null, "pronunciation": "じょうたい", "ipa": "dʑoːtai", "syllable_count": 4, "sentences": [{"text": "今の状態では、旅行に行くのは難しい。", "target_word": "状態", "complexity_tier": "T3", "furigana": "今[いま]の状態[じょうたい]では、旅行[りょこう]に行[い]くのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "電源を切った状態で部品を取り替える決まりだ。", "target_word": "状態", "complexity_tier": "T3", "furigana": "電源[でんげん]を切[き]った状態[じょうたい]で部品[ぶひん]を取[と]り替[か]える決[き]まりだ。", "sentence_source": "generated"}, {"text": "景気がよくない状態が三年も続いている。", "target_word": "状態", "complexity_tier": "T3", "furigana": "景気[けいき]がよくない状態[じょうたい]が三年[さんねん]も続[つづ]いている。", "sentence_source": "generated"}, {"text": "パソコンは、動かない状態のまま机の上に置かれていた。", "target_word": "状態", "complexity_tier": "T3", "furigana": "パソコンは、動[うご]かない状態[じょうたい]のまま机[つくえ]の上[うえ]に置[お]かれていた。", "sentence_source": "generated"}, {"text": "彼女は落ち着いた状態で、試験に臨んだ。", "target_word": "状態", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は落[お]ち着[つ]いた状態[じょうたい]で、試験[しけん]に臨[のぞ]んだ。", "sentence_source": "generated"}, {"text": "この薬は、空腹の状態で飲んではいけない。", "target_word": "状態", "complexity_tier": "T3", "furigana": "この薬[くすり]は、空腹[くうふく]の状態[じょうたい]で飲[の]んではいけない。", "sentence_source": "generated"}, {"text": "ドアが開いた状態では、機械は動かない。", "target_word": "状態", "complexity_tier": "T3", "furigana": "ドアが開[あ]いた状態[じょうたい]では、機械[きかい]は動[うご]かない。", "sentence_source": "generated"}, {"text": "町は、水が出ない状態が二日間続いた。", "target_word": "状態", "complexity_tier": "T3", "furigana": "町[まち]は、水[みず]が出[で]ない状態[じょうたい]が二日間[ふつかかん]続[つづ]いた。", "sentence_source": "generated"}, {"text": "眠い状態で運転すると、事故が起こりやすい。", "target_word": "状態", "complexity_tier": "T3", "furigana": "眠[ねむ]い状態[じょうたい]で運転[うんてん]すると、事故[じこ]が起[お]こりやすい。", "sentence_source": "generated"}, {"text": "先生は、生徒が理解していない状態に気づいて、説明をやり直した。", "target_word": "状態", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]が理解[りかい]していない状態[じょうたい]に気[き]づいて、説明[せつめい]をやり直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "状態", "label": "基本形"}, {"form": "状態の", "label": "連体形"}, {"form": "状態で", "label": "で格"}, {"form": "状態が", "label": "が格"}], "register": "neutral", "sense_fingerprint": "ある時点・条件のもとでの状況", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36643, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "状態", "is_correct": true, "explanation": "正解。「今の状態では」は現在の条件を表し、旅行の可否の前提として自然。"}, {"text": "感想", "is_correct": false, "explanation": "「今の感想では」とすると、旅行が難しい理由にならず不自然。"}, {"text": "味", "is_correct": false, "explanation": "「今の味では」は旅行の条件として意味が通らず、文が成り立たない。"}, {"text": "単位", "is_correct": false, "explanation": "「今の単位では」は旅行の条件として意味が通らない。"}], "explanations": {"状態": "正解。「今の状態では」は現在の条件を表し、旅行の可否の前提として自然。", "感想": "「今の感想では」とすると、旅行が難しい理由にならず不自然。", "味": "「今の味では」は旅行の条件として意味が通らず、文が成り立たない。", "単位": "「今の単位では」は旅行の条件として意味が通らない。"}, "sentence_index": 0, "correct_answer": "状態"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は会社で今の状態が強いので、方針に口を出せる。", "explanation": "ここは〈立場〉の意味。会社での地位の強さは立場で、〈状態〉は物事の今のありさまを指すので合わない。"}, {"text": "この掃除機は吸い込む状態が強く、ゴミがすぐ取れる。", "explanation": "ここは〈性能〉の意味。吸引力の強さは性能で、〈状態〉は物の今の様子を指すので性能の説明には合わない。"}, {"text": "勉強は初級、中級、上級の状態に分かれている。", "explanation": "ここは〈段階〉の意味。学習の進みぐあいの区切りは段階で、〈状態〉では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36643, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "状態", "is_correct": true, "explanation": "正解。「ドアが開いた状態では」は、機械が動かない条件を表す。"}, {"text": "名前", "is_correct": false, "explanation": "「ドアが開いた名前では」は意味が通らず、条件として成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "「ドアが開いた色では」は条件として成り立たず、文意が通らない。"}, {"text": "値段", "is_correct": false, "explanation": "「ドアが開いた値段では」は機械の動作と関係がなく、文意が通らない。"}], "explanations": {"状態": "正解。「ドアが開いた状態では」は、機械が動かない条件を表す。", "名前": "「ドアが開いた名前では」は意味が通らず、条件として成り立たない。", "色": "「ドアが開いた色では」は条件として成り立たず、文意が通らない。", "値段": "「ドアが開いた値段では」は機械の動作と関係がなく、文意が通らない。"}, "sentence_index": 6, "correct_answer": "状態"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "提出の状態は明日の午後までなので、早めに出してください。", "explanation": "ここは〈期限〉の意味。提出を締め切る時刻は期限で、〈状態〉は物事のありさまを指すので合わない。"}, {"text": "列で私の状態は三番目だった。", "explanation": "ここは〈順番〉の意味。列の中で何番目かは順番で、〈状態〉はそれを表せないので合わない。"}, {"text": "宿題の状態が合っているか、先生に聞いた。", "explanation": "ここは〈答え〉の意味。問題の正誤は答えで、「合う」と結びつくのは答えであり、〈状態〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
