INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36644, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "起きること。ベッドから出ること。", "primary_collocate": null, "pronunciation": "きしょう", "ipa": "kiɕoː", "syllable_count": 3, "sentences": [{"text": "平日の起床は、毎朝六時と決めている。", "target_word": "起床", "complexity_tier": "T3", "furigana": "平日[へいじつ]の起床[きしょう]は、毎朝[まいあさ]六時[ろくじ]と決[き]めている。", "sentence_source": "generated"}, {"text": "起床が遅れたせいで、電車に乗り遅れた。", "target_word": "起床", "complexity_tier": "T3", "furigana": "起床[きしょう]が遅[おく]れたせいで、電車[でんしゃ]に乗[の]り遅[おく]れた。", "sentence_source": "generated"}, {"text": "合宿では、七時に起床して全員で朝食をとる。", "target_word": "起床", "complexity_tier": "T3", "furigana": "合宿[がっしゅく]では、七時[しちじ]に起床[きしょう]して全員[ぜんいん]で朝食[ちょうしょく]をとる。", "sentence_source": "generated"}, {"text": "兄は起床してすぐ、顔を洗いに行った。", "target_word": "起床", "complexity_tier": "T3", "furigana": "兄[あに]は起床[きしょう]してすぐ、顔[かお]を洗[あら]いに行[い]った。", "sentence_source": "generated"}, {"text": "寒い冬の朝は、起床するのがつらい。", "target_word": "起床", "complexity_tier": "T3", "furigana": "寒[さむ]い冬[ふゆ]の朝[あさ]は、起床[きしょう]するのがつらい。", "sentence_source": "generated"}, {"text": "早く起床すれば、朝の散歩ができる。", "target_word": "起床", "complexity_tier": "T3", "furigana": "早[はや]く起床[きしょう]すれば、朝[あさ]の散歩[さんぽ]ができる。", "sentence_source": "generated"}, {"text": "休日は起床が遅く、朝食を食べないことが多い。", "target_word": "起床", "complexity_tier": "T3", "furigana": "休日[きゅうじつ]は起床[きしょう]が遅[おそ]く、朝食[ちょうしょく]を食[た]べないことが多[おお]い。", "sentence_source": "generated"}, {"text": "祖父は毎日、日の出とともに起床する。", "target_word": "起床", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎日[まいにち]、日[ひ]の出[で]とともに起床[きしょう]する。", "sentence_source": "generated"}, {"text": "起床の合図で、子どもたちは一斉にベッドから出た。", "target_word": "起床", "complexity_tier": "T3", "furigana": "起床[きしょう]の合図[あいず]で、子[こ]どもたちは一斉[いっせい]にベッドから出[で]た。", "sentence_source": "generated"}, {"text": "病院では、患者の起床は午前六時と決まっている。", "target_word": "起床", "complexity_tier": "T3", "furigana": "病院[びょういん]では、患者[かんじゃ]の起床[きしょう]は午前[ごぜん]六時[ろくじ]と決[き]まっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "起床する", "label": "辞書形"}, {"form": "起床した", "label": "過去形"}, {"form": "起床して", "label": "て形"}, {"form": "起床しない", "label": "否定形"}], "register": "neutral (plain form)", "sense_fingerprint": "朝、寝床から起きて出る動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36644, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起床", "is_correct": true, "explanation": "「起床は、毎朝六時と決めている」で、朝に起きる時刻を表す。ここでの正解。"}, {"text": "寝返り", "is_correct": false, "explanation": "寝返りは寝ている間に体の向きを変えることで、「寝返りは毎朝六時と決めている」は不自然。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている時の呼吸音で、時刻を決める対象にならない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝床は寝る場所で、「寝床は毎朝六時と決めている」は意味が通らない。"}], "explanations": {"起床": "「起床は、毎朝六時と決めている」で、朝に起きる時刻を表す。ここでの正解。", "寝返り": "寝返りは寝ている間に体の向きを変えることで、「寝返りは毎朝六時と決めている」は不自然。", "寝息": "寝息は眠っている時の呼吸音で、時刻を決める対象にならない。", "寝床": "寝床は寝る場所で、「寝床は毎朝六時と決めている」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "起床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "監督は若手選手を起床した。", "explanation": "ここは〈起用〉（人を選んで用いること）の意味。起床は寝床から起きることで、人を任命して用いる場面には使わない。"}, {"text": "授業が始まると、生徒は全員起床した。", "explanation": "ここは〈起立〉（椅子から立つ）の意味。起床はベッドから起きることで、教室で立つ動作には使わない。"}, {"text": "夜中に大きな事件が起床した。", "explanation": "ここは〈発生〉（事件が起こること）の意味。起床は人が寝床から起きることで、事件には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36644, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起床", "is_correct": true, "explanation": "「休日は起床が遅く」で、朝に起きる時刻が遅いことを表す。ここでの正解。"}, {"text": "寝相", "is_correct": false, "explanation": "寝相は寝ている時の姿勢で、「寝相が遅く」は意味が通らない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は寝ながら話す言葉で、「寝言が遅く」は文に合わない。"}, {"text": "寝室", "is_correct": false, "explanation": "寝室は寝る部屋で、「寝室が遅く」は成り立たない。"}], "explanations": {"起床": "「休日は起床が遅く」で、朝に起きる時刻が遅いことを表す。ここでの正解。", "寝相": "寝相は寝ている時の姿勢で、「寝相が遅く」は意味が通らない。", "寝言": "寝言は寝ながら話す言葉で、「寝言が遅く」は文に合わない。", "寝室": "寝室は寝る部屋で、「寝室が遅く」は成り立たない。"}, "sentence_index": 6, "correct_answer": "起床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大学を出て、すぐに事業を起床した。", "explanation": "ここは〈起業〉（事業を始めること）の意味。起床は朝に寝床から起きることで、事業を始める行為には使わない。"}, {"text": "祖父は毎朝、散歩に起床する。", "explanation": "ここは〈外出〉（家から出ること）の意味。起床は寝床から起きる動作で、家の外へ出る行為とは結びつかない。"}, {"text": "仕事の帰りに、彼は書店に起床し、本を買った。", "explanation": "ここは〈立ち寄る〉の意味。起床は寝床から起きることで、店に寄る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36644, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今朝は起床を遅れて、電車に乗り遅れた。", "corrected_sentence": "今朝は起床が遅れて、電車に乗り遅れた。", "error_description": "「起床が遅れる」の主語は「が」で示す。「を」では遅れるの主語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36644, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "休日は、起床を遅くなりがちだ。", "corrected_sentence": "休日は、起床が遅くなりがちだ。", "error_description": "「起床が遅くなる」の主語は「が」で示す。「を」では遅くなる主体にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36645, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「四時に起床して」の「に」。時刻を表し、起床の時点を示す正しい形。"}, {"text": "を", "is_correct": false, "explanation": "「四時を起床して」は時刻を目的語にできず、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「四時が起床して」は主語として意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「四時と起床して」は並列の意味になり、文に合わない。"}], "correct_answer": "に", "explanations": {"に": "「四時に起床して」の「に」。時刻を表し、起床の時点を示す正しい形。", "を": "「四時を起床して」は時刻を目的語にできず、不自然。", "が": "「四時が起床して」は主語として意味が通らない。", "と": "「四時と起床して」は並列の意味になり、文に合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "就寝", "is_correct": true, "explanation": "起床の対義語。寝床に入って眠りにつくことを表す。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩いて出かけることで、起床の対義語ではない。"}, {"text": "通勤", "is_correct": false, "explanation": "通勤は職場へ通うことで、起床の対義語ではない。"}, {"text": "食事", "is_correct": false, "explanation": "食事は物を食べることで、起床の対義語ではない。"}], "correct_answer": "就寝", "explanations": {"就寝": "起床の対義語。寝床に入って眠りにつくことを表す。", "散歩": "散歩は歩いて出かけることで、起床の対義語ではない。", "通勤": "通勤は職場へ通うことで、起床の対義語ではない。", "食事": "食事は物を食べることで、起床の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
