INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36645, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "眠っていた状態から、体を起こして活動を始めること。", "primary_collocate": null, "pronunciation": "きしょう", "ipa": "kiɕoː", "syllable_count": 3, "sentences": [{"text": "兵士たちは夜明け前に起床し、訓練を始めた。", "target_word": "起床", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは夜明[よあ]け前[まえ]に起床[きしょう]し、訓練[くんれん]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "農家の朝は早く、四時に起床して畑へ向かう。", "target_word": "起床", "complexity_tier": "T3", "furigana": "農家[のうか]の朝[あさ]は早[はや]く、四時[よじ]に起床[きしょう]して畑[はたけ]へ向[む]かう。", "sentence_source": "generated"}, {"text": "起床したら、まず窓を開けて空気を入れ替える。", "target_word": "起床", "complexity_tier": "T3", "furigana": "起床[きしょう]したら、まず窓[まど]を開[あ]けて空気[くうき]を入[い]れ替[か]える。", "sentence_source": "generated"}, {"text": "毎朝五時に起床して、ジョギングを日課にしている。", "target_word": "起床", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]五時[ごじ]に起床[きしょう]して、ジョギングを日課[にっか]にしている。", "sentence_source": "generated"}, {"text": "彼女は起床して身支度を整え、仕事に出かけた。", "target_word": "起床", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は起床[きしょう]して身支度[みじたく]を整[ととの]え、仕事[しごと]に出[で]かけた。", "sentence_source": "generated"}, {"text": "修行僧は暗いうちに起床し、お経を唱える。", "target_word": "起床", "complexity_tier": "T3", "furigana": "修行僧[しゅぎょうそう]は暗[くら]いうちに起床[きしょう]し、お経[きょう]を唱[とな]える。", "sentence_source": "generated"}, {"text": "旅行の日は、いつもより一時間早く起床した。", "target_word": "起床", "complexity_tier": "T3", "furigana": "旅行[りょこう]の日[ひ]は、いつもより一時間[いちじかん]早[はや]く起床[きしょう]した。", "sentence_source": "generated"}, {"text": "起床してからの三十分が、一日で最も忙しい。", "target_word": "起床", "complexity_tier": "T3", "furigana": "起床[きしょう]してからの三十分[さんじっぷん]が、一日[いちにち]で最[もっと]も忙[いそが]しい。", "sentence_source": "generated"}, {"text": "夜勤明けの母は、昼に起床して家事を始める。", "target_word": "起床", "complexity_tier": "T3", "furigana": "夜勤明[やきんあ]けの母[はは]は、昼[ひる]に起床[きしょう]して家事[かじ]を始[はじ]める。", "sentence_source": "generated"}, {"text": "弟は起床するとすぐに、ゲームを始めた。", "target_word": "起床", "complexity_tier": "T3", "furigana": "弟[おとうと]は起床[きしょう]するとすぐに、ゲームを始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "起床する", "label": "辞書形"}, {"form": "起床した", "label": "過去形"}, {"form": "起床して", "label": "て形"}, {"form": "起床しない", "label": "否定形"}], "register": "neutral (plain form)", "sense_fingerprint": "眠りから体を起こして一日の活動を始めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36645, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起床", "is_correct": true, "explanation": "「夜明け前に起床し、訓練を始めた」で、寝床から起きることを表す。ここでの正解。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている時の呼吸音で、「寝息し、訓練を始めた」は成り立たない。"}, {"text": "寝室", "is_correct": false, "explanation": "寝室は寝る部屋で、「寝室し、訓練を始めた」は動詞として成り立たない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝床は寝る場所で、「寝床し、訓練を始めた」は動詞として成り立たない。"}], "explanations": {"起床": "「夜明け前に起床し、訓練を始めた」で、寝床から起きることを表す。ここでの正解。", "寝息": "寝息は眠っている時の呼吸音で、「寝息し、訓練を始めた」は成り立たない。", "寝室": "寝室は寝る部屋で、「寝室し、訓練を始めた」は動詞として成り立たない。", "寝床": "寝床は寝る場所で、「寝床し、訓練を始めた」は動詞として成り立たない。"}, "sentence_index": 0, "correct_answer": "起床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赤ちゃんは静かに起床を立てていた。", "explanation": "ここは〈寝息〉（眠っている間の呼吸音）の意味。起床は寝床から起きることで、寝息を立てる様子には使えない。"}, {"text": "式典では、全員が起床して国歌を歌った。", "explanation": "ここは〈起立〉（立ち上がる）の意味。起床はベッドから起きることで、式典で立つ動作には使わない。"}, {"text": "寝る前に起床して、体を温める。", "explanation": "ここは〈寝る前に起きておく〉の意味。起床は眠りから体を起こして活動を始めることなので、寝る前の時間には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36645, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起床", "is_correct": true, "explanation": "「いつもより一時間早く起床した」で、朝に起きたことを表す。ここでの正解。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝袋は野外などで眠るための袋で、「寝袋した」は動詞として成り立たない。"}, {"text": "毛布", "is_correct": false, "explanation": "毛布は体を覆う寝具で、「毛布した」は動詞として成り立たない。"}, {"text": "寝相", "is_correct": false, "explanation": "寝相は寝ている時の姿勢で、「寝相した」は動詞として成り立たない。"}], "explanations": {"起床": "「いつもより一時間早く起床した」で、朝に起きたことを表す。ここでの正解。", "寝袋": "寝袋は野外などで眠るための袋で、「寝袋した」は動詞として成り立たない。", "毛布": "毛布は体を覆う寝具で、「毛布した」は動詞として成り立たない。", "寝相": "寝相は寝ている時の姿勢で、「寝相した」は動詞として成り立たない。"}, "sentence_index": 6, "correct_answer": "起床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "列車は朝六時に起床する。", "explanation": "ここは〈出発〉（発車すること）の意味。起床は人が寝床から起きることで、列車の発車には使わない。"}, {"text": "朝、彼は顔を起床してから出かけた。", "explanation": "ここは〈洗顔〉（顔を洗うこと）の意味。起床は寝床から起きることで、顔を洗う動作とは結びつかない。"}, {"text": "夜、彼は布団を起床してから、電気を消した。", "explanation": "ここは〈敷く〉（布団を用意する）の意味。起床は寝床から起きる動作で、布団を敷く行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36645, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は毎朝、四時に起床を、畑に向かう。", "corrected_sentence": "父は毎朝、四時に起床して、畑に向かう。", "error_description": "起床してから次の動作へ続けるときは「起床して」の形を用いる。「起床を」では続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36645, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は、昼寝の後に起床が、テレビをつけた。", "corrected_sentence": "父は、昼寝の後に起床して、テレビをつけた。", "error_description": "起床してから次の動作へ続けるときは「起床して」の形を用いる。「起床が」では主語にしかならず、続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36646, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直前", "is_correct": true, "explanation": "「直後」の対義語で、ある出来事より前の時点を表す。"}, {"text": "途中", "is_correct": false, "explanation": "動作や期間の途中を表し、対義語ではない。"}, {"text": "最中", "is_correct": false, "explanation": "まさに行っている最中を表し、前後を表す対義語ではない。"}, {"text": "直角", "is_correct": false, "explanation": "九十度の角のことで、時間の語の対義にはならない。"}], "correct_answer": "直前", "explanations": {"直前": "「直後」の対義語で、ある出来事より前の時点を表す。", "途中": "動作や期間の途中を表し、対義語ではない。", "最中": "まさに行っている最中を表し、前後を表す対義語ではない。", "直角": "九十度の角のことで、時間の語の対義にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36646, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を表す。「薬を飲んだ直後に」で、飲んだすぐあとを指す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を表すが、「直後を眠くなった」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、時点を指す「直後へ」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すので、「直後と眠くなった」は不自然。"}], "correct_answer": "に", "explanations": {"に": "時点を表す。「薬を飲んだ直後に」で、飲んだすぐあとを指す。", "を": "動作の対象を表すが、「直後を眠くなった」では文が成り立たない。", "へ": "方向を表すので、時点を指す「直後へ」は合わない。", "と": "相手や並列を表すので、「直後と眠くなった」は不自然。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "相手・並列"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直前", "is_correct": true, "explanation": "「直後」の対義語で、ある出来事より前の時点を表す。"}, {"text": "直進", "is_correct": false, "explanation": "まっすぐ進む意味で、時間の前後を表す対義語ではない。"}, {"text": "最後", "is_correct": false, "explanation": "最終の時点を表す語で、「直後」の対義語ではない。"}, {"text": "直結", "is_correct": false, "explanation": "直接つながる意味で、時間の対義語にはならない。"}], "correct_answer": "直前", "explanations": {"直前": "「直後」の対義語で、ある出来事より前の時点を表す。", "直進": "まっすぐ進む意味で、時間の前後を表す対義語ではない。", "最後": "最終の時点を表す語で、「直後」の対義語ではない。", "直結": "直接つながる意味で、時間の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36646, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かのすぐあと。", "primary_collocate": null, "pronunciation": "ちょくご", "ipa": "tɕokɯɡo", "syllable_count": 3, "sentences": [{"text": "食事の直後に運動すると、お腹が痛くなる。", "target_word": "直後", "complexity_tier": "T3", "furigana": "食事[しょくじ]の直後[ちょくご]に運動[うんどう]すると、お腹[なか]が痛[いた]くなる。", "sentence_source": "generated"}, {"text": "会議が終わった直後、部長が私を呼んだ。", "target_word": "直後", "complexity_tier": "T3", "furigana": "会議[かいぎ]が終[お]わった直後[ちょくご]、部長[ぶちょう]が私[わたし]を呼[よ]んだ。", "sentence_source": "generated"}, {"text": "地震の直後は、まず安全を確かめることが大切だ。", "target_word": "直後", "complexity_tier": "T3", "furigana": "地震[じしん]の直後[ちょくご]は、まず安全[あんぜん]を確[たし]かめることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "雨がやんだ直後に、空に虹が出た。", "target_word": "直後", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだ直後[ちょくご]に、空[そら]に虹[にじ]が出[で]た。", "sentence_source": "generated"}, {"text": "家を出た直後、財布を忘れたことに気づいた。", "target_word": "直後", "complexity_tier": "T3", "furigana": "家[いえ]を出[で]た直後[ちょくご]、財布[さいふ]を忘[わす]れたことに気[き]づいた。", "sentence_source": "generated"}, {"text": "試験の直後は、答え合わせをする気になれない。", "target_word": "直後", "complexity_tier": "T3", "furigana": "試験[しけん]の直後[ちょくご]は、答[こた]え合[あ]わせをする気[き]になれない。", "sentence_source": "generated"}, {"text": "発売の直後から、店の前に長い列ができた。", "target_word": "直後", "complexity_tier": "T3", "furigana": "発売[はつばい]の直後[ちょくご]から、店[みせ]の前[まえ]に長[なが]い列[れつ]ができた。", "sentence_source": "generated"}, {"text": "薬を飲んだ直後に、少し眠くなった。", "target_word": "直後", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだ直後[ちょくご]に、少[すこ]し眠[ねむ]くなった。", "sentence_source": "generated"}, {"text": "先生の話の直後に、質問の手が上がった。", "target_word": "直後", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]の直後[ちょくご]に、質問[しつもん]の手[て]が上[あ]がった。", "sentence_source": "generated"}, {"text": "事故の直後、運転手はすぐに救急車を呼んだ。", "target_word": "直後", "complexity_tier": "T3", "furigana": "事故[じこ]の直後[ちょくご]、運転手[うんてんしゅ]はすぐに救急車[きゅうきゅうしゃ]を呼[よ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直後", "label": "基本形"}, {"form": "直後に", "label": "時を表す形"}, {"form": "直後の", "label": "連体形"}], "register": "neutral (plain form)", "sense_fingerprint": "ある時点や出来事のすぐ後の時間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36646, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直後", "is_correct": true, "explanation": "「食事が終わったすぐあと」の意味で、文の時間の指定にそのまま入る。"}, {"text": "直線", "is_correct": false, "explanation": "まっすぐな線の意味で、食事の時間には続かない。"}, {"text": "直径", "is_correct": false, "explanation": "円の中心を通る線分の長さで、時間の前後を表せない。"}, {"text": "直感", "is_correct": false, "explanation": "ひらめき・勘の意味で、「食事の直感に」では文が成り立たない。"}], "explanations": {"直後": "「食事が終わったすぐあと」の意味で、文の時間の指定にそのまま入る。", "直線": "まっすぐな線の意味で、食事の時間には続かない。", "直径": "円の中心を通る線分の長さで、時間の前後を表せない。", "直感": "ひらめき・勘の意味で、「食事の直感に」では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "直後"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この家の直後に、古い公園がある。", "explanation": "場所の「うしろ」の意味で使っている。「直後」は出来事のあとの時間にだけ使い、場所は指せない。"}, {"text": "宿題は直後に終わらせよう。", "explanation": "「後で」の意味で使っている。「直後」は前に出来事がある時に使うので、基準のない文では不自然。"}, {"text": "この道は駅まで直後に続いている。", "explanation": "「まっすぐな」の意味で使っている。まっすぐという意味は「直線」にあり、「直後」にはその意味がない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36646, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直後", "is_correct": true, "explanation": "「発売のすぐあと」の意味で、「直後から」と時点を指す。"}, {"text": "直下", "is_correct": false, "explanation": "真下を指す語で、時間の前後には使えない。"}, {"text": "直射", "is_correct": false, "explanation": "光が直接当たることで、時点を表さない。"}, {"text": "直視", "is_correct": false, "explanation": "まっすぐ見ることで、「発売の直視から」では文が成り立たない。"}], "explanations": {"直後": "「発売のすぐあと」の意味で、「直後から」と時点を指す。", "直下": "真下を指す語で、時間の前後には使えない。", "直射": "光が直接当たることで、時点を表さない。", "直視": "まっすぐ見ることで、「発売の直視から」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "直後"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生に直後相談した。", "explanation": "「直接」の意味で使っている。「直後」は出来事のあとの時間を表すので、「面と向かって」の意味では使えない。"}, {"text": "一時間直後に戻ります。", "explanation": "「一時間以内に」の意味で使っている。「直後」は出来事のすぐあとを表すので、期間を区切る言い方には使えない。"}, {"text": "机の直後に鍵が落ちていた。", "explanation": "「真下」や「後ろ」の意味で使っている。「直後」は時間にだけ使うので、場所は指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36646, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地震が起きた直後の、非常ベルが鳴った。", "corrected_sentence": "地震が起きた直後に、非常ベルが鳴った。", "error_description": "「直後」に続く助詞が「の」になっている。時点を表すには「に」が必要で、正しくは「直後に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36646, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ワクチンを打った直後な、腕が少し痛くなった。", "corrected_sentence": "ワクチンを打った直後に、腕が少し痛くなった。", "error_description": "「直後」に続く「に」が「な」になっている。時点を表すには「直後に」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36647, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を表す。「電話を切った直後に」で、切ったすぐあとを指す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を表すが、「直後を鳴った」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、時点を指す「直後へ」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すので、「直後と鳴った」は不自然。"}], "correct_answer": "に", "explanations": {"に": "時点を表す。「電話を切った直後に」で、切ったすぐあとを指す。", "を": "動作の対象を表すが、「直後を鳴った」では文が成り立たない。", "へ": "方向を表すので、時点を指す「直後へ」は合わない。", "と": "相手や並列を表すので、「直後と鳴った」は不自然。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直前", "is_correct": true, "explanation": "「直後」の対義語で、ある出来事より前の時点を表す。"}, {"text": "途中", "is_correct": false, "explanation": "動作や期間の途中を表し、対義語ではない。"}, {"text": "最中", "is_correct": false, "explanation": "まさに行っている最中を表し、前後を表す対義語ではない。"}, {"text": "直径", "is_correct": false, "explanation": "円の中心を通る線分の長さで、時間の語の対義にはならない。"}], "correct_answer": "直前", "explanations": {"直前": "「直後」の対義語で、ある出来事より前の時点を表す。", "途中": "動作や期間の途中を表し、対義語ではない。", "最中": "まさに行っている最中を表し、前後を表す対義語ではない。", "直径": "円の中心を通る線分の長さで、時間の語の対義にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36647, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "時点を表す。「報告を受けた直後に」で、受けたすぐあとを指す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表すが、後に名詞が続かず「直後の、社長は」では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、「報告を受けた直後より、社長は」では文がつながらない。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すが、「直後が、社長は」と主語が二つ並び、文の中心が決まらない。"}], "correct_answer": "に", "explanations": {"に": "時点を表す。「報告を受けた直後に」で、受けたすぐあとを指す。", "の": "連体修飾を表すが、後に名詞が続かず「直後の、社長は」では文が成り立たない。", "より": "比較を表すので、「報告を受けた直後より、社長は」では文がつながらない。", "が": "主語を表すが、「直後が、社長は」と主語が二つ並び、文の中心が決まらない。"}, "error_tags": {"の": "連体修飾", "より": "比較", "が": "主語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "直前", "is_correct": true, "explanation": "「直後」の対義語で、ある出来事より前の時点を表す。"}, {"text": "直進", "is_correct": false, "explanation": "まっすぐ進む意味で、時間の前後を表す対義語ではない。"}, {"text": "最後", "is_correct": false, "explanation": "最終の時点を表す語で、「直後」の対義語ではない。"}, {"text": "直結", "is_correct": false, "explanation": "直接つながる意味で、時間の対義語にはならない。"}], "correct_answer": "直前", "explanations": {"直前": "「直後」の対義語で、ある出来事より前の時点を表す。", "直進": "まっすぐ進む意味で、時間の前後を表す対義語ではない。", "最後": "最終の時点を表す語で、「直後」の対義語ではない。", "直結": "直接つながる意味で、時間の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36647, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある出来事や動作が終わった直後のこと。", "primary_collocate": null, "pronunciation": "ちょくご", "ipa": "tɕokɯɡo", "syllable_count": 3, "sentences": [{"text": "試合が終わった直後、選手たちは握手をした。", "target_word": "直後", "complexity_tier": "T3", "furigana": "試合[しあい]が終[お]わった直後[ちょくご]、選手[せんしゅ]たちは握手[あくしゅ]をした。", "sentence_source": "generated"}, {"text": "電話を切った直後に、また着信音が鳴った。", "target_word": "直後", "complexity_tier": "T3", "furigana": "電話[でんわ]を切[き]った直後[ちょくご]に、また着信音[ちゃくしんおん]が鳴[な]った。", "sentence_source": "generated"}, {"text": "入浴の直後は、水をたくさん飲んだほうがいい。", "target_word": "直後", "complexity_tier": "T3", "furigana": "入浴[にゅうよく]の直後[ちょくご]は、水[みず]をたくさん飲[の]んだほうがいい。", "sentence_source": "generated"}, {"text": "発表の直後、会場から大きな拍手が起こった。", "target_word": "直後", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の直後[ちょくご]、会場[かいじょう]から大[おお]きな拍手[はくしゅ]が起[お]こった。", "sentence_source": "generated"}, {"text": "手術の直後は、まだ話すことができない。", "target_word": "直後", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]の直後[ちょくご]は、まだ話[はな]すことができない。", "sentence_source": "generated"}, {"text": "卒業式の直後、教室で友達と写真を撮った。", "target_word": "直後", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]の直後[ちょくご]、教室[きょうしつ]で友達[ともだち]と写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "優勝が決まった直後、監督は涙を流した。", "target_word": "直後", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]が決[き]まった直後[ちょくご]、監督[かんとく]は涙[なみだ]を流[なが]した。", "sentence_source": "generated"}, {"text": "報告を受けた直後に、社長は会議を開いた。", "target_word": "直後", "complexity_tier": "T3", "furigana": "報告[ほうこく]を受[う]けた直後[ちょくご]に、社長[しゃちょう]は会議[かいぎ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "授業が終わった直後は、廊下がとてもにぎやかだ。", "target_word": "直後", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が終[お]わった直後[ちょくご]は、廊下[ろうか]がとてもにぎやかだ。", "sentence_source": "generated"}, {"text": "打ち上げの直後、ロケットは雲の中に消えた。", "target_word": "直後", "complexity_tier": "T3", "furigana": "打[う]ち上[あ]げの直後[ちょくご]、ロケットは雲[くも]の中[なか]に消[き]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直後", "label": "基本形"}, {"form": "直後に", "label": "時を表す形"}, {"form": "直後の", "label": "連体形"}], "register": "neutral (plain form)", "sense_fingerprint": "出来事や動作が終わってすぐの時点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36647, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直後", "is_correct": true, "explanation": "「試合が終わったすぐあと」の意味で、文の時間の指定に入る。"}, {"text": "直流", "is_correct": false, "explanation": "電気の流れ方を表し、時間の語ではない。"}, {"text": "直角", "is_correct": false, "explanation": "九十度の角のことで、時点を表せない。"}, {"text": "直面", "is_correct": false, "explanation": "物事に向き合う意味で、「試合が終わった直面」では文が成り立たない。"}], "explanations": {"直後": "「試合が終わったすぐあと」の意味で、文の時間の指定に入る。", "直流": "電気の流れ方を表し、時間の語ではない。", "直角": "九十度の角のことで、時点を表せない。", "直面": "物事に向き合う意味で、「試合が終わった直面」では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "直後"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この建物の直後に、大きな駐車場がある。", "explanation": "場所の「うしろ」の意味で使っている。「直後」は出来事のあとの時間にだけ使い、場所は指せない。"}, {"text": "資料は直後に配ろう。", "explanation": "「後で」の意味で使っている。「直後」は前に出来事がある時に使うので、基準のない文では不自然。"}, {"text": "この川は海まで直後に流れている。", "explanation": "「まっすぐな」の意味で使っている。まっすぐという意味は「直線」にあり、「直後」にはその意味がない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36647, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直後", "is_correct": true, "explanation": "「優勝が決まったすぐあと」の意味で、時点を指す。"}, {"text": "直送", "is_correct": false, "explanation": "直接送る意味で、時間の前後を表せない。"}, {"text": "直下", "is_correct": false, "explanation": "真下を指す語で、時間の語としては使えない。"}, {"text": "直視", "is_correct": false, "explanation": "まっすぐ見ることで、「優勝が決まった直視」では文が成り立たない。"}], "explanations": {"直後": "「優勝が決まったすぐあと」の意味で、時点を指す。", "直送": "直接送る意味で、時間の前後を表せない。", "直下": "真下を指す語で、時間の語としては使えない。", "直視": "まっすぐ見ることで、「優勝が決まった直視」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "直後"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二時間直後に戻ります。", "explanation": "「二時間以内に」の意味で使っている。「直後」は出来事のすぐあとを表すので、期間を区切る言い方には使えない。"}, {"text": "社長に直後、話を聞いた。", "explanation": "「直接」の意味で使っている。「直後」は出来事のあとの時間を表すので、「直接話を聞く」の意味では使えない。"}, {"text": "ベッドの直後に、カーテンがある。", "explanation": "「後ろ」の意味で使っている。「直後」は時間にだけ使うので、場所は指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36647, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卒業式が終わった直後の、みんなで校庭を歩いた。", "corrected_sentence": "卒業式が終わった直後に、みんなで校庭を歩いた。", "error_description": "「直後」に続く助詞が「の」になっている。時点を表すには「に」が必要で、正しくは「直後に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36647, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面接を受けた直後な、胃が痛くなった。", "corrected_sentence": "面接を受けた直後に、胃が痛くなった。", "error_description": "「直後」に続く「に」が「な」になっている。時点を表すには「直後に」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
