INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36648, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「産生が止まった」の主語を示し、止まったのは産生だと表す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を表すが、「産生を止まった」では自動詞「止まった」と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「産生へ止まった」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すので、「産生と止まった」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「産生が止まった」の主語を示し、止まったのは産生だと表す。", "を": "動作の対象を表すが、「産生を止まった」では自動詞「止まった」と合わない。", "へ": "方向を表すので、「産生へ止まった」は文が成り立たない。", "と": "相手や並列を表すので、「産生と止まった」は不自然。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36648, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物や熱などが、自分でできたり、作られたりすること。", "primary_collocate": null, "pronunciation": "さんせい", "ipa": "sansei", "syllable_count": 4, "sentences": [{"text": "その細菌は強い毒素を産生するため、取り扱いには注意が必要だ。", "target_word": "産生", "complexity_tier": "T3", "furigana": "その細菌[さいきん]は強[つよ]い毒素[どくそ]を産生[さんせい]するため、取[と]り扱[あつか]いには注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "発酵の過程で微生物がガスを産生するので、容器がふくらんだ。", "target_word": "産生", "complexity_tier": "T3", "furigana": "発酵[はっこう]の過程[かてい]で微生物[びせいぶつ]がガスを産生[さんせい]するので、容器[ようき]がふくらんだ。", "sentence_source": "generated"}, {"text": "酵母が糖を分解すると、アルコールが産生され、果汁の香りが変わった。", "target_word": "産生", "complexity_tier": "T3", "furigana": "酵母[こうぼ]が糖[とう]を分解[ぶんかい]すると、アルコールが産生[さんせい]され、果汁[かじゅう]の香[か]りが変[か]わった。", "sentence_source": "generated"}, {"text": "この菌は酸素の少ない環境で、大量のガスを産生する。", "target_word": "産生", "complexity_tier": "T3", "furigana": "この菌[きん]は酸素[さんそ]の少[すく]ない環境[かんきょう]で、大量[たいりょう]のガスを産生[さんせい]する。", "sentence_source": "generated"}, {"text": "工場の排水に含まれる菌は、有害な物質の産生を続けていた。", "target_word": "産生", "complexity_tier": "T3", "furigana": "工場[こうじょう]の排水[はいすい]に含[ふく]まれる菌[きん]は、有害[ゆうがい]な物質[ぶっしつ]の産生[さんせい]を続[つづ]けていた。", "sentence_source": "generated"}, {"text": "この藻は光を受けると酸素を産生するが、暗い場所ではほとんど作らない。", "target_word": "産生", "complexity_tier": "T3", "furigana": "この藻[も]は光[ひかり]を受[う]けると酸素[さんそ]を産生[さんせい]するが、暗[くら]い場所[ばしょ]ではほとんど作[つく]らない。", "sentence_source": "generated"}, {"text": "燃料を使わずに熱を産生する方法が、研究者の間で注目されている。", "target_word": "産生", "complexity_tier": "T3", "furigana": "燃料[ねんりょう]を使[つか]わずに熱[ねつ]を産生[さんせい]する方法[ほうほう]が、研究者[けんきゅうしゃ]の間[あいだ]で注目[ちゅうもく]されている。", "sentence_source": "generated"}, {"text": "微生物による酸の産生が止まったので、食品の味は変わらなくなった。", "target_word": "産生", "complexity_tier": "T3", "furigana": "微生物[びせいぶつ]による酸[さん]の産生[さんせい]が止[と]まったので、食品[しょくひん]の味[あじ]は変[か]わらなくなった。", "sentence_source": "generated"}, {"text": "土の中の細菌が有機酸を産生することで、土の性質が保たれる。", "target_word": "産生", "complexity_tier": "T3", "furigana": "土[つち]の中[なか]の細菌[さいきん]が有機酸[ゆうきさん]を産生[さんせい]することで、土[つち]の性質[せいしつ]が保[たも]たれる。", "sentence_source": "generated"}, {"text": "この細胞は酵素を産生するため、食べ物の消化を助けている。", "target_word": "産生", "complexity_tier": "T3", "furigana": "この細胞[さいぼう]は酵素[こうそ]を産生[さんせい]するため、食べ物[たべもの]の消化[しょうか]を助[たす]けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "産生", "label": "基本形"}, {"form": "産生する", "label": "サ変動詞"}, {"form": "産生される", "label": "受身形"}, {"form": "産生した", "label": "過去形"}], "register": "書き言葉・硬い文体", "sense_fingerprint": "物や熱などが自然にできる・作り出される", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: ふくらん (Zipf 2.47)']::text[], '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36648, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "産生", "is_correct": true, "explanation": "物質を作り出す意味で、「毒素を産生するため」と文に合う。"}, {"text": "産卵", "is_correct": false, "explanation": "卵を産む意味で、毒素には使えない。"}, {"text": "産地", "is_correct": false, "explanation": "物が産出される場所で、「毒素を産地する」は成り立たない。"}, {"text": "産声", "is_correct": false, "explanation": "赤ん坊の泣き声で、毒素とは結びつかない。"}], "explanations": {"産生": "物質を作り出す意味で、「毒素を産生するため」と文に合う。", "産卵": "卵を産む意味で、毒素には使えない。", "産地": "物が産出される場所で、「毒素を産地する」は成り立たない。", "産声": "赤ん坊の泣き声で、毒素とは結びつかない。"}, "sentence_index": 0, "correct_answer": "産生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母猫は五匹の子を産生した。", "explanation": "「出産」の意味で使っている。産生は物質やエネルギーを作ることで、子を産む意味では使わない。"}, {"text": "この工場はスマホを大量に産生している。", "explanation": "「生産」の意味で使っている。産生は細胞や体内で物質が作られることに使い、工場の製品には使えない。"}, {"text": "この山では金が産生されている。", "explanation": "「産出」の意味で使っている。金は鉱山で採れるもので、体内や細胞で作られる物質ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36648, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "産生", "is_correct": true, "explanation": "物質や熱を作り出す意味で、「熱を産生する方法」と文に合う。"}, {"text": "養殖", "is_correct": false, "explanation": "魚や貝を人工的に育てることで、熱には使えない。"}, {"text": "生育", "is_correct": false, "explanation": "植物などが育つことで、熱を作る意味にはならない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すことで、熱を生み出す意味には合わない。"}], "explanations": {"産生": "物質や熱を作り出す意味で、「熱を産生する方法」と文に合う。", "養殖": "魚や貝を人工的に育てることで、熱には使えない。", "生育": "植物などが育つことで、熱を作る意味にはならない。", "採掘": "地下の資源を掘り出すことで、熱を生み出す意味には合わない。"}, "sentence_index": 6, "correct_answer": "産生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店で火災が産生した。", "explanation": "「発生」の意味で使っている。火災は体内や細胞で作られるものではないので、「産生」は使えない。"}, {"text": "この会社は自動車を産生している。", "explanation": "「製造」の意味で使っている。産生は細胞や微生物が物質を作ることに使い、工場の製品には使えない。"}, {"text": "AIが文章を産生する。", "explanation": "「生成」の意味で使っている。産生は物質やエネルギーに使うので、文章には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36648, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この細菌は乳酸を産生ため、漬け物が酸っぱくなる。", "corrected_sentence": "この細菌は乳酸を産生するため、漬け物が酸っぱくなる。", "error_description": "「産生」に続く「する」が抜けていて、「ため」につながらない。正しくは「産生するため」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36648, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この細胞は毒素の産生が止めた。", "corrected_sentence": "この細胞は毒素の産生を止めた。", "error_description": "「止めた」は他動詞なので、「産生」には「を」が必要。「が」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
