INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36649, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「産生が抑えられ」の主語を示し、抑えられたのは産生だと表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「産生へ抑えられ」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すので、「産生と抑えられ」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、「産生より抑えられ」は文がつながらない。"}], "correct_answer": "が", "explanations": {"が": "「産生が抑えられ」の主語を示し、抑えられたのは産生だと表す。", "へ": "方向を表すので、「産生へ抑えられ」は文が成り立たない。", "と": "相手や並列を表すので、「産生と抑えられ」は不自然。", "より": "比較を表すので、「産生より抑えられ」は文がつながらない。"}, "error_tags": {"へ": "方向", "と": "相手・並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36649, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "体内や組織・器官などで、物質やエネルギーが作り出されること。", "primary_collocate": null, "pronunciation": "さんせい", "ipa": "sansei", "syllable_count": 4, "sentences": [{"text": "膵臓はインスリンを産生し、血液中の糖の量を調節している。", "target_word": "産生", "complexity_tier": "T3", "furigana": "膵臓[すいぞう]はインスリンを産生[さんせい]し、血液[けつえき]中[ちゅう]の糖[とう]の量[りょう]を調節[ちょうせつ]している。", "sentence_source": "generated"}, {"text": "ウイルスに感染すると、体内で抗体が産生されて病気から守られる。", "target_word": "産生", "complexity_tier": "T3", "furigana": "ウイルスに感染[かんせん]すると、体内[たいない]で抗体[こうたい]が産生[さんせい]されて病気[びょうき]から守[まも]られる。", "sentence_source": "generated"}, {"text": "肝臓の働きが弱ると、必要なたんぱく質の産生が減ってしまう。", "target_word": "産生", "complexity_tier": "T3", "furigana": "肝臓[かんぞう]の働[はたら]きが弱[よわ]ると、必要[ひつよう]なたんぱく質[しつ]の産生[さんせい]が減[へ]ってしまう。", "sentence_source": "generated"}, {"text": "筋肉が動くと熱が産生され、体温が上がる。", "target_word": "産生", "complexity_tier": "T3", "furigana": "筋肉[きんにく]が動[うご]くと熱[ねつ]が産生[さんせい]され、体温[たいおん]が上[あ]がる。", "sentence_source": "generated"}, {"text": "皮膚は日光を受けるとメラニンを産生し、肌の色が濃くなる。", "target_word": "産生", "complexity_tier": "T3", "furigana": "皮膚[ひふ]は日光[にっこう]を受[う]けるとメラニンを産生[さんせい]し、肌[はだ]の色[いろ]が濃[こ]くなる。", "sentence_source": "generated"}, {"text": "甲状腺ホルモンの産生が多すぎると、脈が速くなる。", "target_word": "産生", "complexity_tier": "T3", "furigana": "甲状腺[こうじょうせん]ホルモンの産生[さんせい]が多[おお]すぎると、脈[みゃく]が速[はや]くなる。", "sentence_source": "generated"}, {"text": "骨髄では毎日、新しい血液の細胞が産生されている。", "target_word": "産生", "complexity_tier": "T3", "furigana": "骨髄[こつずい]では毎日[まいにち]、新[あたら]しい血液[けつえき]の細胞[さいぼう]が産生[さんせい]されている。", "sentence_source": "generated"}, {"text": "薬の影響で胃酸の産生が抑えられ、胸やけが楽になった。", "target_word": "産生", "complexity_tier": "T3", "furigana": "薬[くすり]の影響[えいきょう]で胃酸[いさん]の産生[さんせい]が抑[おさ]えられ、胸[むね]やけが楽[らく]になった。", "sentence_source": "generated"}, {"text": "睡眠不足が続くと、体内でストレスのホルモンが過剰に産生される。", "target_word": "産生", "complexity_tier": "T3", "furigana": "睡眠[すいみん]不足[ぶそく]が続[つづ]くと、体内[たいない]でストレスのホルモンが過剰[かじょう]に産生[さんせい]される。", "sentence_source": "generated"}, {"text": "腎臓は赤血球の増加を促すホルモンを産生している。", "target_word": "産生", "complexity_tier": "T3", "furigana": "腎臓[じんぞう]は赤血球[せっけっきゅう]の増加[ぞうか]を促[うなが]すホルモンを産生[さんせい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "産生", "label": "基本形"}, {"form": "産生する", "label": "サ変動詞"}, {"form": "産生される", "label": "受身形"}, {"form": "産生した", "label": "過去形"}], "register": "書き言葉・硬い文体", "sense_fingerprint": "体内や器官でホルモン・抗体・熱などが作り出される", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36649, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "産生", "is_correct": true, "explanation": "体内でホルモンが作り出される意味で、「インスリンを産生し」と文に合う。"}, {"text": "出血", "is_correct": false, "explanation": "血が体の外に流れ出ることで、ホルモンを作る意味にはならない。"}, {"text": "出産", "is_correct": false, "explanation": "子を産む意味で、インスリンには使えない。"}, {"text": "感染", "is_correct": false, "explanation": "病原体が入り込むことで、ホルモンを作るとは言えない。"}], "explanations": {"産生": "体内でホルモンが作り出される意味で、「インスリンを産生し」と文に合う。", "出血": "血が体の外に流れ出ることで、ホルモンを作る意味にはならない。", "出産": "子を産む意味で、インスリンには使えない。", "感染": "病原体が入り込むことで、ホルモンを作るとは言えない。"}, "sentence_index": 0, "correct_answer": "産生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は二人の子を産生した。", "explanation": "「出産」の意味で使っている。産生は物質やエネルギーを作ることで、人の子には使わない。"}, {"text": "昨夜、大きな地震が産生した。", "explanation": "「発生」の意味で使っている。地震は体内で作られるものではないので、「産生」は使えない。"}, {"text": "この鉱山では銅が産生されている。", "explanation": "「産出」の意味で使っている。銅は鉱山で採れるもので、体内や組織で作られる物質ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36649, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "産生", "is_correct": true, "explanation": "細胞が新しく作り出される意味で、「細胞が産生されている」と文に合う。"}, {"text": "消化", "is_correct": false, "explanation": "食べ物を分解することで、細胞を作る意味にはならない。"}, {"text": "陥没", "is_correct": false, "explanation": "地面などが落ち込むことで、細胞には使えない。"}, {"text": "漂白", "is_correct": false, "explanation": "色を抜く意味で、細胞が作られることは表せない。"}], "explanations": {"産生": "細胞が新しく作り出される意味で、「細胞が産生されている」と文に合う。", "消化": "食べ物を分解することで、細胞を作る意味にはならない。", "陥没": "地面などが落ち込むことで、細胞には使えない。", "漂白": "色を抜く意味で、細胞が作られることは表せない。"}, "sentence_index": 6, "correct_answer": "産生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この農家は毎年、野菜を大量に産生している。", "explanation": "「生産」の意味で使っている。産生は体内や器官で物質が作られることに使い、農作物には合わない。"}, {"text": "この工場は部品を産生している。", "explanation": "「製造」の意味で使っている。産生は細胞や体内の物質に使い、工場が作る部品には使えない。"}, {"text": "パソコンが画像を産生する。", "explanation": "「生成」の意味で使っている。産生は体内や細胞で物質が作られることに使い、画像には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36649, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "インスリンの産生を減ると、血糖値が上がる。", "corrected_sentence": "インスリンの産生が減ると、血糖値が上がる。", "error_description": "「減る」は自動詞で「が」を取るのに、「を」が付いている。「産生が減る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36649, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "副腎はストレスホルモンを産生され、血圧を上げる。", "corrected_sentence": "副腎はストレスホルモンを産生し、血圧を上げる。", "error_description": "「産生され」は受身形で、目的語「ストレスホルモンを」と合わない。能動の「産生し」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36650, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "状況を示す「で」。「面接の場面では」と場面の範囲を表し、話し方が大切だという文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語にすると「場面を話す」となり不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語にすると文の意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、話し方を述べる文と合わない。"}], "correct_answer": "で", "explanations": {"で": "状況を示す「で」。「面接の場面では」と場面の範囲を表し、話し方が大切だという文に合う。", "を": "目的語にすると「場面を話す」となり不自然。", "が": "主語にすると文の意味が通らない。", "へ": "方向を表す助詞で、話し方を述べる文と合わない。"}, "error_tags": {"を": "目的語にすると「場面を話す」となり不自然", "が": "主語にすると文の意味が通らない", "へ": "方向を表す助詞で、話し方を述べる文と合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36650, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「思い出す」の目的語を示す「を」。「場面を思い出す」と対象を表し、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「思い出す」の対象を示せないので、文に合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所を示す助詞で、思い出す対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、思い出す対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「思い出す」の目的語を示す「を」。「場面を思い出す」と対象を表し、文に合う。", "に": "「思い出す」の対象を示せないので、文に合わない。", "で": "場所を示す助詞で、思い出す対象にならない。", "へ": "方向を示す助詞で、思い出す対象にならない。"}, "error_tags": {"に": "「思い出す」の対象を示せない", "で": "場所を示す助詞で、思い出す対象にならない", "へ": "方向を示す助詞で、思い出す対象にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36650, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こっているときの場所や時間", "primary_collocate": null, "pronunciation": "ばめん", "ipa": "bameɴ", "syllable_count": 3, "sentences": [{"text": "映画の最後の場面で、私は思わず泣いてしまいました。", "target_word": "場面", "complexity_tier": "T3", "furigana": "映画[えいが]の最後[さいご]の場面[ばめん]で、私[わたし]は思[おも]わず泣[な]いてしまいました。", "sentence_source": "generated"}, {"text": "面接の場面では、ゆっくり話すことが大切です。", "target_word": "場面", "complexity_tier": "T3", "furigana": "面接[めんせつ]の場面[ばめん]では、ゆっくり話[はな]すことが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "この本は、主人公が旅立つ場面から始まります。", "target_word": "場面", "complexity_tier": "T3", "furigana": "この本[ほん]は、主人公[しゅじんこう]が旅立[たびだ]つ場面[ばめん]から始[はじ]まります。", "sentence_source": "generated"}, {"text": "仕事では、敬語を使う場面が多いです。", "target_word": "場面", "complexity_tier": "T3", "furigana": "仕事[しごと]では、敬語[けいご]を使[つか]う場面[ばめん]が多[おお]いです。", "sentence_source": "generated"}, {"text": "事故の場面を見た人は、警察に連絡してください。", "target_word": "場面", "complexity_tier": "T3", "furigana": "事故[じこ]の場面[ばめん]を見[み]た人[ひと]は、警察[けいさつ]に連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "試合の大事な場面で、彼はミスをしてしまった。", "target_word": "場面", "complexity_tier": "T3", "furigana": "試合[しあい]の大事[だいじ]な場面[ばめん]で、彼[かれ]はミスをしてしまった。", "sentence_source": "generated"}, {"text": "ドラマの感動的な場面を、何度も見返しました。", "target_word": "場面", "complexity_tier": "T3", "furigana": "ドラマの感動的[かんどうてき]な場面[ばめん]を、何度[なんど]も見返[みかえ]しました。", "sentence_source": "generated"}, {"text": "友達と別れた場面を思い出すと、今でも悲しくなります。", "target_word": "場面", "complexity_tier": "T3", "furigana": "友達[ともだち]と別[わか]れた場面[ばめん]を思[おも]い出[だ]すと、今[いま]でも悲[かな]しくなります。", "sentence_source": "generated"}, {"text": "緊張する場面でも、彼女はいつも落ち着いています。", "target_word": "場面", "complexity_tier": "T3", "furigana": "緊張[きんちょう]する場面[ばめん]でも、彼女[かのじょ]はいつも落[お]ち着[つ]いています。", "sentence_source": "generated"}, {"text": "買い物の場面で使う言葉を、授業で習いました。", "target_word": "場面", "complexity_tier": "T3", "furigana": "買[か]い物[もの]の場面[ばめん]で使[つか]う言葉[ことば]を、授業[じゅぎょう]で習[なら]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "場面", "label": "基本形"}, {"form": "場面で", "label": "場所・状況を表す形"}], "register": "neutral", "sense_fingerprint": "出来事や物語が進んでいるそのときの場面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36650, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時刻", "is_correct": false, "explanation": "時間を表す語で、映画の中で泣いた場面を述べる文には合わない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車券や入場券の意味で、映画の内容を示す文には合わない。"}, {"text": "場面", "is_correct": true, "explanation": "出来事が進んでいるそのときの様子を表し、映画の最後で泣いた場面として自然。"}, {"text": "料金", "is_correct": false, "explanation": "お金の意味で、映画の内容を述べる文には合わない。"}], "explanations": {"時刻": "時間を表す語で、映画の中で泣いた場面を述べる文には合わない。", "切符": "乗車券や入場券の意味で、映画の内容を示す文には合わない。", "場面": "出来事が進んでいるそのときの様子を表し、映画の最後で泣いた場面として自然。", "料金": "お金の意味で、映画の内容を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "場面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は場面がよくて、落ち着きます。", "explanation": "ここは〈雰囲気〉の意味。場面は出来事の進行中の様子を指し、店の空気には使わないので誤り。"}, {"text": "今日は天気の場面が悪いので、傘を持って行きます。", "explanation": "ここは〈天候〉の意味。空模様を指す天候を使い、出来事の様子を指す場面は合わない。"}, {"text": "この机は場面がつるつるしていて、拭きやすい。", "explanation": "ここは〈表面〉の意味。物の表側を指す表面を使い、出来事の様子を指す場面は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36650, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "字幕", "is_correct": false, "explanation": "画面に出る文字を指すので、感動的な場面を見返すという文には合わない。"}, {"text": "場面", "is_correct": true, "explanation": "ドラマの中の一つの出来事のシーンを表し、何度も見返す対象として自然。"}, {"text": "照明", "is_correct": false, "explanation": "明るさを調整する器具の意味で、見返す対象としては合わない。"}, {"text": "出演者", "is_correct": false, "explanation": "演じる人を指すので、見返す対象として述べる文には合わない。"}], "explanations": {"字幕": "画面に出る文字を指すので、感動的な場面を見返すという文には合わない。", "場面": "ドラマの中の一つの出来事のシーンを表し、何度も見返す対象として自然。", "照明": "明るさを調整する器具の意味で、見返す対象としては合わない。", "出演者": "演じる人を指すので、見返す対象として述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "場面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は場面が広いので、人が集まれます。", "explanation": "ここは〈広さ〉の意味。場面は出来事の様子を指し、空間の広さには使わないので誤り。"}, {"text": "この店は値段の場面が安いので、学生に人気です。", "explanation": "ここは〈価格〉の意味。金額を指す価格を使い、出来事の様子を指す場面は合わない。"}, {"text": "最近は場面が悪いので、早めに寝ています。", "explanation": "ここは〈体調〉の意味。体の具合を表す体調を使い、出来事の様子を指す場面は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36650, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試験の場面を、落ち着いて答えることが大切です。", "corrected_sentence": "試験の場面では、落ち着いて答えることが大切です。", "error_description": "「場面」の後は場所を表す「では」が正しい。「を」にすると「場面を答える」となり、場面を対象にする文として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
