INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36651, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "状況を示す「で」。「戦いの場面では」と場面の範囲を表し、音楽が流れる文に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語にすると文の意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語にすると「流れる」文の流れに合わず不自然。"}, {"text": "の", "is_correct": false, "explanation": "修飾の助詞にすると文の成り立ちが合わない。"}], "correct_answer": "で", "explanations": {"で": "状況を示す「で」。「戦いの場面では」と場面の範囲を表し、音楽が流れる文に合う。", "が": "主語にすると文の意味が通らない。", "を": "目的語にすると「流れる」文の流れに合わず不自然。", "の": "修飾の助詞にすると文の成り立ちが合わない。"}, "error_tags": {"が": "主語にすると文の意味が通らない", "を": "目的語にすると「流れる」文の流れに合わず不自然", "の": "修飾の助詞にすると文の成り立ちが合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
