INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36651, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある出来事が行われている、特定の状況や場所", "primary_collocate": null, "pronunciation": "ばめん", "ipa": "bameɴ", "syllable_count": 3, "sentences": [{"text": "小説の中に、雪の降る場面が出てきます。", "target_word": "場面", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の中[なか]に、雪[ゆき]の降[ふ]る場面[ばめん]が出[で]てきます。", "sentence_source": "generated"}, {"text": "戦いの場面では、大きな音楽が流れます。", "target_word": "場面", "complexity_tier": "T3", "furigana": "戦[たたか]いの場面[ばめん]では、大[おお]きな音楽[おんがく]が流[なが]れます。", "sentence_source": "generated"}, {"text": "結婚式の場面を、カメラマンが撮影しました。", "target_word": "場面", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]の場面[ばめん]を、カメラマンが撮影[さつえい]しました。", "sentence_source": "generated"}, {"text": "劇の最後の場面で、幕がゆっくり下りました。", "target_word": "場面", "complexity_tier": "T3", "furigana": "劇[げき]の最後[さいご]の場面[ばめん]で、幕[まく]がゆっくり下[お]りました。", "sentence_source": "generated"}, {"text": "謝る場面では、ていねいな言葉を選びましょう。", "target_word": "場面", "complexity_tier": "T3", "furigana": "謝[あやま]る場面[ばめん]では、ていねいな言葉[ことば]を選[えら]びましょう。", "sentence_source": "generated"}, {"text": "事件の場面を、目撃者が詳しく説明した。", "target_word": "場面", "complexity_tier": "T3", "furigana": "事件[じけん]の場面[ばめん]を、目撃者[もくげきしゃ]が詳[くわ]しく説明[せつめい]した。", "sentence_source": "generated"}, {"text": "彼は場面に合わせて、話し方を変えます。", "target_word": "場面", "complexity_tier": "T3", "furigana": "彼[かれ]は場面[ばめん]に合[あ]わせて、話[はな]し方[かた]を変[か]えます。", "sentence_source": "generated"}, {"text": "料理をする場面ばかり出てくる漫画を読んでいます。", "target_word": "場面", "complexity_tier": "T3", "furigana": "料理[りょうり]をする場面[ばめん]ばかり出[で]てくる漫画[まんが]を読[よ]んでいます。", "sentence_source": "generated"}, {"text": "会議の場面で使える表現を、メモしておきます。", "target_word": "場面", "complexity_tier": "T3", "furigana": "会議[かいぎ]の場面[ばめん]で使[つか]える表現[ひょうげん]を、メモしておきます。", "sentence_source": "generated"}, {"text": "昔見た映画の場面が、今も目にうかびます。", "target_word": "場面", "complexity_tier": "T3", "furigana": "昔[むかし]見[み]た映画[えいが]の場面[ばめん]が、今[いま]も目[め]にうかびます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "場面", "label": "基本形"}, {"form": "場面に", "label": "状況を表す形"}], "register": "neutral", "sense_fingerprint": "特定の出来事が行われている状況やシーン", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: うかび (Zipf 1.27)']::text[], '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36651, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人物", "is_correct": false, "explanation": "作品に登場する人を指し、雪の降る出来事を述べる文には合わない。"}, {"text": "題名", "is_correct": false, "explanation": "作品の名前の意味で、雪の降る出来事が出てくる文には合わない。"}, {"text": "場面", "is_correct": true, "explanation": "作品の中の特定の出来事のシーンを表し、雪の降る場面が出てくるという文に合う。"}, {"text": "作者", "is_correct": false, "explanation": "作品をつくった人を指すので、場面が出てくる文には合わない。"}], "explanations": {"人物": "作品に登場する人を指し、雪の降る出来事を述べる文には合わない。", "題名": "作品の名前の意味で、雪の降る出来事が出てくる文には合わない。", "場面": "作品の中の特定の出来事のシーンを表し、雪の降る場面が出てくるという文に合う。", "作者": "作品をつくった人を指すので、場面が出てくる文には合わない。"}, "sentence_index": 0, "correct_answer": "場面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この部屋は場面が広いので、人が集まれます。", "explanation": "ここは〈広さ〉の意味。場面は特定の出来事の様子を指し、部屋の広さには使わないので誤り。"}, {"text": "この店は場面が安いので、学生に人気です。", "explanation": "ここは〈値段〉の意味。場面は出来事の様子を指すので、価格の話には使わない。"}, {"text": "この店は場面がよくて、居心地がいい。", "explanation": "ここは〈雰囲気〉の意味。店の空気を表す雰囲気を使い、出来事の様子を指す場面は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36651, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "予算", "is_correct": false, "explanation": "お金の枠を表すので、話し方を状況に合わせる文には合わない。"}, {"text": "場面", "is_correct": true, "explanation": "そのときの状況を表し、状況に合わせて話し方を変えるという文に合う。"}, {"text": "楽譜", "is_correct": false, "explanation": "音楽の記号を書いたものなので、話し方を合わせる文には合わない。"}, {"text": "暗号", "is_correct": false, "explanation": "秘密の文字の規則を指すので、話し方の調整を述べる文には合わない。"}], "explanations": {"予算": "お金の枠を表すので、話し方を状況に合わせる文には合わない。", "場面": "そのときの状況を表し、状況に合わせて話し方を変えるという文に合う。", "楽譜": "音楽の記号を書いたものなので、話し方を合わせる文には合わない。", "暗号": "秘密の文字の規則を指すので、話し方の調整を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "場面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は場面がいいので、散歩しましょう。", "explanation": "ここは〈天気〉の意味。場面は出来事の様子を指すので、空模様には使わないので誤り。"}, {"text": "最近は場面が悪いので、休んでいます。", "explanation": "ここは〈体調〉の意味。場面は出来事の様子を指すので、からだの調子には使わない。"}, {"text": "この包丁は場面がよく切れて、料理が早くできます。", "explanation": "ここは〈切れ味〉の意味。刃物の鋭さを表す切れ味を使い、出来事の様子を指す場面は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36651, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事故の場面に思い出すと、苦しくなります。", "corrected_sentence": "事故の場面を思い出すと、苦しくなります。", "error_description": "「思い出す」は目的語に「を」を取るので、正しくは「場面を」。「に」にすると思い出す対象を示せず、不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36651, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪の降る場面が見ると、切なくなります。", "corrected_sentence": "雪の降る場面を見ると、切なくなります。", "error_description": "「場面」の直後の助詞「が」を「を」に直す誤り。「見る」は目的語に「を」を取るので、主語の「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36652, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「故障が」は主語を示し、故障が頻発するという文の関係に合う。"}, {"text": "を", "is_correct": false, "explanation": "頻発は自動詞なので目的語の「を」は取らず、「故障を頻発する」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「故障に頻発する」では方向や相手を示す形になり、主語と述語の関係が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「故障と頻発する」は並列の形で、頻発の主語にならず文が通らない。"}], "correct_answer": "が", "explanations": {"が": "「故障が」は主語を示し、故障が頻発するという文の関係に合う。", "を": "頻発は自動詞なので目的語の「を」は取らず、「故障を頻発する」は不自然。", "に": "「故障に頻発する」では方向や相手を示す形になり、主語と述語の関係が成り立たない。", "と": "「故障と頻発する」は並列の形で、頻発の主語にならず文が通らない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36652, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「火災が」は主語を示し、火災が頻発したという文の関係に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「火災へ頻発した」は方向を示す形で、火災と頻発の主語関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は頻発と結べず、「火災より頻発した」は文が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では火災を主語として示せず、「火災から頻発した」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「火災が」は主語を示し、火災が頻発したという文の関係に合う。", "へ": "「火災へ頻発した」は方向を示す形で、火災と頻発の主語関係が成り立たない。", "より": "比較の「より」は頻発と結べず、「火災より頻発した」は文が通らない。", "から": "起点の「から」では火災を主語として示せず、「火災から頻発した」は意味が通らない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36652, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "同じことが何度も起きること。", "primary_collocate": null, "pronunciation": "ひんぱつ", "ipa": "çimpatsɯ", "syllable_count": 4, "sentences": [{"text": "ここ数年、この交差点では交通事故が頻発している。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "ここ数年[すうねん]、この交差点[こうさてん]では交通[こうつう]事故[じこ]が頻発[ひんぱつ]している。", "sentence_source": "generated"}, {"text": "古い機械は故障が頻発するので、新しいものに替えることにした。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "古[ふる]い機械[きかい]は故障[こしょう]が頻発[ひんぱつ]するので、新[あたら]しいものに替[か]えることにした。", "sentence_source": "generated"}, {"text": "この地域では毎年、秋に台風による水害が頻発する。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "この地域[ちいき]では毎年[まいとし]、秋[あき]に台風[たいふう]による水害[すいがい]が頻発[ひんぱつ]する。", "sentence_source": "generated"}, {"text": "通信障害が頻発したため、会社は原因の調査を始めた。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "通信[つうしん]障害[しょうがい]が頻発[ひんぱつ]したため、会社[かいしゃ]は原因[げんいん]の調査[ちょうさ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "最近、詐欺の電話が頻発しており、市は注意をよびかけている。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "最近[さいきん]、詐欺[さぎ]の電話[でんわ]が頻発[ひんぱつ]しており、市[し]は注意[ちゅうい]をよびかけている。", "sentence_source": "generated"}, {"text": "トラブルの頻発に悩んだ店長は、作業の手順を見直した。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "トラブルの頻発[ひんぱつ]に悩[なや]んだ店長[てんちょう]は、作業[さぎょう]の手順[てじゅん]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "工事のミスが頻発しているのは、人手が足りないからだ。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "工事[こうじ]のミスが頻発[ひんぱつ]しているのは、人手[ひとで]が足[た]りないからだ。", "sentence_source": "generated"}, {"text": "同じ型の車で火災が頻発したので、会社は製品を回収した。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "同[おな]じ型[かた]の車[くるま]で火災[かさい]が頻発[ひんぱつ]したので、会社[かいしゃ]は製品[せいひん]を回収[かいしゅう]した。", "sentence_source": "generated"}, {"text": "地震が頻発する国では、学校で避難の訓練を何度も行う。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "地震[じしん]が頻発[ひんぱつ]する国[くに]では、学校[がっこう]で避難[ひなん]の訓練[くんれん]を何度[なんど]も行[おこな]う。", "sentence_source": "generated"}, {"text": "事故の頻発を防ぐには、原因を一つずつ調べるしかない。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "事故[じこ]の頻発[ひんぱつ]を防[ふせ]ぐには、原因[げんいん]を一[ひと]つずつ調[しら]べるしかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頻発", "label": "基本形"}, {"form": "頻発する", "label": "サ変動詞"}, {"form": "頻発している", "label": "継続形"}, {"form": "頻発した", "label": "過去形"}], "register": "書き言葉・硬い文体", "sense_fingerprint": "事故やトラブルなど同じことが繰り返し起きる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36652, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頻発", "is_correct": true, "explanation": "「交通事故が頻発している」は、同じ事故が何度も起きているという意味に合い、空欄に入る。"}, {"text": "防止", "is_correct": false, "explanation": "「事故が防止している」では、事故自身が何かを防ぐことになり意味が通らない。防止は人が事故を防ぐ行為。"}, {"text": "点検", "is_correct": false, "explanation": "点検は人や機関が行う確認作業なので、「交通事故が点検している」は主語と動詞が合わない。"}, {"text": "修復", "is_correct": false, "explanation": "修復は壊れたものを直す意味で、事故を主語にすると直す対象にならず、文が成り立たない。"}], "explanations": {"頻発": "「交通事故が頻発している」は、同じ事故が何度も起きているという意味に合い、空欄に入る。", "防止": "「事故が防止している」では、事故自身が何かを防ぐことになり意味が通らない。防止は人が事故を防ぐ行為。", "点検": "点検は人や機関が行う確認作業なので、「交通事故が点検している」は主語と動詞が合わない。", "修復": "修復は壊れたものを直す意味で、事故を主語にすると直す対象にならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "頻発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場は部品を頻発して注文したので、倉庫があふれた。", "explanation": "注文を大量に出す場面だが、頻発は出来事が繰り返し起きる意味で、注文の行為には使えないので合わない。"}, {"text": "その祭りは、年に一度だけ頻発する。", "explanation": "年に一度の行事は、同じことが何度も起きる頻発の意味に合わない。"}, {"text": "政府の補助金が一度だけ頻発して、すぐ終わった。", "explanation": "ここは〈乱発〉の意味。制度や支給を次々と出す意味で、頻発は同じことが何度も起きる意味なので、一度きりの制度には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36652, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頻発", "is_correct": true, "explanation": "「工事のミスが頻発しているのは」は、ミスが繰り返し起きているという意味で、空欄に入る。"}, {"text": "完了", "is_correct": false, "explanation": "完了は作業などが終わることで、「工事のミスが完了している」は意味が通らない。"}, {"text": "修正", "is_correct": false, "explanation": "修正は誰かが直す行為なので、ミスを主語にして「修正している」と言うと文が成り立たない。"}, {"text": "反省", "is_correct": false, "explanation": "反省は人が自分の行いを振り返ることなので、ミスを主語にすると合わない。"}], "explanations": {"頻発": "「工事のミスが頻発しているのは」は、ミスが繰り返し起きているという意味で、空欄に入る。", "完了": "完了は作業などが終わることで、「工事のミスが完了している」は意味が通らない。", "修正": "修正は誰かが直す行為なので、ミスを主語にして「修正している」と言うと文が成り立たない。", "反省": "反省は人が自分の行いを振り返ることなので、ミスを主語にすると合わない。"}, "sentence_index": 6, "correct_answer": "頻発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月、この町では火災が一度だけ頻発した。", "explanation": "ここは〈発生〉の意味。頻発は同じことが何度も起きる意味なので、一度だけの出来事には合わない。"}, {"text": "この単語は試験によく頻発するので、覚えておこう。", "explanation": "試験で繰り返し現れる場合は頻出を使う。頻発は事故や故障など、出来事が繰り返し起きる場合に使う。"}, {"text": "この池ではコイが一年で頻発して、数が増えすぎた。", "explanation": "生き物の数が増える場合は繁殖を使い、頻発は出来事が繰り返す意味で数の増加には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36652, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近、この道では事故を頻発している。", "corrected_sentence": "最近、この道では事故が頻発している。", "error_description": "「頻発」は自動詞で、起きる出来事は「が」で示す。「事故を頻発している」は「を」が不自然で、正しくは「事故が頻発している」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36652, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週、雨の日に事故が頻発している。", "corrected_sentence": "先週、雨の日に事故が頻発した。", "error_description": "「先週」は過去を表すので、「頻発している」（継続）ではなく「頻発した」（過去）が正しい。誤りは「頻発」の活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36653, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「地震が」は主語を示し、地震が頻発したという文の関係に合う。"}, {"text": "を", "is_correct": false, "explanation": "頻発は自動詞なので目的語の「を」は取らず、「地震を頻発して」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「地震に頻発して」では頻発の主語が示せず、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「地震と頻発して」は並列の形で、頻発の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「地震が」は主語を示し、地震が頻発したという文の関係に合う。", "を": "頻発は自動詞なので目的語の「を」は取らず、「地震を頻発して」は不自然。", "に": "「地震に頻発して」では頻発の主語が示せず、文が通らない。", "と": "「地震と頻発して」は並列の形で、頻発の主語にならない。"}, "error_tags": {}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36653, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「フリーズが」は主語を示し、フリーズが頻発したという文の関係に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「フリーズへ頻発して」は方向を示す形で、主語と述語が結べない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は頻発と結べず、「フリーズより頻発して」は文が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では頻発の主語を示せず、「フリーズから頻発して」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「フリーズが」は主語を示し、フリーズが頻発したという文の関係に合う。", "へ": "「フリーズへ頻発して」は方向を示す形で、主語と述語が結べない。", "より": "比較の「より」は頻発と結べず、「フリーズより頻発して」は文が通らない。", "から": "起点の「から」では頻発の主語を示せず、「フリーズから頻発して」は不自然。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36653, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "同じことが短い間に何度も起こること。", "primary_collocate": null, "pronunciation": "ひんぱつ", "ipa": "çimpatsɯ", "syllable_count": 4, "sentences": [{"text": "今週は数日の間に停電が頻発し、店は営業を休んだ。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "今週[こんしゅう]は数日[すうじつ]の間[あいだ]に停電[ていでん]が頻発[ひんぱつ]し、店[みせ]は営業[えいぎょう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "一晩のうちに小さな地震が頻発して、住民はよく眠れなかった。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "一晩[ひとばん]のうちに小[ちい]さな地震[じしん]が頻発[ひんぱつ]して、住民[じゅうみん]はよく眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "開店直後にレジの故障が頻発し、客は長く待たされた。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "開店[かいてん]直後[ちょくご]にレジの故障[こしょう]が頻発[ひんぱつ]し、客[きゃく]は長[なが]く待[ま]たされた。", "sentence_source": "generated"}, {"text": "梅雨の時期は短い間に雷雨が頻発するので、外出に注意が必要だ。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "梅雨[つゆ]の時期[じき]は短[みじか]い間[あいだ]に雷雨[らいう]が頻発[ひんぱつ]するので、外出[がいしゅつ]に注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "試合の終盤にミスが頻発し、チームは逆転された。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "試合[しあい]の終盤[しゅうばん]にミスが頻発[ひんぱつ]し、チームは逆転[ぎゃくてん]された。", "sentence_source": "generated"}, {"text": "大会の直前に練習中のけがが頻発して、監督は日程を変えた。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "大会[たいかい]の直前[ちょくぜん]に練習[れんしゅう]中[ちゅう]のけがが頻発[ひんぱつ]して、監督[かんとく]は日程[にってい]を変[か]えた。", "sentence_source": "generated"}, {"text": "昨日だけで同じ内容の苦情が頻発し、窓口の電話が鳴り止まなかった。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "昨日[きのう]だけで同[おな]じ内容[ないよう]の苦情[くじょう]が頻発[ひんぱつ]し、窓口[まどぐち]の電話[でんわ]が鳴[な]り止[や]まなかった。", "sentence_source": "generated"}, {"text": "数日間、画面のフリーズが頻発して、仕事が進まなかった。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "数日間[すうじつかん]、画面[がめん]のフリーズが頻発[ひんぱつ]して、仕事[しごと]が進[すす]まなかった。", "sentence_source": "generated"}, {"text": "雪の日は短時間で追突事故が頻発し、道路が通れなくなった。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は短時間[たんじかん]で追突[ついとつ]事故[じこ]が頻発[ひんぱつ]し、道路[どうろ]が通[とお]れなくなった。", "sentence_source": "generated"}, {"text": "先月は一週間のうちに小さな火事が頻発し、消防署が警戒を強めた。", "target_word": "頻発", "complexity_tier": "T3", "furigana": "先月[せんげつ]は一週間[いっしゅうかん]のうちに小[ちい]さな火事[かじ]が頻発[ひんぱつ]し、消防署[しょうぼうしょ]が警戒[けいかい]を強[つよ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頻発", "label": "基本形"}, {"form": "頻発する", "label": "サ変動詞"}, {"form": "頻発している", "label": "継続形"}, {"form": "頻発した", "label": "過去形"}], "register": "書き言葉・硬い文体", "sense_fingerprint": "短期間に同じことが立て続けに起こる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36653, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頻発", "is_correct": true, "explanation": "「停電が頻発し」は、短い期間に同じことが立て続けに起きたという意味で、空欄に入る。"}, {"text": "点検", "is_correct": false, "explanation": "点検は人が機器を調べる行為なので、「停電が点検し」では主語と動詞が合わない。"}, {"text": "修理", "is_correct": false, "explanation": "修理は壊れた物を直す行為で、停電を主語にすると文が成り立たない。"}, {"text": "注意", "is_correct": false, "explanation": "注意は人が気をつける行為なので、「停電が注意し」では意味が通らない。"}], "explanations": {"頻発": "「停電が頻発し」は、短い期間に同じことが立て続けに起きたという意味で、空欄に入る。", "点検": "点検は人が機器を調べる行為なので、「停電が点検し」では主語と動詞が合わない。", "修理": "修理は壊れた物を直す行為で、停電を主語にすると文が成り立たない。", "注意": "注意は人が気をつける行為なので、「停電が注意し」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "頻発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "非常時の権限が、一度きりで頻発した。", "explanation": "権限を働かせる場面だが、頻発は同じことが何度も起きる意味なので、一度きりの権限には合わない。"}, {"text": "店の材料が、毎週一度だけ頻発している。", "explanation": "材料の補充は注文を出す行為で、頻発は出来事が繰り返し起きる意味なので合わない。"}, {"text": "同じ練習が一度きりで頻発した。", "explanation": "練習を意図して繰り返す場面で、頻発は意図しない出来事に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36653, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頻発", "is_correct": true, "explanation": "「苦情が頻発し」は、同じ内容の苦情が続けて起きたという意味で、空欄に入る。"}, {"text": "謝罪", "is_correct": false, "explanation": "謝罪は人が詫びる行為なので、「苦情が謝罪し」では主語と動詞が合わない。"}, {"text": "集計", "is_correct": false, "explanation": "集計は数を数えてまとめる行為で、「苦情が集計し」は文が成り立たない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案などを評価する行為なので、苦情を主語にすると意味が通らない。"}], "explanations": {"頻発": "「苦情が頻発し」は、同じ内容の苦情が続けて起きたという意味で、空欄に入る。", "謝罪": "謝罪は人が詫びる行為なので、「苦情が謝罪し」では主語と動詞が合わない。", "集計": "集計は数を数えてまとめる行為で、「苦情が集計し」は文が成り立たない。", "採点": "採点は答案などを評価する行為なので、苦情を主語にすると意味が通らない。"}, "sentence_index": 6, "correct_answer": "頻発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究所で、新しい薬が一度だけ頻発した。", "explanation": "新しい薬を生み出す場面だが、頻発は同じ出来事が何度も起きる意味で、開発の場面には合わない。"}, {"text": "市の広報誌は、年に一度だけ頻発する。", "explanation": "刊行物を定期的に世に出す場面で、頻発は出来事が繰り返す意味なので合わない。"}, {"text": "大会の本番で、ミスが一度だけ頻発した。", "explanation": "ここは〈発生〉の意味。頻発は同じことが何度も起きる意味で、一度だけの出来事には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36653, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨夜、短い間に停電が頻発している。", "corrected_sentence": "昨夜、短い間に停電が頻発した。", "error_description": "「昨夜」は過去を表すので、「頻発している」ではなく「頻発した」が正しい。誤りは「頻発」の活用形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36653, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "数日の間に大雨が頻発を、川が増水した。", "corrected_sentence": "数日の間に大雨が頻発し、川が増水した。", "error_description": "「頻発」はサ変名詞で「頻発し」「頻発する」の形で動詞句を作る。「頻発を」の「を」は付かず、「し」と続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
