INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36654, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "function", "definition": "いつも同じ状態を保とうとするはたらきのこと。", "primary_collocate": null, "pronunciation": "こうじょう", "ipa": "koːdʑoː", "syllable_count": 4, "sentences": [{"text": "体には、外の気温が変わっても体温の恒常を保とうとする働きがある。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "体[からだ]には、外[そと]の気温[きおん]が変[か]わっても体温[たいおん]の恒常[こうじょう]を保[たも]とうとする働[はたら]きがある。", "sentence_source": "generated"}, {"text": "汗をかくのは、体温の恒常を守るための仕組みの一つである。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "汗[あせ]をかくのは、体温[たいおん]の恒常[こうじょう]を守[まも]るための仕組[しく]みの一[ひと]つである。", "sentence_source": "generated"}, {"text": "血糖値の恒常が乱れると、のどが渇いて疲れやすくなる。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "血糖値[けっとうち]の恒常[こうじょう]が乱[みだ]れると、のどが渇[かわ]いて疲[つか]れやすくなる。", "sentence_source": "generated"}, {"text": "体内環境の恒常は、ホルモンと神経の働きで支えられている。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "体内[たいない]環境[かんきょう]の恒常[こうじょう]は、ホルモンと神経[しんけい]の働[はたら]きで支[ささ]えられている。", "sentence_source": "generated"}, {"text": "暑い部屋にいても体温が変わらないのは、恒常のはたらきがあるからだ。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "暑[あつ]い部屋[へや]にいても体温[たいおん]が変[か]わらないのは、恒常[こうじょう]のはたらきがあるからだ。", "sentence_source": "generated"}, {"text": "長い断食の間も、体は血液の成分の恒常を維持しようとする。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "長[なが]い断食[だんじき]の間[あいだ]も、体[からだ]は血液[けつえき]の成分[せいぶん]の恒常[こうじょう]を維持[いじ]しようとする。", "sentence_source": "generated"}, {"text": "病気になると、体の恒常が崩れて熱が出ることがある。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "病気[びょうき]になると、体[からだ]の恒常[こうじょう]が崩[くず]れて熱[ねつ]が出[で]ることがある。", "sentence_source": "generated"}, {"text": "水分が不足すると、体は恒常を保つために尿の量を減らす。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "水分[すいぶん]が不足[ふそく]すると、体[からだ]は恒常[こうじょう]を保[たも]つために尿[にょう]の量[りょう]を減[へ]らす。", "sentence_source": "generated"}, {"text": "生物は外の変化に対して、内部の恒常を守りながら生きている。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "生物[せいぶつ]は外[そと]の変化[へんか]に対[たい]して、内部[ないぶ]の恒常[こうじょう]を守[まも]りながら生[い]きている。", "sentence_source": "generated"}, {"text": "恒常のはたらきが弱まった高齢者は、暑さの影響を受けやすい。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "恒常[こうじょう]のはたらきが弱[よわ]まった高齢者[こうれいしゃ]は、暑[あつ]さの影響[えいきょう]を受[う]けやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "恒常", "label": "基本形"}, {"form": "恒常の", "label": "連体形(の)"}], "register": "書き言葉・硬い文体", "sense_fingerprint": "体内環境などを一定に保とうとする働き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36654, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恒常", "is_correct": true, "explanation": "「体温の恒常を保とう」は、体温を一定に保つ働きという意味に合い、空欄に入る。"}, {"text": "変動", "is_correct": false, "explanation": "変動は変わり動くことなので、「体温の変動を保とう」は保つ対象として意味が逆になり通らない。"}, {"text": "誤差", "is_correct": false, "explanation": "誤差は測定値のずれを表すので、保つ対象にはならず「誤差を保とう」は成り立たない。"}, {"text": "拡大", "is_correct": false, "explanation": "拡大は広がることなので、「体温の拡大を保とう」では意味が合わない。"}], "explanations": {"恒常": "「体温の恒常を保とう」は、体温を一定に保つ働きという意味に合い、空欄に入る。", "変動": "変動は変わり動くことなので、「体温の変動を保とう」は保つ対象として意味が逆になり通らない。", "誤差": "誤差は測定値のずれを表すので、保つ対象にはならず「誤差を保とう」は成り立たない。", "拡大": "拡大は広がることなので、「体温の拡大を保とう」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "恒常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "恒常は夜空で何億年も光を放ち続ける。", "explanation": "「恒星」の文だが、恒常は天体を表す語ではない。"}, {"text": "恒常によって、体は食べ物からエネルギーを作る。", "explanation": "食べ物をエネルギーに変える過程は「代謝」と言い、恒常は体の状態を保つ働きを指すので合わない。"}, {"text": "血液の恒常によって、酸素が全身に運ばれる。", "explanation": "血液が体内を巡る働きは「循環」と言い、恒常は体の状態を保つ働きを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36654, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恒常", "is_correct": true, "explanation": "「体の恒常が崩れて」は、体内の状態を一定に保つ働きが乱れるという意味に合い、空欄に入る。"}, {"text": "老化", "is_correct": false, "explanation": "老化は年を重ねて衰えることで、「体の老化が崩れて」は意味が通らない。"}, {"text": "分裂", "is_correct": false, "explanation": "分裂は一つのものが割れることで、「体の分裂が崩れて」は文が成り立たない。"}, {"text": "停止", "is_correct": false, "explanation": "停止は動きが止まることで、「体の停止が崩れて」は意味が合わない。"}], "explanations": {"恒常": "「体の恒常が崩れて」は、体内の状態を一定に保つ働きが乱れるという意味に合い、空欄に入る。", "老化": "老化は年を重ねて衰えることで、「体の老化が崩れて」は意味が通らない。", "分裂": "分裂は一つのものが割れることで、「体の分裂が崩れて」は文が成り立たない。", "停止": "停止は動きが止まることで、「体の停止が崩れて」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "恒常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電気の恒常によって、ランプが光る。", "explanation": "電気を光に変える働きは「変換」と言い、恒常は同じ状態を保つ働きを指すので合わない。"}, {"text": "化学の恒常によって、液の色が変わる。", "explanation": "物質が変わる過程は「反応」と言い、同じ状態を保つ働きの恒常には合わない。"}, {"text": "鍋の恒常によって、スープが冷めない。", "explanation": "熱を逃さず温かさを保つ行為は「保温」と言い、恒常の働きとは別語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36654, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "血糖を恒常を守る仕組みがある。", "corrected_sentence": "血糖の恒常を守る仕組みがある。", "error_description": "「恒常」は名詞で、直前の「血糖」とは「の」で結ぶ。「血糖を」と「を」にすると文の関係が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36654, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い日も、恒常を働きで体温は保たれる。", "corrected_sentence": "寒い日も、恒常の働きで体温は保たれる。", "error_description": "「恒常」は名詞で、「働き」と結ぶには「の」を使う。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36655, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "変化", "is_correct": true, "explanation": "変化は変わり続けることで、変わらず続く意味の恒常と対になる対義語。"}, {"text": "慣習", "is_correct": false, "explanation": "慣習は昔から続くならわしのことで、恒常の対義語ではない。"}, {"text": "順序", "is_correct": false, "explanation": "順序は物事の並び方を表し、恒常と対になる語ではない。"}, {"text": "規模", "is_correct": false, "explanation": "規模は大きさの程度を表し、恒常と反対の関係にはならない。"}], "correct_answer": "変化", "explanations": {"変化": "変化は変わり続けることで、変わらず続く意味の恒常と対になる対義語。", "慣習": "慣習は昔から続くならわしのことで、恒常の対義語ではない。", "順序": "順序は物事の並び方を表し、恒常と対になる語ではない。", "規模": "規模は大きさの程度を表し、恒常と反対の関係にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36655, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "変化", "is_correct": true, "explanation": "変化は変わり続けることで、変わらず続く意味の恒常と対になる対義語。"}, {"text": "規則", "is_correct": false, "explanation": "規則は守るべききまりのことで、恒常と反対の関係にはならない。"}, {"text": "所在", "is_correct": false, "explanation": "所在はものがある場所を表し、恒常と対になる語ではない。"}, {"text": "配置", "is_correct": false, "explanation": "配置は物を並べて置くことで、恒常の対義語ではない。"}], "correct_answer": "変化", "explanations": {"変化": "変化は変わり続けることで、変わらず続く意味の恒常と対になる対義語。", "規則": "規則は守るべききまりのことで、恒常と反対の関係にはならない。", "所在": "所在はものがある場所を表し、恒常と対になる語ではない。", "配置": "配置は物を並べて置くことで、恒常の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36655, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物事の状態が変わらずに続くこと。また、その性質。", "primary_collocate": null, "pronunciation": "こうじょう", "ipa": "koːdʑoː", "syllable_count": 4, "sentences": [{"text": "この川の水温は一年中ほとんど変わらず、恒常を保っている。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "この川[かわ]の水温[すいおん]は一年中[いちねんじゅう]ほとんど変[か]わらず、恒常[こうじょう]を保[たも]っている。", "sentence_source": "generated"}, {"text": "この値は、どの条件でも恒常を保つことが実験で確かめられた。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "この値は、どの条件でも恒常[こうじょう]を保つことが実験で確かめられた。", "sentence_source": "generated"}, {"text": "哲学者は、移り変わる世界の中の恒常を探し求めた。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "哲学者[てつがくしゃ]は、移[うつ]り変[か]わる世界[せかい]の中[なか]の恒常[こうじょう]を探[さが]し求[もと]めた。", "sentence_source": "generated"}, {"text": "恒常と変化は反対の考え方として、よく比べられる。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "恒常[こうじょう]と変化[へんか]は反対[はんたい]の考[かんが]え方[かた]として、よく比[くら]べられる。", "sentence_source": "generated"}, {"text": "気温の恒常がこの島の特徴で、冬でも夏と変わらない。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "気温[きおん]の恒常[こうじょう]がこの島[しま]の特徴[とくちょう]で、冬[ふゆ]でも夏[なつ]と変[か]わらない。", "sentence_source": "generated"}, {"text": "老舗の店は、味の恒常を何より大切にしている。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "老舗[しにせ]の店[みせ]は、味[あじ]の恒常[こうじょう]を何[なに]より大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "季節ごとに収入が変わるため、生活の恒常は望めない。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "季節[きせつ]ごとに収入[しゅうにゅう]が変[か]わるため、生活[せいかつ]の恒常[こうじょう]は望[のぞ]めない。", "sentence_source": "generated"}, {"text": "法則の恒常を信じるからこそ、科学者は実験をくり返す。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "法則[ほうそく]の恒常[こうじょう]を信[しん]じるからこそ、科学者[かがくしゃ]は実験[じっけん]をくり返[かえ]す。", "sentence_source": "generated"}, {"text": "物価の恒常が失われ、買い物の予定が立てにくくなった。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "物価[ぶっか]の恒常[こうじょう]が失[うしな]われ、買[か]い物[もの]の予定[よてい]が立[た]てにくくなった。", "sentence_source": "generated"}, {"text": "恒常を重んじる文化では、古い習慣が長く守られる。", "target_word": "恒常", "complexity_tier": "T3", "furigana": "恒常[こうじょう]を重[おも]んじる文化[ぶんか]では、古[ふる]い習慣[しゅうかん]が長[なが]く守[まも]られる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "恒常", "label": "基本形"}, {"form": "恒常の", "label": "連体形(の)"}], "register": "書き言葉・硬い文体", "sense_fingerprint": "状態が変わらず続くこと・その性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '546220dd-468e-4d38-9f83-4f30b18313f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36655, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恒常", "is_correct": true, "explanation": "「水温は恒常を保っている」は、変わらない状態を続けるという意味に合い、空欄に入る。"}, {"text": "振動", "is_correct": false, "explanation": "振動は揺れ動くことなので、保つ対象として「振動を保っている」は意味が合わない。"}, {"text": "誤差", "is_correct": false, "explanation": "誤差はずれの大きさを表すので、「誤差を保っている」は文が成り立たない。"}, {"text": "流動", "is_correct": false, "explanation": "流動は流れ動くことなので、変わらず保つ内容として「流動を保っている」は意味が合わない。"}], "explanations": {"恒常": "「水温は恒常を保っている」は、変わらない状態を続けるという意味に合い、空欄に入る。", "振動": "振動は揺れ動くことなので、保つ対象として「振動を保っている」は意味が合わない。", "誤差": "誤差はずれの大きさを表すので、「誤差を保っている」は文が成り立たない。", "流動": "流動は流れ動くことなので、変わらず保つ内容として「流動を保っている」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "恒常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "恒常は北の空で一晩中輝いている。", "explanation": "「恒星」の文だが、恒常は天体を表す語ではない。"}, {"text": "電気を光に変換する恒常が、この機械の仕組みだ。", "explanation": "電気を光に変える過程は「変換」と言い、恒常は変わらず続く状態を指すので合わない。"}, {"text": "恒常によって、食べ物は体内でエネルギーに変わる。", "explanation": "食べ物をエネルギーに変える過程は「代謝」と言い、恒常の意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36655, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恒常", "is_correct": true, "explanation": "「生活の恒常は望めない」は、変わらない安定が得られないという意味に合い、空欄に入る。"}, {"text": "残高", "is_correct": false, "explanation": "残高は口座などに残った金額のことで、「生活の残高は望めない」は意味が通らない。"}, {"text": "公転", "is_correct": false, "explanation": "公転は天体が周りを回ることで、生活を主語にすると意味が合わない。"}, {"text": "結合", "is_correct": false, "explanation": "結合はものを結びつけることで、「生活の結合は望めない」は文の意味が合わない。"}], "explanations": {"恒常": "「生活の恒常は望めない」は、変わらない安定が得られないという意味に合い、空欄に入る。", "残高": "残高は口座などに残った金額のことで、「生活の残高は望めない」は意味が通らない。", "公転": "公転は天体が周りを回ることで、生活を主語にすると意味が合わない。", "結合": "結合はものを結びつけることで、「生活の結合は望めない」は文の意味が合わない。"}, "sentence_index": 6, "correct_answer": "恒常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "化学の恒常によって、液の色が変わる。", "explanation": "物質が変わる過程は「反応」と言い、変わらず続く状態を指す恒常には合わない。"}, {"text": "鍋の恒常によって、スープが冷めない。", "explanation": "熱を保つ行為は「保温」と言い、恒常の意味には合わない。"}, {"text": "血液の恒常によって、酸素が全身に運ばれる。", "explanation": "血液が巡る働きは「循環」と言い、恒常の意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36655, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この川の水温は、季節を問わず恒常している。", "corrected_sentence": "この川の水温は、季節を問わず恒常を保っている。", "error_description": "「恒常」は名詞で、「保つ」と組んで使うのが自然。「恒常している」とは言わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36655, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この国の経済を恒常が、人々の安心を支えている。", "corrected_sentence": "この国の経済の恒常が、人々の安心を支えている。", "error_description": "「恒常」は名詞で、直前の「経済」とは「の」で結ぶ。「経済を」と「を」にすると文の関係が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '723beb0a-91e1-4a1c-9cea-c7d6308197af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36656, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「価格を維持する」の『を』。価格が維持の対象になるので、直前にこの助詞が入る。"}, {"text": "が", "is_correct": false, "explanation": "「価格が維持するため」は価格が維持する主体になり、意味が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。「価格へ維持する」は対象を表せず成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示す。「価格から維持する」は維持の対象を表せないので不適切。"}], "correct_answer": "を", "explanations": {"を": "「価格を維持する」の『を』。価格が維持の対象になるので、直前にこの助詞が入る。", "が": "「価格が維持するため」は価格が維持する主体になり、意味が不自然になる。", "へ": "『へ』は方向を示す。「価格へ維持する」は対象を表せず成り立たない。", "から": "『から』は起点を示す。「価格から維持する」は維持の対象を表せないので不適切。"}, "error_tags": {"が": "主語を示す", "へ": "方向を示す", "から": "起点を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36656, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「体重を維持したい」の『を』。体重が維持の対象になるので、直前にこの助詞が入る。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や相手を示す。「体重と維持したい」は対象を表せず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示す。「体重より維持したい」は比べる文脈がなく、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示す。「体重で維持したい」は維持の対象を表せず不自然。"}], "correct_answer": "を", "explanations": {"を": "「体重を維持したい」の『を』。体重が維持の対象になるので、直前にこの助詞が入る。", "と": "『と』は並列や相手を示す。「体重と維持したい」は対象を表せず、文が成り立たない。", "より": "『より』は比較を示す。「体重より維持したい」は比べる文脈がなく、意味が通らない。", "で": "『で』は手段や場所を示す。「体重で維持したい」は維持の対象を表せず不自然。"}, "error_tags": {"と": "並列を示す", "より": "比較を示す", "で": "手段を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36656, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "同じ状態を続けること。", "primary_collocate": null, "pronunciation": "いじ", "ipa": "idʑi", "syllable_count": 2, "sentences": [{"text": "健康を維持するために、毎朝三十分歩いている。", "target_word": "維持", "complexity_tier": "T3", "furigana": "健康[けんこう]を維持[いじ]するために、毎朝[まいあさ]三十分[さんじゅっぷん]歩[ある]いている。", "sentence_source": "generated"}, {"text": "この店は低い価格を維持するため、材料を大量に買っている。", "target_word": "維持", "complexity_tier": "T3", "furigana": "この店[みせ]は低[ひく]い価格[かかく]を維持[いじ]するため、材料[ざいりょう]を大量[たいりょう]に買[か]っている。", "sentence_source": "generated"}, {"text": "部屋の温度を一定に維持するには、エアコンが必要だ。", "target_word": "維持", "complexity_tier": "T3", "furigana": "部屋[へや]の温度[おんど]を一定[いってい]に維持[いじ]するには、エアコンが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "古い橋の維持には、毎年多くのお金がかかる。", "target_word": "維持", "complexity_tier": "T3", "furigana": "古[ふる]い橋[はし]の維持[いじ]には、毎年[まいとし]多[おお]くのお金[かね]がかかる。", "sentence_source": "generated"}, {"text": "彼は一位の成績を維持して、奨学金をもらい続けた。", "target_word": "維持", "complexity_tier": "T3", "furigana": "彼[かれ]は一位[いちい]の成績[せいせき]を維持[いじ]して、奨学金[しょうがくきん]をもらい続[つづ]けた。", "sentence_source": "generated"}, {"text": "工事のおかげで、この道路の安全は維持されている。", "target_word": "維持", "complexity_tier": "T3", "furigana": "工事[こうじ]のおかげで、この道路[どうろ]の安全[あんぜん]は維持[いじ]されている。", "sentence_source": "generated"}, {"text": "現状を維持するだけでは、会社は大きくならない。", "target_word": "維持", "complexity_tier": "T3", "furigana": "現状[げんじょう]を維持[いじ]するだけでは、会社[かいしゃ]は大[おお]きくならない。", "sentence_source": "generated"}, {"text": "体重を維持したいので、夜はあまり食べない。", "target_word": "維持", "complexity_tier": "T3", "furigana": "体重[たいじゅう]を維持[いじ]したいので、夜[よる]はあまり食[た]べない。", "sentence_source": "generated"}, {"text": "平和を維持するために、各国が話し合いを続けている。", "target_word": "維持", "complexity_tier": "T3", "furigana": "平和[へいわ]を維持[いじ]するために、各国[かっこく]が話[はな]し合[あ]いを続[つづ]けている。", "sentence_source": "generated"}, {"text": "冷蔵庫は食べ物を低い温度に維持して、腐るのを防ぐ。", "target_word": "維持", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]は食[た]べ物[もの]を低[ひく]い温度[おんど]に維持[いじ]して、腐[くさ]るのを防[ふせ]ぐ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "維持する", "label": "辞書形"}, {"form": "維持した", "label": "過去形"}, {"form": "維持して", "label": "て形"}, {"form": "維持される", "label": "受身形"}, {"form": "維持できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "今の状態や水準が変わらないように保ち続けること（健康・価格・平和などを維持する）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36656, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "維持", "is_correct": true, "explanation": "「健康を維持するために」は『健康な状態を保つために』の意味で、この文に合う。"}, {"text": "解説", "is_correct": false, "explanation": "「健康を解説するために」は意味が通らない。解説は物事を説明する行為で、健康の状態には使えない。"}, {"text": "注文", "is_correct": false, "explanation": "「健康を注文するために」は不自然。注文は品物などを頼む行為で、状態を保つ意味とは合わない。"}, {"text": "出張", "is_correct": false, "explanation": "「健康を出張するために」は成り立たない。出張は仕事で他の場所へ行くことで、ここでは意味が合わない。"}], "explanations": {"維持": "「健康を維持するために」は『健康な状態を保つために』の意味で、この文に合う。", "解説": "「健康を解説するために」は意味が通らない。解説は物事を説明する行為で、健康の状態には使えない。", "注文": "「健康を注文するために」は不自然。注文は品物などを頼む行為で、状態を保つ意味とは合わない。", "出張": "「健康を出張するために」は成り立たない。出張は仕事で他の場所へ行くことで、ここでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "維持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大切な書類を金庫に維持しておく。", "explanation": "ここは〈保管〉の意味。維持は状態を保つことで、物を安全な場所に置いておく場合は〈保管する〉を使う。"}, {"text": "会議は三時間も維持した。", "explanation": "ここは〈継続〉の意味。維持は今の状態を保つことで、会議のような出来事が続いた場合は〈継続した〉を使う。"}, {"text": "重い箱を両手で維持して運んだ。", "explanation": "ここは〈支える〉の意味。維持は状態を保つことなので、重い物を手で支えて運ぶ動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36656, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "維持", "is_correct": true, "explanation": "「現状を維持するだけでは」は『今の状態を保つだけでは』の意味で、この文に合う。"}, {"text": "脱線", "is_correct": false, "explanation": "「現状を脱線するだけでは」は意味が通らない。脱線は本来の道筋から外れることで、状態には使えない。"}, {"text": "注射", "is_correct": false, "explanation": "「現状を注射するだけでは」は成り立たない。注射は薬などを体に入れる行為なので合わない。"}, {"text": "点滅", "is_correct": false, "explanation": "「現状を点滅するだけでは」は不自然。点滅は明かりがついたり消えたりすることで、ここには合わない。"}], "explanations": {"維持": "「現状を維持するだけでは」は『今の状態を保つだけでは』の意味で、この文に合う。", "脱線": "「現状を脱線するだけでは」は意味が通らない。脱線は本来の道筋から外れることで、状態には使えない。", "注射": "「現状を注射するだけでは」は成り立たない。注射は薬などを体に入れる行為なので合わない。", "点滅": "「現状を点滅するだけでは」は不自然。点滅は明かりがついたり消えたりすることで、ここには合わない。"}, "sentence_index": 6, "correct_answer": "維持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が一晩中維持した。", "explanation": "ここは〈持続〉の意味。維持は状態を保つことで、雨が途切れず降り続く場合は〈持続した〉を使う。"}, {"text": "古い時計を、最後まで維持して売った。", "explanation": "ここは〈売る〉の意味。維持は状態を保つことで、物を手放して金に換える動作には使わない。"}, {"text": "彼は見事に試験を維持した。", "explanation": "ここは〈合格〉の意味。維持は状態を保つことで、試験に受かる結果を表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36656, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日の運動で、体力に維持している。", "corrected_sentence": "毎日の運動で、体力を維持している。", "error_description": "「維持する」は目的語に「を」を取る。「体力に」は誤りで、正しくは「体力を維持している」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36656, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今の水準を維持れば、もっと人手が要る。", "corrected_sentence": "今の水準を維持すれば、もっと人手が要る。", "error_description": "「維持する」はサ変動詞で、仮定形は「維持すれば」。「維持れば」は活用が誤りで、正しくは「維持すれば」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36658, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「経済の側面」の『の』。経済の側面という名詞句を作るので、直前にこの助詞が入る。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示す。「経済が側面だけで考えてはいけない」は主語が変わり、文が不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。「経済へ側面だけで考える」は意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は対象や位置を示す。「経済に側面だけで考える」は意味が不自然で成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「経済の側面」の『の』。経済の側面という名詞句を作るので、直前にこの助詞が入る。", "が": "『が』は主語を示す。「経済が側面だけで考えてはいけない」は主語が変わり、文が不自然。", "へ": "『へ』は方向を示す。「経済へ側面だけで考える」は意味が通らない。", "に": "『に』は対象や位置を示す。「経済に側面だけで考える」は意味が不自然で成り立たない。"}, "error_tags": {"が": "主語を示す", "へ": "方向を示す", "に": "位置・対象を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36658, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「悲しい側面を描く」の『を』。描く対象が側面なので、直後にこの助詞が入る。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や共同を示す。「悲しい側面と描いている」は対象を表せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示す。「悲しい側面より描いている」は比べる文脈がなく成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ。「悲しい側面の描いている」は動詞の目的語を示せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「悲しい側面を描く」の『を』。描く対象が側面なので、直後にこの助詞が入る。", "と": "『と』は並列や共同を示す。「悲しい側面と描いている」は対象を表せず不自然。", "より": "『より』は比較を示す。「悲しい側面より描いている」は比べる文脈がなく成り立たない。", "の": "『の』は名詞をつなぐ。「悲しい側面の描いている」は動詞の目的語を示せず、文が成り立たない。"}, "error_tags": {"と": "並列を示す", "より": "比較を示す", "の": "連体修飾を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36658, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとの ひとつの めん", "primary_collocate": null, "pronunciation": "そくめん", "ipa": "sokɯmeɴ", "syllable_count": 4, "sentences": [{"text": "彼には、家ではおとなしいが、仕事では厳しいという二つの側面がある。", "target_word": "側面", "complexity_tier": "T3", "furigana": "彼[かれ]には、家[いえ]ではおとなしいが、仕事[しごと]では厳[きび]しいという二[ふた]つの側面[そくめん]がある。", "sentence_source": "generated"}, {"text": "この問題は、経済の側面だけで考えてはいけない。", "target_word": "側面", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、経済[けいざい]の側面[そくめん]だけで考[かんが]えてはいけない。", "sentence_source": "generated"}, {"text": "新しい制度には、よい側面と悪い側面の両方がある。", "target_word": "側面", "complexity_tier": "T3", "furigana": "新[あたら]しい制度[せいど]には、よい側面[そくめん]と悪[わる]い側面[そくめん]の両方[りょうほう]がある。", "sentence_source": "generated"}, {"text": "先生の意外な側面を見て、私は驚いた。", "target_word": "側面", "complexity_tier": "T3", "furigana": "先生[せんせい]の意外[いがい]な側面[そくめん]を見[み]て、私[わたし]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "ゲームには、子どもの想像力を育てる側面もある。", "target_word": "側面", "complexity_tier": "T3", "furigana": "ゲームには、子[こ]どもの想像力[そうぞうりょく]を育[そだ]てる側面[そくめん]もある。", "sentence_source": "generated"}, {"text": "歴史を学ぶと、国の文化の別の側面が見えてくる。", "target_word": "側面", "complexity_tier": "T3", "furigana": "歴史[れきし]を学[まな]ぶと、国[くに]の文化[ぶんか]の別[べつ]の側面[そくめん]が見[み]えてくる。", "sentence_source": "generated"}, {"text": "彼女には優しい側面があるので、みんなに好かれている。", "target_word": "側面", "complexity_tier": "T3", "furigana": "彼女[かのじょ]には優[やさ]しい側面[そくめん]があるので、みんなに好[す]かれている。", "sentence_source": "generated"}, {"text": "この映画は戦争の悲しい側面を描いている。", "target_word": "側面", "complexity_tier": "T3", "furigana": "この映画[えいが]は戦争[せんそう]の悲[かな]しい側面[そくめん]を描[えが]いている。", "sentence_source": "generated"}, {"text": "一つの側面だけを見て、人を決めてはいけない。", "target_word": "側面", "complexity_tier": "T3", "furigana": "一[ひと]つの側面[そくめん]だけを見[み]て、人[ひと]を決[き]めてはいけない。", "sentence_source": "generated"}, {"text": "観光は、地域の経済を助ける側面を持っている。", "target_word": "側面", "complexity_tier": "T3", "furigana": "観光[かんこう]は、地域[ちいき]の経済[けいざい]を助[たす]ける側面[そくめん]を持[も]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "側面", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人やものごとを見るときの、ある一つの面・一面（よい側面、経済の側面など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36658, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "側面", "is_correct": true, "explanation": "「二つの側面がある」は物事の二つの面があるという意味で、この文に合う。"}, {"text": "空気", "is_correct": false, "explanation": "「二つの空気がある」は数えられないものを二つと数えることになり、不自然。"}, {"text": "平等", "is_correct": false, "explanation": "「二つの平等がある」は意味が通らない。平等は数えて二つとあらわす概念ではない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「二つの砂糖がある」は物質を二つ数える文になり、この文の意味に合わない。"}], "explanations": {"側面": "「二つの側面がある」は物事の二つの面があるという意味で、この文に合う。", "空気": "「二つの空気がある」は数えられないものを二つと数えることになり、不自然。", "平等": "「二つの平等がある」は意味が通らない。平等は数えて二つとあらわす概念ではない。", "砂糖": "「二つの砂糖がある」は物質を二つ数える文になり、この文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "側面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合は重要な側面を迎えた。", "explanation": "ここは〈局面〉の意味。側面は物事の見方の一つで、試合が進む段階を表す場合は〈局面〉を使う。"}, {"text": "この試合は、我々の側面が勝った。", "explanation": "ここは〈陣営〉の意味。側面は物事の見方の一つで、試合で対立する一方の組を指す場合は〈陣営〉を使う。"}, {"text": "この電車は東京の側面へ向かう。", "explanation": "ここは〈方面〉の意味。側面は物事の見方の一つで、行き先の方向を表す場合は〈方面〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36658, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "側面", "is_correct": true, "explanation": "「優しい側面があるので」は人の性格の一面があるという意味で、この文に合う。"}, {"text": "階段", "is_correct": false, "explanation": "「優しい階段があるので」は意味が通らない。階段は形状を表す語で、性格には使えない。"}, {"text": "天井", "is_correct": false, "explanation": "「優しい天井があるので」は成り立たない。天井は建物の部位で、人の性質とは合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「優しい冷蔵庫があるので」は不自然。冷蔵庫は家電で、人の性格を表す語ではない。"}], "explanations": {"側面": "「優しい側面があるので」は人の性格の一面があるという意味で、この文に合う。", "階段": "「優しい階段があるので」は意味が通らない。階段は形状を表す語で、性格には使えない。", "天井": "「優しい天井があるので」は成り立たない。天井は建物の部位で、人の性質とは合わない。", "冷蔵庫": "「優しい冷蔵庫があるので」は不自然。冷蔵庫は家電で、人の性格を表す語ではない。"}, "sentence_index": 6, "correct_answer": "側面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "映画のラストの側面で、客がみんな泣いた。", "explanation": "ここは〈場面〉の意味。側面は物事の見方の一つで、映像の一場面を指す場合は〈場面〉を使う。"}, {"text": "昨夜、彼の体温が側面に上がった。", "explanation": "ここは〈熱〉の意味。側面は物事の見方の一つで、体の熱が上がる現象には使わない。"}, {"text": "夏休みの側面に、祖母の家へ行った。", "explanation": "ここは〈期間〉の意味。側面は物事の見方の一つで、時間の長さを指す場合は〈期間〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36658, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その計画は、経済の側面に見ると問題がある。", "corrected_sentence": "その計画は、経済の側面から見ると問題がある。", "error_description": "「〜の側面から見る」が正しい形。「側面に見る」は助詞が誤りで、正しくは「側面から見る」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36658, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "観光は、地域の経済で側面を果たしている。", "corrected_sentence": "観光は、地域の経済で役割を果たしている。", "error_description": "「果たす」は「役割」「責任」などと組む。「側面を果たす」は組み合わせが誤りで、正しくは「役割を果たす」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36662, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「脳内で思い描いた」は、想像が行われる場所を表す。"}, {"text": "が", "is_correct": false, "explanation": "「脳内が思い描いた」では脳内が動作主になり、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「脳内を、旅行の計画を思い描いた」は目的語が重なり、文意が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「脳内と思い描いた」は共同の相手を表すが、脳内は相手にならず文意が通らない。"}], "correct_answer": "で", "explanations": {"で": "正解。「脳内で思い描いた」は、想像が行われる場所を表す。", "が": "「脳内が思い描いた」では脳内が動作主になり、不自然。", "を": "「脳内を、旅行の計画を思い描いた」は目的語が重なり、文意が通らない。", "と": "「脳内と思い描いた」は共同の相手を表すが、脳内は相手にならず文意が通らない。"}, "error_tags": {"が": "主語", "を": "対象", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36662, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「脳内に何度も浮かんだ」は、笑顔が現れる場所を表す。"}, {"text": "の", "is_correct": false, "explanation": "「脳内の何度も浮かんだ」では、脳内が場所にならず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「脳内より何度も浮かんだ」は比べる意味になり、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「脳内を何度も浮かんだ」は、「浮かぶ」が目的語を取らないので不自然。"}], "correct_answer": "に", "explanations": {"に": "正解。「脳内に何度も浮かんだ」は、笑顔が現れる場所を表す。", "の": "「脳内の何度も浮かんだ」では、脳内が場所にならず文が成り立たない。", "より": "「脳内より何度も浮かんだ」は比べる意味になり、不自然。", "を": "「脳内を何度も浮かんだ」は、「浮かぶ」が目的語を取らないので不自然。"}, "error_tags": {"の": "所属・修飾", "より": "比較", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36662, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あたまのなか。", "primary_collocate": null, "pronunciation": "のうない", "ipa": "noːnai", "syllable_count": 4, "sentences": [{"text": "脳内で、昨日聞いた曲がずっと流れている。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "脳内[のうない]で、昨日[きのう]聞[き]いた曲[きょく]がずっと流[なが]れている。", "sentence_source": "generated"}, {"text": "彼は脳内で、旅行の計画を何度も思い描いた。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "彼[かれ]は脳内[のうない]で、旅行[りょこう]の計画[けいかく]を何度[なんど]も思[おも]い描[えが]いた。", "sentence_source": "generated"}, {"text": "脳内の地図を頼りに、暗い道を歩いた。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "脳内[のうない]の地図[ちず]を頼[たよ]りに、暗[くら]い道[みち]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "試験中、緊張のあまり脳内が混乱して、何も書けなかった。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "試験[しけん]中[ちゅう]、緊張[きんちょう]のあまり脳内[のうない]が混乱[こんらん]して、何[なに]も書[か]けなかった。", "sentence_source": "generated"}, {"text": "ゲームの音楽が脳内で繰り返され、眠れなかった。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "ゲームの音楽[おんがく]が脳内[のうない]で繰[く]り返[かえ]され、眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "彼女は脳内で、明日の発表の練習をしている。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は脳内[のうない]で、明日[あした]の発表[はっぴょう]の練習[れんしゅう]をしている。", "sentence_source": "generated"}, {"text": "脳内にいる想像の友だちと、よく話していたそうだ。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "脳内[のうない]にいる想像[そうぞう]の友[とも]だちと、よく話[はな]していたそうだ。", "sentence_source": "generated"}, {"text": "好きな人の笑顔が、脳内に何度も浮かんだ。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "好[す]きな人[ひと]の笑顔[えがお]が、脳内[のうない]に何度[なんど]も浮[う]かんだ。", "sentence_source": "generated"}, {"text": "絵を描く前に、脳内で全体の形を決めておく。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "絵[え]を描[か]く前[まえ]に、脳内[のうない]で全体[ぜんたい]の形[かたち]を決[き]めておく。", "sentence_source": "generated"}, {"text": "夜になると、脳内で今日の失敗が思い出される。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "夜[よる]になると、脳内[のうない]で今日[きょう]の失敗[しっぱい]が思[おも]い出[だ]される。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脳内", "label": "基本形"}, {"form": "脳内で", "label": "で格"}, {"form": "脳内に", "label": "に格"}, {"form": "脳内の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "頭の中（想像や記憶が浮かぶ場所）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36662, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脳内", "is_correct": true, "explanation": "正解。「脳内で」は頭の中という場所を表し、曲が頭の中で流れている意味になる。"}, {"text": "体重", "is_correct": false, "explanation": "「体重で」は場所にならず、「曲が流れている」の場所として意味が通らない。"}, {"text": "値段", "is_correct": false, "explanation": "「値段で」は音楽の流れる場所にならず、文が成り立たない。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題で」は曲が流れる場所を表せず、意味が通らない。"}], "explanations": {"脳内": "正解。「脳内で」は頭の中という場所を表し、曲が頭の中で流れている意味になる。", "体重": "「体重で」は場所にならず、「曲が流れている」の場所として意味が通らない。", "値段": "「値段で」は音楽の流れる場所にならず、文が成り立たない。", "宿題": "「宿題で」は曲が流れる場所を表せず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "脳内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は脳内がとても良く、数学の問題をすぐ解ける。", "explanation": "ここは〈頭脳〉の意味。賢さや頭の働きは頭脳で、〈脳内〉は頭の中の場所を指すので合わない。"}, {"text": "彼女は脳内がとても温かく、友達を励ました。", "explanation": "ここは〈心〉の意味。思いやりの気持ちは心で表すので、〈脳内〉を当てると合わない。"}, {"text": "雨の日は脳内で洗濯物を干すことにしている。", "explanation": "ここは〈室内〉の意味。雨の日に洗濯物を干す場所は家の中の室内で、〈脳内〉は頭の中を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36662, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脳内", "is_correct": true, "explanation": "正解。「脳内にいる」は頭の中に存在する想像の友だちを表す。"}, {"text": "寝言", "is_correct": false, "explanation": "「寝言にいる友だち」は存在の場所にならず、意味が通らない。"}, {"text": "切手", "is_correct": false, "explanation": "「切手にいる友だち」は場所として成り立たず、不自然。"}, {"text": "卒業", "is_correct": false, "explanation": "「卒業にいる」は存在の場所を表せず、文が成り立たない。"}], "explanations": {"脳内": "正解。「脳内にいる」は頭の中に存在する想像の友だちを表す。", "寝言": "「寝言にいる友だち」は存在の場所にならず、意味が通らない。", "切手": "「切手にいる友だち」は場所として成り立たず、不自然。", "卒業": "「卒業にいる」は存在の場所を表せず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "脳内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋の脳内にエアコンがついている。", "explanation": "ここは〈天井〉の意味。エアコンを取り付ける場所は天井で、〈脳内〉は頭の中を指すので合わない。"}, {"text": "窓の脳内から冷たい風が入ってきた。", "explanation": "ここは〈開口部〉の意味。風が通る開いた場所は、頭の中を指す〈脳内〉では表せないので合わない。"}, {"text": "来週は脳内で会議があるので、スーツを用意した。", "explanation": "ここは〈社内〉の意味。会社の中で会議をするので社内で、〈脳内〉は頭の中を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36662, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜、脳内を昔の友達の声が聞こえた。", "corrected_sentence": "夜、脳内で昔の友達の声が聞こえた。", "error_description": "「脳内」に続く格助詞の誤り。声が聞こえる場所は「で」で表す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
