INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36663, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "頭の中。思考や感情が生まれる場所。", "primary_collocate": null, "pronunciation": "のうない", "ipa": "noːnai", "syllable_count": 4, "sentences": [{"text": "考えや気持ちは、脳内で生まれると言われている。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "考[かんが]えや気持[きも]ちは、脳内[のうない]で生[う]まれると言[い]われている。", "sentence_source": "generated"}, {"text": "脳内で言葉を組み立ててから、ゆっくり話した。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "脳内[のうない]で言葉[ことば]を組[く]み立[た]ててから、ゆっくり話[はな]した。", "sentence_source": "generated"}, {"text": "怒りの感情が、脳内で大きくなっていくのを感じた。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "怒[いか]りの感情[かんじょう]が、脳内[のうない]で大[おお]きくなっていくのを感[かん]じた。", "sentence_source": "generated"}, {"text": "その科学者は、脳内の働きを長年研究している。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "その科学者[かがくしゃ]は、脳内[のうない]の働[はたら]きを長年[ながねん]研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "脳内で何度も考えたが、答えは出なかった。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "脳内[のうない]で何度[なんど]も考[かんが]えたが、答[こた]えは出[で]なかった。", "sentence_source": "generated"}, {"text": "不安な思いが脳内を駆け巡って、落ち着かなかった。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "不安[ふあん]な思[おも]いが脳内[のうない]を駆[か]け巡[めぐ]って、落[お]ち着[つ]かなかった。", "sentence_source": "generated"}, {"text": "勉強したことは、脳内で整理すると覚えやすい。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "勉強[べんきょう]したことは、脳内[のうない]で整理[せいり]すると覚[おぼ]えやすい。", "sentence_source": "generated"}, {"text": "アイデアは、脳内で静かに育っていくものだ。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "アイデアは、脳内[のうない]で静[しず]かに育[そだ]っていくものだ。", "sentence_source": "generated"}, {"text": "彼は脳内の声に従って、新しい仕事を選んだ。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "彼[かれ]は脳内[のうない]の声[こえ]に従[したが]って、新[あたら]しい仕事[しごと]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "脳内で想像した場面を、そのまま絵にした。", "target_word": "脳内", "complexity_tier": "T3", "furigana": "脳内[のうない]で想像[そうぞう]した場面[ばめん]を、そのまま絵[え]にした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脳内", "label": "基本形"}, {"form": "脳内で", "label": "で格"}, {"form": "脳内を", "label": "を格"}, {"form": "脳内の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "思考や感情が生まれる頭の中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36663, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脳内", "is_correct": true, "explanation": "正解。「脳内で生まれる」は、考えや気持ちが頭の中で生じることを表す。"}, {"text": "衣装", "is_correct": false, "explanation": "「衣装で生まれる」は場所にならず、意味が通らない。"}, {"text": "倉庫", "is_correct": false, "explanation": "「倉庫で生まれる」は、考えや気持ちが生じる場所として不自然。"}, {"text": "切手", "is_correct": false, "explanation": "「切手で生まれる」は場所にならず、文が成り立たない。"}], "explanations": {"脳内": "正解。「脳内で生まれる」は、考えや気持ちが頭の中で生じることを表す。", "衣装": "「衣装で生まれる」は場所にならず、意味が通らない。", "倉庫": "「倉庫で生まれる」は、考えや気持ちが生じる場所として不自然。", "切手": "「切手で生まれる」は場所にならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "脳内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は脳内が広くて、席も多い。", "explanation": "ここは〈店内〉の意味。店の中の広さは店内で、〈脳内〉は頭の中を指すので合わない。"}, {"text": "彼女は脳内がとても優しく、いつも人を気づかう。", "explanation": "ここは〈心〉の意味。人を思いやる気持ちは心で表すので、〈脳内〉を当てると不自然。"}, {"text": "脳内で祭りがあるので、みんなで準備している。", "explanation": "ここは〈町内〉の意味。地域の中で祭りを行うので町内で、〈脳内〉は頭の中を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36663, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脳内", "is_correct": true, "explanation": "正解。「脳内で整理する」は、頭の中で考えをまとめる場所を表す。"}, {"text": "水", "is_correct": false, "explanation": "「水で整理する」は場所にならず、意味が通らない。"}, {"text": "雨", "is_correct": false, "explanation": "「雨で整理する」は整理の場所にならず、文が成り立たない。"}, {"text": "体温", "is_correct": false, "explanation": "「体温で整理する」は整理の場所にも道具にもならず、不自然。"}], "explanations": {"脳内": "正解。「脳内で整理する」は、頭の中で考えをまとめる場所を表す。", "水": "「水で整理する」は場所にならず、意味が通らない。", "雨": "「雨で整理する」は整理の場所にならず、文が成り立たない。", "体温": "「体温で整理する」は整理の場所にも道具にもならず、不自然。"}, "sentence_index": 6, "correct_answer": "脳内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨漏りで、脳内の屋根から水が落ちてきた。", "explanation": "ここは〈建物の上を覆うもの〉の意味。雨をさえぎる上の覆いは頭の中にはなく、〈脳内〉は頭の中を指すので合わない。"}, {"text": "鍋の脳内で野菜を煮込んだ。", "explanation": "ここは〈容器の内側〉の意味。野菜を入れて煮る器の中は、頭の中を指す〈脳内〉では表せないので合わない。"}, {"text": "子どもたちは、庭の脳内で花を育てた。", "explanation": "ここは〈屋外の土地〉の意味。花を植えて育てる場所は屋外の土地で、〈脳内〉は頭の中を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36663, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "焦りが脳内を広がり、集中できなかった。", "corrected_sentence": "焦りが脳内に広がり、集中できなかった。", "error_description": "「脳内」に続く格助詞の誤り。「広がる」は自動詞で、場所には「に」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36663, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夢は、脳内を静かに育っていくものだと思う。", "corrected_sentence": "夢は、脳内で静かに育っていくものだと思う。", "error_description": "「脳内」に続く格助詞の誤り。「育つ」は自動詞で、夢が育つ場所は「で」で表す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36664, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「出て」の主語。ドーパミンが出るという文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「出る」は自動詞なので取らない。"}, {"text": "に", "is_correct": false, "explanation": "着点の「に」。「ドーパミンに出て」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」。ドーパミンを主語にする文では合わない。"}], "correct_answer": "が", "explanations": {"が": "「出て」の主語。ドーパミンが出るという文に合う。", "を": "目的語の「を」。「出る」は自動詞なので取らない。", "に": "着点の「に」。「ドーパミンに出て」は成り立たない。", "で": "手段や場所の「で」。ドーパミンを主語にする文では合わない。"}, "error_tags": {"を": "目的語", "に": "着点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36664, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題の「は」。ドーパミンについて説明する文の主題になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「作られる」の受身文では主語になるので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「ドーパミンへ作られる」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "着点の「に」。受身の動作主として不自然で、文の意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "主題の「は」。ドーパミンについて説明する文の主題になる。", "を": "目的語の「を」。「作られる」の受身文では主語になるので合わない。", "へ": "方向の「へ」。「ドーパミンへ作られる」は成り立たない。", "に": "着点の「に」。受身の動作主として不自然で、文の意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "着点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36664, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだの中で、気持ちをいい気分にしたり、元気を出すのを助けるものだよ。", "primary_collocate": null, "pronunciation": "どーぱみん", "ipa": "doːpamiɴ", "syllable_count": 5, "sentences": [{"text": "ドーパミンは、からだの中で元気を出す手助けをするよ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ドーパミンは、からだの中[なか]で元気[げんき]を出[だ]す手助[てだす]けをするよ。", "sentence_source": "generated"}, {"text": "ゲームに勝つと、ドーパミンが出てうれしくなるんだ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ゲームに勝[か]つと、ドーパミンが出[で]てうれしくなるんだ。", "sentence_source": "generated"}, {"text": "おいしいものを食べると、ドーパミンが出るよ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "おいしいものを食[た]べると、ドーパミンが出[で]るよ。", "sentence_source": "generated"}, {"text": "運動をすると、ドーパミンが出て気持ちがよくなるんだ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "運動[うんどう]をすると、ドーパミンが出[で]て気持[きも]ちがよくなるんだ。", "sentence_source": "generated"}, {"text": "ドーパミンが少ないと、やる気が出ないことがあるよ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ドーパミンが少[すく]ないと、やる気[き]が出[で]ないことがあるよ。", "sentence_source": "generated"}, {"text": "ほめられるとうれしいのは、ドーパミンのはたらきなんだ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ほめられるとうれしいのは、ドーパミンのはたらきなんだ。", "sentence_source": "generated"}, {"text": "友だちと遊んだあとは、ドーパミンのおかげで楽しい気分が続くよ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "友[とも]だちと遊[あそ]んだあとは、ドーパミンのおかげで楽[たの]しい気分[きぶん]が続[つづ]くよ。", "sentence_source": "generated"}, {"text": "ドーパミンは、からだの中で作られる、元気のもとだよ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ドーパミンは、からだの中[なか]で作[つく]られる、元気[げんき]のもとだよ。", "sentence_source": "generated"}, {"text": "新しいことに挑戦すると、ドーパミンが出てわくわくするんだ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "新[あたら]しいことに挑戦[ちょうせん]すると、ドーパミンが出[で]てわくわくするんだ。", "sentence_source": "generated"}, {"text": "ドーパミンが出ると、もっとやってみたい気持ちになるよ。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ドーパミンが出[で]ると、もっとやってみたい気持[きも]ちになるよ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ドーパミン", "label": "基本形"}], "register": "casual, child-friendly (だよ・んだ)", "sense_fingerprint": "子ども向けの説明。からだの中にあって、いい気分や元気、やる気のもとになるもの。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36664, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ドーパミン", "is_correct": true, "explanation": "からだの中で元気を出す手助けをする物質の名前。空所に入る。"}, {"text": "ガラス", "is_correct": false, "explanation": "透明な素材。体の中で元気を出す手助けはしないので合わない。"}, {"text": "タイヤ", "is_correct": false, "explanation": "車輪のゴム部品。からだの中で働くものではない。"}, {"text": "ポスター", "is_correct": false, "explanation": "掲示用の紙。からだの中で元気を出す働きはない。"}], "explanations": {"ドーパミン": "からだの中で元気を出す手助けをする物質の名前。空所に入る。", "ガラス": "透明な素材。体の中で元気を出す手助けはしないので合わない。", "タイヤ": "車輪のゴム部品。からだの中で働くものではない。", "ポスター": "掲示用の紙。からだの中で元気を出す働きはない。"}, "sentence_index": 0, "correct_answer": "ドーパミン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドーパミンを絞って、ジュースを作った。", "explanation": "ドーパミンは体内で働く物質で、絞って取り出すものではないので、この文は成り立たない。"}, {"text": "毎朝ドーパミンを飲むと、体の調子がよくなる。", "explanation": "ドーパミンは体内で作られる物質で、飲んで取り入れるものではないので合わない。"}, {"text": "ドーパミンを補給すると、貧血がよくなる。", "explanation": "ドーパミンは体内で作られる物質で、貧血の補給として使うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36664, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ドーパミン", "is_correct": true, "explanation": "「〜のおかげで楽しい気分が続く」の空所。気分に関わる物質として文に合う。"}, {"text": "ゴミ箱", "is_correct": false, "explanation": "ごみを入れる容器。楽しい気分が続く理由にはならない。"}, {"text": "ねじ", "is_correct": false, "explanation": "物を留める部品。「〜のおかげで楽しい気分が続く」とは言えない。"}, {"text": "ペンキ", "is_correct": false, "explanation": "塗料。楽しい気分が続く理由として意味が通らない。"}], "explanations": {"ドーパミン": "「〜のおかげで楽しい気分が続く」の空所。気分に関わる物質として文に合う。", "ゴミ箱": "ごみを入れる容器。楽しい気分が続く理由にはならない。", "ねじ": "物を留める部品。「〜のおかげで楽しい気分が続く」とは言えない。", "ペンキ": "塗料。楽しい気分が続く理由として意味が通らない。"}, "sentence_index": 6, "correct_answer": "ドーパミン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前にドーパミンを取ると眠れなくなる。", "explanation": "ドーパミンは体内で働く物質で、食品として取り入れるものではないので合わない。"}, {"text": "このドーパミンを炊くと、ご飯がおいしくなる。", "explanation": "ドーパミンは炊いて食べるものではないので、この文は成り立たない。"}, {"text": "深呼吸でドーパミンを取り込む。", "explanation": "ドーパミンは空気のように取り込むものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36664, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "楽しい話を聞くと、ドーパミンを出る。", "corrected_sentence": "楽しい話を聞くと、ドーパミンが出る。", "error_description": "「出る」は自動詞なので、ドーパミンを主語として「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36664, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ドーパミンが多く出まると、やる気が高まる。", "corrected_sentence": "ドーパミンが多く出ると、やる気が高まる。", "error_description": "「出る」の活用は「出ると」。「出まる」は誤った形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36665, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題の「は」。ドーパミンについて述べる文の主題になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「関わる」は「に」を取るので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「ドーパミンへ関わる」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「ドーパミンから関わる」は不自然。"}], "correct_answer": "は", "explanations": {"は": "主題の「は」。ドーパミンについて述べる文の主題になる。", "を": "目的語の「を」。「関わる」は「に」を取るので合わない。", "へ": "方向の「へ」。「ドーパミンへ関わる」は成り立たない。", "から": "起点の「から」。「ドーパミンから関わる」は不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36665, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題の「は」。脳内のドーパミンが主語となる文に合う。"}, {"text": "に", "is_correct": false, "explanation": "与格・到達の「に」。「ドーパミンに…行動を促す」では促す対象が立たず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」。後ろに並ぶ名詞を要求するが、「ドーパミンと、…促す」は主語も目的語も立たず文が途切れる。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」。「ドーパミンの、」と切れると修飾先がなく、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題の「は」。脳内のドーパミンが主語となる文に合う。", "に": "与格・到達の「に」。「ドーパミンに…行動を促す」では促す対象が立たず、文が成り立たない。", "と": "並列の「と」。後ろに並ぶ名詞を要求するが、「ドーパミンと、…促す」は主語も目的語も立たず文が途切れる。", "の": "連体の「の」。「ドーパミンの、」と切れると修飾先がなく、文が成り立たない。"}, "error_tags": {"に": "与格・対象の欠落", "と": "並列・文の途切れ", "の": "連体・修飾先なし"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36665, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "脳内で作られる神経伝達物質の一つで、快感や意欲、動機づけなどに関わる化学物質。", "primary_collocate": null, "pronunciation": "どーぱみん", "ipa": "doːpamiɴ", "syllable_count": 5, "sentences": [{"text": "ドーパミンは脳内で作られる神経伝達物質の一つである。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ドーパミンは脳内[のうない]で作[つく]られる神経伝達物質[しんけいでんたつぶっしつ]の一[ひと]つである。", "sentence_source": "generated"}, {"text": "ドーパミンは快感や意欲に深く関わっている。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ドーパミンは快感[かいかん]や意欲[いよく]に深[ふか]く関[かか]わっている。", "sentence_source": "generated"}, {"text": "報酬を予測すると、ドーパミンの分泌が増えることが知られている。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "報酬[ほうしゅう]を予測[よそく]すると、ドーパミンの分泌[ぶんぴつ]が増[ふ]えることが知[し]られている。", "sentence_source": "generated"}, {"text": "パーキンソン病では、ドーパミンを作る神経細胞が減少する。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "パーキンソン病[びょう]では、ドーパミンを作[つく]る神経細胞[しんけいさいぼう]が減少[げんしょう]する。", "sentence_source": "generated"}, {"text": "ドーパミンの量が不足すると、意欲の低下につながることがある。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ドーパミンの量[りょう]が不足[ふそく]すると、意欲[いよく]の低下[ていか]につながることがある。", "sentence_source": "generated"}, {"text": "研究者は、ドーパミンが学習の動機づけに果たす役割を調べた。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、ドーパミンが学習[がくしゅう]の動機[どうき]づけに果[は]たす役割[やくわり]を調[しら]べた。", "sentence_source": "generated"}, {"text": "薬の中には、ドーパミンの働きを強めるものがある。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "薬[くすり]の中[なか]には、ドーパミンの働[はたら]きを強[つよ]めるものがある。", "sentence_source": "generated"}, {"text": "脳内のドーパミンは、快い経験をくり返す行動を促す。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "脳内[のうない]のドーパミンは、快[こころよ]い経験[けいけん]をくり返[かえ]す行動[こうどう]を促[うなが]す。", "sentence_source": "generated"}, {"text": "ドーパミンの過剰な分泌は、依存の一因になると考えられている。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "ドーパミンの過剰[かじょう]な分泌[ぶんぴつ]は、依存[いぞん]の一因[いちいん]になると考[かんが]えられている。", "sentence_source": "generated"}, {"text": "実験では、ドーパミンの濃度の変化を測定した。", "target_word": "ドーパミン", "complexity_tier": "T3", "furigana": "実験[じっけん]では、ドーパミンの濃度[のうど]の変化[へんか]を測定[そくてい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ドーパミン", "label": "基本形"}], "register": "formal written (文章体・である調)", "sense_fingerprint": "神経科学の用語。脳内の神経伝達物質で、快感・意欲・学習・報酬に関わる化学物質。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36665, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ドーパミン", "is_correct": true, "explanation": "脳内で作られる神経伝達物質の名前。空所に入り、定義に合う。"}, {"text": "アスファルト", "is_correct": false, "explanation": "道路の舗装材。脳内で作られるものではない。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓を覆う布。脳内で作られる神経伝達物質ではない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "楽器。脳内で作られるものではないので文が成り立たない。"}], "explanations": {"ドーパミン": "脳内で作られる神経伝達物質の名前。空所に入り、定義に合う。", "アスファルト": "道路の舗装材。脳内で作られるものではない。", "カーテン": "窓を覆う布。脳内で作られる神経伝達物質ではない。", "ピアノ": "楽器。脳内で作られるものではないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "ドーパミン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の前に、ドーパミンを顔に塗って日焼けを防いだ。", "explanation": "ドーパミンは脳内の物質で、顔に塗るものではないので合わない。"}, {"text": "ドーパミンを煮込んで、スープを作った。", "explanation": "ドーパミンは脳内の物質で、煮込んで料理にする材料ではないので合わない。"}, {"text": "寒い夜、コートのドーパミンを留めて外に出た。", "explanation": "ドーパミンは脳内の物質で、衣類を留めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36665, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ドーパミン", "is_correct": true, "explanation": "「薬の中には〜の働きを強めるものがある」の空所。脳内の物質として文に合う。"}, {"text": "ゴム", "is_correct": false, "explanation": "弾力のある素材。薬の働きを強める対象として意味が通らない。"}, {"text": "ネジ", "is_correct": false, "explanation": "物を留める部品。薬の働きを強める対象にはならない。"}, {"text": "ペンキ", "is_correct": false, "explanation": "塗料。薬の働きを強める対象として意味が通らない。"}], "explanations": {"ドーパミン": "「薬の中には〜の働きを強めるものがある」の空所。脳内の物質として文に合う。", "ゴム": "弾力のある素材。薬の働きを強める対象として意味が通らない。", "ネジ": "物を留める部品。薬の働きを強める対象にはならない。", "ペンキ": "塗料。薬の働きを強める対象として意味が通らない。"}, "sentence_index": 6, "correct_answer": "ドーパミン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ドーパミンを接種して、感染を防いだ。", "explanation": "ドーパミンは脳内の物質で、体に接種するものではないので合わない。"}, {"text": "ドーパミンを縫って、傷口をふさいだ。", "explanation": "ドーパミンは脳内の物質で、縫い合わせる糸ではないので合わない。"}, {"text": "布をドーパミンで染めた。", "explanation": "ドーパミンは脳内の物質で、布を染める染料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36665, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "快感を得ると、脳内でドーパミンを分泌される。", "corrected_sentence": "快感を得ると、脳内でドーパミンが分泌される。", "error_description": "「分泌される」は受身で、ドーパミンが主語になるので「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36665, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "脳内でドーパミンが分泌れると、意欲が高まる。", "corrected_sentence": "脳内でドーパミンが分泌されると、意欲が高まる。", "error_description": "「分泌される」の「される」が抜けている。「分泌れる」は誤った形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36666, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「セロトニン」が主語になり、自動詞「増える」と結びつく形。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「増える」の主語にはならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、増える主体を表す位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、増える主体を表す位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「セロトニン」が主語になり、自動詞「増える」と結びつく形。", "と": "「と」は並列や相手を示すが、「増える」の主語にはならず文が成り立たない。", "へ": "「へ」は方向を示すが、増える主体を表す位置には入らない。", "で": "「で」は手段や場所を示すが、増える主体を表す位置には合わない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36666, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「〜のおかげで」の形で、名詞に「の」が付いて後ろの語句に続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「おかげで」の前には続かないので文に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「におかげで」とは言わないので、この位置には「に」は入らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「おかげで」の前には続かず文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「〜のおかげで」の形で、名詞に「の」が付いて後ろの語句に続く。", "を": "「を」は目的語を示すが、「おかげで」の前には続かないので文に合わない。", "に": "「におかげで」とは言わないので、この位置には「に」は入らない。", "から": "「から」は起点を示すが、「おかげで」の前には続かず文が成り立たない。"}, "error_tags": {"を": "目的語（おかげで に続かない）", "に": "「におかげで」は不自然", "から": "起点（おかげで に続かない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36666, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "脳の中で、気持ちを落ち着かせるはたらきをするもの。", "primary_collocate": null, "pronunciation": "せろとにん", "ipa": "seɾotoniɴ", "syllable_count": 5, "sentences": [{"text": "セロトニンは、気持ちを落ち着かせる脳のはたらきをします。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "セロトニンは、気持[きも]ちを落[お]ち着[つ]かせる脳[のう]のはたらきをします。", "sentence_source": "generated"}, {"text": "朝日を浴びると、セロトニンが増えると言われています。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "朝日[あさひ]を浴[あ]びると、セロトニンが増[ふ]えると言[い]われています。", "sentence_source": "generated"}, {"text": "セロトニンが足りないと、不安になりやすいそうです。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "セロトニンが足[た]りないと、不安[ふあん]になりやすいそうです。", "sentence_source": "generated"}, {"text": "医者は、セロトニンを増やす食べ物を教えてくれました。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、セロトニンを増[ふ]やす食[た]べ物[もの]を教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "散歩をするとセロトニンが出て、気持ちが軽くなります。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "散歩[さんぽ]をするとセロトニンが出[で]て、気持[きも]ちが軽[かる]くなります。", "sentence_source": "generated"}, {"text": "バナナには、セロトニンのもとになる成分が入っています。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "バナナには、セロトニンのもとになる成分[せいぶん]が入[はい]っています。", "sentence_source": "generated"}, {"text": "セロトニンが十分あると、心が落ち着いて、よく眠れます。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "セロトニンが十分[じゅうぶん]あると、心[こころ]が落[お]ち着[つ]いて、よく眠[ねむ]れます。", "sentence_source": "generated"}, {"text": "運動を続けたら、セロトニンのおかげで気分が安定しました。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "運動[うんどう]を続[つづ]けたら、セロトニンのおかげで気分[きぶん]が安定[あんてい]しました。", "sentence_source": "generated"}, {"text": "先生は「セロトニンは脳で働く大切なものです」と話しました。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "先生[せんせい]は「セロトニンは脳[のう]で働[はたら]く大切[たいせつ]なものです」と話[はな]しました。", "sentence_source": "generated"}, {"text": "よくかんで食べると、セロトニンが出やすくなります。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "よくかんで食[た]べると、セロトニンが出[で]やすくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "セロトニン", "label": "基本形"}], "register": "polite", "sense_fingerprint": "脳内で気持ちを落ち着かせる物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36666, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "セロトニン", "is_correct": true, "explanation": "脳内で気持ちを落ち着かせる物質の名前で、文の主語として自然に入る。"}, {"text": "血液", "is_correct": false, "explanation": "血液は血管を流れる体液で、脳のはたらきを担う主語にはならないので文に合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の熱の度合いを指すもので、脳が気持ちを落ち着かせるはたらきの主語にはならない。"}, {"text": "皮膚", "is_correct": false, "explanation": "皮膚は体の表面をおおう器官で、脳のはたらきを担うものではないので合わない。"}], "explanations": {"セロトニン": "脳内で気持ちを落ち着かせる物質の名前で、文の主語として自然に入る。", "血液": "血液は血管を流れる体液で、脳のはたらきを担う主語にはならないので文に合わない。", "体温": "体温は体の熱の度合いを指すもので、脳が気持ちを落ち着かせるはたらきの主語にはならない。", "皮膚": "皮膚は体の表面をおおう器官で、脳のはたらきを担うものではないので合わない。"}, "sentence_index": 0, "correct_answer": "セロトニン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "驚いて心臓が速く打ったのは、セロトニンが出たからです。", "explanation": "ここは〈アドレナリン〉の働き（驚きや緊張で心拍が上がる）。セロトニンは気持ちを落ち着かせる物質なので、心拍を速める場面には合わない。"}, {"text": "熱が出たので、セロトニンを飲んで熱を下げます。", "explanation": "ここは〈解熱剤〉（熱を下げる薬）の働き。セロトニンは気持ちを落ち着かせる物質で、熱を下げる薬としては使わないので合わない。"}, {"text": "車のガソリンが切れたので、セロトニンを入れて走ります。", "explanation": "ここは〈燃料〉（車を動かすもの）の働き。セロトニンは脳の物質で、車の燃料には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36666, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "セロトニン", "is_correct": true, "explanation": "気持ちを落ち着かせる物質の名前で、「十分ある」の主語として自然に入る。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電気を蓄える装置で、心の落ち着きや睡眠の主語にはならないので文に合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙や荷物を届ける仕組みで、心が落ち着くことの主語にはならない。"}, {"text": "漢字", "is_correct": false, "explanation": "漢字は文字の種類で、十分あると心が落ち着いて眠れるという文の主語として合わない。"}], "explanations": {"セロトニン": "気持ちを落ち着かせる物質の名前で、「十分ある」の主語として自然に入る。", "電池": "電池は電気を蓄える装置で、心の落ち着きや睡眠の主語にはならないので文に合わない。", "郵便": "郵便は手紙や荷物を届ける仕組みで、心が落ち着くことの主語にはならない。", "漢字": "漢字は文字の種類で、十分あると心が落ち着いて眠れるという文の主語として合わない。"}, "sentence_index": 6, "correct_answer": "セロトニン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ご褒美をもらうと、セロトニンが出て、やる気がわいてきます。", "explanation": "ここは〈ドーパミン〉（やる気や喜びに関わる）の働き。セロトニンは気持ちを落ち着かせる物質なので、やる気を出す場面には合わない。"}, {"text": "コーヒーを飲むと、セロトニンが出て、頭がはっきりします。", "explanation": "ここは〈カフェイン〉（眠気を抑える覚醒作用）の働き。セロトニンは頭をはっきりさせる物質ではないので合わない。"}, {"text": "お皿の油汚れを、セロトニンで洗い落とします。", "explanation": "ここは〈洗剤〉（汚れを落とす液）の働き。セロトニンは脳内の物質で、油汚れを落とすものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36666, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "セロトニンを増えると、気分が安定しやすくなります。", "corrected_sentence": "セロトニンが増えると、気分が安定しやすくなります。", "error_description": "「増える」は自動詞なので、主語を示す「が」が正しい。「を」は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36666, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "散歩を続けると、セロトニンが増やして気分が明るくなります。", "corrected_sentence": "散歩を続けると、セロトニンが増えて気分が明るくなります。", "error_description": "「が」の後には自動詞「増える」が来る。「増やす」は他動詞で「を」を取るので、ここは「増えて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36667, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「セロトニンの量」のように、名詞と名詞をつなぐ「の」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すもので、「量」を修飾する位置には使えない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すもので、名詞の間には入らないので文に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や場所を示すもので、「量」を修飾する位置には使えない。"}], "correct_answer": "の", "explanations": {"の": "「セロトニンの量」のように、名詞と名詞をつなぐ「の」が入る。", "が": "「が」は主語を示すもので、「量」を修飾する位置には使えない。", "を": "「を」は目的語を示すもので、名詞の間には入らないので文に合わない。", "に": "「に」は方向や場所を示すもので、「量」を修飾する位置には使えない。"}, "error_tags": {"が": "主語（名詞修飾に使えない）", "を": "目的語（名詞の間に入らない）", "に": "方向・場所（名詞修飾に使えない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36667, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「セロトニンの不足」のように、名詞と名詞をつなぐ「の」が入る。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「不足」を修飾する位置には使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「不足」を修飾する位置には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すもので、「不足」を修飾する位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「セロトニンの不足」のように、名詞と名詞をつなぐ「の」が入る。", "と": "「と」は並列や相手を示すが、「不足」を修飾する位置には使えない。", "で": "「で」は場所や手段を示すが、「不足」を修飾する位置には合わない。", "へ": "「へ」は方向を示すもので、「不足」を修飾する位置には入らない。"}, "error_tags": {"と": "並列・相手", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36667, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "脳内で神経伝達に関わる物質の一つで、気分の安定や幸福感に関与する。", "primary_collocate": null, "pronunciation": "せろとにん", "ipa": "seɾotoniɴ", "syllable_count": 5, "sentences": [{"text": "セロトニンは、気分の安定に関わる神経伝達物質である。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "セロトニンは、気分[きぶん]の安定[あんてい]に関[かか]わる神経伝達物質[しんけいでんたつぶっしつ]である。", "sentence_source": "generated"}, {"text": "研究者は、セロトニンの量とうつ病の関係を調べている。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、セロトニンの量[りょう]とうつ病[びょう]の関係[かんけい]を調[しら]べている。", "sentence_source": "generated"}, {"text": "睡眠不足が続くと、セロトニンの分泌が減る傾向がある。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "睡眠不足[すいみんぶそく]が続[つづ]くと、セロトニンの分泌[ぶんぴつ]が減[へ]る傾向[けいこう]がある。", "sentence_source": "generated"}, {"text": "この薬は、脳内のセロトニンの働きを助ける。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "この薬[くすり]は、脳内[のうない]のセロトニンの働[はたら]きを助[たす]ける。", "sentence_source": "generated"}, {"text": "セロトニンは幸福感に関与するため、「幸せホルモン」とも呼ばれる。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "セロトニンは幸福感[こうふくかん]に関与[かんよ]するため、「幸[しあわ]せホルモン」とも呼[よ]ばれる。", "sentence_source": "generated"}, {"text": "腸でもセロトニンが作られることが、研究で明らかになった。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "腸[ちょう]でもセロトニンが作[つく]られることが、研究[けんきゅう]で明[あき]らかになった。", "sentence_source": "generated"}, {"text": "日光を浴びる習慣は、セロトニンの合成を促す。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "日光[にっこう]を浴[あ]びる習慣[しゅうかん]は、セロトニンの合成[ごうせい]を促[うなが]す。", "sentence_source": "generated"}, {"text": "セロトニンの不足は、気分の落ち込みと関連している。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "セロトニンの不足[ぶそく]は、気分[きぶん]の落[お]ち込[こ]みと関連[かんれん]している。", "sentence_source": "generated"}, {"text": "実験では、セロトニンの濃度を測定して比較した。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "実験[じっけん]では、セロトニンの濃度[のうど]を測定[そくてい]して比較[ひかく]した。", "sentence_source": "generated"}, {"text": "規則正しい生活を送ると、セロトニンのバランスが整いやすい。", "target_word": "セロトニン", "complexity_tier": "T3", "furigana": "規則正[きそくただ]しい生活[せいかつ]を送[おく]ると、セロトニンのバランスが整[ととの]いやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "セロトニン", "label": "基本形"}], "register": "formal", "sense_fingerprint": "気分の安定や幸福感に関わる神経伝達物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36667, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "セロトニン", "is_correct": true, "explanation": "気分の安定に関わる神経伝達物質の名前で、文の主語として合う。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の熱の度合いで、神経伝達物質ではないので文に合わない。"}, {"text": "血液", "is_correct": false, "explanation": "血液は血管を流れる体液で、神経伝達物質ではないので文に合わない。"}, {"text": "筋肉", "is_correct": false, "explanation": "筋肉は体を動かす組織で、神経伝達物質ではないので文に合わない。"}], "explanations": {"セロトニン": "気分の安定に関わる神経伝達物質の名前で、文の主語として合う。", "体温": "体温は体の熱の度合いで、神経伝達物質ではないので文に合わない。", "血液": "血液は血管を流れる体液で、神経伝達物質ではないので文に合わない。", "筋肉": "筋肉は体を動かす組織で、神経伝達物質ではないので文に合わない。"}, "sentence_index": 0, "correct_answer": "セロトニン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "傷口が化膿しないように、セロトニンを塗ります。", "explanation": "ここは〈消毒薬〉（傷の細菌を殺す薬）の働き。セロトニンは脳の神経伝達物質で、傷の消毒には使わないので合わない。"}, {"text": "ゲームに勝つと、脳内のセロトニンが急に増えて、興奮が高まります。", "explanation": "ここは〈ドーパミン〉（報酬や興奮に関わる）の働き。セロトニンは興奮を高める物質ではなく気分を安定させるので合わない。"}, {"text": "食べ物が胃に入ると、セロトニンが出て、食べ物を溶かします。", "explanation": "ここは〈胃酸〉（食べ物を溶かす）の働き。セロトニンは食べ物を溶かす役割を持たないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36667, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "セロトニン", "is_correct": true, "explanation": "「合成を促す」の対象になる物質名で、「の合成」の形に入る。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表す語で、物質の合成の対象にはならない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙や荷物を届ける仕組みで、合成されるものではない。"}, {"text": "鼓動", "is_correct": false, "explanation": "鼓動は心臓の拍動で、化学的に合成されるものではないので合わない。"}], "explanations": {"セロトニン": "「合成を促す」の対象になる物質名で、「の合成」の形に入る。", "天気": "天気は空模様を表す語で、物質の合成の対象にはならない。", "郵便": "郵便は手紙や荷物を届ける仕組みで、合成されるものではない。", "鼓動": "鼓動は心臓の拍動で、化学的に合成されるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "セロトニン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "紅茶に、セロトニンを入れて甘くします。", "explanation": "ここは〈砂糖〉（甘みを出すもの）の働き。セロトニンは脳内の神経伝達物質で、甘みをつけるものではないので合わない。"}, {"text": "急な物音に驚くと、セロトニンが出て、心拍が一気に上がります。", "explanation": "ここは〈アドレナリン〉（緊張や驚きで出るホルモン）の働き。セロトニンは気分を落ち着ける物質なので、心拍を上げる場面には合わない。"}, {"text": "脂肪の多い食事をすると、セロトニンが出て、脂肪を分解します。", "explanation": "ここは〈胆汁〉（脂肪を分解する消化液）の働き。セロトニンは脂肪を分解しないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36667, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は、セロトニンを気分の関係を調べている。", "corrected_sentence": "研究者は、セロトニンと気分の関係を調べている。", "error_description": "「AとBの関係」の形では、Aに「と」が入る。「を」は「調べる」の目的語を示すので、ここでは「と」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36667, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実験では、血液中のセロトニンが濃度を測った。", "corrected_sentence": "実験では、血液中のセロトニンの濃度を測った。", "error_description": "「濃度」は「セロトニンの濃度」の形で、名詞と名詞をつなぐ「の」が正しい。「が」は主語を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36668, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象の格。『使う』の目的語には『を』が付くので、『アセチルコリンを使う』が正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語の格。使う主体は神経などで、使われる対象のアセチルコリンに『が』は合わない。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の格。『に』は場所や相手を表すので、使う対象には付かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の格。『へ』は向かう先を表すが、『使う』は対象を取るので『へ』は合わない。"}], "correct_answer": "を", "explanations": {"を": "対象の格。『使う』の目的語には『を』が付くので、『アセチルコリンを使う』が正しい。", "が": "主語の格。使う主体は神経などで、使われる対象のアセチルコリンに『が』は合わない。", "に": "位置・相手の格。『に』は場所や相手を表すので、使う対象には付かない。", "へ": "方向の格。『へ』は向かう先を表すが、『使う』は対象を取るので『へ』は合わない。"}, "error_tags": {}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36668, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "所有・修飾の『の』。『アセチルコリンの働き』のように名詞をつなぐ正しい形。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の格。『と』は並ぶ相手や引用を表すので、『量』をつなぐ位置には入らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の格。『から』は出どころを表すが、ここは名詞同士をつなぐ位置なので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の格。『より』は比べる基準を表すが、『アセチルコリンより量』とは続かない。"}], "correct_answer": "の", "explanations": {"の": "所有・修飾の『の』。『アセチルコリンの働き』のように名詞をつなぐ正しい形。", "と": "共同・引用の格。『と』は並ぶ相手や引用を表すので、『量』をつなぐ位置には入らない。", "から": "起点の格。『から』は出どころを表すが、ここは名詞同士をつなぐ位置なので合わない。", "より": "比較の格。『より』は比べる基準を表すが、『アセチルコリンより量』とは続かない。"}, "error_tags": {}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36668, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「アセチルコリン」は、体の中で情報を伝える役割をする物質です。", "primary_collocate": null, "pronunciation": "あせちるこりん", "ipa": "asetɕiɾɯkoɾiɴ", "syllable_count": 7, "sentences": [{"text": "アセチルコリンは、体の中で情報を伝える物質だ。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "アセチルコリンは、体[からだ]の中[なか]で情報[じょうほう]を伝[つた]える物質[ぶっしつ]だ。", "sentence_source": "generated"}, {"text": "神経は、アセチルコリンを使って次の細胞に合図を送る。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "神経[しんけい]は、アセチルコリンを使[つか]って次[つぎ]の細胞[さいぼう]に合図[あいず]を送[おく]る。", "sentence_source": "generated"}, {"text": "アセチルコリンが足りないと、体にうまく信号が伝わらない。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "アセチルコリンが足[た]りないと、体[からだ]にうまく信号[しんごう]が伝[つた]わらない。", "sentence_source": "generated"}, {"text": "理科の授業で、アセチルコリンの働きを習った。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、アセチルコリンの働[はたら]きを習[なら]った。", "sentence_source": "generated"}, {"text": "アセチルコリンのおかげで、脳から手に指令が届く。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "アセチルコリンのおかげで、脳[のう]から手[て]に指令[しれい]が届[とど]く。", "sentence_source": "generated"}, {"text": "先生は、アセチルコリンについて図を使って説明した。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "先生[せんせい]は、アセチルコリンについて図[ず]を使[つか]って説明[せつめい]した。", "sentence_source": "generated"}, {"text": "アセチルコリンは体の中で作られ、すぐに分解される。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "アセチルコリンは体[からだ]の中[なか]で作[つく]られ、すぐに分解[ぶんかい]される。", "sentence_source": "generated"}, {"text": "医者は、アセチルコリンの量を調べる検査について話した。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、アセチルコリンの量[りょう]を調[しら]べる検査[けんさ]について話[はな]した。", "sentence_source": "generated"}, {"text": "神経の先からアセチルコリンが出て、細胞が反応する。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "神経[しんけい]の先[さき]からアセチルコリンが出[で]て、細胞[さいぼう]が反応[はんのう]する。", "sentence_source": "generated"}, {"text": "兄は生物の試験のために、アセチルコリンの名前を覚えた。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "兄[あに]は生物[せいぶつ]の試験[しけん]のために、アセチルコリンの名前[なまえ]を覚[おぼ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アセチルコリン", "label": "基本形"}], "register": "technical", "sense_fingerprint": "体の中で神経の情報を伝える物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36668, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アセチルコリン", "is_correct": true, "explanation": "神経の情報を伝える物質そのもの。『体の中で情報を伝える物質だ』の主語として合う。"}, {"text": "神経", "is_correct": false, "explanation": "神経は情報を伝える組織で物質ではないので、『神経は物質だ』とは言えない。"}, {"text": "脳", "is_correct": false, "explanation": "脳は器官で伝達物質ではないので、『脳は物質だ』は不自然。"}, {"text": "筋肉", "is_correct": false, "explanation": "筋肉は体の組織で、情報を伝える物質ではないので文に合わない。"}], "explanations": {"アセチルコリン": "神経の情報を伝える物質そのもの。『体の中で情報を伝える物質だ』の主語として合う。", "神経": "神経は情報を伝える組織で物質ではないので、『神経は物質だ』とは言えない。", "脳": "脳は器官で伝達物質ではないので、『脳は物質だ』は不自然。", "筋肉": "筋肉は体の組織で、情報を伝える物質ではないので文に合わない。"}, "sentence_index": 0, "correct_answer": "アセチルコリン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アセチルコリンは血液で全身に運ばれ、代謝を調節する。", "explanation": "ここは〈ホルモン〉の意味。血液で全身に運ばれて代謝を調節する物質の話で、神経の先で情報を伝えるアセチルコリンとは合わない。"}, {"text": "アセチルコリンは、食べ物を分解する。", "explanation": "ここは〈酵素〉の意味。食べ物を分解する酵素の働きで、情報を伝える物質のアセチルコリンとは合わない。"}, {"text": "アセチルコリンは、食事から取る必要のある栄養素だ。", "explanation": "ここは〈ビタミン〉の意味。食事で取る栄養素の話で、体の中で神経の情報を伝える物質のアセチルコリンとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36668, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アセチルコリン", "is_correct": true, "explanation": "体内で作られてすぐ分解される神経の物質として、文に合う。"}, {"text": "酸素", "is_correct": false, "explanation": "酸素は体外から取り入れるもので、体の中で作られないので文に合わない。"}, {"text": "心臓", "is_correct": false, "explanation": "心臓は器官で、作られたあとに分解される対象ではないので合わない。"}, {"text": "眼", "is_correct": false, "explanation": "眼は器官で、体の中で作られて分解される物質ではないので不自然。"}], "explanations": {"アセチルコリン": "体内で作られてすぐ分解される神経の物質として、文に合う。", "酸素": "酸素は体外から取り入れるもので、体の中で作られないので文に合わない。", "心臓": "心臓は器官で、作られたあとに分解される対象ではないので合わない。", "眼": "眼は器官で、体の中で作られて分解される物質ではないので不自然。"}, "sentence_index": 6, "correct_answer": "アセチルコリン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アセチルコリンは、骨の材料になる。", "explanation": "ここは〈カルシウム〉の意味。骨の材料になるミネラルの話で、神経の情報を伝えるアセチルコリンとは合わない。"}, {"text": "アセチルコリンは、血管の壁に溜まりやすい脂質だ。", "explanation": "ここは〈コレステロール〉の意味。血管に溜まりやすい脂質の話で、神経で情報を伝える物質のアセチルコリンとは合わない。"}, {"text": "アセチルコリンは、体に入った細菌を見つけて攻撃する。", "explanation": "ここは〈抗体〉の意味。免疫で細菌を攻撃する物質の話で、神経の情報を伝えるアセチルコリンとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36668, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "脳は、アセチルコリンへ使って手に指令を送る。", "corrected_sentence": "脳は、アセチルコリンを使って手に指令を送る。", "error_description": "『使う』の対象は『を』で表す。『へ』は方向を表すので、『アセチルコリンへ使う』は不自然。正しくは『アセチルコリンを使う』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36668, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "アセチルコリンは神経で作られ、すぐに分解れる。", "corrected_sentence": "アセチルコリンは神経で作られ、すぐに分解される。", "error_description": "『分解される』の活用が誤り。『分解れる』ではなく『分解される』が正しい形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36669, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語の格。『減りやすい』の主語は『アセチルコリン』なので『が』が正しい。"}, {"text": "を", "is_correct": false, "explanation": "対象の格。『減る』は自動詞で、物が主語になるので『を』は合わない。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の格。『に』は場所や相手を表すので、減る主体には付かない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格。『で』は手段や場所を表すが、ここは主語の位置なので合わない。"}], "correct_answer": "が", "explanations": {"が": "主語の格。『減りやすい』の主語は『アセチルコリン』なので『が』が正しい。", "を": "対象の格。『減る』は自動詞で、物が主語になるので『を』は合わない。", "に": "位置・相手の格。『に』は場所や相手を表すので、減る主体には付かない。", "で": "手段・場所の格。『で』は手段や場所を表すが、ここは主語の位置なので合わない。"}, "error_tags": {}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36669, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "所有・修飾の『の』。『アセチルコリンの量』のように名詞をつなぐ正しい形。"}, {"text": "へ", "is_correct": false, "explanation": "方向の格。『へ』は向かう先を表すので、名詞をつなぐ位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "共同・引用の格。『と』は並ぶ相手や引用を表すので、『量』に続けると意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の格。『から』は出どころを表すが、ここは名詞同士をつなぐ位置なので合わない。"}], "correct_answer": "の", "explanations": {"の": "所有・修飾の『の』。『アセチルコリンの量』のように名詞をつなぐ正しい形。", "へ": "方向の格。『へ』は向かう先を表すので、名詞をつなぐ位置には入らない。", "と": "共同・引用の格。『と』は並ぶ相手や引用を表すので、『量』に続けると意味が通らない。", "から": "起点の格。『から』は出どころを表すが、ここは名詞同士をつなぐ位置なので合わない。"}, "error_tags": {}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36669, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "アセチルコリンは、神経伝達物質の一つで、筋肉を動かしたり、記憶や学習に関わる働きをします。", "primary_collocate": null, "pronunciation": "あせちるこりん", "ipa": "asetɕiɾɯkoɾiɴ", "syllable_count": 7, "sentences": [{"text": "アセチルコリンは神経伝達物質で、筋肉を動かす時に必要だ。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "アセチルコリンは神経伝達物質[しんけいでんたつぶっしつ]で、筋肉[きんにく]を動[うご]かす時[とき]に必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "年を取ると、記憶に関わるアセチルコリンが減りやすい。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると、記憶[きおく]に関[かか]わるアセチルコリンが減[へ]りやすい。", "sentence_source": "generated"}, {"text": "アセチルコリンが出ると、筋肉が縮んで腕が動く。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "アセチルコリンが出[で]ると、筋肉[きんにく]が縮[ちぢ]んで腕[うで]が動[うご]く。", "sentence_source": "generated"}, {"text": "研究者は、学習とアセチルコリンの関係を調べている。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、学習[がくしゅう]とアセチルコリンの関係[かんけい]を調[しら]べている。", "sentence_source": "generated"}, {"text": "認知症の薬には、アセチルコリンを増やすものがある。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "認知症[にんちしょう]の薬[くすり]には、アセチルコリンを増[ふ]やすものがある。", "sentence_source": "generated"}, {"text": "この毒は、アセチルコリンの働きをじゃまして筋肉を止める。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "この毒[どく]は、アセチルコリンの働[はたら]きをじゃまして筋肉[きんにく]を止[と]める。", "sentence_source": "generated"}, {"text": "アセチルコリンが不足すると、物覚えが悪くなることがある。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "アセチルコリンが不足[ふそく]すると、物覚[ものおぼ]えが悪[わる]くなることがある。", "sentence_source": "generated"}, {"text": "論文では、睡眠中のアセチルコリンの量が記憶を左右すると述べている。", "target_word": "アセチルコリン", "complexity_tier": "T4", "furigana": "論文[ろんぶん]では、睡眠中[すいみんちゅう]のアセチルコリンの量[りょう]が記憶[きおく]を左右[さゆう]すると述[の]べている。", "sentence_source": "generated"}, {"text": "アセチルコリンは運動にも勉強にも関わる大切な物質だ。", "target_word": "アセチルコリン", "complexity_tier": "T3", "furigana": "アセチルコリンは運動[うんどう]にも勉強[べんきょう]にも関[かか]わる大切[たいせつ]な物質[ぶっしつ]だ。", "sentence_source": "generated"}, {"text": "実験でネズミのアセチルコリンを測り、迷路の成績と比べた。", "target_word": "アセチルコリン", "complexity_tier": "T4", "furigana": "実験[じっけん]でネズミのアセチルコリンを測[はか]り、迷路[めいろ]の成績[せいせき]と比[くら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アセチルコリン", "label": "基本形"}], "register": "technical", "sense_fingerprint": "筋肉の運動や記憶・学習に関わる神経伝達物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36669, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アセチルコリン", "is_correct": true, "explanation": "筋肉を動かす時に必要な神経伝達物質そのもの。文の主語として合う。"}, {"text": "脳", "is_correct": false, "explanation": "脳は器官で、神経伝達物質ではないので『脳は神経伝達物質で』は合わない。"}, {"text": "酸素", "is_correct": false, "explanation": "酸素は気体で、神経伝達物質ではないので文に合わない。"}, {"text": "血液", "is_correct": false, "explanation": "血液は体液で、神経伝達物質ではないので文の主語としては不自然。"}], "explanations": {"アセチルコリン": "筋肉を動かす時に必要な神経伝達物質そのもの。文の主語として合う。", "脳": "脳は器官で、神経伝達物質ではないので『脳は神経伝達物質で』は合わない。", "酸素": "酸素は気体で、神経伝達物質ではないので文に合わない。", "血液": "血液は体液で、神経伝達物質ではないので文の主語としては不自然。"}, "sentence_index": 0, "correct_answer": "アセチルコリン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アセチルコリンは、骨を丈夫にする栄養素だ。", "explanation": "ここは〈カルシウム〉の意味。骨を丈夫にする栄養素の話で、記憶や筋肉の信号に関わるアセチルコリンとは合わない。"}, {"text": "アセチルコリンは、血糖を下げるために働く。", "explanation": "ここは〈インスリン〉の意味。血糖を下げるホルモンの働きで、神経の信号に関わるアセチルコリンとは違う。"}, {"text": "アセチルコリンは、体を動かすエネルギー源になる糖だ。", "explanation": "ここは〈グルコース〉の意味。エネルギー源になる糖の話で、神経の信号に関わるアセチルコリンとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36669, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アセチルコリン", "is_correct": true, "explanation": "不足すると物覚えが悪くなることがある神経伝達物質で、文の主語として合う。"}, {"text": "皮膚", "is_correct": false, "explanation": "皮膚は体の表面を覆う器官で、不足しても物覚えに関わるとは言えない。"}, {"text": "爪", "is_correct": false, "explanation": "爪は体の組織で、不足が物覚えの低下につながるとは言えないので合わない。"}, {"text": "歯", "is_correct": false, "explanation": "歯は噛むための器官で、不足が物覚えに関わるとは言えないので文に合わない。"}], "explanations": {"アセチルコリン": "不足すると物覚えが悪くなることがある神経伝達物質で、文の主語として合う。", "皮膚": "皮膚は体の表面を覆う器官で、不足しても物覚えに関わるとは言えない。", "爪": "爪は体の組織で、不足が物覚えの低下につながるとは言えないので合わない。", "歯": "歯は噛むための器官で、不足が物覚えに関わるとは言えないので文に合わない。"}, "sentence_index": 6, "correct_answer": "アセチルコリン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アセチルコリンは、アレルギーの症状を起こす。", "explanation": "ここは〈ヒスタミン〉の意味。アレルギー反応を起こす物質の話で、神経の信号を伝えるアセチルコリンとは違う。"}, {"text": "アセチルコリンは、日光を浴びると体の中で作られる。", "explanation": "ここは〈ビタミンD〉の意味。日光を浴びて体内で作られる物質の話で、神経の信号に関わるアセチルコリンとは合わない。"}, {"text": "アセチルコリンは、血管の壁に溜まりやすい脂質だ。", "explanation": "ここは〈コレステロール〉の意味。血管に溜まる脂質の話で、アセチルコリンは脂質ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36669, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この薬は、アセチルコリンへ働きを助けて、物覚えをよくする。", "corrected_sentence": "この薬は、アセチルコリンの働きを助けて、物覚えをよくする。", "error_description": "『働き』に係る『の』が正しい。『へ』は方向を表すため、『アセチルコリンへ働き』は不自然。正しくは『アセチルコリンの働き』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36669, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この新薬は、アセチルコリンを増やすせて、記憶をよくする。", "corrected_sentence": "この新薬は、アセチルコリンを増やして、記憶をよくする。", "error_description": "『増やす』の活用が誤り。『増やすせて』ではなく『増やして』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36670, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「物質が必要です」の形で、必要とされるものを主語として示す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「必要」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「必要」とは結びつかない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示すが、この位置では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「物質が必要です」の形で、必要とされるものを主語として示す。", "で": "「で」は手段や場所を示すが、「必要」の主語にはならない。", "へ": "「へ」は方向を示すが、「必要」とは結びつかない。", "から": "「から」は起点や理由を示すが、この位置では文が成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "から": "起点・理由"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36670, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「書く」の目的語（書いたもの）を示すので、「物質を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や方向を示すが、物質の後には続かず、書く対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、書く対象にはならないので文に合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、書く動作の主体は先生なので物質には付かない。"}], "correct_answer": "を", "explanations": {"を": "「書く」の目的語（書いたもの）を示すので、「物質を」が入る。", "に": "「に」は場所や方向を示すが、物質の後には続かず、書く対象にはならない。", "と": "「と」は並列や相手を示すが、書く対象にはならないので文に合わない。", "が": "「が」は主語を示すが、書く動作の主体は先生なので物質には付かない。"}, "error_tags": {"に": "場所・方向（目的語にならない）", "と": "並列・相手", "が": "主語（書く主体は先生）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36670, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを作るときに使う、中身の材料のことです。", "primary_collocate": null, "pronunciation": "ぶっしつ", "ipa": "bɯɕːitsɯ", "syllable_count": 4, "sentences": [{"text": "この物質は水にとけやすいので、料理にも使われます。", "target_word": "物質", "complexity_tier": "T3", "furigana": "この物質[ぶっしつ]は水[みず]にとけやすいので、料理[りょうり]にも使[つか]われます。", "sentence_source": "generated"}, {"text": "石けんを作るには、油とある物質が必要です。", "target_word": "物質", "complexity_tier": "T3", "furigana": "石[せっ]けんを作[つく]るには、油[あぶら]とある物質[ぶっしつ]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "このかばんは、丈夫な物質で作られています。", "target_word": "物質", "complexity_tier": "T3", "furigana": "このかばんは、丈夫[じょうぶ]な物質[ぶっしつ]で作[つく]られています。", "sentence_source": "generated"}, {"text": "茶碗は、粘土という物質を焼いて作ります。", "target_word": "物質", "complexity_tier": "T3", "furigana": "茶碗[ちゃわん]は、粘土[ねんど]という物質[ぶっしつ]を焼[や]いて作[つく]ります。", "sentence_source": "generated"}, {"text": "工場では、新しい物質を使って軽いかばんを作っています。", "target_word": "物質", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、新[あたら]しい物質[ぶっしつ]を使[つか]って軽[かる]いかばんを作[つく]っています。", "sentence_source": "generated"}, {"text": "このパイプは、銅という物質でできています。", "target_word": "物質", "complexity_tier": "T3", "furigana": "このパイプは、銅[どう]という物質[ぶっしつ]でできています。", "sentence_source": "generated"}, {"text": "紙を作るには、木からとった繊維という物質を使います。", "target_word": "物質", "complexity_tier": "T3", "furigana": "紙[かみ]を作[つく]るには、木[き]からとった繊維[せんい]という物質[ぶっしつ]を使[つか]います。", "sentence_source": "generated"}, {"text": "先生は、ガラスの材料になる物質を黒板に書きました。", "target_word": "物質", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ガラスの材料[ざいりょう]になる物質[ぶっしつ]を黒板[こくばん]に書[か]きました。", "sentence_source": "generated"}, {"text": "このおもちゃは、やわらかい樹脂という物質で作られています。", "target_word": "物質", "complexity_tier": "T3", "furigana": "このおもちゃは、やわらかい樹脂[じゅし]という物質[ぶっしつ]で作[つく]られています。", "sentence_source": "generated"}, {"text": "鉄という物質は、固くて建物の材料に向いています。", "target_word": "物質", "complexity_tier": "T3", "furigana": "鉄[てつ]という物質[ぶっしつ]は、固[かた]くて建物[たてもの]の材料[ざいりょう]に向[む]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物質", "label": "基本形"}], "register": "polite", "sense_fingerprint": "ものを作る材料になる中身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36670, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物質", "is_correct": true, "explanation": "水にとけやすく料理にも使える、ものの材料になる中身を指すので文に合う。"}, {"text": "鉄", "is_correct": false, "explanation": "鉄は水にとけず料理に使われるものではないので、「水にとけやすい」の主語に合わない。"}, {"text": "粘土", "is_correct": false, "explanation": "粘土は焼き物の材料で、水にとけやすく料理に使うものではないので文に合わない。"}, {"text": "ガラス", "is_correct": false, "explanation": "ガラスは水にとけず料理にも使わないので、この文の主語として合わない。"}], "explanations": {"物質": "水にとけやすく料理にも使える、ものの材料になる中身を指すので文に合う。", "鉄": "鉄は水にとけず料理に使われるものではないので、「水にとけやすい」の主語に合わない。", "粘土": "粘土は焼き物の材料で、水にとけやすく料理に使うものではないので文に合わない。", "ガラス": "ガラスは水にとけず料理にも使わないので、この文の主語として合わない。"}, "sentence_index": 0, "correct_answer": "物質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "災害のあと、支援の物質を被災地に送った。", "explanation": "ここは〈物資〉（支援などで届ける品物）の意味。物質は材料や成分のことなので、支援の品を指すのには合わない。"}, {"text": "この工場では、毎日千個の物質を作っています。", "explanation": "ここは〈製品〉の意味。物質は作る材料のことなので、完成品を数える使い方には合わない。"}, {"text": "ひどい風邪という物質にかかって、三日も寝込んだ。", "explanation": "ここは〈病気〉（体にかかるもの）の意味。物質は材料や成分のことなので、病気を指すのには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36670, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物質", "is_correct": true, "explanation": "木からとった繊維という、紙の材料になる中身を指すので文に合う。"}, {"text": "季節", "is_correct": false, "explanation": "季節は春や夏などの時期を表すもので、紙を作る材料としては合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙や荷物を届ける仕組みで、紙を作る材料にはならない。"}, {"text": "時間", "is_correct": false, "explanation": "時間は時の長さを表すもので、紙の材料を言う文には合わない。"}], "explanations": {"物質": "木からとった繊維という、紙の材料になる中身を指すので文に合う。", "季節": "季節は春や夏などの時期を表すもので、紙を作る材料としては合わない。", "郵便": "郵便は手紙や荷物を届ける仕組みで、紙を作る材料にはならない。", "時間": "時間は時の長さを表すもので、紙の材料を言う文には合わない。"}, "sentence_index": 6, "correct_answer": "物質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この時計は、小さな歯車という物質で動いています。", "explanation": "ここは〈部品〉の意味。歯車は組み立てる部品のことで、物質は材料の意味なので合わない。"}, {"text": "大工さんは、のこぎりという物質で木を切ります。", "explanation": "ここは〈道具〉の意味。のこぎりは木を切る道具で、物質（材料や成分）とは言わない。"}, {"text": "彼女は、長い小説という物質を書き上げました。", "explanation": "ここは〈作品〉の意味。小説は書き上げる完成品で、物質は材料のことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36670, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ケーキ作りには、小麦粉という物質に必要です。", "corrected_sentence": "ケーキ作りには、小麦粉という物質が必要です。", "error_description": "「必要だ」は「〜が必要です」の形で、必要なものに「が」が付く。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36670, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この皿は、白い粘土という物質をできています。", "corrected_sentence": "この皿は、白い粘土という物質でできています。", "error_description": "「できている」は「〜でできている」の形で、材料を「で」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36671, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「構成する」の目的語として「物質を」が入り、「あらゆる物質を構成する」の形になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「構成する」の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「構成する」の目的語を表す位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「構成する」の目的語を表すことはできないので文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「構成する」の目的語として「物質を」が入り、「あらゆる物質を構成する」の形になる。", "と": "「と」は並列や相手を示すが、「構成する」の目的語にはならない。", "へ": "「へ」は方向を示すが、「構成する」の目的語を表す位置には入らない。", "で": "「で」は手段を示すが、「構成する」の目的語を表すことはできないので文が成り立たない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "で": "手段（目的語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
