INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36671, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物体を構成する材料や成分。", "primary_collocate": null, "pronunciation": "ぶっしつ", "ipa": "bɯɕːitsɯ", "syllable_count": 4, "sentences": [{"text": "水は、酸素と水素からできている物質である。", "target_word": "物質", "complexity_tier": "T3", "furigana": "水[みず]は、酸素[さんそ]と水素[すいそ]からできている物質[ぶっしつ]である。", "sentence_source": "generated"}, {"text": "原子は、あらゆる物質を構成する最も小さな単位の一つだ。", "target_word": "物質", "complexity_tier": "T3", "furigana": "原子[げんし]は、あらゆる物質[ぶっしつ]を構成[こうせい]する最[もっと]も小[ちい]さな単位[たんい]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "空気中の有害な物質を、フィルターで取り除く。", "target_word": "物質", "complexity_tier": "T3", "furigana": "空気中[くうきちゅう]の有害[ゆうがい]な物質[ぶっしつ]を、フィルターで取[と]り除[のぞ]く。", "sentence_source": "generated"}, {"text": "化学では、温度による物質の性質の変化を調べる。", "target_word": "物質", "complexity_tier": "T3", "furigana": "化学[かがく]では、温度[おんど]による物質[ぶっしつ]の性質[せいしつ]の変化[へんか]を調[しら]べる。", "sentence_source": "generated"}, {"text": "食品に含まれる物質は、表示を見れば分かる。", "target_word": "物質", "complexity_tier": "T3", "furigana": "食品[しょくひん]に含[ふく]まれる物質[ぶっしつ]は、表示[ひょうじ]を見[み]れば分[わ]かる。", "sentence_source": "generated"}, {"text": "古代の哲学者は、世界は一つの物質からできていると考えた。", "target_word": "物質", "complexity_tier": "T3", "furigana": "古代[こだい]の哲学者[てつがくしゃ]は、世界[せかい]は一[ひと]つの物質[ぶっしつ]からできていると考[かんが]えた。", "sentence_source": "generated"}, {"text": "金は化学的に安定した物質で、さびにくい。", "target_word": "物質", "complexity_tier": "T3", "furigana": "金[きん]は化学的[かがくてき]に安定[あんてい]した物質[ぶっしつ]で、さびにくい。", "sentence_source": "generated"}, {"text": "水は温度が変わると、固体や気体に姿を変える物質だ。", "target_word": "物質", "complexity_tier": "T3", "furigana": "水[みず]は温度[おんど]が変[か]わると、固体[こたい]や気体[きたい]に姿[すがた]を変[か]える物質[ぶっしつ]だ。", "sentence_source": "generated"}, {"text": "土の中の物質が川に流れ込み、水質に影響した。", "target_word": "物質", "complexity_tier": "T3", "furigana": "土[つち]の中[なか]の物質[ぶっしつ]が川[かわ]に流[なが]れ込[こ]み、水質[すいしつ]に影響[えいきょう]した。", "sentence_source": "generated"}, {"text": "原料から不要な物質を取り除いて、純度を高める。", "target_word": "物質", "complexity_tier": "T3", "furigana": "原料[げんりょう]から不要[ふよう]な物質[ぶっしつ]を取[と]り除[のぞ]いて、純度[じゅんど]を高[たか]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "物質", "label": "基本形"}], "register": "formal", "sense_fingerprint": "物体を構成する材料や成分としての物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36671, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物質", "is_correct": true, "explanation": "物体を構成する材料や成分を表し、「水は〜からできている」の主語として合う。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は音の芸術で、水の構成を説明する文の主語にはならない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は春や夏などの時期で、水の構成要素として合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙や荷物を届ける仕組みで、水の構成を説明する文には合わない。"}], "explanations": {"物質": "物体を構成する材料や成分を表し、「水は〜からできている」の主語として合う。", "音楽": "音楽は音の芸術で、水の構成を説明する文の主語にはならない。", "季節": "季節は春や夏などの時期で、水の構成要素として合わない。", "郵便": "郵便は手紙や荷物を届ける仕組みで、水の構成を説明する文には合わない。"}, "sentence_index": 0, "correct_answer": "物質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "悲しみという物質に包まれて、涙が止まらなかった。", "explanation": "ここは〈感情〉の意味（心に湧く気持ち）。物質は物を作る材料や成分のことなので、感情を指すのには合わない。"}, {"text": "彼は明るい物質の持ち主で、いつも周りを笑顔にする。", "explanation": "ここは〈性格〉（その人の気質）の意味。物質は材料や成分のことで、人柄を言うときには使わないので合わない。"}, {"text": "来年の物質が、ついに発表された。", "explanation": "ここは〈計画〉（これから進める予定）の意味。物質は材料や成分のことなので、計画を指すのには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36671, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物質", "is_correct": true, "explanation": "化学的に安定した、さびにくい金の性質を説明する対象として合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表すもので、化学的な安定性やさびやすさの説明には合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は書いて送る文書で、化学的に安定しているかどうかの説明には合わない。"}, {"text": "名前", "is_correct": false, "explanation": "名前は呼び方を表すもので、化学的な安定性を説明する文の対象にはならない。"}], "explanations": {"物質": "化学的に安定した、さびにくい金の性質を説明する対象として合う。", "天気": "天気は空模様を表すもので、化学的な安定性やさびやすさの説明には合わない。", "手紙": "手紙は書いて送る文書で、化学的に安定しているかどうかの説明には合わない。", "名前": "名前は呼び方を表すもので、化学的な安定性を説明する文の対象にはならない。"}, "sentence_index": 6, "correct_answer": "物質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールという物質が、転がって壁にぶつかった。", "explanation": "ここは〈物体〉の意味。ボールは形のある物体で、物質（材料や成分）とは言わないので合わない。"}, {"text": "桜という物質が、春に花を咲かせる。", "explanation": "ここは〈植物〉の意味。桜は生きている植物で、物質（材料や成分）とは言わないので合わない。"}, {"text": "家族は、大きな電車という物質で、遠くまで旅行した。", "explanation": "ここは〈乗り物〉の意味。電車は人を運ぶ乗り物で、物質（材料や成分）とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36671, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空気は、窒素や酸素などの物質を混ざったものだ。", "corrected_sentence": "空気は、窒素や酸素などの物質が混ざったものだ。", "error_description": "「混ざる」は自動詞なので、主語を示す「が」が正しい。「を」は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36671, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水は、いろいろな物質が溶かす性質がある。", "corrected_sentence": "水は、いろいろな物質を溶かす性質がある。", "error_description": "「溶かす」は他動詞なので目的語を示す「を」が正しい。「が」にすると「物質が溶かす」となり意味が逆になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
