INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36672, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「発現が早い」で、早さの主体（現れること）を示す正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "位置や時を示す。「発現に早い」は述語と合わず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「発現で早い」は形容詞の主語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「発現へ早い」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「発現が早い」で、早さの主体（現れること）を示す正しい格助詞。", "に": "位置や時を示す。「発現に早い」は述語と合わず成り立たない。", "で": "手段や場所を示す。「発現で早い」は形容詞の主語として成り立たない。", "へ": "方向を示す。「発現へ早い」は文として成り立たない。"}, "error_tags": {"に": "位置", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36672, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが外に出てくること。", "primary_collocate": null, "pronunciation": "はつげん", "ipa": "hatsɯɡeɴ", "syllable_count": 4, "sentences": [{"text": "薬を飲んでから数時間後に、副作用の発現が見られた。", "target_word": "発現", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んでから数時間後[すうじかんご]に、副作用[ふくさよう]の発現[はつげん]が見[み]られた。", "sentence_source": "generated"}, {"text": "ストレスが原因で、長く隠れていた持病の症状が発現した。", "target_word": "発現", "complexity_tier": "T3", "furigana": "ストレスが原因[げんいん]で、長く隠[かく]れていた持病[じびょう]の症状[しょうじょう]が発現[はつげん]した。", "sentence_source": "generated"}, {"text": "病気の症状の発現は、人によって時期が違う。", "target_word": "発現", "complexity_tier": "T3", "furigana": "病気[びょうき]の症状[しょうじょう]の発現[はつげん]は、人[ひと]によって時期[じき]が違[ちが]う。", "sentence_source": "generated"}, {"text": "能力の発現には、長い訓練と時間が必要だ。", "target_word": "発現", "complexity_tier": "T3", "furigana": "能力[のうりょく]の発現[はつげん]には、長[なが]い訓練[くんれん]と時間[じかん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "植物の花の色の発現は、温度に影響される。", "target_word": "発現", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]の花[はな]の色[いろ]の発現[はつげん]は、温度[おんど]に影響[えいきょう]される。", "sentence_source": "generated"}, {"text": "ウイルスに感染しても、症状の発現がないこともある。", "target_word": "発現", "complexity_tier": "T3", "furigana": "ウイルスに感染[かんせん]しても、症状[しょうじょう]の発現[はつげん]がないこともある。", "sentence_source": "generated"}, {"text": "才能の発現を待つよりも、毎日練習を続けるほうがいい。", "target_word": "発現", "complexity_tier": "T3", "furigana": "才能[さいのう]の発現[はつげん]を待[ま]つよりも、毎日[まいにち]練習[れんしゅう]を続[つづ]けるほうがいい。", "sentence_source": "generated"}, {"text": "この薬は効果の発現が早いので、急な痛みにも使われる。", "target_word": "発現", "complexity_tier": "T3", "furigana": "この薬[くすり]は効果[こうか]の発現[はつげん]が早[はや]いので、急[きゅう]な痛[いた]みにも使[つか]われる。", "sentence_source": "generated"}, {"text": "病状の発現を早く察知できれば、治療の選択肢も広がる。", "target_word": "発現", "complexity_tier": "T3", "furigana": "病状[びょうじょう]の発現[はつげん]を早く察知[さっち]できれば、治療[ちりょう]の選択肢[せんたくし]も広がる。", "sentence_source": "generated"}, {"text": "子どもの個性の発現を、親は温かく見守るべきだ。", "target_word": "発現", "complexity_tier": "T3", "furigana": "子[こ]どもの個性[こせい]の発現[はつげん]を、親[おや]は温[あたた]かく見守[みまも]るべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発現する", "label": "サ変動詞 終止形"}, {"form": "発現した", "label": "過去形"}, {"form": "発現して", "label": "て形"}, {"form": "発現しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "内にあったものが外に出て現れてくること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36672, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発現", "is_correct": true, "explanation": "名詞。「副作用の発現が見られた」と、「の」の後に名詞として入る正しい形。"}, {"text": "発現する", "is_correct": false, "explanation": "動詞の終止形。「副作用の発現する」となり、名詞として続かない。"}, {"text": "発現した", "is_correct": false, "explanation": "動詞の過去形。「副作用の発現した」は名詞句として成り立たない。"}, {"text": "発現しない", "is_correct": false, "explanation": "否定の動詞形。「副作用の発現しない」は名詞句として成り立たない。"}], "explanations": {"発現": "名詞。「副作用の発現が見られた」と、「の」の後に名詞として入る正しい形。", "発現する": "動詞の終止形。「副作用の発現する」となり、名詞として続かない。", "発現した": "動詞の過去形。「副作用の発現した」は名詞句として成り立たない。", "発現しない": "否定の動詞形。「副作用の発現しない」は名詞句として成り立たない。"}, "sentence_index": 0, "correct_answer": "発現"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議で、みんなの前で意見を発現した。", "explanation": "ここは同音の〈発言〉の意味。発現は内にあったものが外に現れることで、意見を述べる意味にはならない。"}, {"text": "彼女は言葉で、自分の気持ちを発現した。", "explanation": "ここは〈表現〉の意味。発現は内にあるものが現れることで、気持ちを言葉で表す意味には使わない。"}, {"text": "長年の夢が、ついに発現した。", "explanation": "ここは〈実現〉の意味。発現は現象や性質が現れることで、計画や夢が形になる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36672, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発現", "is_correct": true, "explanation": "名詞。「才能の発現を待つ」と、「の」の後で目的語になる正しい形。"}, {"text": "発現し", "is_correct": false, "explanation": "連用形。「才能の発現しを待つ」となり、名詞として成り立たない。"}, {"text": "発現す", "is_correct": false, "explanation": "動詞の語幹。「才能の発現すを待つ」となり、文として成り立たない。"}, {"text": "発現せ", "is_correct": false, "explanation": "未然形。「才能の発現せを待つ」となり、名詞として続かない。"}], "explanations": {"発現": "名詞。「才能の発現を待つ」と、「の」の後で目的語になる正しい形。", "発現し": "連用形。「才能の発現しを待つ」となり、名詞として成り立たない。", "発現す": "動詞の語幹。「才能の発現すを待つ」となり、文として成り立たない。", "発現せ": "未然形。「才能の発現せを待つ」となり、名詞として続かない。"}, "sentence_index": 6, "correct_answer": "発現"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に事故が発現して、道が封鎖された。", "explanation": "ここは〈発生〉の意味。発現は内にあったものが外に現れることで、事故が起こる意味には使わない。"}, {"text": "社長は新しい方針を発現した。", "explanation": "ここは〈表明〉の意味。発現は現れることで、方針を公に示す意味にはならない。"}, {"text": "会議の日程を発現した。", "explanation": "ここは〈延期〉の意味。発現は現れることで、日程を先に延ばす意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36672, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強いストレスで、長く隠れていた症状を発現した。", "corrected_sentence": "強いストレスで、長く隠れていた症状が発現した。", "error_description": "誤りは「症状を」。発現は自動詞で、現れるもの（症状）は「が」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36672, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病気の症状を、夜になると発現しやすい。", "corrected_sentence": "病気の症状が、夜になると発現しやすい。", "error_description": "誤りは「症状を」。発現の主体には「が」を使い、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36674, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「動物を飼ってはいけない」で、飼う対象として動物を示す「を」が入る。"}, {"text": "へ", "is_correct": false, "explanation": "「動物へ飼ってはいけない」は方向の意味になり、飼う対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「動物で飼ってはいけない」は手段の意味になり、飼う対象を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「動物の飼ってはいけない」は名詞の修飾になり、動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "正解。「動物を飼ってはいけない」で、飼う対象として動物を示す「を」が入る。", "へ": "「動物へ飼ってはいけない」は方向の意味になり、飼う対象を表せない。", "で": "「動物で飼ってはいけない」は手段の意味になり、飼う対象を表せない。", "の": "「動物の飼ってはいけない」は名詞の修飾になり、動詞の目的語にならない。"}, "error_tags": {"へ": "方向", "で": "手段", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36674, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「動物にやさしい」で、やさしくする対象として動物を示す「に」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「やさしい」は目的語を取れないので、「動物をやさしい」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「動物からやさしい」は起点の意味になり、やさしさの対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「動物とやさしい」は並列・相手の意味になり、やさしさの対象を表せない。"}], "correct_answer": "に", "explanations": {"に": "正解。「動物にやさしい」で、やさしくする対象として動物を示す「に」が入る。", "を": "「やさしい」は目的語を取れないので、「動物をやさしい」は成り立たない。", "から": "「動物からやさしい」は起点の意味になり、やさしさの対象を表せない。", "と": "「動物とやさしい」は並列・相手の意味になり、やさしさの対象を表せない。"}, "error_tags": {"を": "目的語", "から": "起点", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36674, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生きもののこと。犬や猫、鳥、魚など、人間以外の生きものをいう。", "primary_collocate": null, "pronunciation": "どうぶつ", "ipa": "doːbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "動物の中で、犬がいちばん好きだ。", "target_word": "動物", "complexity_tier": "T2", "furigana": "動物[どうぶつ]の中[なか]で、犬[いぬ]がいちばん好[す]きだ。", "sentence_source": "generated"}, {"text": "私の町には、動物を飼ってはいけないアパートが多い。", "target_word": "動物", "complexity_tier": "T3", "furigana": "私[わたし]の町[まち]には、動物[どうぶつ]を飼[か]ってはいけないアパートが多[おお]い。", "sentence_source": "generated"}, {"text": "旅行の間、飼っている動物は友だちが世話してくれた。", "target_word": "動物", "complexity_tier": "T3", "furigana": "旅行[りょこう]の間[あいだ]、飼[か]っている動物[どうぶつ]は友[とも]だちが世話[せわ]してくれた。", "sentence_source": "generated"}, {"text": "子どもたちは、動物の絵本を読むのが好きだ。", "target_word": "動物", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、動物[どうぶつ]の絵本[えほん]を読[よ]むのが好[す]きだ。", "sentence_source": "generated"}, {"text": "水の中にすむ動物には、魚のほかに貝もいる。", "target_word": "動物", "complexity_tier": "T3", "furigana": "水[みず]の中[なか]にすむ動物[どうぶつ]には、魚[さかな]のほかに貝[かい]もいる。", "sentence_source": "generated"}, {"text": "動物に急に近づくと、おどろいてにげてしまう。", "target_word": "動物", "complexity_tier": "T3", "furigana": "動物[どうぶつ]に急[きゅう]に近[ちか]づくと、おどろいてにげてしまう。", "sentence_source": "generated"}, {"text": "祖父の家では、いろいろな動物を飼っていた。", "target_word": "動物", "complexity_tier": "T3", "furigana": "祖父[そふ]の家[いえ]では、いろいろな動物[どうぶつ]を飼[か]っていた。", "sentence_source": "generated"}, {"text": "動物にやさしい人は、人にもやさしいと思う。", "target_word": "動物", "complexity_tier": "T3", "furigana": "動物[どうぶつ]にやさしい人[ひと]は、人[ひと]にもやさしいと思[おも]う。", "sentence_source": "generated"}, {"text": "雪の上に、小さな動物の足あとが残っていた。", "target_word": "動物", "complexity_tier": "T3", "furigana": "雪[ゆき]の上[うえ]に、小[ちい]さな動物[どうぶつ]の足[あし]あとが残[のこ]っていた。", "sentence_source": "generated"}, {"text": "動物は食べ物がないと、生きていけない。", "target_word": "動物", "complexity_tier": "T3", "furigana": "動物[どうぶつ]は食[た]べ物[もの]がないと、生[い]きていけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動物", "label": "基本形"}, {"form": "動物たち", "label": "複数"}], "register": "neutral", "sense_fingerprint": "犬・猫・鳥・魚など、人間以外の身近な生きもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36674, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動物", "is_correct": true, "explanation": "正解。「動物の中で、犬がいちばん好きだ」で、犬が含まれる生きものの範囲を指す。"}, {"text": "季節", "is_correct": false, "explanation": "「季節の中で、犬がいちばん好きだ」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の中で、犬がいちばん好きだ」は意味が通らない。"}, {"text": "色", "is_correct": false, "explanation": "「色の中で、犬がいちばん好きだ」は意味が通らない。"}], "explanations": {"動物": "正解。「動物の中で、犬がいちばん好きだ」で、犬が含まれる生きものの範囲を指す。", "季節": "「季節の中で、犬がいちばん好きだ」は意味が通らない。", "天気": "「天気の中で、犬がいちばん好きだ」は意味が通らない。", "色": "「色の中で、犬がいちばん好きだ」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "動物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓辺に、動物の花を植えた。", "explanation": "ここは〈植物〉の意味。花は植物なので、動物の花という言い方は合わない。"}, {"text": "港には、古い動物が停泊している。", "explanation": "ここは〈船〉の意味。停泊するのは船なので、動物が港に止まる話には合わない。"}, {"text": "台所で、動物の鍋を磨いた。", "explanation": "ここは〈道具〉の意味。鍋は道具なので、動物の鍋という言い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36674, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動物", "is_correct": true, "explanation": "正解。「祖父の家では、いろいろな動物を飼っていた」で、飼われていた生きものを指す。"}, {"text": "道具", "is_correct": false, "explanation": "「いろいろな道具を飼っていた」は意味が通らず、道具は飼わない。"}, {"text": "家具", "is_correct": false, "explanation": "「いろいろな家具を飼っていた」は意味が通らず、家具は飼わない。"}, {"text": "文房具", "is_correct": false, "explanation": "「いろいろな文房具を飼っていた」は意味が通らず、文房具は飼わない。"}], "explanations": {"動物": "正解。「祖父の家では、いろいろな動物を飼っていた」で、飼われていた生きものを指す。", "道具": "「いろいろな道具を飼っていた」は意味が通らず、道具は飼わない。", "家具": "「いろいろな家具を飼っていた」は意味が通らず、家具は飼わない。", "文房具": "「いろいろな文房具を飼っていた」は意味が通らず、文房具は飼わない。"}, "sentence_index": 6, "correct_answer": "動物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空には、星という動物が光っている。", "explanation": "ここは〈星〉の意味。星は動物ではないので、星を動物と呼ぶのは合わない。"}, {"text": "この動物は、ガソリンで走る乗り物だ。", "explanation": "ここは〈乗り物〉の意味。乗り物は人や物を運ぶもので、動物をそう呼ぶのは合わない。"}, {"text": "この動物は、本棚に並べて読む一冊だ。", "explanation": "ここは〈本〉の意味。本は読むものなので、動物を一冊と数えるのは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36674, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、庭で動物とえさを与えている。", "corrected_sentence": "祖母は、庭で動物にえさを与えている。", "error_description": "与える相手の助詞の誤り。正しくは「動物に与える」で、「動物と」では与える相手を表せず不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36674, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "動物に飼う人は、最後まで世話をする責任がある。", "corrected_sentence": "動物を飼う人は、最後まで世話をする責任がある。", "error_description": "目的語の助詞の誤り。正しくは「動物を飼う」で、「動物に飼う」は飼う対象を表せず不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36675, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「めずらしい動物がすんでいる」で、すむ主体として動物を示す「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「すむ」は目的語を取らないので、「動物をすんでいる」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するだけで、「動物の何種類もすんでいる」では動詞の主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「すむ」の主語を表せない。"}], "correct_answer": "が", "explanations": {"が": "正解。「めずらしい動物がすんでいる」で、すむ主体として動物を示す「が」が入る。", "を": "「すむ」は目的語を取らないので、「動物をすんでいる」は成り立たない。", "の": "「の」は名詞を修飾するだけで、「動物の何種類もすんでいる」では動詞の主語にならない。", "へ": "「へ」は方向を示すので、「すむ」の主語を表せない。"}, "error_tags": {"を": "目的語", "の": "修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36675, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「動物に餌をやる」で、餌を与える相手として動物を示す「に」が入る。"}, {"text": "で", "is_correct": false, "explanation": "「動物で餌をやる」は手段・場所の意味になり、与える相手を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「動物から餌をやる」は起点の意味になり、与える相手を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「動物より餌をやる」は比較の意味になり、文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「動物に餌をやる」で、餌を与える相手として動物を示す「に」が入る。", "で": "「動物で餌をやる」は手段・場所の意味になり、与える相手を表せない。", "から": "「動物から餌をやる」は起点の意味になり、与える相手を表せない。", "より": "「動物より餌をやる」は比較の意味になり、文として成り立たない。"}, "error_tags": {"で": "手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36675, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間以外の生物。特に、移動する能力をもつ生物の総称。", "primary_collocate": null, "pronunciation": "どうぶつ", "ipa": "doːbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "彼が大切にしているのは、動物である鶏たちへの給餌だ。", "target_word": "動物", "complexity_tier": "T3", "furigana": "彼[かれ]が大切[たいせつ]にしているのは、動物[どうぶつ]である鶏[にわとり]たちへの給餌[きゅうじ]だ。", "sentence_source": "mined"}, {"text": "ここの森には、めずらしい動物が何種類もすんでいる。", "target_word": "動物", "complexity_tier": "T3", "furigana": "ここの森[もり]には、めずらしい動物[どうぶつ]が何種類[なんしゅるい]もすんでいる。", "sentence_source": "generated"}, {"text": "動物が好きな妹は、将来獣医になりたいと言っている。", "target_word": "動物", "complexity_tier": "T3", "furigana": "動物[どうぶつ]が好[す]きな妹[いもうと]は、将来[しょうらい]獣医[じゅうい]になりたいと言[い]っている。", "sentence_source": "generated"}, {"text": "犬や猫のような動物は、人間と一緒に暮らすことが多い。", "target_word": "動物", "complexity_tier": "T3", "furigana": "犬[いぬ]や猫[ねこ]のような動物[どうぶつ]は、人間[にんげん]と一緒[いっしょ]に暮[く]らすことが多[おお]い。", "sentence_source": "generated"}, {"text": "冬になると、動物の中には長く眠るものもいる。", "target_word": "動物", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、動物[どうぶつ]の中[なか]には長[なが]く眠[ねむ]るものもいる。", "sentence_source": "generated"}, {"text": "植物は動かないが、動物は自分で動いて食べ物を探す。", "target_word": "動物", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は動[うご]かないが、動物[どうぶつ]は自分[じぶん]で動[うご]いて食[た]べ物[もの]を探[さが]す。", "sentence_source": "generated"}, {"text": "この島には、ほかの国では見られない動物がいる。", "target_word": "動物", "complexity_tier": "T3", "furigana": "この島[しま]には、ほかの国[くに]では見[み]られない動物[どうぶつ]がいる。", "sentence_source": "generated"}, {"text": "動物にえさをやる前に、必ず手を洗うことになっている。", "target_word": "動物", "complexity_tier": "T3", "furigana": "動物[どうぶつ]にえさをやる前[まえ]に、必[かなら]ず手[て]を洗[あら]うことになっている。", "sentence_source": "generated"}, {"text": "クジラやライオンも、動物の仲間に入る。", "target_word": "動物", "complexity_tier": "T3", "furigana": "クジラやライオンも、動物[どうぶつ]の仲間[なかま]に入[はい]る。", "sentence_source": "generated"}, {"text": "夜になると、山の動物たちは静かに動き出す。", "target_word": "動物", "complexity_tier": "T3", "furigana": "夜[よる]になると、山[やま]の動物[どうぶつ]たちは静[しず]かに動[うご]き出[だ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動物", "label": "基本形"}, {"form": "動物たち", "label": "複数"}], "register": "neutral", "sense_fingerprint": "植物に対し、移動能力をもつ生物の総称（人間を除く）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36675, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動物", "is_correct": true, "explanation": "正解。「動物である鶏たち」で、鶏が生きものの一種であることを表す。"}, {"text": "道具", "is_correct": false, "explanation": "「道具である鶏たち」は意味が通らず、鶏は道具ではない。"}, {"text": "家具", "is_correct": false, "explanation": "「家具である鶏たち」は意味が通らず、鶏は家具ではない。"}, {"text": "文房具", "is_correct": false, "explanation": "「文房具である鶏たち」は意味が通らず、鶏は文房具ではない。"}], "explanations": {"動物": "正解。「動物である鶏たち」で、鶏が生きものの一種であることを表す。", "道具": "「道具である鶏たち」は意味が通らず、鶏は道具ではない。", "家具": "「家具である鶏たち」は意味が通らず、鶏は家具ではない。", "文房具": "「文房具である鶏たち」は意味が通らず、鶏は文房具ではない。"}, "sentence_index": 0, "correct_answer": "動物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の草木も、大切な動物の一つだ。", "explanation": "ここは〈生き物〉の意味。草木は動物ではないので、植物も含めるなら生き物と言うべきで、動物とは合わない。"}, {"text": "この細菌は、動物の仲間に入る。", "explanation": "ここは〈微生物〉の意味。細菌は微生物で動物の仲間ではないので、動物とは合わない。"}, {"text": "山の上には、古い動物が建っている。", "explanation": "ここは〈建物〉の意味。動物は建つものではないので、山の上の建物の話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36675, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動物", "is_correct": true, "explanation": "正解。「この島にはほかの国では見られない動物がいる」で、島にいる生きものを指す。"}, {"text": "食器", "is_correct": false, "explanation": "「食器がいる」は意味が通らず、食器は生きものではない。"}, {"text": "楽器", "is_correct": false, "explanation": "「楽器がいる」は意味が通らず、楽器は生きものではない。"}, {"text": "家屋", "is_correct": false, "explanation": "「家屋がいる」は意味が通らず、家屋は生きものではない。"}], "explanations": {"動物": "正解。「この島にはほかの国では見られない動物がいる」で、島にいる生きものを指す。", "食器": "「食器がいる」は意味が通らず、食器は生きものではない。", "楽器": "「楽器がいる」は意味が通らず、楽器は生きものではない。", "家屋": "「家屋がいる」は意味が通らず、家屋は生きものではない。"}, "sentence_index": 6, "correct_answer": "動物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "動物の入場料は、大人千円だ。", "explanation": "ここは〈動物園〉の意味。動物は生きものそのものなので、施設の入場料の話には合わない。"}, {"text": "ワカメは、動物として海で育つ。", "explanation": "ここは〈植物〉の意味。ワカメは海藻という植物なので、動物の分類には入らない。"}, {"text": "この鉱石は、動物の一種だと教わった。", "explanation": "ここは〈鉱物〉の意味。鉱石は生きものではないので、動物の一種とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36675, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の家では、動物で三匹飼っている。", "corrected_sentence": "私の家では、動物を三匹飼っている。", "error_description": "目的語の助詞の誤り。正しくは「動物を飼う」で、「動物で」は手段・場所の意味になり、飼う対象を表せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36675, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "動物園では、珍しい動物で見ることができる。", "corrected_sentence": "動物園では、珍しい動物を見ることができる。", "error_description": "目的語の助詞の誤り。正しくは「動物を見る」で、「動物で」は手段の意味になり、見る対象を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
