INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36676, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが本当かどうかを確かめるために、やってみること。", "primary_collocate": null, "pronunciation": "じっけん", "ipa": "dʑikkeɴ", "syllable_count": 4, "sentences": [{"text": "この実験は、氷が水より軽いかどうかを確かめるものです。", "target_word": "実験", "complexity_tier": "T3", "furigana": "この実験(じっけん)は、氷(こおり)が水(みず)より軽(かる)いかどうかを確(たし)かめるものです。", "sentence_source": "generated"}, {"text": "学校で、火を使わない簡単な実験をしました。", "target_word": "実験", "complexity_tier": "T3", "furigana": "学校(がっこう)で、火(ひ)を使(つか)わない簡単(かんたん)な実験(じっけん)をしました。", "sentence_source": "generated"}, {"text": "実験をして、予想が正しいかどうか調べました。", "target_word": "実験", "complexity_tier": "T3", "furigana": "実験(じっけん)をして、予想(よそう)が正(ただ)しいかどうか調(しら)べました。", "sentence_source": "generated"}, {"text": "実験のあとで、道具をきれいに洗いました。", "target_word": "実験", "complexity_tier": "T3", "furigana": "実験(じっけん)のあとで、道具(どうぐ)をきれいに洗(あら)いました。", "sentence_source": "generated"}, {"text": "兄は台所で、ジュースの色が変わるか実験している。", "target_word": "実験", "complexity_tier": "T3", "furigana": "兄(あに)は台所(だいどころ)で、ジュースの色(いろ)が変(か)わるか実験(じっけん)している。", "sentence_source": "generated"}, {"text": "実験が成功して、みんなで喜びました。", "target_word": "実験", "complexity_tier": "T3", "furigana": "実験(じっけん)が成功(せいこう)して、みんなで喜(よろこ)びました。", "sentence_source": "generated"}, {"text": "私の実験では、水をやらなくても豆から芽が出ました。", "target_word": "実験", "complexity_tier": "T3", "furigana": "私(わたし)の実験(じっけん)では、水(みず)をやらなくても豆(まめ)から芽(め)が出(で)ました。", "sentence_source": "generated"}, {"text": "先生と一緒に、風の強さをはかる実験を見ました。", "target_word": "実験", "complexity_tier": "T3", "furigana": "先生(せんせい)と一緒(いっしょ)に、風(かぜ)の強(つよ)さをはかる実験(じっけん)を見(み)ました。", "sentence_source": "generated"}, {"text": "実験の前に、ゴーグルをつけてください。", "target_word": "実験", "complexity_tier": "T3", "furigana": "実験(じっけん)の前(まえ)に、ゴーグルをつけてください。", "sentence_source": "generated"}, {"text": "砂糖が本当に水に溶けるのか、実験してみよう。", "target_word": "実験", "complexity_tier": "T3", "furigana": "砂糖(さとう)が本当(ほんとう)に水(みず)に溶(と)けるのか、実験(じっけん)してみよう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実験", "label": "基本形"}, {"form": "実験する", "label": "サ変動詞"}, {"form": "実験した", "label": "過去形"}, {"form": "実験して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "本当かどうかを確かめるために実際にやってみること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36676, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実験", "is_correct": true, "explanation": "「本当かどうかを確かめるもの」という文の内容に合う、確かめのために試す活動を指す語。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物を作ることで、氷と水の重さを確かめる文には合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行は場所を移動して楽しむ活動で、ものの性質を確かめる内容とは合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩いて過ごすことで、確かめる目的を述べる文脈に合わない。"}], "explanations": {"実験": "「本当かどうかを確かめるもの」という文の内容に合う、確かめのために試す活動を指す語。", "料理": "料理は食べ物を作ることで、氷と水の重さを確かめる文には合わない。", "旅行": "旅行は場所を移動して楽しむ活動で、ものの性質を確かめる内容とは合わない。", "散歩": "散歩は歩いて過ごすことで、確かめる目的を述べる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "実験"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は舞台で、王様の実験を演じた。", "explanation": "ここは〈演技〉の意味。役を演じることは演技で、確かめるための試みの実験とは言わない。"}, {"text": "健康診断で、血液の実験を受けました。", "explanation": "ここは〈検査〉の意味。実験は自分で試して確かめる作業で、病院の検査には使わない。"}, {"text": "新しい社長は、会社の実験を握った。", "explanation": "ここは〈実権〉（本当の権限）の意味の別の語。実験は確かめる試みを指すので、組織の権力には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36676, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実験", "is_correct": true, "explanation": "豆に水をやらずに芽が出たという内容を試す、確かめのための試みを表す語。"}, {"text": "誕生日", "is_correct": false, "explanation": "誕生日は祝う日のことで、豆の芽の話の文脈に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、「私の天気では」という言い方は成り立たない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙や荷物を送ることで、豆の芽が出た話には合わない。"}], "explanations": {"実験": "豆に水をやらずに芽が出たという内容を試す、確かめのための試みを表す語。", "誕生日": "誕生日は祝う日のことで、豆の芽の話の文脈に合わない。", "天気": "天気は空模様のことで、「私の天気では」という言い方は成り立たない。", "郵便": "郵便は手紙や荷物を送ることで、豆の芽が出た話には合わない。"}, "sentence_index": 6, "correct_answer": "実験"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は論文のために古い資料を実験している。", "explanation": "ここは〈研究〉の意味。資料を調べて考察する作業は研究で、確かめるための試みの実験とは言わない。"}, {"text": "毎週土曜日に、部屋の実験をする。", "explanation": "ここは〈掃除〉の意味。部屋をきれいにする作業で、実験とは言わない。"}, {"text": "先生が答案の実験をしている。", "explanation": "ここは〈採点〉の意味。答案に点数をつける作業で、実験は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36676, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は、氷が溶けるかどうかを実験に確かめた。", "corrected_sentence": "私は、氷が溶けるかどうかを実験で確かめた。", "error_description": "「実験で確かめる」が正しい。手段を表す「で」を使う。「実験に」は「確かめる」と続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36676, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実験を開く前に、器具を確かめた。", "corrected_sentence": "実験を行う前に、器具を確かめた。", "error_description": "「実験を行う」が正しい。「開く」は会や店などに使い、実験とは続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
