INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36677, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「楽しんだ」の目的語（実験を楽しむ）なので「を」。"}, {"text": "が", "is_correct": false, "explanation": "「楽しんだ」の主語は子どもたちなので、目的語の位置に「が」は入らない。"}, {"text": "に", "is_correct": false, "explanation": "「実験に楽しんだ」は成り立たない。「楽しむ」は「を」で目的語を取る。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「実験へ楽しむ」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「楽しんだ」の目的語（実験を楽しむ）なので「を」。", "が": "「楽しんだ」の主語は子どもたちなので、目的語の位置に「が」は入らない。", "に": "「実験に楽しんだ」は成り立たない。「楽しむ」は「を」で目的語を取る。", "へ": "「へ」は方向を表すので、「実験へ楽しむ」は意味が通らない。"}, "error_tags": {"が": "主語", "に": "位置・対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36677, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あることが正しいかどうかや、どんな結果になるかを調べるために行うこと。", "primary_collocate": null, "pronunciation": "じっけん", "ipa": "dʑikkeɴ", "syllable_count": 4, "sentences": [{"text": "水温と室温をミリ単位で制御し、小麦粉と水のみを混ぜ合わせる行為は、単なる調理の域を超え、微生物の生態系を育む科学的な実験とも呼応する。", "target_word": "実験", "complexity_tier": "T5", "furigana": "水温(すいおん)と室温(しつおん)をミリ単位(たんい)で制御(せいぎょ)し、小麦粉(こむぎこ)と水(みず)のみを混(ま)ぜ合(あ)わせる行為(こうい)は、単(たん)なる調理(ちょうり)の域(いき)を超(こ)え、微生物(びせいぶつ)の生態系(せいたいけい)を育(はぐく)む科学的(かがくてき)な実験(じっけん)とも呼応(こおう)する。", "sentence_source": "mined"}, {"text": "理科の授業で、水が百度で沸騰するか実験しました。", "target_word": "実験", "complexity_tier": "T3", "furigana": "理科(りか)の授業(じゅぎょう)で、水(みず)が百度(ひゃくど)で沸騰(ふっとう)するか実験(じっけん)しました。", "sentence_source": "generated"}, {"text": "この実験では、温度を変えても結果が同じかどうかを調べます。", "target_word": "実験", "complexity_tier": "T3", "furigana": "この実験(じっけん)では、温度(おんど)を変(か)えても結果(けっか)が同(おな)じかどうかを調(しら)べます。", "sentence_source": "generated"}, {"text": "新しい薬の効果を確かめるため、動物を使った実験が行われた。", "target_word": "実験", "complexity_tier": "T3", "furigana": "新(あたら)しい薬(くすり)の効果(こうか)を確(たし)かめるため、動物(どうぶつ)を使(つか)った実験(じっけん)が行(おこな)われた。", "sentence_source": "generated"}, {"text": "実験に失敗したので、原因を考えてもう一度やり直した。", "target_word": "実験", "complexity_tier": "T3", "furigana": "実験(じっけん)に失敗(しっぱい)したので、原因(げんいん)を考(かんが)えてもう一度(いちど)やり直(なお)した。", "sentence_source": "generated"}, {"text": "彼は自分の仮説が正しいと証明するために、何度も実験を重ねた。", "target_word": "実験", "complexity_tier": "T3", "furigana": "彼(かれ)は自分(じぶん)の仮説(かせつ)が正(ただ)しいと証明(しょうめい)するために、何度(なんど)も実験(じっけん)を重(かさ)ねた。", "sentence_source": "generated"}, {"text": "実験の結果、植物は光がなくても数日は生きることが分かった。", "target_word": "実験", "complexity_tier": "T3", "furigana": "実験(じっけん)の結果(けっか)、植物(しょくぶつ)は光(ひかり)がなくても数日(すうじつ)は生(い)きることが分(わ)かった。", "sentence_source": "generated"}, {"text": "子どもたちは、磁石がくっつく物を調べる実験を楽しんだ。", "target_word": "実験", "complexity_tier": "T3", "furigana": "子(こ)どもたちは、磁石(じしゃく)がくっつく物(もの)を調(しら)べる実験(じっけん)を楽(たの)しんだ。", "sentence_source": "generated"}, {"text": "研究室では、安全のため実験の前に必ず手順を確認する。", "target_word": "実験", "complexity_tier": "T3", "furigana": "研究室(けんきゅうしつ)では、安全(あんぜん)のため実験(じっけん)の前(まえ)に必(かなら)ず手順(てじゅん)を確認(かくにん)する。", "sentence_source": "generated"}, {"text": "実験で得たデータを、表にまとめて先生に提出した。", "target_word": "実験", "complexity_tier": "T3", "furigana": "実験(じっけん)で得(え)たデータを、表(ひょう)にまとめて先生(せんせい)に提出(ていしゅつ)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実験", "label": "基本形"}, {"form": "実験する", "label": "サ変動詞"}, {"form": "実験した", "label": "過去形"}, {"form": "実験して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "仮説が正しいか、結果がどうなるかを調べるために行う操作や試み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 7 words above tier T2 (max 3): 水温 (Zipf 3.22), 室温 (Zipf 3.3), 小麦粉 (Zipf 3.59), 混ぜ合わ (Zipf 2.89), 微生物 (Zipf 3.52), 育む (Zipf 3.02)']::text[], 'a709c419-0fda-4240-8628-7e66ce402bcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36677, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演奏", "is_correct": false, "explanation": "「科学的な演奏」は成り立たない。演奏は音楽の行為で、科学的な営みとは呼応しない。"}, {"text": "実験", "is_correct": true, "explanation": "「科学的な実験」とつながり、科学的な試みとして文の流れに合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「科学的な散歩」は意味が通らない。散歩は歩く行為で、科学とは呼応しない。"}, {"text": "掃除", "is_correct": false, "explanation": "「科学的な掃除」は不自然。掃除は清める行為で、科学的な試みには当たらない。"}], "explanations": {"演奏": "「科学的な演奏」は成り立たない。演奏は音楽の行為で、科学的な営みとは呼応しない。", "実験": "「科学的な実験」とつながり、科学的な試みとして文の流れに合う。", "散歩": "「科学的な散歩」は意味が通らない。散歩は歩く行為で、科学とは呼応しない。", "掃除": "「科学的な掃除」は不自然。掃除は清める行為で、科学的な試みには当たらない。"}, "sentence_index": 0, "correct_answer": "実験"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎日、ピアノの実験をして上達を目指す。", "explanation": "ここは〈練習〉の意味。上達のために繰り返し行うのは練習で、確かめる実験とは言わない。"}, {"text": "健康診断で、血液の実験を受けた。", "explanation": "ここは〈検査〉の意味。健康状態を調べるのは検査で、「実験を受ける」とは言わない。"}, {"text": "夕飯に、家族のために実験を作った。", "explanation": "ここは〈料理〉の意味。食事を作るのは料理で、実験を食事として作ることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36677, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "料理", "is_correct": false, "explanation": "「料理の結果、植物は光がなくても数日は生きる」は意味が通らない。料理は調理で、植物の性質の結果にはならない。"}, {"text": "実験", "is_correct": true, "explanation": "「実験の結果」は、調べて分かった結果を表す自然な言い方で、後ろの内容につながる。"}, {"text": "旅行", "is_correct": false, "explanation": "「旅行の結果」は植物の性質の結論にならず、文の流れに合わない。"}, {"text": "買い物", "is_correct": false, "explanation": "「買い物の結果」は植物の性質の結論に続かず、不自然。"}], "explanations": {"料理": "「料理の結果、植物は光がなくても数日は生きる」は意味が通らない。料理は調理で、植物の性質の結果にはならない。", "実験": "「実験の結果」は、調べて分かった結果を表す自然な言い方で、後ろの内容につながる。", "旅行": "「旅行の結果」は植物の性質の結論にならず、文の流れに合わない。", "買い物": "「買い物の結果」は植物の性質の結論に続かず、不自然。"}, "sentence_index": 6, "correct_answer": "実験"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店で、日替わりの実験を注文した。", "explanation": "ここは〈注文〉の意味。料理や品物を頼むのは注文で、実験は品物として頼めるものではない。"}, {"text": "夏休みの宿題で、感想の実験を書いた。", "explanation": "ここは〈作文〉の意味。感想を書くのは作文で、「感想の実験」とは言わない。"}, {"text": "店の看板に、実験の値段を書いた。", "explanation": "ここは〈価格〉の意味。値段は商品に付くもので、確かめるための試みの実験には付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36677, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このクラスでは、毎週実験を行く。", "corrected_sentence": "このクラスでは、毎週実験を行う。", "error_description": "「行く」が誤り。「実験を行う」は「実験をする」と同じ意味で、「行う」が正しい。「行く」は移動の動詞なので目的語「実験を」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36677, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、新しい実験が準備した。", "corrected_sentence": "先生は、新しい実験を準備した。", "error_description": "「が」が誤り。「準備する」は目的語の「を」を取るので「実験を準備した」が正しい。「が」では主語と目的語が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39ae80f2-7971-4e83-ace3-8fd39bc67ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
