INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36678, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「臨床の経験」と名詞をつなぐ正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「臨床を経験が少ない」は二つの要素が衝突し、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「臨床に経験が少ない」は帰着点の意味になり、経験の所在として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「臨床へ経験が少ない」は方向の「へ」が経験に結びつかず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「臨床の経験」と名詞をつなぐ正しい助詞。", "を": "「臨床を経験が少ない」は二つの要素が衝突し、文が成り立たない。", "に": "「臨床に経験が少ない」は帰着点の意味になり、経験の所在として不自然。", "へ": "「臨床へ経験が少ない」は方向の「へ」が経験に結びつかず、文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36678, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "病気や体のことを調べるときに、実際に患者さんを診て行うことです。", "primary_collocate": null, "pronunciation": "りんしょう", "ipa": "ɾiɴɕoː", "syllable_count": 4, "sentences": [{"text": "彼は大学で教えながら、週に二日は臨床にも出ています。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]で教[おし]えながら、週[しゅう]に二日[ふつか]は臨床[りんしょう]にも出[で]ています。", "sentence_source": "generated"}, {"text": "医学生は、本で学んだ知識を臨床で使えるようになりたい。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "医学生[いがくせい]は、本[ほん]で学[まな]んだ知識[ちしき]を臨床[りんしょう]で使[つか]えるようになりたい。", "sentence_source": "generated"}, {"text": "研究室より臨床のほうが好きで、病院で働くことにした。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "研究室[けんきゅうしつ]より臨床[りんしょう]のほうが好[す]きで、病院[びょういん]で働[はたら]くことにした。", "sentence_source": "generated"}, {"text": "長年臨床に携わってきた医師が、新人に診察のしかたを教えた。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "長年[ながねん]臨床[りんしょう]に携[たずさ]わってきた医師[いし]が、新人[しんじん]に診察[しんさつ]のしかたを教[おし]えた。", "sentence_source": "generated"}, {"text": "臨床では、検査の数字だけでなく、患者の表情も大切にする。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "臨床[りんしょう]では、検査[けんさ]の数字[すうじ]だけでなく、患者[かんじゃ]の表情[ひょうじょう]も大切[たいせつ]にする。", "sentence_source": "generated"}, {"text": "彼女は研究をやめて、臨床に戻ることを決めた。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は研究[けんきゅう]をやめて、臨床[りんしょう]に戻[もど]ることを決[き]めた。", "sentence_source": "generated"}, {"text": "教科書だけでは分からないことが、臨床ではたくさんある。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "教科書[きょうかしょ]だけでは分[わ]からないことが、臨床[りんしょう]ではたくさんある。", "sentence_source": "generated"}, {"text": "臨床の経験が少ないので、まず先輩の診察を見て学びます。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "臨床[りんしょう]の経験[けいけん]が少[すく]ないので、まず先輩[せんぱい]の診察[しんさつ]を見[み]て学[まな]びます。", "sentence_source": "generated"}, {"text": "看護師になって、初めて臨床で患者さんと話した。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "看護師[かんごし]になって、初[はじ]めて臨床[りんしょう]で患者[かんじゃ]さんと話[はな]した。", "sentence_source": "generated"}, {"text": "私は研究より、患者さんを直接診る臨床がしたい。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "私[わたし]は研究[けんきゅう]より、患者[かんじゃ]さんを直接[ちょくせつ]診[み]る臨床[りんしょう]がしたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "臨床", "label": "基本形"}, {"form": "臨床的", "label": "形状詞化"}], "register": "formal", "sense_fingerprint": "臨床=実際に患者を診る医療の実践(研究室・教科書に対する現場での診療)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36678, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "臨床", "is_correct": true, "explanation": "実際の患者を診る医療の現場。「臨床に出る」は診療に携わる意味で合う。"}, {"text": "診断", "is_correct": false, "explanation": "病気を見極める行為で、「診断に出る」とは言わない。"}, {"text": "処方", "is_correct": false, "explanation": "薬を出す行為で、「処方に出る」とは言えない。"}, {"text": "薬品", "is_correct": false, "explanation": "薬の物質で、「薬品に出る」とは言わない。"}], "explanations": {"臨床": "実際の患者を診る医療の現場。「臨床に出る」は診療に携わる意味で合う。", "診断": "病気を見極める行為で、「診断に出る」とは言わない。", "処方": "薬を出す行為で、「処方に出る」とは言えない。", "薬品": "薬の物質で、「薬品に出る」とは言わない。"}, "sentence_index": 0, "correct_answer": "臨床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場の臨床で、機械の不具合を一つずつ点検した。", "explanation": "ここは〈現場〉の意味。臨床は医療で患者を診る場面を指し、工場の機械の点検には使わない。"}, {"text": "電車の臨床を見て、前回の時刻を確かめた。", "explanation": "ここは〈時刻表〉の意味。臨床は時刻表を指さないので、時刻を確かめる場面には使わない。"}, {"text": "患者は臨床で傘を借りて、家に帰った。", "explanation": "ここは〈貸し出し〉の意味。臨床は傘を貸す場所ではないので、傘を借りる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36678, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "臨床", "is_correct": true, "explanation": "患者を診る実践の場。教科書にない知識がある場面として合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "甘味の食品で、知識がある場面としては成り立たない。"}, {"text": "靴下", "is_correct": false, "explanation": "衣類で、分からないことが多い場面としては合わない。"}, {"text": "雨", "is_correct": false, "explanation": "天気を表す語で、分からないことが多い場面とは言えない。"}], "explanations": {"臨床": "患者を診る実践の場。教科書にない知識がある場面として合う。", "砂糖": "甘味の食品で、知識がある場面としては成り立たない。", "靴下": "衣類で、分からないことが多い場面としては合わない。", "雨": "天気を表す語で、分からないことが多い場面とは言えない。"}, "sentence_index": 6, "correct_answer": "臨床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "受付で臨床の切符を買った。", "explanation": "ここは〈乗車券〉の意味。臨床は切符を指さないので、切符を買う場面には使わない。"}, {"text": "臨床で飲み物を買って、待合室で飲んだ。", "explanation": "ここは〈売店〉の意味。臨床は買い物をする場所ではないので、買うという行為と合わない。"}, {"text": "臨床で代金を払って帰った。", "explanation": "ここは〈会計〉の意味。臨床は支払いをする場所ではないので、代金を払う場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36678, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩は臨床を現場で、患者さんへの説明のしかたを教えてくれた。", "corrected_sentence": "先輩は臨床の現場で、患者さんへの説明のしかたを教えてくれた。", "error_description": "誤: 臨床を現場、正: 臨床の現場。「現場」は「臨床」を修飾する名詞なので「の」で結ぶ。「を」は目的語で、名詞どうしには使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36678, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "臨床に経験を積むと、患者さんとの信頼が深まる。", "corrected_sentence": "臨床で経験を積むと、患者さんとの信頼が深まる。", "error_description": "誤: 臨床に経験を積む、正: 臨床で経験を積む。「で」は活動の場を示す。「に」は帰着点や方向を示し、場所で積むという意味にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36679, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「臨床の研究」と名詞をつなぐ正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「臨床を研究では」は目的語の形になり、主題を示す文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「臨床に研究では」は帰着点となり、研究の分野を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「臨床へ研究では」は方向を示すが、研究の分野を表す文にならない。"}], "correct_answer": "の", "explanations": {"の": "「臨床の研究」と名詞をつなぐ正しい助詞。", "を": "「臨床を研究では」は目的語の形になり、主題を示す文として不自然。", "に": "「臨床に研究では」は帰着点となり、研究の分野を示せない。", "へ": "「臨床へ研究では」は方向を示すが、研究の分野を表す文にならない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "基礎", "is_correct": true, "explanation": "患者を直接対象にする臨床と対になり、基礎医学や理論中心の立場を表す。"}, {"text": "教科書", "is_correct": false, "explanation": "学習に使う本で、臨床の対義語ではない。"}, {"text": "患者", "is_correct": false, "explanation": "臨床の対象となる人で、対になる概念ではない。"}, {"text": "病院", "is_correct": false, "explanation": "臨床が行われる場所で、対義語ではない。"}], "correct_answer": "基礎", "explanations": {"基礎": "患者を直接対象にする臨床と対になり、基礎医学や理論中心の立場を表す。", "教科書": "学習に使う本で、臨床の対義語ではない。", "患者": "臨床の対象となる人で、対になる概念ではない。", "病院": "臨床が行われる場所で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36679, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「臨床で役に立つ」は場面を示す正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "「臨床と役に立つ」は並列となり、場面を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「臨床から役に立つ」は起点の意味になり、場面を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「臨床を役に立つ」は「役に立つ」に目的語を置く形で、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「臨床で役に立つ」は場面を示す正しい助詞。", "と": "「臨床と役に立つ」は並列となり、場面を示せない。", "から": "「臨床から役に立つ」は起点の意味になり、場面を表せない。", "を": "「臨床を役に立つ」は「役に立つ」に目的語を置く形で、文が成り立たない。"}, "error_tags": {"と": "並列", "から": "起点", "を": "目的語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "基礎", "is_correct": true, "explanation": "患者を直接対象にする臨床と対になり、基礎医学や理論中心の立場を表す。"}, {"text": "検査", "is_correct": false, "explanation": "病気を調べる行為で、臨床と対になる語ではない。"}, {"text": "処方", "is_correct": false, "explanation": "薬を出す行為で、臨床の対義語ではない。"}, {"text": "学会", "is_correct": false, "explanation": "研究者の集まりで、臨床と対になる語ではない。"}], "correct_answer": "基礎", "explanations": {"基礎": "患者を直接対象にする臨床と対になり、基礎医学や理論中心の立場を表す。", "検査": "病気を調べる行為で、臨床と対になる語ではない。", "処方": "薬を出す行為で、臨床の対義語ではない。", "学会": "研究者の集まりで、臨床と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36679, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際の患者を診察・治療する現場での観察や研究に関わること。", "primary_collocate": null, "pronunciation": "りんしょう", "ipa": "ɾiɴɕoː", "syllable_count": 4, "sentences": [{"text": "この薬は、臨床の現場でも効果が確かめられた。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "この薬[くすり]は、臨床[りんしょう]の現場[げんば]でも効果[こうか]が確[たし]かめられた。", "sentence_source": "generated"}, {"text": "臨床の研究では、実際の患者のデータを集めて分析する。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "臨床[りんしょう]の研究[けんきゅう]では、実際[じっさい]の患者[かんじゃ]のデータを集[あつ]めて分析[ぶんせき]する。", "sentence_source": "generated"}, {"text": "彼は基礎ではなく、臨床の立場から病気を研究している。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "彼[かれ]は基礎[きそ]ではなく、臨床[りんしょう]の立場[たちば]から病気[びょうき]を研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "臨床の観察から、新しい治療法のヒントが見つかった。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "臨床[りんしょう]の観察[かんさつ]から、新[あたら]しい治療法[ちりょうほう]のヒントが見[み]つかった。", "sentence_source": "generated"}, {"text": "動物での実験だけでなく、臨床での確認も必要だ。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "動物[どうぶつ]での実験[じっけん]だけでなく、臨床[りんしょう]での確認[かくにん]も必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "臨床の医師と研究者が集まって、症例について話し合った。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "臨床[りんしょう]の医師[いし]と研究者[けんきゅうしゃ]が集[あつ]まって、症例[しょうれい]について話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "臨床の報告によると、この症状は若い人にも多い。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "臨床[りんしょう]の報告[ほうこく]によると、この症状[しょうじょう]は若[わか]い人[ひと]にも多[おお]い。", "sentence_source": "generated"}, {"text": "理論は正しくても、臨床で役に立つとは限らない。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "理論[りろん]は正[ただ]しくても、臨床[りんしょう]で役[やく]に立[た]つとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "彼女は臨床の知識が豊富で、研究会でもよく質問される。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は臨床[りんしょう]の知識[ちしき]が豊富[ほうふ]で、研究会[けんきゅうかい]でもよく質問[しつもん]される。", "sentence_source": "generated"}, {"text": "臨床の現場からの意見を、病院の新しい制度に生かした。", "target_word": "臨床", "complexity_tier": "T3", "furigana": "臨床[りんしょう]の現場[げんば]からの意見[いけん]を、病院[びょういん]の新[あたら]しい制度[せいど]に生[い]かした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "臨床", "label": "基本形"}, {"form": "臨床的", "label": "形状詞化"}], "register": "formal", "sense_fingerprint": "臨床=実際の患者を対象にした現場での観察・研究・確認(基礎や理論に対する立場)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36679, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "臨床", "is_correct": true, "explanation": "実際の患者を対象にする現場。薬の効果を確かめる場面として合う。"}, {"text": "玩具", "is_correct": false, "explanation": "遊び道具で、薬の効果を確かめる現場とは言えない。"}, {"text": "掃除機", "is_correct": false, "explanation": "家電で、薬の効果を確かめる現場とは言えない。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態で、薬の効果を確かめる現場にはならない。"}], "explanations": {"臨床": "実際の患者を対象にする現場。薬の効果を確かめる場面として合う。", "玩具": "遊び道具で、薬の効果を確かめる現場とは言えない。", "掃除機": "家電で、薬の効果を確かめる現場とは言えない。", "天気": "空の状態で、薬の効果を確かめる現場にはならない。"}, "sentence_index": 0, "correct_answer": "臨床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選手の臨床から、新しい練習法のヒントが見つかった。", "explanation": "ここは〈観察〉の意味。臨床は医療で患者を対象にする場面を指し、選手の練習には使わない。"}, {"text": "試験管の臨床から、新しい薬のヒントが見つかった。", "explanation": "ここは〈実験〉の意味。試験管の中で行う実験は患者を対象にしないので、臨床とは言わない。"}, {"text": "数式だけの臨床から、新しい治療法の答えを導いた。", "explanation": "ここは〈理論〉の意味。数式だけで考える研究は理論と言い、患者を対象とする臨床とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36679, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "臨床", "is_correct": true, "explanation": "患者を対象に得られた情報。症状の多さを示す報告の出どころとして合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "甘味の食品で、症状の報告の出どころにはならない。"}, {"text": "靴", "is_correct": false, "explanation": "履き物で、症状の報告の出どころにはならない。"}, {"text": "夢", "is_correct": false, "explanation": "寝ている間の経験で、症状の報告の根拠にはならない。"}], "explanations": {"臨床": "患者を対象に得られた情報。症状の多さを示す報告の出どころとして合う。", "砂糖": "甘味の食品で、症状の報告の出どころにはならない。", "靴": "履き物で、症状の報告の出どころにはならない。", "夢": "寝ている間の経験で、症状の報告の根拠にはならない。"}, "sentence_index": 6, "correct_answer": "臨床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その臨床は、患者に優しく話しかける人だ。", "explanation": "ここは〈医師〉の意味。臨床は人を指さないので、人物の説明には使えない。"}, {"text": "臨床を箱に入れて、薬として患者に配った。", "explanation": "ここは〈薬〉の意味。臨床は実践の分野で、物として箱に入れたり配ったりはできない。"}, {"text": "農家の臨床から、新しい品種のヒントが見つかった。", "explanation": "ここは〈栽培〉の意味。臨床は医療の現場を指し、農作物の研究には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36679, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい薬の効果を、臨床に確かめた。", "corrected_sentence": "新しい薬の効果を、臨床で確かめた。", "error_description": "誤: 臨床に確かめた、正: 臨床で確かめた。「で」は確かめる場面を示す。「に」は帰着点を示すので、場面を表せず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36679, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "臨床を報告が、来月の雑誌に載ることになった。", "corrected_sentence": "臨床の報告が、来月の雑誌に載ることになった。", "error_description": "誤: 臨床を報告、正: 臨床の報告。「報告」を修飾する「の」が必要。「を」は動作の対象を示すので、名詞の並びには使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
