INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36681, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事のようすや動きを、注意深く見たり調べたりすること。", "primary_collocate": null, "pronunciation": "かんさつ", "ipa": "kaɴsat͡sɯ", "syllable_count": 4, "sentences": [{"text": "酵母の活動を観察しながら生地を仕上げ、いよいよ焼成へと進みます。", "target_word": "観察", "complexity_tier": "T4", "furigana": "酵母[こうぼ]の活動[かつどう]を観察[かんさつ]しながら生地[きじ]を仕上[しあ]げ、いよいよ焼成[しょうせい]へと進[すす]みます。", "sentence_source": "mined"}, {"text": "毎朝、庭のアサガオの成長を観察して、ノートに記録しています。", "target_word": "観察", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、庭[にわ]のアサガオの成長[せいちょう]を観察[かんさつ]して、ノートに記録[きろく]しています。", "sentence_source": "generated"}, {"text": "理科の授業で、メダカの卵が育つ様子を観察しました。", "target_word": "観察", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、メダカの卵[たまご]が育[そだ]つ様子[ようす]を観察[かんさつ]しました。", "sentence_source": "generated"}, {"text": "医者は患者の様子を注意深く観察し、薬の量を決めた。", "target_word": "観察", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]の様子[ようす]を注意深[ちゅういぶか]く観察[かんさつ]し、薬[くすり]の量[りょう]を決[き]めた。", "sentence_source": "generated"}, {"text": "双眼鏡を使えば、遠くの鳥の動きを観察できます。", "target_word": "観察", "complexity_tier": "T3", "furigana": "双眼鏡[そうがんきょう]を使[つか]えば、遠[とお]くの鳥[とり]の動[うご]きを観察[かんさつ]できます。", "sentence_source": "generated"}, {"text": "彼は人を観察するのが得意で、小さな表情の変化にもすぐ気づく。", "target_word": "観察", "complexity_tier": "T3", "furigana": "彼[かれ]は人[ひと]を観察[かんさつ]するのが得意[とくい]で、小[ちい]さな表情[ひょうじょう]の変化[へんか]にもすぐ気[き]づく。", "sentence_source": "generated"}, {"text": "雲の形を観察していると、明日の天気がなんとなく分かる。", "target_word": "観察", "complexity_tier": "T3", "furigana": "雲[くも]の形[かたち]を観察[かんさつ]していると、明日[あした]の天気[てんき]がなんとなく分[わ]かる。", "sentence_source": "generated"}, {"text": "子どもの行動を観察した結果、昼寝のあとに機嫌が悪くなることが分かった。", "target_word": "観察", "complexity_tier": "T3", "furigana": "子[こ]どもの行動[こうどう]を観察[かんさつ]した結果[けっか]、昼寝[ひるね]のあとに機嫌[きげん]が悪[わる]くなることが分[わ]かった。", "sentence_source": "generated"}, {"text": "実験では、水の色が変わる瞬間をよく観察してください。", "target_word": "観察", "complexity_tier": "T3", "furigana": "実験[じっけん]では、水[みず]の色[いろ]が変[か]わる瞬間[しゅんかん]をよく観察[かんさつ]してください。", "sentence_source": "generated"}, {"text": "顕微鏡で観察すると、小さな虫の体の仕組みがはっきり見える。", "target_word": "観察", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]で観察[かんさつ]すると、小[ちい]さな虫[むし]の体[からだ]の仕組[しく]みがはっきり見[み]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "観察", "label": "基本形"}, {"form": "観察する", "label": "辞書形"}, {"form": "観察した", "label": "過去形"}, {"form": "観察して", "label": "て形"}, {"form": "観察される", "label": "受身形"}], "register": "標準（中立）", "sense_fingerprint": "物事の様子や動きを注意深く見て調べること。サ変名詞（観察する）。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8c3c963-2a95-475a-8066-2eceb2411f9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36681, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "観察", "is_correct": true, "explanation": "「観察しながら生地を仕上げる」と文意が通る正解。"}, {"text": "清掃", "is_correct": false, "explanation": "「清掃」は場所や物をきれいにする意味で、酵母の活動を対象にできない。"}, {"text": "注文", "is_correct": false, "explanation": "「注文」は品物や料理を頼む意味で、活動を対象にする文脈に合わない。"}, {"text": "通知", "is_correct": false, "explanation": "「通知」は知らせる意味で、活動を見ながら作業する流れに合わない。"}], "explanations": {"観察": "「観察しながら生地を仕上げる」と文意が通る正解。", "清掃": "「清掃」は場所や物をきれいにする意味で、酵母の活動を対象にできない。", "注文": "「注文」は品物や料理を頼む意味で、活動を対象にする文脈に合わない。", "通知": "「通知」は知らせる意味で、活動を見ながら作業する流れに合わない。"}, "sentence_index": 0, "correct_answer": "観察"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "取引先の見積もりを観察して、契約を正式に承認した。", "explanation": "ここは〈判断して認める〉の意味。観察は様子を注意深く見ることで、承認の意味は含まないので合わない。"}, {"text": "毎朝、ぐらつく椅子を観察して、腕立て伏せを十回した。", "explanation": "ここは〈鍛える〉の意味。観察は様子を注意深く見ることで、体を動かして鍛える行為は含まないので合わない。"}, {"text": "全員にアンケートを配って、学校の給食の満足度を観察した。", "explanation": "ここは〈アンケートで調べる〉の意味。観察は直接見て様子を知る行為で、アンケートによる調査とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36681, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "観察", "is_correct": true, "explanation": "雲の形を見続けることで天気が分かるという流れに合う正解。"}, {"text": "配達", "is_correct": false, "explanation": "「配達」は品物を届ける意味で、雲の形には使えない。"}, {"text": "洗浄", "is_correct": false, "explanation": "「洗浄」は汚れを洗い落とす意味で、雲の形には合わない。"}, {"text": "購入", "is_correct": false, "explanation": "「購入」は買う意味で、雲の形を対象にできない。"}], "explanations": {"観察": "雲の形を見続けることで天気が分かるという流れに合う正解。", "配達": "「配達」は品物を届ける意味で、雲の形には使えない。", "洗浄": "「洗浄」は汚れを洗い落とす意味で、雲の形には合わない。", "購入": "「購入」は買う意味で、雲の形を対象にできない。"}, "sentence_index": 6, "correct_answer": "観察"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末に映画を観察して、友達と感想を語り合った。", "explanation": "ここは〈鑑賞する〉の意味。観察は様子や変化を注意深く調べることで、映画を楽しんで味わう行為には使わないので合わない。"}, {"text": "荷物を観察して、そのまま家まで届けた。", "explanation": "ここは〈届ける〉の意味。観察は対象を見て様子を知ることで、荷物を運んで届ける行為は含まないので合わない。"}, {"text": "ベッドで天井をぼんやり観察しながら、うとうとした。", "explanation": "ここは〈ぼんやり眺める〉の意味。観察は注意深く調べることで、気を抜いてぼんやり見る様子には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36681, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の間、川の魚の動きを観察に続けている。", "corrected_sentence": "夏の間、川の魚の動きを観察し続けている。", "error_description": "「観察」の後の「に続ける」が誤り。サ変動詞「観察する」の連用形「観察し」に「続ける」を付けて「観察し続ける」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36681, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎晩、星の位置を観察に、表に記録する。", "corrected_sentence": "毎晩、星の位置を観察して、表に記録する。", "error_description": "「観察」の後に「に」は続かない。「観察して」（て形）として、後の「記録する」につなげる必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c533aa2e-e72a-4880-bd9a-6c2afcc806d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36682, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『示唆は正しかった』の『は』。話題として示唆を取り上げる。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すが、『示唆を正しかった』は成立しない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は帰着先を示すが、『示唆に正しかった』は不自然。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、『示唆で正しかった』は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "『示唆は正しかった』の『は』。話題として示唆を取り上げる。", "を": "『を』は目的語を示すが、『示唆を正しかった』は成立しない。", "に": "『に』は帰着先を示すが、『示唆に正しかった』は不自然。", "で": "『で』は手段や場所を示すので、『示唆で正しかった』は意味が通らない。"}, "error_tags": {"を": "対格", "に": "帰着", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36682, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『示唆が私の背中を押した』の『が』。示唆を主語として示す。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、主語の位置では不自然。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並列や引用に使うので、『示唆と私の背中を押した』は成立しない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較に使うので、この位置では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "『示唆が私の背中を押した』の『が』。示唆を主語として示す。", "へ": "『へ』は方向を表すので、主語の位置では不自然。", "と": "『と』は並列や引用に使うので、『示唆と私の背中を押した』は成立しない。", "より": "『より』は比較に使うので、この位置では意味が通らない。"}, "error_tags": {"へ": "方向", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36682, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることが正しいと、かんがえさせること。", "primary_collocate": null, "pronunciation": "しさ", "ipa": "ɕisa", "syllable_count": 2, "sentences": [{"text": "医者の示唆に従った。", "target_word": "示唆", "complexity_tier": "T2", "furigana": "医者[いしゃ]の示唆[しさ]に従[したが]った。", "sentence_source": "generated"}, {"text": "彼の示唆は正しかった。", "target_word": "示唆", "complexity_tier": "T2", "furigana": "彼[かれ]の示唆[しさ]は正[ただ]しかった。", "sentence_source": "generated"}, {"text": "先生の示唆で、答えに気づいた。", "target_word": "示唆", "complexity_tier": "T3", "furigana": "先生[せんせい]の示唆[しさ]で、答[こた]えに気[き]づいた。", "sentence_source": "generated"}, {"text": "この本は多くの示唆を与えてくれる。", "target_word": "示唆", "complexity_tier": "T3", "furigana": "この本[ほん]は多[おお]くの示唆[しさ]を与[あた]えてくれる。", "sentence_source": "generated"}, {"text": "研究が新しい考えを示唆した。", "target_word": "示唆した", "complexity_tier": "T3", "furigana": "研究[けんきゅう]が新[あたら]しい考[かんが]えを示唆[しさ]した。", "sentence_source": "generated"}, {"text": "兄は何も示唆しなかった。", "target_word": "示唆しなかった", "complexity_tier": "T2", "furigana": "兄[あに]は何[なに]も示唆[しさ]しなかった。", "sentence_source": "generated"}, {"text": "実験の結果は、仮説が正しいことを示唆している。", "target_word": "示唆している", "complexity_tier": "T4", "furigana": "実験[じっけん]の結果[けっか]は、仮説[かせつ]が正[ただ]しいことを示唆[しさ]している。", "sentence_source": "generated"}, {"text": "母のさりげない示唆が、私の背中を押した。", "target_word": "示唆", "complexity_tier": "T4", "furigana": "母[はは]のさりげない示唆[しさ]が、私[わたし]の背中[せなか]を押[お]した。", "sentence_source": "generated"}, {"text": "示唆されたとおりに直した。", "target_word": "示唆された", "complexity_tier": "T3", "furigana": "示唆[しさ]されたとおりに直[なお]した。", "sentence_source": "generated"}, {"text": "古い記録は、その橋が早くからあったことを示唆している。", "target_word": "示唆している", "complexity_tier": "T4", "furigana": "古[ふる]い記録[きろく]は、その橋[はし]が早[はや]くからあったことを示唆[しさ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "示唆する", "label": "活用"}, {"form": "示唆した", "label": "活用"}, {"form": "示唆される", "label": "活用"}, {"form": "示唆的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | ある考えが正しいと気づかせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36682, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "示唆", "is_correct": true, "explanation": "『医者の示唆に従った』は、医者のほのめかしや助言に従った意味で文脈に合う。"}, {"text": "注射", "is_correct": false, "explanation": "『医者の注射に従った』は意味が通らず、従う対象にならない。"}, {"text": "入院", "is_correct": false, "explanation": "『入院』は病院に入る行為で、『従う』対象として不自然。"}, {"text": "検温", "is_correct": false, "explanation": "『検温』は体温を測ることで、従う対象としては不自然。"}], "explanations": {"示唆": "『医者の示唆に従った』は、医者のほのめかしや助言に従った意味で文脈に合う。", "注射": "『医者の注射に従った』は意味が通らず、従う対象にならない。", "入院": "『入院』は病院に入る行為で、『従う』対象として不自然。", "検温": "『検温』は体温を測ることで、従う対象としては不自然。"}, "sentence_index": 0, "correct_answer": "示唆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上司は部下に示唆を命じた。", "explanation": "ここは〈命じる〉の意味。示唆は強制ではないので、命令の形で伝える内容ではない。"}, {"text": "弟は示唆を体重計に乗せて量った。", "explanation": "ここは〈計量する〉の意味。示唆は考えさせる働きで、重さを量れるものではない。"}, {"text": "父は大切な示唆を鍋で煮た。", "explanation": "ここは〈煮る〉の意味。示唆は食材ではないので、鍋で煮る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36682, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "示唆している", "is_correct": true, "explanation": "『仮説が正しいことを示唆している』で、遠回しにそうだと考えさせる意味になる。"}, {"text": "注文している", "is_correct": false, "explanation": "『注文している』は商品などを頼む意味で、実験結果の文脈には合わない。"}, {"text": "撤去している", "is_correct": false, "explanation": "『撤去している』は取り除く意味で、仮説の文脈では不自然。"}, {"text": "配達している", "is_correct": false, "explanation": "『配達している』は品物を届ける意味で、仮説の文脈には当てはまらない。"}], "explanations": {"示唆している": "『仮説が正しいことを示唆している』で、遠回しにそうだと考えさせる意味になる。", "注文している": "『注文している』は商品などを頼む意味で、実験結果の文脈には合わない。", "撤去している": "『撤去している』は取り除く意味で、仮説の文脈では不自然。", "配達している": "『配達している』は品物を届ける意味で、仮説の文脈には当てはまらない。"}, "sentence_index": 6, "correct_answer": "示唆している"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は示唆を購入した。", "explanation": "ここは〈購入する〉の意味。示唆は物ではないので、買う対象にはならない。"}, {"text": "先生に示唆を修理してもらった。", "explanation": "ここは〈修理する〉の意味。示唆は形のあるものではないので直せない。"}, {"text": "彼は示唆を畳んで、財布にしまった。", "explanation": "ここは〈畳む〉の意味。示唆は紙ではないので、畳んで財布にしまう対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36682, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母の示唆を従って、道を見つけた。", "corrected_sentence": "母の示唆に従って、道を見つけた。", "error_description": "助詞の誤り。『従う』は『〜に従う』と『に』を取る。『を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36682, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その研究は、示唆が富んでいる。", "corrected_sentence": "その研究は、示唆に富んでいる。", "error_description": "助詞の誤り。『示唆に富む』は『に』を取る。『が』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36683, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『示唆が存する』の『が』。主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すが、『示唆を存する』は文として成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、この位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を表すので、主語の位置では不自然。"}], "correct_answer": "が", "explanations": {"が": "『示唆が存する』の『が』。主語を示す。", "を": "『を』は目的語を示すが、『示唆を存する』は文として成立しない。", "へ": "『へ』は方向を表すので、この位置には入らない。", "で": "『で』は場所や手段を表すので、主語の位置では不自然。"}, "error_tags": {"を": "対格", "へ": "方向", "で": "場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36683, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『ことを示唆している』の『を』。示唆の内容を目的語として示す。"}, {"text": "に", "is_correct": false, "explanation": "『に』は帰着先を示すが、『ことに示唆している』は不自然。"}, {"text": "と", "is_correct": false, "explanation": "『と』は引用に使うが、この位置では文が成立しない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較に使うので、この位置では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "『ことを示唆している』の『を』。示唆の内容を目的語として示す。", "に": "『に』は帰着先を示すが、『ことに示唆している』は不自然。", "と": "『と』は引用に使うが、この位置では文が成立しない。", "より": "『より』は比較に使うので、この位置では意味が通らない。"}, "error_tags": {"に": "帰着", "と": "引用", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36683, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "はっきりと言わずに、そうではないかと想像させること。", "primary_collocate": null, "pronunciation": "しさ", "ipa": "ɕisa", "syllable_count": 2, "sentences": [{"text": "こうした文脈下、人工知能アルゴリズムによるリアルタイムの習熟度分析を通じて学習者の認知特性に最適化された教材提示を可能にするアダプティブラーニングプラットフォームの導入は、教育学の観点から極めて示唆に富む。", "target_word": "示唆", "complexity_tier": "T6", "furigana": "こうした文脈下[ぶんみゃくか]、人工知能[じんこうちのう]アルゴリズムによるリアルタイムの習熟度[しゅうじゅくど]分析[ぶんせき]を通[つう]じて学習者[がくしゅうしゃ]の認知[にんち]特性[とくせい]に最適化[さいてきか]された教材[きょうざい]提示[ていじ]を可能[かのう]にするアダプティブラーニングプラットフォームの導入[どうにゅう]は、教育学[きょういくがく]の観点[かんてん]から極[きわ]めて示唆[しさ]に富[と]む。", "sentence_source": "mined"}, {"text": "すなわち、技術的革新は単なる効率化の道具にとどまらず、教育の公平性と個別最適化を両立させる新たな認識論的枠組みを構築し得るという点に、その本質的な教育的示唆が存すると言えよう。", "target_word": "示唆", "complexity_tier": "T6", "furigana": "すなわち、技術的[ぎじゅつてき]革新[かくしん]は単[たん]なる効率化[こうりつか]の道具[どうぐ]にとどまらず、教育[きょういく]の公平性[こうへいせい]と個別[こべつ]最適化[さいてきか]を両立[りょうりつ]させる新[あら]たな認識論的[にんしきろんてき]枠組[わくぐ]みを構築[こうちく]し得[う]るという点[てん]に、その本質的[ほんしつてき]な教育的[きょういくてき]示唆[しさ]が存[そん]すると言[い]えよう。", "sentence_source": "mined"}, {"text": "先生は大切な示唆をくれた。", "target_word": "示唆", "complexity_tier": "T2", "furigana": "先生[せんせい]は大切[たいせつ]な示唆[しさ]をくれた。", "sentence_source": "generated"}, {"text": "この結果は、重要な示唆を与える。", "target_word": "示唆", "complexity_tier": "T3", "furigana": "この結果[けっか]は、重要[じゅうよう]な示唆[しさ]を与[あた]える。", "sentence_source": "generated"}, {"text": "彼の話は示唆に富んでいた。", "target_word": "示唆", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は示唆[しさ]に富[と]んでいた。", "sentence_source": "generated"}, {"text": "調査は、景気が回復する示唆を含んでいる。", "target_word": "示唆", "complexity_tier": "T4", "furigana": "調査[ちょうさ]は、景気[けいき]が回復[かいふく]する示唆[しさ]を含[ふく]んでいる。", "sentence_source": "generated"}, {"text": "先生が別の方法を示唆した。", "target_word": "示唆した", "complexity_tier": "T3", "furigana": "先生[せんせい]が別[べつ]の方法[ほうほう]を示唆[しさ]した。", "sentence_source": "generated"}, {"text": "データは、原因が別にあることを示唆している。", "target_word": "示唆している", "complexity_tier": "T4", "furigana": "データは、原因[げんいん]が別[べつ]にあることを示唆[しさ]している。", "sentence_source": "generated"}, {"text": "彼は何も言わなかったが、辞める意思を示唆した。", "target_word": "示唆した", "complexity_tier": "T4", "furigana": "彼[かれ]は何[なに]も言[い]わなかったが、辞[や]める意思[いし]を示唆[しさ]した。", "sentence_source": "generated"}, {"text": "示唆を受けて考え直した。", "target_word": "示唆", "complexity_tier": "T2", "furigana": "示唆[しさ]を受[う]けて考[かんが]え直[なお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "示唆する", "label": "活用"}, {"form": "示唆した", "label": "活用"}, {"form": "示唆される", "label": "活用"}, {"form": "示唆的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 遠回しに示して想像させること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e79c8402-25fb-4bfb-b78f-f87dfd2b54f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36683, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "示唆", "is_correct": true, "explanation": "『極めて示唆に富む』は『遠回しに考えさせる要素が多い』の意味で、文脈に合う。"}, {"text": "色彩", "is_correct": false, "explanation": "『色彩に富む』は絵画や描写に使い、教育の導入には合わない。"}, {"text": "余韻", "is_correct": false, "explanation": "『余韻に富む』は文章や音楽について使い、導入の評価には不自然。"}, {"text": "栄養", "is_correct": false, "explanation": "『栄養に富む』は食べ物について使うので、導入には当てはまらない。"}], "explanations": {"示唆": "『極めて示唆に富む』は『遠回しに考えさせる要素が多い』の意味で、文脈に合う。", "色彩": "『色彩に富む』は絵画や描写に使い、教育の導入には合わない。", "余韻": "『余韻に富む』は文章や音楽について使い、導入の評価には不自然。", "栄養": "『栄養に富む』は食べ物について使うので、導入には当てはまらない。"}, "sentence_index": 0, "correct_answer": "示唆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は荷物を示唆して運んだ。", "explanation": "ここは〈運ぶ〉の意味。示唆は物を動かす行為ではなく、想像させることなので合わない。"}, {"text": "弟は示唆の重さを体重計で量った。", "explanation": "ここは〈計量する〉の意味。示唆は考えさせる働きで、重さを量れるものではない。"}, {"text": "彼女は証拠を示唆して、犯人を特定した。", "explanation": "ここは〈特定する〉の意味。示唆は想像させることで、犯人を確定させる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36683, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "示唆した", "is_correct": true, "explanation": "『先生が別の方法を示唆した』で、遠回しにほのめかした意味になる。"}, {"text": "否定した", "is_correct": false, "explanation": "『別の方法を否定した』は退けた意味で、ほのめかす文脈とは逆。"}, {"text": "翻訳した", "is_correct": false, "explanation": "『翻訳した』は言語を別の言語に置き換える意味で、方法には使わない。"}, {"text": "録画した", "is_correct": false, "explanation": "『録画した』は映像を記録する意味で、方法について使うと不自然。"}], "explanations": {"示唆した": "『先生が別の方法を示唆した』で、遠回しにほのめかした意味になる。", "否定した": "『別の方法を否定した』は退けた意味で、ほのめかす文脈とは逆。", "翻訳した": "『翻訳した』は言語を別の言語に置き換える意味で、方法には使わない。", "録画した": "『録画した』は映像を記録する意味で、方法について使うと不自然。"}, "sentence_index": 6, "correct_answer": "示唆した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その結論は示唆で証明された。", "explanation": "ここは〈証明する〉の意味。示唆はほのめかすことなので、証明の手段にはならない。"}, {"text": "彼は確信を示唆して、断言した。", "explanation": "ここは〈断言する〉の意味。示唆は断定しないことなので、断言とは逆の内容になる。"}, {"text": "その事実を示唆で確認した。", "explanation": "ここは〈確認する〉の意味。示唆は想像させることで、事実を確かめる手段には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36683, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の提案は、会議の方向性に大きな示唆が与えた。", "corrected_sentence": "彼の提案は、会議の方向性に大きな示唆を与えた。", "error_description": "助詞の誤り。『与える』の目的語は『を』で取る。『が』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36683, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この実験結果は、重要な示唆が与えてくれる。", "corrected_sentence": "この実験結果は、重要な示唆を与えてくれる。", "error_description": "助詞の誤り。『与える』の目的語は『を』で取る。『が』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c80372a0-9596-467c-b547-59d40c36d3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36684, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「虫の活性が落ちて」は活性が主語となり、働きが鈍るという正しい文になる。"}, {"text": "を", "is_correct": false, "explanation": "「活性を落ちて」は落ちるという自動詞に目的語を置くことになり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「活性に落ちて」は到達点を示すので、活性の低下を主語で表す形にならない。"}, {"text": "で", "is_correct": false, "explanation": "「活性で落ちて」は手段や原因を示し、活性が落ちるという主語の関係にならない。"}], "correct_answer": "が", "explanations": {"が": "「虫の活性が落ちて」は活性が主語となり、働きが鈍るという正しい文になる。", "を": "「活性を落ちて」は落ちるという自動詞に目的語を置くことになり、文が成り立たない。", "に": "「活性に落ちて」は到達点を示すので、活性の低下を主語で表す形にならない。", "で": "「活性で落ちて」は手段や原因を示し、活性が落ちるという主語の関係にならない。"}, "error_tags": {"を": "目的語（他動詞の対象）", "に": "方向・帰着点", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36684, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「活性が高まり」は活性が主語となり、働きが強まるという正しい文になる。"}, {"text": "へ", "is_correct": false, "explanation": "「活性へ高まり」は方向を示す「へ」になり、活性が高まるという主語の関係にならない。"}, {"text": "から", "is_correct": false, "explanation": "「活性から高まり」は起点を示すので、活性が主語で高まるという文の形にならない。"}, {"text": "より", "is_correct": false, "explanation": "「活性より高まり」は比較を示すので、活性が高まるという主語の関係を表せない。"}], "correct_answer": "が", "explanations": {"が": "「活性が高まり」は活性が主語となり、働きが強まるという正しい文になる。", "へ": "「活性へ高まり」は方向を示す「へ」になり、活性が高まるという主語の関係にならない。", "から": "「活性から高まり」は起点を示すので、活性が主語で高まるという文の形にならない。", "より": "「活性より高まり」は比較を示すので、活性が高まるという主語の関係を表せない。"}, "error_tags": {"へ": "方向・到達点", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36684, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体・細胞・酵素などの働きが活発になること。", "primary_collocate": null, "pronunciation": "かっせい", "ipa": "kasseː", "syllable_count": 4, "sentences": [{"text": "運動をすると、脳の活性が高まると言われている。", "target_word": "活性", "complexity_tier": "T3", "furigana": "運動[うんどう]をすると、脳[のう]の活性[かっせい]が高[たか]まると言[い]われている。", "sentence_source": "generated"}, {"text": "寒くなると、虫の活性が落ちて、あまり見かけなくなる。", "target_word": "活性", "complexity_tier": "T3", "furigana": "寒[さむ]くなると、虫[むし]の活性[かっせい]が落[お]ちて、あまり見[み]かけなくなる。", "sentence_source": "generated"}, {"text": "酵素は温度が低すぎると、活性が下がってしまう。", "target_word": "活性", "complexity_tier": "T3", "furigana": "酵素[こうそ]は温度[おんど]が低[ひく]すぎると、活性[かっせい]が下[さ]がってしまう。", "sentence_source": "generated"}, {"text": "朝の散歩は、体の活性を上げるのにいい。", "target_word": "活性", "complexity_tier": "T3", "furigana": "朝[あさ]の散歩[さんぽ]は、体[からだ]の活性[かっせい]を上[あ]げるのにいい。", "sentence_source": "generated"}, {"text": "薬を加えたら、細胞の活性が急に高まった。", "target_word": "活性", "complexity_tier": "T3", "furigana": "薬[くすり]を加[くわ]えたら、細胞[さいぼう]の活性[かっせい]が急[きゅう]に高[たか]まった。", "sentence_source": "generated"}, {"text": "この土は微生物の活性が強く、野菜がよく育つ。", "target_word": "活性", "complexity_tier": "T3", "furigana": "この土[つち]は微生物[びせいぶつ]の活性[かっせい]が強[つよ]く、野菜[やさい]がよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "冬は魚の活性が低く、釣りをしてもなかなか釣れない。", "target_word": "活性", "complexity_tier": "T3", "furigana": "冬[ふゆ]は魚[さかな]の活性[かっせい]が低[ひく]く、釣[つ]りをしてもなかなか釣[つ]れない。", "sentence_source": "generated"}, {"text": "酵母は砂糖を入れると活性が高まり、パンがふくらむ。", "target_word": "活性", "complexity_tier": "T3", "furigana": "酵母[こうぼ]は砂糖[さとう]を入[い]れると活性[かっせい]が高[たか]まり、パンがふくらむ。", "sentence_source": "generated"}, {"text": "熱を加えると、この触媒は活性が強くなる。", "target_word": "活性", "complexity_tier": "T3", "furigana": "熱[ねつ]を加[くわ]えると、この触媒[しょくばい]は活性[かっせい]が強[つよ]くなる。", "sentence_source": "generated"}, {"text": "薬の効果で、免疫の活性が上がった。", "target_word": "活性", "complexity_tier": "T3", "furigana": "薬[くすり]の効果[こうか]で、免疫[めんえき]の活性[かっせい]が上[あ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活性", "label": "基本形"}, {"form": "活性化", "label": "派生語(サ変名詞)"}], "register": "formal", "sense_fingerprint": "活性=体・細胞・酵素・生き物などの働きが活発になること(活性が上がる・高まる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36684, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "「脳の活性が高まる」は脳の働きが活発になることを表し、文脈に合う。"}, {"text": "重量", "is_correct": false, "explanation": "「脳の重量が高まる」は重さが増える意味になり、運動の文脈と合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "「脳の色彩が高まる」とは言わず、意味が通らない。"}, {"text": "湿度", "is_correct": false, "explanation": "「脳の湿度」という言い方はせず、運動で何が高まるかという文脈に合わない。"}], "explanations": {"活性": "「脳の活性が高まる」は脳の働きが活発になることを表し、文脈に合う。", "重量": "「脳の重量が高まる」は重さが増える意味になり、運動の文脈と合わない。", "色彩": "「脳の色彩が高まる」とは言わず、意味が通らない。", "湿度": "「脳の湿度」という言い方はせず、運動で何が高まるかという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は活性がよく、料理がおいしいと評判だ。", "explanation": "ここは〈味・品質〉の意味で使っている。活性は体や物の働きが活発なことを指すので、店の味には使わない。"}, {"text": "今月はイベントの活性が多く、休む日がほとんどなかった。", "explanation": "ここは〈活動〉の意味で使っている。活性は働きの活発さを指すので、行事や仕事の数を言うには活動を使う。"}, {"text": "この車は活性が高くて、燃費もいい。", "explanation": "ここは〈性能〉の意味で使っている。活性は生物や物質の働きに使うので、車の性能には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36684, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "「魚の活性が低い」は魚の働きが鈍いことを表し、冬の釣りの文脈に合う。"}, {"text": "体積", "is_correct": false, "explanation": "魚の体積が低いという言い方はせず、釣れにくさの理由にならない。"}, {"text": "硬度", "is_correct": false, "explanation": "硬度は物質の固さを言うので、魚の状態には使わず不自然。"}, {"text": "比重", "is_correct": false, "explanation": "比重は密度の比のことで、魚の動きや釣れやすさの話には合わない。"}], "explanations": {"活性": "「魚の活性が低い」は魚の働きが鈍いことを表し、冬の釣りの文脈に合う。", "体積": "魚の体積が低いという言い方はせず、釣れにくさの理由にならない。", "硬度": "硬度は物質の固さを言うので、魚の状態には使わず不自然。", "比重": "比重は密度の比のことで、魚の動きや釣れやすさの話には合わない。"}, "sentence_index": 6, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの選手は活性の強い走りで、チームの勝利に貢献した。", "explanation": "ここは〈活躍〉の意味で使っている。活性は体や物の働きを言うので、人の活躍を表すことはできない。"}, {"text": "彼は毎日、勉強の活性を重ねて成績を伸ばした。", "explanation": "ここは〈工夫〉の意味で使っている。活性は働きの活発さを指すので、やり方を考え直して改善する意味は表さない。"}, {"text": "彼女は活性の高い性格で、いつも周りを笑わせる。", "explanation": "ここは〈性格〉の意味で使っている。活性は生物や物質の働きを言い、人柄には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36684, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝、軽く体操をすると、体の活性を高まりやすい。", "corrected_sentence": "朝、軽く体操をすると、体の活性が高まりやすい。", "error_description": "「高まる」は自動詞なので、活性は「が」で受ける。「を」は他動詞の目的語の形で、誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36684, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の暑さで、微生物の活性を強くなった。", "corrected_sentence": "夏の暑さで、微生物の活性が強くなった。", "error_description": "「強くなる」の主語は活性なので「が」で受ける。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
