INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36685, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "活発に活動する状態になること。または、その状態。", "primary_collocate": null, "pronunciation": "かっせい", "ipa": "kasseː", "syllable_count": 4, "sentences": [{"text": "この酵素は、体温ぐらいのときに活性が最も高い。", "target_word": "活性", "complexity_tier": "T3", "furigana": "この酵素[こうそ]は、体温[たいおん]ぐらいのときに活性[かっせい]が最[もっと]も高[たか]い。", "sentence_source": "generated"}, {"text": "活性が高い状態が続くと、細胞は疲れてしまう。", "target_word": "活性", "complexity_tier": "T3", "furigana": "活性[かっせい]が高[たか]い状態[じょうたい]が続[つづ]くと、細胞[さいぼう]は疲[つか]れてしまう。", "sentence_source": "generated"}, {"text": "低温では、この触媒の活性が著しく弱まる。", "target_word": "活性", "complexity_tier": "T3", "furigana": "低温[ていおん]では、この触媒[しょくばい]の活性[かっせい]が著[いちじる]しく弱[よわ]まる。", "sentence_source": "generated"}, {"text": "冷蔵庫に入れると、菌の活性が弱まる。", "target_word": "活性", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]に入[い]れると、菌[きん]の活性[かっせい]が弱[よわ]まる。", "sentence_source": "generated"}, {"text": "乾燥した種は、水を吸うと活性を取り戻して芽を出す。", "target_word": "活性", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した種[たね]は、水[みず]を吸[す]うと活性[かっせい]を取[と]り戻[もど]して芽[め]を出[だ]す。", "sentence_source": "generated"}, {"text": "検査の結果、肝臓の酵素の活性が正常より高かった。", "target_word": "活性", "complexity_tier": "T3", "furigana": "検査[けんさ]の結果[けっか]、肝臓[かんぞう]の酵素[こうそ]の活性[かっせい]が正常[せいじょう]より高[たか]かった。", "sentence_source": "generated"}, {"text": "活性を失った触媒は、新しいものに取りかえる。", "target_word": "活性", "complexity_tier": "T3", "furigana": "活性[かっせい]を失[うしな]った触媒[しょくばい]は、新[あたら]しいものに取[と]りかえる。", "sentence_source": "generated"}, {"text": "寝不足の日は、脳の活性が低くて、考えがまとまらない。", "target_word": "活性", "complexity_tier": "T3", "furigana": "寝不足[ねぶそく]の日[ひ]は、脳[のう]の活性[かっせい]が低[ひく]くて、考[かんが]えがまとまらない。", "sentence_source": "generated"}, {"text": "薬品の活性は時間がたつと弱くなるので、早めに使ってください。", "target_word": "活性", "complexity_tier": "T3", "furigana": "薬品[やくひん]の活性[かっせい]は時間[じかん]がたつと弱[よわ]くなるので、早[はや]めに使[つか]ってください。", "sentence_source": "generated"}, {"text": "実験では、温度を変えて酵母の活性を比べた。", "target_word": "活性", "complexity_tier": "T3", "furigana": "実験[じっけん]では、温度[おんど]を変[か]えて酵母[こうぼ]の活性[かっせい]を比[くら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活性", "label": "基本形"}, {"form": "活性化", "label": "派生語(サ変名詞)"}], "register": "formal", "sense_fingerprint": "活性=酵素・細菌・触媒などが活発に働いている状態、またはその度合い(活性が高い・低い)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36685, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "「体温ぐらいのときに活性が最も高い」は酵素の働きの度合いを表し、文の内容に合う。"}, {"text": "色彩", "is_correct": false, "explanation": "酵素の色彩が最も高いという言い方はせず、意味が通らない。"}, {"text": "重量", "is_correct": false, "explanation": "酵素の重量が体温で最も高いという話にはならず、働きの話と合わない。"}, {"text": "香り", "is_correct": false, "explanation": "「香りが最も高い」は酵素を説明する言い方ではなく、文脈に合わない。"}], "explanations": {"活性": "「体温ぐらいのときに活性が最も高い」は酵素の働きの度合いを表し、文の内容に合う。", "色彩": "酵素の色彩が最も高いという言い方はせず、意味が通らない。", "重量": "酵素の重量が体温で最も高いという話にはならず、働きの話と合わない。", "香り": "「香りが最も高い」は酵素を説明する言い方ではなく、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鉄板は活性が強く、重い荷物も支えられる。", "explanation": "ここは〈強度〉の意味で使っている。活性は働きの活発さを指すので、鉄板の強さには使わない。"}, {"text": "大会で活性の記録を出し、優勝した。", "explanation": "ここは〈記録〉の意味で使っている。活性は働きの程度で、タイムや得点は表さない。"}, {"text": "彼女は活性が豊かで、絵の色づかいがいつも美しい。", "explanation": "ここは〈感性〉の意味で使っている。活性は働きの活発さを指すので、感覚の鋭さや豊かさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36685, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "「活性を失った触媒」は触媒の働きが弱くなったことを表し、取りかえる理由として合う。"}, {"text": "組成", "is_correct": false, "explanation": "「組成を失った触媒」とは言わず、物質の構成が取りかえの理由にならない。"}, {"text": "密度", "is_correct": false, "explanation": "「密度を失った」は不自然で、触媒の状態を表す言い方ではない。"}, {"text": "比重", "is_correct": false, "explanation": "「比重を失った」は言わず、触媒の働きの話にならない。"}], "explanations": {"活性": "「活性を失った触媒」は触媒の働きが弱くなったことを表し、取りかえる理由として合う。", "組成": "「組成を失った触媒」とは言わず、物質の構成が取りかえの理由にならない。", "密度": "「密度を失った」は不自然で、触媒の状態を表す言い方ではない。", "比重": "「比重を失った」は言わず、触媒の働きの話にならない。"}, "sentence_index": 6, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この建物は活性が美しく、観光客に人気がある。", "explanation": "ここは〈見た目〉の意味で使っている。活性は働きの活発さで、建物の美しさは表さない。"}, {"text": "ダイエットで、体重ではなく活性を三キロ減らした。", "explanation": "ここは〈体重〉の意味で使っている。活性は働きの程度を指し、重さを減らすことは言わない。"}, {"text": "テレビの活性を上げて、家族みんなで聞いた。", "explanation": "ここは〈音量〉の意味で使っている。活性は働きの活発さで、テレビの音の大きさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36685, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い朝は、酵母の活性が低める。", "corrected_sentence": "寒い朝は、酵母の活性が低い。", "error_description": "「活性が低い」と形容詞で言う。「低める」は他動詞で、活性を主語にすると文が成り立たないため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36685, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "室温では、この酵素の活性を十分に保たれる。", "corrected_sentence": "室温では、この酵素の活性が十分に保たれる。", "error_description": "「保たれる」は受身なので、活性は「が」で受ける。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36686, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「発作を誘発する」は引き起こす対象を「を」で示す正しい形。"}, {"text": "に", "is_correct": false, "explanation": "「発作に誘発する」は方向や相手を示し、引き起こす対象にはならない。"}, {"text": "が", "is_correct": false, "explanation": "「発作が誘発する」は主語を示すので、引き起こす対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「発作で誘発する」は手段を示し、引き起こす対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「発作を誘発する」は引き起こす対象を「を」で示す正しい形。", "に": "「発作に誘発する」は方向や相手を示し、引き起こす対象にはならない。", "が": "「発作が誘発する」は主語を示すので、引き起こす対象を表せない。", "で": "「発作で誘発する」は手段を示し、引き起こす対象を表せない。"}, "error_tags": {"に": "方向・相手", "が": "主語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36686, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「崩れを誘発する」は引き起こす対象を「を」で示す正しい形。"}, {"text": "へ", "is_correct": false, "explanation": "「崩れへ誘発した」は方向を示すので、引き起こす対象を表せず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「崩れから誘発した」は起点を示すので、崩れを引き起こすという対象の関係にならない。"}, {"text": "より", "is_correct": false, "explanation": "「崩れより誘発した」は比較を示すので、引き起こす対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「崩れを誘発する」は引き起こす対象を「を」で示す正しい形。", "へ": "「崩れへ誘発した」は方向を示すので、引き起こす対象を表せず文が成り立たない。", "から": "「崩れから誘発した」は起点を示すので、崩れを引き起こすという対象の関係にならない。", "より": "「崩れより誘発した」は比較を示すので、引き起こす対象を表せない。"}, "error_tags": {"へ": "方向・到達点", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36686, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あることをきっかけにして、何かが起こるようにすること。", "primary_collocate": null, "pronunciation": "ゆうはつ", "ipa": "jɯːhatsɯ", "syllable_count": 4, "sentences": [{"text": "小さな地震が大きな地震を誘発することがある。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "小[ちい]さな地震[じしん]が大[おお]きな地震[じしん]を誘発[ゆうはつ]することがある。", "sentence_source": "generated"}, {"text": "強い光が発作を誘発する場合があるので、注意が必要だ。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "強[つよ]い光[ひかり]が発作[ほっさ]を誘発[ゆうはつ]する場合[ばあい]があるので、注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼の一言が、会場の笑いを誘発した。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "彼[かれ]の一言[ひとこと]が、会場[かいじょう]の笑[わら]いを誘発[ゆうはつ]した。", "sentence_source": "generated"}, {"text": "急な温度の変化が、頭痛を誘発したようだ。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "急[きゅう]な温度[おんど]の変化[へんか]が、頭痛[ずつう]を誘発[ゆうはつ]したようだ。", "sentence_source": "generated"}, {"text": "新製品の発売は、他社の値下げを誘発した。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]の発売[はつばい]は、他社[たしゃ]の値下[ねさ]げを誘発[ゆうはつ]した。", "sentence_source": "generated"}, {"text": "過度な緊張は、ミスを誘発しやすい。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "過度[かど]な緊張[きんちょう]は、ミスを誘発[ゆうはつ]しやすい。", "sentence_source": "generated"}, {"text": "彼女の話はもらい泣きを誘発し、会場が静かになった。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の話[はなし]はもらい泣[な]きを誘発[ゆうはつ]し、会場[かいじょう]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "大雨が山の斜面の崩れを誘発したと考えられている。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "大雨[おおあめ]が山[やま]の斜面[しゃめん]の崩[くず]れを誘発[ゆうはつ]したと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "無理なダイエットは、体調不良を誘発することがある。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "無理[むり]なダイエットは、体調不良[たいちょうふりょう]を誘発[ゆうはつ]することがある。", "sentence_source": "generated"}, {"text": "一つの事故が連続した事故を誘発しないよう、すぐに道を封鎖した。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "一[ひと]つの事故[じこ]が連続[れんぞく]した事故[じこ]を誘発[ゆうはつ]しないよう、すぐに道[みち]を封鎖[ふうさ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誘発する", "label": "辞書形"}, {"form": "誘発した", "label": "過去形"}, {"form": "誘発して", "label": "て形"}, {"form": "誘発される", "label": "受身形"}], "register": "neutral-written", "sense_fingerprint": "ある出来事を引き金にして別の出来事を起こすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36686, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誘発", "is_correct": true, "explanation": "「大きな地震を誘発する」は、ある地震が別の地震を引き起こすことを表し、文に合う。"}, {"text": "誘拐", "is_correct": false, "explanation": "地震は人ではないので誘拐できず、意味が通らない。"}, {"text": "誘致", "is_correct": false, "explanation": "「地震を誘致する」は招き寄せる意味になり、この文の内容に合わない。"}, {"text": "誘惑", "is_correct": false, "explanation": "地震は意志を持たないので誘惑できず、文脈に合わない。"}], "explanations": {"誘発": "「大きな地震を誘発する」は、ある地震が別の地震を引き起こすことを表し、文に合う。", "誘拐": "地震は人ではないので誘拐できず、意味が通らない。", "誘致": "「地震を誘致する」は招き寄せる意味になり、この文の内容に合わない。", "誘惑": "地震は意志を持たないので誘惑できず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "誘発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい薬は、治療を誘発している。", "explanation": "ここは〈促進〉の意味で使っている。誘発は何かをきっかけに新しい現象を生じさせる語で、すでに進んでいる治療を速める意味は表さないので、治療の進行には使わない。"}, {"text": "夏休みに友達を誘発して、海へ行った。", "explanation": "ここは〈誘う〉の意味で使っている。誘発は出来事を引き起こすことで、人を誘うことには使わない。"}, {"text": "係員が客を誘発して、出口へ案内した。", "explanation": "ここは〈誘導〉の意味で使っている。誘発は出来事を生じさせる語で、人を案内する意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36686, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誘発", "is_correct": true, "explanation": "「もらい泣きを誘発し」は、話が涙を引き起こしたことを表し、会場が静かになった流れに合う。"}, {"text": "勧誘", "is_correct": false, "explanation": "もらい泣きを勧誘するとは言わず、人に勧める語なので意味が通らない。"}, {"text": "採用", "is_correct": false, "explanation": "もらい泣きを採用するとは言わず、文の内容と合わない。"}, {"text": "検閲", "is_correct": false, "explanation": "もらい泣きを検閲することはなく、話の効果を表せない。"}], "explanations": {"誘発": "「もらい泣きを誘発し」は、話が涙を引き起こしたことを表し、会場が静かになった流れに合う。", "勧誘": "もらい泣きを勧誘するとは言わず、人に勧める語なので意味が通らない。", "採用": "もらい泣きを採用するとは言わず、文の内容と合わない。", "検閲": "もらい泣きを検閲することはなく、話の効果を表せない。"}, "sentence_index": 6, "correct_answer": "誘発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は長年の夢を誘発し、ついに実現させた。", "explanation": "ここは〈実現〉の意味で使っている。誘発は引き起こす語で、夢を叶える意味はない。"}, {"text": "新しい客を誘発するため、チラシを配った。", "explanation": "ここは〈勧誘〉の意味で使っている。誘発は出来事を生じさせる語で、客を勧めて集める意味は表さない。"}, {"text": "先生を誘発して、パーティーに来てもらった。", "explanation": "ここは〈招待〉の意味で使っている。誘発は出来事を引き起こす語で、人を招く意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36686, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒さが、関節の痛みを誘発されることがある。", "corrected_sentence": "寒さが、関節の痛みを誘発することがある。", "error_description": "誤: 誘発される、正: 誘発する。「誘発される」は受身で、痛みが寒さによって引き起こされる意味になるが、ここは寒さが主語なので能動の「誘発する」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36686, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝不足が、集中力の低下に誘発しやすい。", "corrected_sentence": "寝不足が、集中力の低下を誘発しやすい。", "error_description": "誤: 低下に誘発、正: 低下を誘発。「誘発」は引き起こす対象を「を」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
