INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36687, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある現象や行動を引き起こすこと。原因となって生じさせること。", "primary_collocate": null, "pronunciation": "ゆうはつ", "ipa": "jɯːhatsɯ", "syllable_count": 4, "sentences": [{"text": "薬の飲み合わせが、思わぬ副作用を誘発した。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "薬[くすり]の飲[の]み合[あ]わせが、思[おも]わぬ副作用[ふくさよう]を誘発[ゆうはつ]した。", "sentence_source": "generated"}, {"text": "乾燥した空気が、せきを誘発しているのかもしれない。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した空気[くうき]が、せきを誘発[ゆうはつ]しているのかもしれない。", "sentence_source": "generated"}, {"text": "長い待ち時間は、客の不満を誘発しやすい。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "長[なが]い待[ま]ち時間[じかん]は、客[きゃく]の不満[ふまん]を誘発[ゆうはつ]しやすい。", "sentence_source": "generated"}, {"text": "地下水のくみ上げが、地盤沈下を誘発した。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "地下水[ちかすい]のくみ上[あ]げが、地盤沈下[じばんちんか]を誘発[ゆうはつ]した。", "sentence_source": "generated"}, {"text": "不公平な評価は、社員の反発を誘発しかねない。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "不公平[ふこうへい]な評価[ひょうか]は、社員[しゃいん]の反発[はんぱつ]を誘発[ゆうはつ]しかねない。", "sentence_source": "generated"}, {"text": "睡眠不足がさまざまな病気を誘発するという研究がある。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "睡眠不足[すいみんぶそく]がさまざまな病気[びょうき]を誘発[ゆうはつ]するという研究[けんきゅう]がある。", "sentence_source": "generated"}, {"text": "大きな音は、犬の興奮を誘発するので避けたい。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "大[おお]きな音[おと]は、犬[いぬ]の興奮[こうふん]を誘発[ゆうはつ]するので避[さ]けたい。", "sentence_source": "generated"}, {"text": "悪いうわさが、さらなる混乱を誘発した。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "悪[わる]いうわさが、さらなる混乱[こんらん]を誘発[ゆうはつ]した。", "sentence_source": "generated"}, {"text": "工事の振動が、近くの建物のひびを誘発したと報告された。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "工事[こうじ]の振動[しんどう]が、近[ちか]くの建物[たてもの]のひびを誘発[ゆうはつ]したと報告[ほうこく]された。", "sentence_source": "generated"}, {"text": "食べ物のアレルギーが、じんましんを誘発した。", "target_word": "誘発", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]のアレルギーが、じんましんを誘発[ゆうはつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "誘発する", "label": "辞書形"}, {"form": "誘発した", "label": "過去形"}, {"form": "誘発して", "label": "て形"}, {"form": "誘発される", "label": "受身形"}], "register": "neutral-written", "sense_fingerprint": "原因となって現象や症状・行動を生じさせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36687, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "誘発", "is_correct": true, "explanation": "「副作用を誘発した」は薬の飲み合わせが副作用を引き起こしたことを表し、文に合う。"}, {"text": "誘拐", "is_correct": false, "explanation": "副作用は人ではないので誘拐できず、意味が通らない。"}, {"text": "検閲", "is_correct": false, "explanation": "副作用を検閲するとは言わず、薬の飲み合わせの話に合わない。"}, {"text": "監禁", "is_correct": false, "explanation": "副作用を監禁することはなく、文脈と全く合わない。"}], "explanations": {"誘発": "「副作用を誘発した」は薬の飲み合わせが副作用を引き起こしたことを表し、文に合う。", "誘拐": "副作用は人ではないので誘拐できず、意味が通らない。", "検閲": "副作用を検閲するとは言わず、薬の飲み合わせの話に合わない。", "監禁": "副作用を監禁することはなく、文脈と全く合わない。"}, "sentence_index": 0, "correct_answer": "誘発"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市は新しい駅を造り、大型店の誘発を目指している。", "explanation": "ここは〈誘致〉の意味で使っている。誘発は何かを引き起こす語で、施設や店を呼び寄せる意味は表さないので、ここでは使わない。"}, {"text": "祖母を誘発して、温泉に行った。", "explanation": "ここは〈誘う〉の意味で使っている。誘発は出来事を引き起こす語で、人を誘う意味には使わない。"}, {"text": "古い看板を誘発して、取り外した。", "explanation": "ここは〈撤去〉の意味で使っている。誘発は出来事を生じさせる語で、物を取り外す意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36687, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "誘発", "is_correct": true, "explanation": "「犬の興奮を誘発する」は音が興奮を引き起こすことを表し、避けたい理由として合う。"}, {"text": "採用", "is_correct": false, "explanation": "犬の興奮を採用するとは言わず、音の影響を表せない。"}, {"text": "勧誘", "is_correct": false, "explanation": "犬の興奮を勧誘するという言い方はせず、文の内容に合わない。"}, {"text": "支給", "is_correct": false, "explanation": "興奮を支給するとは言わず、意味が通らない。"}], "explanations": {"誘発": "「犬の興奮を誘発する」は音が興奮を引き起こすことを表し、避けたい理由として合う。", "採用": "犬の興奮を採用するとは言わず、音の影響を表せない。", "勧誘": "犬の興奮を勧誘するという言い方はせず、文の内容に合わない。", "支給": "興奮を支給するとは言わず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "誘発"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨で試合を誘発したので、中止になった。", "explanation": "ここは〈中止〉の意味で使っている。誘発は引き起こす語で、試合を取りやめる意味は表さない。"}, {"text": "この会社は、優秀な学生を誘発しようと、説明会を増やした。", "explanation": "ここは〈採用〉の意味で使っている。誘発は引き起こすことで、人を雇い入れる意味は表さないので、ここでは採用が正しい。"}, {"text": "市は古い資料を誘発して、窓口で配った。", "explanation": "ここは〈配布〉の意味で使っている。誘発は出来事を引き起こす語で、資料を配る意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36687, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ストレスが、胃の不調を誘発ことがある。", "corrected_sentence": "ストレスが、胃の不調を誘発することがある。", "error_description": "誤: 誘発ことがある、正: 誘発することがある。「誘発」はサ変名詞なので、動詞として使うには「する」を付ける必要がある。「する」が抜けている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36687, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大量の糖分が、血糖値の急上昇で誘発することがある。", "corrected_sentence": "大量の糖分が、血糖値の急上昇を誘発することがある。", "error_description": "「誘発」の目的語は「を」で示す。「で」は手段の意味になり、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36690, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "笑いが抑制の対象なので「を」。"}, {"text": "の", "is_correct": false, "explanation": "「笑いの抑制する」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「笑いから抑制する」は対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「笑いと抑制する」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "笑いが抑制の対象なので「を」。", "の": "「笑いの抑制する」は文として成り立たない。", "から": "「笑いから抑制する」は対象を表せない。", "と": "「笑いと抑制する」は文として成り立たない。"}, "error_tags": {"の": "noun_link", "から": "source", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "促進", "is_correct": true, "explanation": "広がりを進める意味で、抑制の反対。"}, {"text": "禁止", "is_correct": false, "explanation": "止める意味で、反対ではない。"}, {"text": "予防", "is_correct": false, "explanation": "起こらないよう備える意味で、反対ではない。"}, {"text": "阻止", "is_correct": false, "explanation": "止める意味で近く、反対ではない。"}], "correct_answer": "促進", "explanations": {"促進": "広がりを進める意味で、抑制の反対。", "禁止": "止める意味で、反対ではない。", "予防": "起こらないよう備える意味で、反対ではない。", "阻止": "止める意味で近く、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
