INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36690, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを止めること。", "primary_collocate": null, "pronunciation": "よくせい", "ipa": "jokɯseː", "syllable_count": 4, "sentences": [{"text": "怒りを抑制した。", "target_word": "抑制", "complexity_tier": "T1", "furigana": "怒[いか]りを抑制[よくせい]した。", "sentence_source": "generated"}, {"text": "笑いを抑制するのに苦労した。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "笑[わら]いを抑制[よくせい]するのに苦労[くろう]した。", "sentence_source": "generated"}, {"text": "抑制が必要です。", "target_word": "抑制", "complexity_tier": "T2", "furigana": "抑制[よくせい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "病気の広がりを抑制する。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "病気[びょうき]の広[ひろ]がりを抑制[よくせい]する。", "sentence_source": "generated"}, {"text": "値上がりを抑制するため、国が動いた。", "target_word": "抑制", "complexity_tier": "T4", "furigana": "値上[ねあ]がりを抑制[よくせい]するため、国[くに]が動[うご]いた。", "sentence_source": "generated"}, {"text": "騒音の抑制に取り組む。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "騒音[そうおん]の抑制[よくせい]に取[と]り組[く]む。", "sentence_source": "generated"}, {"text": "彼女は感情を抑制している。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は感情[かんじょう]を抑制[よくせい]している。", "sentence_source": "generated"}, {"text": "抑制された声で話した。", "target_word": "抑制", "complexity_tier": "T4", "furigana": "抑制[よくせい]された声[こえ]で話[はな]した。", "sentence_source": "generated"}, {"text": "抑制の効果はすぐに出た。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "抑制[よくせい]の効果[こうか]はすぐに出[で]た。", "sentence_source": "generated"}, {"text": "食事の量の抑制を始めた。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "食事[しょくじ]の量[りょう]の抑制[よくせい]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抑制する", "label": "活用"}, {"form": "抑制される", "label": "活用"}, {"form": "抑制的", "label": "派生"}, {"form": "抑制力", "label":