INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36691, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かの働きや動きを、力で押さえつけて止めること。", "primary_collocate": null, "pronunciation": "よくせい", "ipa": "jokɯseː", "syllable_count": 4, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "抑制", "complexity_tier": "T6", "furigana": "気候変動[きこうへんどう]という地球的[ちきゅうてき]危機[きき]の緩和[かんわ]に向[む]け、産業[さんぎょう]セクターにおける排出量[はいしゅつりょう]の抑制[よくせい]は、持続可能性[じぞくかのうせい]を担保[たんぽ]する上[うえ]で不可避[ふかひ]の責務[せきむ]である。", "sentence_source": "mined"}, {"text": "薬で痛みを抑制する。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "薬[くすり]で痛[いた]みを抑制[よくせい]する。", "sentence_source": "generated"}, {"text": "物価の上昇を抑制したい。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "物価[ぶっか]の上昇[じょうしょう]を抑制[よくせい]したい。", "sentence_source": "generated"}, {"text": "薬で熱の上昇を抑制した。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "薬[くすり]で熱[ねつ]の上昇[じょうしょう]を抑制[よくせい]した。", "sentence_source": "generated"}, {"text": "彼は怒りを抑制できなかった。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "彼[かれ]は怒[いか]りを抑制[よくせい]できなかった。", "sentence_source": "generated"}, {"text": "政府は支出の抑制を決めた。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "政府[せいふ]は支出[ししゅつ]の抑制[よくせい]を決[き]めた。", "sentence_source": "generated"}, {"text": "食欲を抑制する薬を飲んだ。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "食欲[しょくよく]を抑制[よくせい]する薬[くすり]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "感情の抑制は難しい。", "target_word": "抑制", "complexity_tier": "T3", "furigana": "感情[かんじょう]の抑制[よくせい]は難[むずか]しい。", "sentence_source": "generated"}, {"text": "薬で咳が抑制された。", "target_word": "抑制", "complexity_tier": "T4", "furigana": "薬[くすり]で咳[せき]が抑制[よくせい]された。", "sentence_source": "generated"}, {"text": "抑制しないと、被害が広がる。", "target_word": "抑制", "complexity_tier": "T4", "furigana": "抑制[よくせい]しないと、被害[ひがい]が広[ひろ]がる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "抑制する", "label": "活用"}, {"form": "抑制される", "label": "活用"}, {"form": "抑制的", "label": "派生"}, {"form": "抑制力", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 働きや動きを押さえて止めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb16110-7121-4281-9462-fbd42844389b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36691, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抑制", "is_correct": true, "explanation": "排出量を抑えることが責務という文脈に合う。"}, {"text": "拡大", "is_correct": false, "explanation": "形は合うが、緩和に向けた責務という意味が合わない。"}, {"text": "放置", "is_correct": false, "explanation": "形は合うが、責務という意味が合わない。"}, {"text": "宣伝", "is_correct": false, "explanation": "形は合うが、排出量の話に意味が合わない。"}], "explanations": {"抑制": "排出量を抑えることが責務という文脈に合う。", "拡大": "形は合うが、緩和に向けた責務という意味が合わない。", "放置": "形は合うが、責務という意味が合わない。", "宣伝": "形は合うが、排出量の話に意味が合わない。"}, "sentence_index": 0, "correct_answer": "抑制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熱を抑制して、体温を上げた。", "explanation": "抑制は抑えて止めることなので、体温を上げる意味と矛盾する。"}, {"text": "抑制を食べて、お腹がいっぱいになった。", "explanation": "抑制は動作・働きであり、食べられる物ではない。"}, {"text": "駅で抑制に乗って、会社へ行った。", "explanation": "抑制は乗り物ではないので、乗るという使い方は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36691, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抑制", "is_correct": true, "explanation": "食欲を押さえる薬という意味に合う。"}, {"text": "運搬", "is_correct": false, "explanation": "形は合うが、食欲を運搬するという意味が合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "形は合うが、食欲を翻訳するという意味が合わない。"}, {"text": "解凍", "is_correct": false, "explanation": "形は合うが、食欲を解凍するという意味が合わない。"}], "explanations": {"抑制": "食欲を押さえる薬という意味に合う。", "運搬": "形は合うが、食欲を運搬するという意味が合わない。", "翻訳": "形は合うが、食欲を翻訳するという意味が合わない。", "解凍": "形は合うが、食欲を解凍するという意味が合わない。"}, "sentence_index": 6, "correct_answer": "抑制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "涙を抑制して、思い切り泣いた。", "explanation": "抑制は押さえることなので、思い切り泣くという結果と矛盾する。"}, {"text": "音楽を抑制して、大きな音で流した。", "explanation": "抑制は音を抑える意味で、大きく流す意味にはならない。"}, {"text": "抑制を飲んで、体を洗った。", "explanation": "抑制は飲む物ではなく、動作を表す語である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
