INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36692, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「事例を聞いて」の「を」で、聞く対象（話）を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象や方向を示すが、「聞く」の目的語には使わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。聞く対象には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。聞く対象とは結びつかない。"}], "correct_answer": "を", "explanations": {"を": "「事例を聞いて」の「を」で、聞く対象（話）を示す。", "に": "「に」は対象や方向を示すが、「聞く」の目的語には使わない。", "で": "「で」は手段や場所を示す。聞く対象には合わない。", "へ": "「へ」は方向を示す。聞く対象とは結びつかない。"}, "error_tags": {"に": "対象・方向", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36692, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「事例がすでにたくさんある」の「が」で、ある対象を主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の目的語に付く。「ある」の主語には使えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は存在の場所を示す。「たくさんある」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。主語を表すことはできない。"}], "correct_answer": "が", "explanations": {"が": "「事例がすでにたくさんある」の「が」で、ある対象を主語として示す。", "を": "「を」は動作の目的語に付く。「ある」の主語には使えない。", "に": "「に」は存在の場所を示す。「たくさんある」の主語にはならない。", "と": "「と」は並列や相手を示す。主語を表すことはできない。"}, "error_tags": {"を": "目的語", "に": "場所・対象", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36692, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることが本当にあったという話や例のこと。", "primary_collocate": null, "pronunciation": "じれい", "ipa": "dʑiɾeː", "syllable_count": 3, "sentences": [{"text": "同じような事例が、去年も別の町で報告されました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "同(おな)じような事例(じれい)が、去年(きょねん)も別(べつ)の町(まち)で報告(ほうこく)されました。", "sentence_source": "generated"}, {"text": "成功した事例を聞いて、私たちもやってみることにしました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "成功(せいこう)した事例(じれい)を聞(き)いて、私(わたし)たちもやってみることにしました。", "sentence_source": "generated"}, {"text": "先生は、実際にあった事例を使って説明してくれました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "先生(せんせい)は、実際(じっさい)にあった事例(じれい)を使(つか)って説明(せつめい)してくれました。", "sentence_source": "generated"}, {"text": "事例が少ないので、はっきりしたことはまだ言えません。", "target_word": "事例", "complexity_tier": "T3", "furigana": "事例(じれい)が少(すく)ないので、はっきりしたことはまだ言(い)えません。", "sentence_source": "generated"}, {"text": "この病気の事例は、日本ではとてもまれです。", "target_word": "事例", "complexity_tier": "T3", "furigana": "この病気(びょうき)の事例(じれい)は、日本(にほん)ではとてもまれです。", "sentence_source": "generated"}, {"text": "失敗した事例から学ぶことも、大切だと思います。", "target_word": "事例", "complexity_tier": "T3", "furigana": "失敗(しっぱい)した事例(じれい)から学(まな)ぶことも、大切(たいせつ)だと思(おも)います。", "sentence_source": "generated"}, {"text": "町で起きた事例を集めた本を読んで、参考にしました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "町(まち)で起(お)きた事例(じれい)を集(あつ)めた本(ほん)を読(よ)んで、参考(さんこう)にしました。", "sentence_source": "generated"}, {"text": "海外では、似た事例がすでにたくさんあります。", "target_word": "事例", "complexity_tier": "T3", "furigana": "海外(かいがい)では、似(に)た事例(じれい)がすでにたくさんあります。", "sentence_source": "generated"}, {"text": "会議では、過去の事例をもとに対策を話し合いました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "会議(かいぎ)では、過去(かこ)の事例(じれい)をもとに対策(たいさく)を話(はな)し合(あ)いました。", "sentence_source": "generated"}, {"text": "こんな事例は初めてなので、みんな驚きました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "こんな事例(じれい)は初(はじ)めてなので、みんな驚(おどろ)きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事例", "label": "基本形"}, {"form": "事例の", "label": "連体修飾形"}], "register": "中立（丁寧体）", "sense_fingerprint": "実際にあった出来事としての話・前例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36692, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事例", "is_correct": true, "explanation": "実際にあった話という意味で、同じような話が報告されたという文脈に合う。"}, {"text": "印象", "is_correct": false, "explanation": "受けた感じを表す語。報告される対象としては不自然。"}, {"text": "余裕", "is_correct": false, "explanation": "時間や心の空きを表す語。報告される内容には当てはまらない。"}, {"text": "理念", "is_correct": false, "explanation": "組織の根本的な考え方を表す語。実際にあった話とは合わない。"}], "explanations": {"事例": "実際にあった話という意味で、同じような話が報告されたという文脈に合う。", "印象": "受けた感じを表す語。報告される対象としては不自然。", "余裕": "時間や心の空きを表す語。報告される内容には当てはまらない。", "理念": "組織の根本的な考え方を表す語。実際にあった話とは合わない。"}, "sentence_index": 0, "correct_answer": "事例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の事例は、運動会を中止します。", "explanation": "〈場合〉の意味です。「〜の場合は」と条件を表すのは「場合」で、「事例」は実際にあった話や例を指すので、条件を表す文には使えない。"}, {"text": "交差点で事例があり、車が止まりました。", "explanation": "〈事故〉の場面です。交通の出来事は「事故」と言い、「事例」は話や例を指すので合わない。"}, {"text": "事例が悪化して、会議が止まりました。", "explanation": "〈事態〉の場面です。状況が悪化するのは「事態」で、「事例」は状況を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36692, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事例", "is_correct": true, "explanation": "町で起きた実際の話を集めた本という文脈に合う。"}, {"text": "気配", "is_correct": false, "explanation": "何かがいそうな様子を表す語。集める対象には合わない。"}, {"text": "気迫", "is_correct": false, "explanation": "強い意気込みを表す語。本の内容を集めるとは言わない。"}, {"text": "語感", "is_correct": false, "explanation": "言葉から受ける感じを表す語。町の出来事を集める文脈には合わない。"}], "explanations": {"事例": "町で起きた実際の話を集めた本という文脈に合う。", "気配": "何かがいそうな様子を表す語。集める対象には合わない。", "気迫": "強い意気込みを表す語。本の内容を集めるとは言わない。", "語感": "言葉から受ける感じを表す語。町の出来事を集める文脈には合わない。"}, "sentence_index": 6, "correct_answer": "事例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お客さんが大きな事例をしたので、店は大忙しでした。", "explanation": "〈注文〉の場面です。客が品物を頼むのは「注文」と言い、「事例」は話や例を指すので頼む意味では使えない。"}, {"text": "その日、驚くような事例を開いて、学校は休みになりました。", "explanation": "〈会〉の場面です。会や集まりを開くのは「開く」で、「事例」は具体的な話や例を指すので開くことはできない。"}, {"text": "子どもの事例が鈍いので、心配です。", "explanation": "〈反応〉の場面です。刺激に対する動きは「反応」と言い、「事例」は話や例を指すので、動きの鈍さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36692, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、身近な事例に挙げて説明しました。", "corrected_sentence": "先生は、身近な事例を挙げて説明しました。", "error_description": "誤: 事例に挙げて / 正: 事例を挙げて。「挙げる」は目的語に「を」をとるので、「事例」に付く助詞は「を」になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36692, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい事例をまとまって、資料にしました。", "corrected_sentence": "新しい事例をまとめて、資料にしました。", "error_description": "誤: 事例をまとまって / 正: 事例をまとめて。「まとまる」は目的語をとらない自動詞。「まとめる」は「を」をとる他動詞なので、ここでは「まとめて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36693, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "「事例も書いてください」の「も」で、理論に加えて事例を挙げることを示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。書く対象を並べる位置には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示す。書く内容を示す位置には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。書く対象とは結びつかない。"}], "correct_answer": "も", "explanations": {"も": "「事例も書いてください」の「も」で、理論に加えて事例を挙げることを示す。", "が": "「が」は主語を示す。書く対象を並べる位置には合わない。", "に": "「に」は場所や相手を示す。書く内容を示す位置には入らない。", "へ": "「へ」は方向を示す。書く対象とは結びつかない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36693, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「似た事例の判決」の「の」で、事例と判決の関係を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の目的語に付く。名詞同士をつなぐ位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や対象を示す。名詞をつなぐ位置では成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。名詞をつなぐ位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「似た事例の判決」の「の」で、事例と判決の関係を示す。", "を": "「を」は動作の目的語に付く。名詞同士をつなぐ位置には入らない。", "に": "「に」は場所や対象を示す。名詞をつなぐ位置では成り立たない。", "へ": "「へ」は方向を示す。名詞をつなぐ位置には入らない。"}, "error_tags": {"を": "目的語", "に": "場所・対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36693, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "実際に起こった出来事や、その具体例を示すこと。", "primary_collocate": null, "pronunciation": "じれい", "ipa": "dʑiɾeː", "syllable_count": 3, "sentences": [{"text": "説明のとき、事例をひとつ挙げると、聞く人によく伝わります。", "target_word": "事例", "complexity_tier": "T3", "furigana": "説明(せつめい)のとき、事例(じれい)をひとつ挙(あ)げると、聞(き)く人(ひと)によく伝(つた)わります。", "sentence_source": "generated"}, {"text": "レポートには、理論だけでなく具体的な事例も書いてください。", "target_word": "事例", "complexity_tier": "T3", "furigana": "レポートには、理論(りろん)だけでなく具体的(ぐたいてき)な事例(じれい)も書(か)いてください。", "sentence_source": "generated"}, {"text": "この本は、会社で起きた事例を順番に紹介しています。", "target_word": "事例", "complexity_tier": "T3", "furigana": "この本(ほん)は、会社(かいしゃ)で起(お)きた事例(じれい)を順番(じゅんばん)に紹介(しょうかい)しています。", "sentence_source": "generated"}, {"text": "事例を示したおかげで、客はすぐに納得しました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "事例(じれい)を示(しめ)したおかげで、客(きゃく)はすぐに納得(なっとく)しました。", "sentence_source": "generated"}, {"text": "授業では、事故の事例を見ながら、原因を考えました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "授業(じゅぎょう)では、事故(じこ)の事例(じれい)を見(み)ながら、原因(げんいん)を考(かんが)えました。", "sentence_source": "generated"}, {"text": "発表では、三つの事例を取り上げます。", "target_word": "事例", "complexity_tier": "T3", "furigana": "発表(はっぴょう)では、三(みっ)つの事例(じれい)を取(と)り上(あ)げます。", "sentence_source": "generated"}, {"text": "参考になる事例が見つからず、資料作りが止まりました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "参考(さんこう)になる事例(じれい)が見(み)つからず、資料作(しりょうづく)りが止(と)まりました。", "sentence_source": "generated"}, {"text": "裁判では、似た事例の判決が参考にされました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "裁判(さいばん)では、似(に)た事例(じれい)の判決(はんけつ)が参考(さんこう)にされました。", "sentence_source": "generated"}, {"text": "事例を比べると、二つの町の違いがよくわかります。", "target_word": "事例", "complexity_tier": "T3", "furigana": "事例(じれい)を比(くら)べると、二(ふた)つの町(まち)の違(ちが)いがよくわかります。", "sentence_source": "generated"}, {"text": "彼は自分の経験を事例として話しました。", "target_word": "事例", "complexity_tier": "T3", "furigana": "彼(かれ)は自分(じぶん)の経験(けいけん)を事例(じれい)として話(はな)しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "事例", "label": "基本形"}, {"form": "事例として", "label": "資格を示す形"}], "register": "中立（丁寧体）", "sense_fingerprint": "説明や研究のために示す具体的な実例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36693, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事例", "is_correct": true, "explanation": "説明のために示す具体例という意味で、聞く人に伝わるという文脈に合う。"}, {"text": "気圧", "is_correct": false, "explanation": "空気の圧力を表す語。説明のための例としては合わない。"}, {"text": "通信", "is_correct": false, "explanation": "情報を送り届けること。挙げる対象の例としては成り立たない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている人の息づかい。説明の例として挙げる内容ではない。"}], "explanations": {"事例": "説明のために示す具体例という意味で、聞く人に伝わるという文脈に合う。", "気圧": "空気の圧力を表す語。説明のための例としては合わない。", "通信": "情報を送り届けること。挙げる対象の例としては成り立たない。", "寝息": "眠っている人の息づかい。説明の例として挙げる内容ではない。"}, "sentence_index": 0, "correct_answer": "事例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日から事例が激しくて、眠れませんでした。", "explanation": "〈痛み〉の場面です。体に感じる苦しさは「痛み」と言い、「事例」は話や例を指すので、体の感覚には使えない。"}, {"text": "事例を飲むと、客はすぐに元気になります。", "explanation": "〈薬〉の場面です。薬などを体に入れるのは「飲む」で、「事例」は話や例を指すので飲むことはできない。"}, {"text": "事例を手に取らせると、客は安心します。", "explanation": "〈実物〉の場面です。手に取らせるのは品物で、「事例」は話や例を指すので、物として扱うことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36693, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事例", "is_correct": true, "explanation": "参考になる具体的な実例を探すという文脈に合う。"}, {"text": "締切", "is_correct": false, "explanation": "提出の期限を表す語。参考になるものとしては合わない。"}, {"text": "残業", "is_correct": false, "explanation": "決まった時間を超えて働くこと。参考にする対象ではない。"}, {"text": "返信", "is_correct": false, "explanation": "返事を返すこと。参考になる内容として見つける対象ではない。"}], "explanations": {"事例": "参考になる具体的な実例を探すという文脈に合う。", "締切": "提出の期限を表す語。参考になるものとしては合わない。", "残業": "決まった時間を超えて働くこと。参考にする対象ではない。", "返信": "返事を返すこと。参考になる内容として見つける対象ではない。"}, "sentence_index": 6, "correct_answer": "事例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事例を飾ると、部屋が明るくなります。", "explanation": "〈絵〉の場面です。部屋に飾るのは絵や写真などで、「事例」は話や例を指すので飾れない。"}, {"text": "事例を歌って、会場を盛り上げました。", "explanation": "〈歌〉の場面です。歌うのは歌で、「事例」は説明用の具体例を指すので歌うことはできない。"}, {"text": "事例を演奏して、会場を盛り上げました。", "explanation": "〈楽器〉の場面です。演奏するのは楽器や曲で、「事例」は具体例を指すので演奏の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36693, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事例が一つ挙げて、説明します。", "corrected_sentence": "事例を一つ挙げて、説明します。", "error_description": "誤: 事例が一つ挙げて / 正: 事例を一つ挙げて。「挙げる」は目的語に「を」をとるので、「事例」に付く助詞は「を」になる。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36693, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い事例を調べれて、報告書を書きました。", "corrected_sentence": "古い事例を調べて、報告書を書きました。", "error_description": "誤: 調べれて / 正: 調べて。「調べる」の接続は「調べて」で、「調べれて」は誤った形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
