INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36694, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「報告を聞いて」の「を」。聞く対象である報告を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す「が」。ここは聞く対象なので使えない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。動詞「聞いて」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。報告を聞く対象を示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「報告を聞いて」の「を」。聞く対象である報告を示す。", "が": "主語を表す「が」。ここは聞く対象なので使えない。", "の": "連体修飾の「の」。動詞「聞いて」の対象にはならない。", "へ": "方向を表す「へ」。報告を聞く対象を示すことはできない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36694, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かについて、みんなに知らせることです。", "primary_collocate": null, "pronunciation": "ほうこく", "ipa": "hoːkokɯ", "syllable_count": 4, "sentences": [{"text": "会議のあとで、田中さんが結果をみんなに報告しました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "会議[かいぎ]のあとで、田中[たなか]さんが結果[けっか]をみんなに報告[ほうこく]しました。", "sentence_source": "generated"}, {"text": "工事が遅れていることを、住民に報告する必要があります。", "target_word": "報告", "complexity_tier": "T3", "furigana": "工事[こうじ]が遅[おく]れていることを、住民[じゅうみん]に報告[ほうこく]する必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "委員長は、今年の活動について総会で報告しました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "委員長[いいんちょう]は、今年[ことし]の活動[かつどう]について総会[そうかい]で報告[ほうこく]しました。", "sentence_source": "generated"}, {"text": "調査でわかったことを、クラスのみんなに報告します。", "target_word": "報告", "complexity_tier": "T3", "furigana": "調査[ちょうさ]でわかったことを、クラスのみんなに報告[ほうこく]します。", "sentence_source": "generated"}, {"text": "事故の原因がわかったので、全社員に報告しました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]がわかったので、全社員[ぜんしゃいん]に報告[ほうこく]しました。", "sentence_source": "generated"}, {"text": "旅行から帰った兄は、見たことを家族に報告しました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "旅行[りょこう]から帰[かえ]った兄[あに]は、見[み]たことを家族[かぞく]に報告[ほうこく]しました。", "sentence_source": "generated"}, {"text": "決まったことは、すぐ全員に報告してください。", "target_word": "報告", "complexity_tier": "T3", "furigana": "決[き]まったことは、すぐ全員[ぜんいん]に報告[ほうこく]してください。", "sentence_source": "generated"}, {"text": "報告を聞いて、集まった人たちはとても安心しました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "報告[ほうこく]を聞[き]いて、集[あつ]まった人[ひと]たちはとても安心[あんしん]しました。", "sentence_source": "generated"}, {"text": "報告が遅れたので、みんなが心配していました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "報告[ほうこく]が遅[おく]れたので、みんなが心配[しんぱい]していました。", "sentence_source": "generated"}, {"text": "山田さんは大会の結果を、チームのみんなにメールで報告しました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "山田[やまだ]さんは大会[たいかい]の結果[けっか]を、チームのみんなにメールで報告[ほうこく]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "報告", "label": "基本形"}, {"form": "報告する", "label": "サ変動詞の終止形"}, {"form": "報告した", "label": "過去形"}, {"form": "報告して", "label": "て形"}], "register": "丁寧", "sense_fingerprint": "決まったことやわかったことを、多くの人に知らせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36694, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "報告", "is_correct": true, "explanation": "「結果をみんなに」に続けて、知らせる意味の「報告」が入るので正解。"}, {"text": "応募", "is_correct": false, "explanation": "応募は申し込むことなので、結果を人に知らせる意味にはならない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集まりを終わらせることなので、結果を伝える動作には合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "欠席は会などに出ないことなので、結果を伝える動作にはならない。"}], "explanations": {"報告": "「結果をみんなに」に続けて、知らせる意味の「報告」が入るので正解。", "応募": "応募は申し込むことなので、結果を人に知らせる意味にはならない。", "解散": "解散は集まりを終わらせることなので、結果を伝える動作には合わない。", "欠席": "欠席は会などに出ないことなので、結果を伝える動作にはならない。"}, "sentence_index": 0, "correct_answer": "報告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は好きな人に、ずっと抱いていた気持ちを報告しました。", "explanation": "ここは〈打ち明ける〉の意味。報告は調べた事実や決まったことを知らせることで、気持ちには使わない。"}, {"text": "宿題を、先生に報告しました。", "explanation": "ここは〈提出〉の意味。報告は事実を知らせることで、宿題を渡す行為には使わない。"}, {"text": "新しい友達を、クラスのみんなに報告しました。", "explanation": "ここは〈紹介〉の意味。報告は知らせることで、人を引き合わせる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36694, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "報告", "is_correct": true, "explanation": "「すぐ全員に」に続けて、決まったことを知らせる「報告」が入るので正解。"}, {"text": "購入", "is_correct": false, "explanation": "購入は品物を買うことなので、全員に決定を伝える意味にはならない。"}, {"text": "延期", "is_correct": false, "explanation": "延期は日時を後ろにずらすことなので、「全員に」と続けても知らせる意味にならない。"}, {"text": "外出", "is_correct": false, "explanation": "外出は場所を離れることなので、「全員に」と続く文には合わない。"}], "explanations": {"報告": "「すぐ全員に」に続けて、決まったことを知らせる「報告」が入るので正解。", "購入": "購入は品物を買うことなので、全員に決定を伝える意味にはならない。", "延期": "延期は日時を後ろにずらすことなので、「全員に」と続けても知らせる意味にならない。", "外出": "外出は場所を離れることなので、「全員に」と続く文には合わない。"}, "sentence_index": 6, "correct_answer": "報告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店員に、お昼の料理を報告しました。", "explanation": "ここは〈注文〉の意味。報告は知らせることで、料理を頼む行為には使わない。"}, {"text": "新しい靴を、昨日報告しました。", "explanation": "ここは〈購入〉の意味。報告は情報を伝えることで、品物を買う意味にはならない。"}, {"text": "旅行のホテルを、電話で報告しました。", "explanation": "ここは〈予約〉の意味。報告は事実を知らせることで、部屋を取る意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36694, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の結果の報告を遅れました。", "corrected_sentence": "会議の結果の報告が遅れました。", "error_description": "「報告を遅れました」は誤り。「遅れる」は主語に「が」を取るので、報告に直接つく助詞は「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36694, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週の結果を、部長に報告いた。", "corrected_sentence": "先週の結果を、部長に報告した。", "error_description": "「報告いた」は誤り。サ変動詞「する」の過去形は「報告した」で、「いた」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
