INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36695, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「報告がありました」の「が」。報告が存在することを表す主語。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。「報告をありました」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示す。「報告にありました」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「報告のありました」では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「報告がありました」の「が」。報告が存在することを表す主語。", "を": "「を」は動作の対象を示す。「報告をありました」は不自然。", "に": "「に」は場所や相手を示す。「報告にありました」は意味が通らない。", "の": "連体修飾の「の」。「報告のありました」では文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36695, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある事柄や情報を、人に伝えること。また、その知らせ。", "primary_collocate": null, "pronunciation": "ほうこく", "ipa": "hoːkokɯ", "syllable_count": 4, "sentences": [{"text": "部長に、仕事の進み具合を報告しました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "部長[ぶちょう]に、仕事[しごと]の進[すす]み具合[ぐあい]を報告[ほうこく]しました。", "sentence_source": "generated"}, {"text": "問題が起きたら、すぐに上司へ報告してください。", "target_word": "報告", "complexity_tier": "T3", "furigana": "問題[もんだい]が起[お]きたら、すぐに上司[じょうし]へ報告[ほうこく]してください。", "sentence_source": "generated"}, {"text": "医者は、検査の結果を患者に報告しました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、検査[けんさ]の結果[けっか]を患者[かんじゃ]に報告[ほうこく]しました。", "sentence_source": "generated"}, {"text": "報告が遅れて、先生に注意されました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "報告[ほうこく]が遅[おく]れて、先生[せんせい]に注意[ちゅうい]されました。", "sentence_source": "generated"}, {"text": "警察に事故を報告したのは、近くにいた男性でした。", "target_word": "報告", "complexity_tier": "T3", "furigana": "警察[けいさつ]に事故[じこ]を報告[ほうこく]したのは、近[ちか]くにいた男性[だんせい]でした。", "sentence_source": "generated"}, {"text": "出張から戻ったので、課長に報告しなければなりません。", "target_word": "報告", "complexity_tier": "T3", "furigana": "出張[しゅっちょう]から戻[もど]ったので、課長[かちょう]に報告[ほうこく]しなければなりません。", "sentence_source": "generated"}, {"text": "来月までに、調査の報告を出す予定です。", "target_word": "報告", "complexity_tier": "T3", "furigana": "来月[らいげつ]までに、調査[ちょうさ]の報告[ほうこく]を出[だ]す予定[よてい]です。", "sentence_source": "generated"}, {"text": "出張先の支社から、無事に到着したという報告がありました。", "target_word": "報告", "complexity_tier": "T3", "furigana": "出張先[しゅっちょうさき]の支社[ししゃ]から、無事[ぶじ]に到着[とうちゃく]したという報告[ほうこく]がありました。", "sentence_source": "generated"}, {"text": "毎週月曜日に、先輩へ仕事の報告をしています。", "target_word": "報告", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]月曜日[げつようび]に、先輩[せんぱい]へ仕事[しごと]の報告[ほうこく]をしています。", "sentence_source": "generated"}, {"text": "間違いを見つけたら、隠さずに報告することが大切です。", "target_word": "報告", "complexity_tier": "T3", "furigana": "間違[まちが]いを見[み]つけたら、隠[かく]さずに報告[ほうこく]することが大切[たいせつ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "報告", "label": "基本形"}, {"form": "報告する", "label": "サ変動詞の終止形"}, {"form": "報告した", "label": "過去形"}, {"form": "報告して", "label": "て形"}], "register": "丁寧", "sense_fingerprint": "仕事や調査の内容を、上司や相手に伝えること。その知らせ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36695, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "報告", "is_correct": true, "explanation": "「仕事の進み具合を」に続けて、知らせる意味の「報告」が入るので正解。"}, {"text": "応募", "is_correct": false, "explanation": "応募は申し込むことなので、進み具合を伝える意味にはならない。"}, {"text": "購入", "is_correct": false, "explanation": "購入は品物を買うことなので、「進み具合」とは合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "欠席は会などに出ないことなので、進み具合を伝える動作にはならない。"}], "explanations": {"報告": "「仕事の進み具合を」に続けて、知らせる意味の「報告」が入るので正解。", "応募": "応募は申し込むことなので、進み具合を伝える意味にはならない。", "購入": "購入は品物を買うことなので、「進み具合」とは合わない。", "欠席": "欠席は会などに出ないことなので、進み具合を伝える動作にはならない。"}, "sentence_index": 0, "correct_answer": "報告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行のホテルを、電話で報告しました。", "explanation": "ここは〈予約〉の意味。報告は知らせる行為で、部屋を取る意味にはならない。"}, {"text": "旅行で撮った写真を、SNSに報告しました。", "explanation": "ここは〈投稿〉の意味。写真を公開する行為は報告ではない。"}, {"text": "新しく来た社員を、みんなに報告しました。", "explanation": "ここは〈紹介〉の意味。人を引き合わせる意味は報告にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36695, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "報告", "is_correct": true, "explanation": "「調査の」に続けて、提出する内容を表す「報告」が入るので正解。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集まりを終わらせることなので、調査の内容を出す意味にはならない。"}, {"text": "外出", "is_correct": false, "explanation": "外出は場所を離れることなので、書類を出す意味には合わない。"}, {"text": "通院", "is_correct": false, "explanation": "通院は病院へ通うことなので、調査の内容とは合わない。"}], "explanations": {"報告": "「調査の」に続けて、提出する内容を表す「報告」が入るので正解。", "解散": "解散は集まりを終わらせることなので、調査の内容を出す意味にはならない。", "外出": "外出は場所を離れることなので、書類を出す意味には合わない。", "通院": "通院は病院へ通うことなので、調査の内容とは合わない。"}, "sentence_index": 6, "correct_answer": "報告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店員に、ランチを報告しました。", "explanation": "ここは〈注文〉の意味。報告は知らせる行為で、料理を頼む意味にはならない。"}, {"text": "宅配便が、荷物を報告しました。", "explanation": "ここは〈配達〉の意味。荷物を届ける行為は報告ではない。"}, {"text": "試合の日、大きな声で選手を報告しました。", "explanation": "ここは〈応援〉の意味。報告は事実を伝えることで、選手を励む意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36695, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "報告で受けて、対応を決めました。", "corrected_sentence": "報告を受けて、対応を決めました。", "error_description": "「報告で受けて」は誤り。「受ける」は対象を「を」で示すので、「報告を受けて」が正しい。「で」は手段や場所を表し、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36695, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "すぐに上司へ報告ります。", "corrected_sentence": "すぐに上司へ報告します。", "error_description": "「報告ります」は誤り。サ変動詞の「報告」には「します」が必要で、「し」が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
