INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36696, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体の中で自然に起こる動きやはたらきのことです。", "primary_collocate": null, "pronunciation": "せいり", "ipa": "seːɾi", "syllable_count": 3, "sentences": [{"text": "人間の体の生理について、本で調べました。", "target_word": "生理", "complexity_tier": "T3", "furigana": "人間[にんげん]の体[からだ]の生理[せいり]について、本[ほん]で調[しら]べました。", "sentence_source": "generated"}, {"text": "眠くなるのは、体の生理だから仕方がない。", "target_word": "生理", "complexity_tier": "T3", "furigana": "眠[ねむ]くなるのは、体[からだ]の生理[せいり]だから仕方[しかた]がない。", "sentence_source": "generated"}, {"text": "年をとると、体の生理も少しずつ変わる。", "target_word": "生理", "complexity_tier": "T3", "furigana": "年[とし]をとると、体[からだ]の生理[せいり]も少[すこ]しずつ変[か]わる。", "sentence_source": "generated"}, {"text": "食べたものが消化される生理を、図で説明した。", "target_word": "生理", "complexity_tier": "T3", "furigana": "食[た]べたものが消化[しょうか]される生理[せいり]を、図[ず]で説明[せつめい]した。", "sentence_source": "generated"}, {"text": "汗が出るのは、体温を下げる生理のはたらきだ。", "target_word": "生理", "complexity_tier": "T3", "furigana": "汗[あせ]が出[で]るのは、体温[たいおん]を下[さ]げる生理[せいり]のはたらきだ。", "sentence_source": "generated"}, {"text": "医者は、病気を治療するには体の生理をよく知る必要があると言った。", "target_word": "生理", "complexity_tier": "T3", "furigana": "いしゃは、びょうきをちりょうするにはからだのせいりをよくしるひつようがあるといった。", "sentence_source": "generated"}, {"text": "寝ている間の生理について、先生が話してくれた。", "target_word": "生理", "complexity_tier": "T3", "furigana": "寝[ね]ている間[あいだ]の生理[せいり]について、先生[せんせい]が話[はな]してくれた。", "sentence_source": "generated"}, {"text": "運動すると心拍数が上がるのも、生理の一つです。", "target_word": "生理", "complexity_tier": "T3", "furigana": "運動[うんどう]すると心拍数[しんぱくすう]が上[あ]がるのも、生理[せいり]の一[ひと]つです。", "sentence_source": "generated"}, {"text": "子どもの体の生理は、大人とは少し違う。", "target_word": "生理", "complexity_tier": "T3", "furigana": "子[こ]どもの体[からだ]の生理[せいり]は、大人[おとな]とは少[すこ]し違[ちが]う。", "sentence_source": "generated"}, {"text": "呼吸のような生理は、意識しなくても続く。", "target_word": "生理", "complexity_tier": "T3", "furigana": "呼吸[こきゅう]のような生理[せいり]は、意識[いしき]しなくても続[つづ]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生理", "label": "基本形"}, {"form": "生理の", "label": "連体形（の）"}], "register": "neutral", "sense_fingerprint": "人の体の中で自然に起こる働き（消化・呼吸・発汗など）。体の生理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36696, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生理", "is_correct": true, "explanation": "「人間の体の生理について」には、体の働きを指す「生理」が入る。"}, {"text": "地理", "is_correct": false, "explanation": "土地の様子を指す語で、体について調べる文脈には合わない。"}, {"text": "倫理", "is_correct": false, "explanation": "人の道や善悪を指す語で、体の働きには当たらない。"}, {"text": "雑誌", "is_correct": false, "explanation": "定期刊行物を指す語で、「体の雑誌」は意味をなさない。"}], "explanations": {"生理": "「人間の体の生理について」には、体の働きを指す「生理」が入る。", "地理": "土地の様子を指す語で、体について調べる文脈には合わない。", "倫理": "人の道や善悪を指す語で、体の働きには当たらない。", "雑誌": "定期刊行物を指す語で、「体の雑誌」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "生理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重力の生理によって、ボールは地面に落ちる。", "explanation": "ここは〈法則〉の意味。生理は生き物の体の働きを指し、重力のような物理の法則には使わない。"}, {"text": "この機械の生理は、古くなると落ちる。", "explanation": "ここは〈機能〉の意味。生理は生き物の体の働きに使い、機械には使わない。"}, {"text": "この紙の生理は、湿気で少しずつ変わる。", "explanation": "ここは〈性質〉の意味。紙は生きていないので、体の働きを指す生理は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36696, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生理", "is_correct": true, "explanation": "「寝ている間の生理について」には、睡眠中の体の働きを指す「生理」が入る。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙や荷物を送る制度を指す語で、体の働きには当たらない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便料金を示す証票で、体について話す文脈には合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "授業で使う本で、「寝ている間の教科書」は意味をなさない。"}], "explanations": {"生理": "「寝ている間の生理について」には、睡眠中の体の働きを指す「生理」が入る。", "郵便": "手紙や荷物を送る制度を指す語で、体の働きには当たらない。", "切手": "郵便料金を示す証票で、体について話す文脈には合わない。", "教科書": "授業で使う本で、「寝ている間の教科書」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "生理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作品は、作者の生理を強く感じさせる。", "explanation": "ここは〈性格〉の意味。生理は体の働きを指し、人の内面を表すのには使わない。"}, {"text": "山の生理は、高さによって変わる。", "explanation": "ここは〈地形〉の意味。生理は生き物の体の働きを指すので、山には使わない。"}, {"text": "布の生理は柔らかく、肌触りがいい。", "explanation": "ここは〈感触〉の意味。生理は生き物の体の働きに使い、布の手触りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36696, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜更かしは、体の生理を乱れる。", "corrected_sentence": "夜更かしは、体の生理を乱す。", "error_description": "「乱す」は他動詞で「を」を取る。「乱れる」は自動詞なので「を」と合わない。正しくは「乱す」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36696, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "運動は、体の生理が整える。", "corrected_sentence": "運動は、体の生理を整える。", "error_description": "「整える」は他動詞で「を」を取る。「が」は誤りで、正しくは「体の生理を整える」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36697, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「魚の生理」の「の」は、「魚」と「生理」をつなぐので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」が二つ続いて二重になり、「魚を生理を」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、名詞どうしの関係を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「知る」は「に」を取らないので、「魚に生理を知る」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「魚の生理」の「の」は、「魚」と「生理」をつなぐので正しい。", "を": "「を」が二つ続いて二重になり、「魚を生理を」は成り立たない。", "へ": "「へ」は方向を示すので、名詞どうしの関係を表せない。", "に": "「知る」は「に」を取らないので、「魚に生理を知る」は不自然。"}, "error_tags": {"を": "二重の格: 「知る」の目的語にすでに「を」が付いている", "に": "相手: 「知る」は「に」の相手を取らない", "へ": "方向の格: 方向を示し、名詞どうしの関係を作れない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
