INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36697, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生物の体が生きていくために、自然に行われる活動や反応のこと。", "primary_collocate": null, "pronunciation": "せいり", "ipa": "seːɾi", "syllable_count": 3, "sentences": [{"text": "この授業では、植物の生理を学びます。", "target_word": "生理", "complexity_tier": "T3", "furigana": "この授業[じゅぎょう]では、植物[しょくぶつ]の生理[せいり]を学[まな]びます。", "sentence_source": "generated"}, {"text": "魚の生理を知ると、飼い方がよくわかる。", "target_word": "生理", "complexity_tier": "T3", "furigana": "魚[さかな]の生理[せいり]を知[し]ると、飼[か]い方[かた]がよくわかる。", "sentence_source": "generated"}, {"text": "冬眠する動物の生理は、とても不思議だ。", "target_word": "生理", "complexity_tier": "T3", "furigana": "冬眠[とうみん]する動物[どうぶつ]の生理[せいり]は、とても不思議[ふしぎ]だ。", "sentence_source": "generated"}, {"text": "虫が光に集まる生理を、実験で調べた。", "target_word": "生理", "complexity_tier": "T3", "furigana": "虫[むし]が光[ひかり]に集[あつ]まる生理[せいり]を、実験[じっけん]で調[しら]べた。", "sentence_source": "generated"}, {"text": "暑さに弱い生物の生理について発表した。", "target_word": "生理", "complexity_tier": "T3", "furigana": "暑[あつ]さに弱[よわ]い生物[せいぶつ]の生理[せいり]について発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "彼女は海の生き物の生理を研究している。", "target_word": "生理", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は海[うみ]の生[い]き物[もの]の生理[せいり]を研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "鳥が渡りをする生理は、まだ完全にはわかっていない。", "target_word": "生理", "complexity_tier": "T3", "furigana": "鳥[とり]が渡[わた]りをする生理[せいり]は、まだ完全[かんぜん]にはわかっていない。", "sentence_source": "generated"}, {"text": "植物が光を使って育つ生理を、図で見た。", "target_word": "生理", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]が光[ひかり]を使[つか]って育[そだ]つ生理[せいり]を、図[ず]で見[み]た。", "sentence_source": "generated"}, {"text": "動物の生理を理解すれば、病気も防げる。", "target_word": "生理", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の生理[せいり]を理解[りかい]すれば、病気[びょうき]も防[ふせ]げる。", "sentence_source": "generated"}, {"text": "犬と猫では、体の生理がかなり違う。", "target_word": "生理", "complexity_tier": "T3", "furigana": "犬[いぬ]と猫[ねこ]では、体[からだ]の生理[せいり]がかなり違[ちが]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生理", "label": "基本形"}, {"form": "生理の", "label": "連体形（の）"}], "register": "neutral", "sense_fingerprint": "動物・植物など生物一般の体が生きるために行う活動や反応。生物の生理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36697, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生理", "is_correct": true, "explanation": "「植物の生理を学びます」には、生物が生きるための働きを指す「生理」が入る。"}, {"text": "倫理", "is_correct": false, "explanation": "人の道や善悪を指す語で、植物の働きには当たらない。"}, {"text": "雑誌", "is_correct": false, "explanation": "定期刊行物を指す語で、「植物の雑誌」は意味をなさない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便料金の証票で、植物を学ぶ文脈には合わない。"}], "explanations": {"生理": "「植物の生理を学びます」には、生物が生きるための働きを指す「生理」が入る。", "倫理": "人の道や善悪を指す語で、植物の働きには当たらない。", "雑誌": "定期刊行物を指す語で、「植物の雑誌」は意味をなさない。", "切手": "郵便料金の証票で、植物を学ぶ文脈には合わない。"}, "sentence_index": 0, "correct_answer": "生理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石が雨で割れる生理を、実験で調べた。", "explanation": "ここは〈物理〉の意味。生理は生き物の働きに使うので、石の性質には合わない。"}, {"text": "機械が熱で止まる生理を、図で調べた。", "explanation": "ここは〈仕組み〉の意味。生理は生き物の体の働きを指し、機械には使わない。"}, {"text": "鉄の生理を、実験で調べた。", "explanation": "ここは〈性質〉の意味。生理は生き物の体の働きを指し、金属の性質には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36697, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生理", "is_correct": true, "explanation": "「鳥が渡りをする生理」には、生き物の体の働きを指す「生理」が入る。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙や荷物を送る制度で、生き物の働きには当たらない。"}, {"text": "切符", "is_correct": false, "explanation": "乗車や入場の証明で、「渡りをする切符」は意味をなさない。"}, {"text": "商品", "is_correct": false, "explanation": "販売される品物で、鳥の働きを表せない。"}], "explanations": {"生理": "「鳥が渡りをする生理」には、生き物の体の働きを指す「生理」が入る。", "郵便": "手紙や荷物を送る制度で、生き物の働きには当たらない。", "切符": "乗車や入場の証明で、「渡りをする切符」は意味をなさない。", "商品": "販売される品物で、鳥の働きを表せない。"}, "sentence_index": 6, "correct_answer": "生理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "犬と猫では、値段の生理がかなり違う。", "explanation": "ここは〈価格〉の意味。生理は生き物の体の働きを指すので、値段には使わない。"}, {"text": "犬と猫では、天気の生理がかなり違う。", "explanation": "ここは〈天候〉の意味。生理は生き物の体の働きを指し、天気の移り変わりには使わない。"}, {"text": "犬と猫では、機械の生理がかなり違う。", "explanation": "ここは〈仕組み〉の意味。生理は生き物の体の働きに使い、機械には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36697, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬眠する動物は、体の生理を大きく変わる。", "corrected_sentence": "冬眠する動物は、体の生理を大きく変える。", "error_description": "「変える」は他動詞で「を」を取る。「変わる」は自動詞なので「を」と合わない。正しくは「変える」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36697, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い日は、体の生理に一定に保つ。", "corrected_sentence": "寒い日は、体の生理を一定に保つ。", "error_description": "「保つ」は他動詞で「を」を取る。「に」は誤りで、正しくは「体の生理を一定に保つ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36698, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「大阪に留まる」で、留まる場所を示すため「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「留まる」は目的語を取らないため「大阪を留まって」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示すが、「大阪と留まって」は場所を示せず文として通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「大阪から留まって」では出発の意味になり、居続ける内容と合わない。"}], "correct_answer": "に", "explanations": {"に": "「大阪に留まる」で、留まる場所を示すため「に」が正しい。", "を": "目的語を示すが、「留まる」は目的語を取らないため「大阪を留まって」は成り立たない。", "と": "並列や共同を示すが、「大阪と留まって」は場所を示せず文として通らない。", "から": "起点を示すが、「大阪から留まって」では出発の意味になり、居続ける内容と合わない。"}, "error_tags": {"を": "目的語", "と": "並列・共同", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "去る", "is_correct": true, "explanation": "「留まる」の対義語。その場にとどまらず離れる意味で、「家に留まる」と反対の内容になる。"}, {"text": "広がる", "is_correct": false, "explanation": "範囲が広がる意味で、その場に居続ける「留まる」と対立しない。"}, {"text": "続く", "is_correct": false, "explanation": "時間が途切れず続く意味で、場所に居続ける「留まる」の対義語にはならない。"}, {"text": "集まる", "is_correct": false, "explanation": "人や物が一か所に寄る意味で、「留まる」の対義語ではない。"}], "correct_answer": "去る", "explanations": {"去る": "「留まる」の対義語。その場にとどまらず離れる意味で、「家に留まる」と反対の内容になる。", "広がる": "範囲が広がる意味で、その場に居続ける「留まる」と対立しない。", "続く": "時間が途切れず続く意味で、場所に居続ける「留まる」の対義語にはならない。", "集まる": "人や物が一か所に寄る意味で、「留まる」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36698, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一つの国に留まらず」で、留まる場所を示すため「に」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「一つの国が留まらず」では主語の彼の行動の説明と成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「留まる」は方向に向かう動詞ではないので「国へ留まらず」は合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、「国より留まらず」は文として通らない。"}], "correct_answer": "に", "explanations": {"に": "「一つの国に留まらず」で、留まる場所を示すため「に」が正しい。", "が": "主語を示すが、「一つの国が留まらず」では主語の彼の行動の説明と成り立たない。", "へ": "方向を示すが、「留まる」は方向に向かう動詞ではないので「国へ留まらず」は合わない。", "より": "比較を示すが、「国より留まらず」は文として通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "去る", "is_correct": true, "explanation": "「留まる」の対義語。その場にとどまらず離れる意味で、「大雪で列車の中に留まった」と反対の内容になる。"}, {"text": "増える", "is_correct": false, "explanation": "数や量が多くなる意味で、居続けることとは対義にならない。"}, {"text": "集う", "is_correct": false, "explanation": "人が集まって楽しむ意味で、居続ける「留まる」の対義語ではない。"}, {"text": "冷める", "is_correct": false, "explanation": "温度が下がる意味で、場所に居続ける「留まる」とは対義関係にない。"}], "correct_answer": "去る", "explanations": {"去る": "「留まる」の対義語。その場にとどまらず離れる意味で、「大雪で列車の中に留まった」と反対の内容になる。", "増える": "数や量が多くなる意味で、居続けることとは対義にならない。", "集う": "人が集まって楽しむ意味で、居続ける「留まる」の対義語ではない。", "冷める": "温度が下がる意味で、場所に居続ける「留まる」とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36698, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "同じところにずっといる。", "primary_collocate": null, "pronunciation": "とまる", "ipa": "tomaɾɯ", "syllable_count": 3, "sentences": [{"text": "嵐のため、私たちは山小屋に留まることにした。", "target_word": "留まる", "complexity_tier": "T3", "furigana": "嵐(あらし)のため、私(わたし)たちは山小屋(やまごや)に留(とま)ることにした。", "sentence_source": "generated"}, {"text": "彼は大阪に留まって、父の店をついだ。", "target_word": "留まって", "complexity_tier": "T3", "furigana": "彼(かれ)は大阪(おおさか)に留(とま)って、父(ちち)の店(みせ)をついだ。", "sentence_source": "generated"}, {"text": "危ないので、この場所に留まらないでください。", "target_word": "留まらない", "complexity_tier": "T3", "furigana": "危(あぶ)ないので、この場所(ばしょ)に留(とま)らないでください。", "sentence_source": "generated"}, {"text": "火事のとき、家に留まるのは危険だ。", "target_word": "留まる", "complexity_tier": "T3", "furigana": "火事(かじ)のとき、家(いえ)に留(とま)るのは危険(きけん)だ。", "sentence_source": "generated"}, {"text": "彼女は故郷に留まり、祖母の世話をした。", "target_word": "留まり", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は故郷(ふるさと)に留(とま)り、祖母(そぼ)の世話(せわ)をした。", "sentence_source": "generated"}, {"text": "雨が止むまで、駅に留まっていた。", "target_word": "留まって", "complexity_tier": "T3", "furigana": "雨(あめ)が止(や)むまで、駅(えき)に留(とま)っていた。", "sentence_source": "generated"}, {"text": "会社に留まるか、辞めるか、まだ決められない。", "target_word": "留まる", "complexity_tier": "T3", "furigana": "会社(かいしゃ)に留(とま)るか、辞(や)めるか、まだ決(き)められない。", "sentence_source": "generated"}, {"text": "彼は一つの国に留まらず、世界中を旅した。", "target_word": "留まらず", "complexity_tier": "T3", "furigana": "彼(かれ)は一(ひと)つの国(くに)に留(とま)らず、世界中(せかいじゅう)を旅(たび)した。", "sentence_source": "generated"}, {"text": "先生に言われて、私は教室に留まった。", "target_word": "留まった", "complexity_tier": "T3", "furigana": "先生(せんせい)に言(い)われて、私(わたし)は教室(きょうしつ)に留(とま)った。", "sentence_source": "generated"}, {"text": "大雪で、列車の中に一晩留まった。", "target_word": "留まった", "complexity_tier": "T3", "furigana": "大雪(おおゆき)で、列車(れっしゃ)の中(なか)に一晩(ひとばん)留(とま)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "留まる", "label": "辞書形"}, {"form": "留まらない", "label": "否定形"}, {"form": "留まり", "label": "連用形"}, {"form": "留まった", "label": "過去形"}, {"form": "留まって", "label": "て形"}, {"form": "留まれば", "label": "仮定形"}], "register": "標準語", "sense_fingerprint": "ある場所に動かずそのまま居続ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36698, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "留まる", "is_correct": true, "explanation": "文中の形。「山小屋に留まることにした」で、その場に居続ける意味が自然。"}, {"text": "離れる", "is_correct": false, "explanation": "「山小屋に離れる」は場所への動きとして成り立たず、決めた内容として文が通らない。"}, {"text": "飛ぶ", "is_correct": false, "explanation": "「山小屋に飛ぶ」は意味が通らず、嵐のため決めた行動として不自然。"}, {"text": "凍る", "is_correct": false, "explanation": "「山小屋に凍る」は意味をなさず、山小屋に避難する話の流れと合わない。"}], "explanations": {"留まる": "文中の形。「山小屋に留まることにした」で、その場に居続ける意味が自然。", "離れる": "「山小屋に離れる」は場所への動きとして成り立たず、決めた内容として文が通らない。", "飛ぶ": "「山小屋に飛ぶ」は意味が通らず、嵐のため決めた行動として不自然。", "凍る": "「山小屋に凍る」は意味をなさず、山小屋に避難する話の流れと合わない。"}, "sentence_index": 0, "correct_answer": "留まる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "支払いが留まっていて、会社は困っている。", "explanation": "ここは〈滞る〉の場面。支払いが進まない状態を表すのは「滞る」で、〈留まる〉の居続ける意味とは合わない。"}, {"text": "会議の日程が留まって、来月になった。", "explanation": "ここは〈延期〉の場面。日程を先送りにするのは「延期」で、〈留まる〉の居続ける意味とは合わない。"}, {"text": "昼過ぎになって、ようやく雨が留まった。", "explanation": "ここは〈止む〉の場面。雨がやむのは「止む」で、〈留まる〉の場所に居続ける意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36698, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留まる", "is_correct": true, "explanation": "文中の形。「会社に留まるか、辞めるか」で、会社に残るかどうかの選択として自然。"}, {"text": "漂う", "is_correct": false, "explanation": "「会社に漂うか」は場所への動きとして成り立たず、選択の文として通らない。"}, {"text": "急ぐ", "is_correct": false, "explanation": "「会社に急ぐか」は文法的にも意味的にも通らず、残るかどうかの話と合わない。"}, {"text": "出発する", "is_correct": false, "explanation": "「会社に出発するか」は場所との結びつきが不自然で、辞めるかどうかの選択と合わない。"}], "explanations": {"留まる": "文中の形。「会社に留まるか、辞めるか」で、会社に残るかどうかの選択として自然。", "漂う": "「会社に漂うか」は場所への動きとして成り立たず、選択の文として通らない。", "急ぐ": "「会社に急ぐか」は文法的にも意味的にも通らず、残るかどうかの話と合わない。", "出発する": "「会社に出発するか」は場所との結びつきが不自然で、辞めるかどうかの選択と合わない。"}, "sentence_index": 6, "correct_answer": "留まる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は驚いて、表情が留まった。", "explanation": "ここは〈固まる〉の場面。表情が動かなくなる様子は「固まる」で、〈留まる〉の居続ける意味とは合わない。"}, {"text": "庭の隅に草が留まってきた。", "explanation": "ここは〈生える〉の場面。草が育って現れることは「生える」で、〈留まる〉は合わない。"}, {"text": "髪が留まって、肩に届いた。", "explanation": "ここは〈伸びる〉の場面。長さが増すことは「伸びる」で、〈留まる〉の場所に居続ける意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36698, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は故郷を留まって、家業を継いだ。", "corrected_sentence": "彼は故郷に留まって、家業を継いだ。", "error_description": "「留まる」は目的語の「を」を取らない自動詞。場所は「に」で示すため、「故郷を」は「故郷に」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "留まって", "is_correct": true, "explanation": "文中のて形。「留まって、父の店をついだ」と動作を続けて述べる形。"}, {"text": "留まる", "is_correct": false, "explanation": "辞書形。「大阪に留まる、父の店をついだ」と続かず、文の流れが成り立たない。"}, {"text": "留まらない", "is_correct": false, "explanation": "否定形。居続けないという意味になり、父の店をついだ流れと合わない。"}, {"text": "留まった", "is_correct": false, "explanation": "過去形。「留まった、父の店をついだ」と時間の関係が変わり、文の流れに合わない。"}], "correct_form": "留まって", "base_form": "留まる", "form_label": "て形", "sentence_index": 1, "explanations": {"留まって": "文中のて形。「留まって、父の店をついだ」と動作を続けて述べる形。", "留まる": "辞書形。「大阪に留まる、父の店をついだ」と続かず、文の流れが成り立たない。", "留まらない": "否定形。居続けないという意味になり、父の店をついだ流れと合わない。", "留まった": "過去形。「留まった、父の店をついだ」と時間の関係が変わり、文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36698, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は祖母の家に留まいて、家事を手伝った。", "corrected_sentence": "彼女は祖母の家に留まって、家事を手伝った。", "error_description": "「留まいて」は誤ったて形。「留まる」のて形は「留まって」で、ここでは「留まって」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "留まらず", "is_correct": true, "explanation": "文中の連用形（ず）。「留まらず、世界中を旅した」で、居続けないことを表す。"}, {"text": "留まれ", "is_correct": false, "explanation": "命令形。「留まれ、世界中を旅した」と命令が続き、過去の旅の出来事を述べる文と合わない。"}, {"text": "留まれば", "is_correct": false, "explanation": "仮定形。「留まれば、世界中を旅した」と条件節だけでは文が完結せず、成り立たない。"}, {"text": "留まろう", "is_correct": false, "explanation": "意志形。勧誘や意志の意味になり、過去の旅の出来事を述べる文と合わない。"}], "correct_form": "留まらず", "base_form": "留まる", "form_label": "連用形（ず）", "sentence_index": 7, "explanations": {"留まらず": "文中の連用形（ず）。「留まらず、世界中を旅した」で、居続けないことを表す。", "留まれ": "命令形。「留まれ、世界中を旅した」と命令が続き、過去の旅の出来事を述べる文と合わない。", "留まれば": "仮定形。「留まれば、世界中を旅した」と条件節だけでは文が完結せず、成り立たない。", "留まろう": "意志形。勧誘や意志の意味になり、過去の旅の出来事を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36700, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静的", "is_correct": true, "explanation": "「動的」と反対の、変化しないようすを表す語なので対義語。"}, {"text": "複雑", "is_correct": false, "explanation": "複雑は入り組んでいるようすで、動的の反対語ではない。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速は速いようすで、変化の有無の対義にはならない。"}, {"text": "活発", "is_correct": false, "explanation": "活発は盛んに動くようすで、動的に近い意味なので対義語にはならない。"}], "correct_answer": "静的", "explanations": {"静的": "「動的」と反対の、変化しないようすを表す語なので対義語。", "複雑": "複雑は入り組んでいるようすで、動的の反対語ではない。", "迅速": "迅速は速いようすで、変化の有無の対義にはならない。", "活発": "活発は盛んに動くようすで、動的に近い意味なので対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36700, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静的", "is_correct": true, "explanation": "「動的」と反対の、変化しないようすを表す語なので対義語。"}, {"text": "正確", "is_correct": false, "explanation": "正確は誤りがないようすで、動的の反対語ではない。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は丈夫なようすで、変化の有無の対義にはならない。"}, {"text": "豊か", "is_correct": false, "explanation": "豊かは量や内容が十分なようすで、動的の対義語ではない。"}], "correct_answer": "静的", "explanations": {"静的": "「動的」と反対の、変化しないようすを表す語なので対義語。", "正確": "正確は誤りがないようすで、動的の反対語ではない。", "頑丈": "頑丈は丈夫なようすで、変化の有無の対義にはならない。", "豊か": "豊かは量や内容が十分なようすで、動的の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36700, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "動くときのようすが変わっていくこと。", "primary_collocate": null, "pronunciation": "どうてき", "ipa": "doːteki", "syllable_count": 4, "sentences": [{"text": "この踊りは動的で、リズムに合わせて動きがどんどん変わる。", "target_word": "動的", "complexity_tier": "T3", "furigana": "この踊(おど)りは動的(どうてき)で、リズムに合(あ)わせて動(うご)きがどんどん変(か)わる。", "sentence_source": "generated"}, {"text": "写真は止まっているが、動画は動的だ。", "target_word": "動的", "complexity_tier": "T2", "furigana": "写真(しゃしん)は止(と)まっているが、動画(どうが)は動的(どうてき)だ。", "sentence_source": "generated"}, {"text": "この絵は人が走る場面で、動的な印象がある。", "target_word": "動的", "complexity_tier": "T3", "furigana": "この絵(え)は人(ひと)が走(はし)る場面(ばめん)で、動的(どうてき)な印象(いんしょう)がある。", "sentence_source": "generated"}, {"text": "動的な演技の選手は、見ていて飽きない。", "target_word": "動的", "complexity_tier": "T3", "furigana": "動的(どうてき)な演技(えんぎ)の選手(せんしゅ)は、見(み)ていて飽(あ)きない。", "sentence_source": "generated"}, {"text": "水の流れを動的にとらえる映像が、授業で使われた。", "target_word": "動的", "complexity_tier": "T3", "furigana": "水(みず)の流(なが)れを動的(どうてき)にとらえる映像(えいぞう)が、授業(じゅぎょう)で使(つか)われた。", "sentence_source": "generated"}, {"text": "先生は星の位置の変化を、動的なアニメーションで見せてくれた。", "target_word": "動的", "complexity_tier": "T3", "furigana": "先生(せんせい)は星(ほし)の位置(いち)の変化(へんか)を、動的(どうてき)なアニメーションで見(み)せてくれた。", "sentence_source": "generated"}, {"text": "静かな曲より、動的な曲のほうが走るときに合う。", "target_word": "動的", "complexity_tier": "T2", "furigana": "静(しず)かな曲(きょく)より、動的(どうてき)な曲(きょく)のほうが走(はし)るときに合(あ)う。", "sentence_source": "generated"}, {"text": "このロボットは動的に歩いて、坂道も上れる。", "target_word": "動的", "complexity_tier": "T3", "furigana": "このロボットは動的(どうてき)に歩(ある)いて、坂道(さかみち)も上(のぼ)れる。", "sentence_source": "generated"}, {"text": "彫刻なのに、風の中を進むような動的な形をしている。", "target_word": "動的", "complexity_tier": "T3", "furigana": "彫刻(ちょうこく)なのに、風(かぜ)の中(なか)を進(すす)むような動的(どうてき)な形(かたち)をしている。", "sentence_source": "generated"}, {"text": "展示の動的な映像は、時間とともに形が変わっていく。", "target_word": "動的", "complexity_tier": "T3", "furigana": "展示(てんじ)の動的(どうてき)な映像(えいぞう)は、時間(じかん)とともに形(かたち)が変(か)わっていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動的だ", "label": "終止形"}, {"form": "動的な", "label": "連体形"}, {"form": "動的に", "label": "連用形"}, {"form": "動的で", "label": "て形相当"}], "register": "neutral", "sense_fingerprint": "動きのようすが変わっていき、躍動感があるさま（形容動詞的）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36700, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動的", "is_correct": true, "explanation": "「この踊りは動的で」の動的で、動きが変わっていくようすを表すので正解。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は丈夫さを表し、踊りの動き方の説明には合わない。"}, {"text": "上機嫌", "is_correct": false, "explanation": "上機嫌は人の気分を表す語で、踊りの説明には合わない。"}, {"text": "生意気", "is_correct": false, "explanation": "生意気は人の態度を表す語で、踊りの説明には合わない。"}], "explanations": {"動的": "「この踊りは動的で」の動的で、動きが変わっていくようすを表すので正解。", "頑丈": "頑丈は丈夫さを表し、踊りの動き方の説明には合わない。", "上機嫌": "上機嫌は人の気分を表す語で、踊りの説明には合わない。", "生意気": "生意気は人の態度を表す語で、踊りの説明には合わない。"}, "sentence_index": 0, "correct_answer": "動的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この看板は動的で、何も動かない。", "explanation": "ここは〈固定的〉の意味。位置や形が決まったままのようすは固定的で、動的は動きが変わることを表すので、動かない看板には合わない。"}, {"text": "学生たちは教室で動的に眠っていた。", "explanation": "ここは〈静止〉の意味。じっと動かないようすを表す静止が合い、動的は動きの変化を表すので、眠っている人の説明には合わない。"}, {"text": "ロボットは動的に同じ動きを繰り返す。", "explanation": "ここは〈機械的〉の意味。考えずに同じ動作を続けるのが機械的で、動的は動きが変わっていくようすなので、同じ動きの繰り返しには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36700, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動的", "is_correct": true, "explanation": "「静かな曲より、動的な曲」の動的で、動きの変化がある曲を表すので正解。"}, {"text": "健気", "is_correct": false, "explanation": "健気は人のひたむきさを表すので、曲の説明には合わない。"}, {"text": "無作法", "is_correct": false, "explanation": "無作法は人の振る舞いを指すので、曲の説明には合わない。"}, {"text": "不器用", "is_correct": false, "explanation": "不器用は人の手際を表すので、曲の説明には合わない。"}], "explanations": {"動的": "「静かな曲より、動的な曲」の動的で、動きの変化がある曲を表すので正解。", "健気": "健気は人のひたむきさを表すので、曲の説明には合わない。", "無作法": "無作法は人の振る舞いを指すので、曲の説明には合わない。", "不器用": "不器用は人の手際を表すので、曲の説明には合わない。"}, "sentence_index": 6, "correct_answer": "動的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この曲は動的で、どこも変わらない。", "explanation": "ここは〈単調〉の意味。同じ調子が続くのが単調で、動的は変化していくようすなので、どこも変わらない曲には合わない。"}, {"text": "この色は動的で、時間がたっても同じだ。", "explanation": "ここは〈不変〉の意味。時間がたっても変わらないのが不変で、動的は変化を表すので、色の変わらなさを説明する文には合わない。"}, {"text": "海は動的で、波がほとんどない。", "explanation": "ここは〈穏やか〉の意味。波が静かなようすは穏やかで、動的は動きが変わることを表すので、波のない海には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36700, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この選手の動的ダンスは、見る人を引き込む。", "corrected_sentence": "この選手の動的なダンスは、見る人を引き込む。", "error_description": "「動的ダンス」が誤り。正しくは「動的なダンス」。形容動詞が名詞を修飾するときは「な」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "動的だ", "is_correct": true, "explanation": "「動画は」の後で文を言い切る終止形で、正解。"}, {"text": "動的な", "is_correct": false, "explanation": "連体形で、後ろに名詞が続くときに使うので、文末の述語には合わない。"}, {"text": "動的に", "is_correct": false, "explanation": "連用形で、後ろに動詞が続く形なので、文を言い切る述語にはならない。"}, {"text": "動的で", "is_correct": false, "explanation": "て形で文を続ける形なので、文末に置いて言い切ることはできない。"}], "correct_form": "動的だ", "base_form": "動的だ", "form_label": "終止形", "sentence_index": 1, "explanations": {"動的だ": "「動画は」の後で文を言い切る終止形で、正解。", "動的な": "連体形で、後ろに名詞が続くときに使うので、文末の述語には合わない。", "動的に": "連用形で、後ろに動詞が続く形なので、文を言い切る述語にはならない。", "動的で": "て形で文を続ける形なので、文末に置いて言い切ることはできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36700, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あのロボットは歩き方を動的は変えて、坂道も上れる。", "corrected_sentence": "あのロボットは歩き方を動的に変えて、坂道も上れる。", "error_description": "「動的は変えて」が誤り。正しくは「動的に変えて」。動詞を修飾する形容動詞には「に」が必要で、「は」は話題を示すので合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "動的に", "is_correct": true, "explanation": "「歩いて」を修飾する連用形で、正解。"}, {"text": "動的ではない", "is_correct": false, "explanation": "否定の形で、動き方を変える文には合わない。"}, {"text": "動的だった", "is_correct": false, "explanation": "過去の形で、今の動作を述べる文には合わない。"}, {"text": "動的であった", "is_correct": false, "explanation": "過去の丁寧な断定で、動作を修飾する位置には入らない。"}], "correct_form": "動的に", "base_form": "動的だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"動的に": "「歩いて」を修飾する連用形で、正解。", "動的ではない": "否定の形で、動き方を変える文には合わない。", "動的だった": "過去の形で、今の動作を述べる文には合わない。", "動的であった": "過去の丁寧な断定で、動作を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36701, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静的", "is_correct": true, "explanation": "「動的」と反対の、変化しないようすを表す語なので対義語。"}, {"text": "複雑", "is_correct": false, "explanation": "複雑は入り組んでいるようすで、動的の反対語ではない。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速は速いようすで、変化の有無の対義にはならない。"}, {"text": "活発", "is_correct": false, "explanation": "活発は盛んに動くようすで、動的に近い意味なので対義語にはならない。"}], "correct_answer": "静的", "explanations": {"静的": "「動的」と反対の、変化しないようすを表す語なので対義語。", "複雑": "複雑は入り組んでいるようすで、動的の反対語ではない。", "迅速": "迅速は速いようすで、変化の有無の対義にはならない。", "活発": "活発は盛んに動くようすで、動的に近い意味なので対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36701, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静的", "is_correct": true, "explanation": "「動的」と反対の、変化しないようすを表す語なので対義語。"}, {"text": "正確", "is_correct": false, "explanation": "正確は誤りがないようすで、動的の反対語ではない。"}, {"text": "頑丈", "is_correct": false, "explanation": "頑丈は丈夫なようすで、変化の有無の対義にはならない。"}, {"text": "豊か", "is_correct": false, "explanation": "豊かは量や内容が十分なようすで、動的の対義語ではない。"}], "correct_answer": "静的", "explanations": {"静的": "「動的」と反対の、変化しないようすを表す語なので対義語。", "正確": "正確は誤りがないようすで、動的の反対語ではない。", "頑丈": "頑丈は丈夫なようすで、変化の有無の対義にはならない。", "豊か": "豊かは量や内容が十分なようすで、動的の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36701, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "時間とともに変化する、または状況に応じて変化するようす。", "primary_collocate": null, "pronunciation": "どうてき", "ipa": "doːteki", "syllable_count": 4, "sentences": [{"text": "川の流れは動的で、雨の日は形がどんどん変わる。", "target_word": "動的", "complexity_tier": "T3", "furigana": "川(かわ)の流(なが)れは動的(どうてき)で、雨(あめ)の日(ひ)は形(かたち)がどんどん変(か)わる。", "sentence_source": "generated"}, {"text": "このサイトは、利用者の操作に合わせて表示が動的に変わる。", "target_word": "動的", "complexity_tier": "T3", "furigana": "このサイトは、利用者(りようしゃ)の操作(そうさ)に合(あ)わせて表示(ひょうじ)が動的(どうてき)に変(か)わる。", "sentence_source": "generated"}, {"text": "数字だけの静的な表ではなく、動的な図で流れを示した。", "target_word": "動的", "complexity_tier": "T3", "furigana": "数字(すうじ)だけの静的(せいてき)な表(ひょう)ではなく、動的(どうてき)な図(ず)で流(なが)れを示(しめ)した。", "sentence_source": "generated"}, {"text": "市場は動的なものなので、一度立てた計画を状況に応じて見直す必要がある。", "target_word": "動的", "complexity_tier": "T4", "furigana": "市場(しじょう)は動的(どうてき)なものなので、一度(いちど)立(た)てた計画(けいかく)を状況(じょうきょう)に応(おう)じて見直(みなお)す必要(ひつよう)がある。", "sentence_source": "generated"}, {"text": "動的な価格設定では、需要が高い日ほど料金が上がる。", "target_word": "動的", "complexity_tier": "T4", "furigana": "動的(どうてき)な価格(かかく)設定(せってい)では、需要(じゅよう)が高(たか)い日(ひ)ほど料金(りょうきん)が上(あ)がる。", "sentence_source": "generated"}, {"text": "社会は常に動的に変化しているため、昨年の調査結果は今年は通用しない。", "target_word": "動的", "complexity_tier": "T4", "furigana": "社会(しゃかい)は常(つね)に動的(どうてき)に変化(へんか)しているため、昨年(さくねん)の調査(ちょうさ)結果(けっか)は今年(ことし)は通用(つうよう)しない。", "sentence_source": "generated"}, {"text": "この会社の組織は動的で、プロジェクトごとにチームが組み替えられる。", "target_word": "動的", "complexity_tier": "T4", "furigana": "この会社(かいしゃ)の組織(そしき)は動的(どうてき)で、プロジェクトごとにチームが組(く)み替(か)えられる。", "sentence_source": "generated"}, {"text": "生態系を動的にとらえると、種の数が増えたり減ったりする理由がわかる。", "target_word": "動的", "complexity_tier": "T4", "furigana": "生態系(せいたいけい)を動的(どうてき)にとらえると、種(しゅ)の数(かず)が増(ふ)えたり減(へ)ったりする理由(りゆう)がわかる。", "sentence_source": "generated"}, {"text": "地図は固定された画像ではなく、交通状況に応じて動的に更新される。", "target_word": "動的", "complexity_tier": "T4", "furigana": "地図(ちず)は固定(こてい)された画像(がぞう)ではなく、交通(こうつう)状況(じょうきょう)に応(おう)じて動的(どうてき)に更新(こうしん)される。", "sentence_source": "generated"}, {"text": "人の関係を静止した形で見ず、動的なものとして考えるべきだ。", "target_word": "動的", "complexity_tier": "T4", "furigana": "人(ひと)の関係(かんけい)を静止(せいし)した形(かたち)で見(み)ず、動的(どうてき)なものとして考(かんが)えるべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動的だ", "label": "終止形"}, {"form": "動的な", "label": "連体形"}, {"form": "動的に", "label": "連用形"}, {"form": "動的で", "label": "て形相当"}], "register": "neutral", "sense_fingerprint": "時間や状況に応じて変化していくさま（形容動詞的）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e0df04-93ce-41d8-b3b1-6e849a052392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36701, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動的", "is_correct": true, "explanation": "「川の流れは動的で」の動的で、時間とともに形が変わるようすを表すので正解。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は明るく快活なようすで、ヒエラルキーの性質を表す語としては合わない。"}, {"text": "不器用", "is_correct": false, "explanation": "不器用は手際の悪さを表し、組織の構造の説明には合わない。"}, {"text": "不機嫌", "is_correct": false, "explanation": "不機嫌は気分が悪いようすで、ヒエラルキーの説明には合わない。"}], "explanations": {"動的": "「川の流れは動的で」の動的で、時間とともに形が変わるようすを表すので正解。", "陽気": "陽気は明るく快活なようすで、ヒエラルキーの性質を表す語としては合わない。", "不器用": "不器用は手際の悪さを表し、組織の構造の説明には合わない。", "不機嫌": "不機嫌は気分が悪いようすで、ヒエラルキーの説明には合わない。"}, "sentence_index": 0, "correct_answer": "動的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この制度は動的で、何十年もずっと変わらない。", "explanation": "ここは〈固定的〉の意味。決まったまま変わらないようすは固定的で、動的は時間とともに変化する意味なので、変わらない制度の説明には使えない。"}, {"text": "子どもたちは校庭で動的に寝転んでいた。", "explanation": "ここは〈静止〉の意味。じっと横になっているようすは静止で、動的は動きの変化を表すので、寝転んでいる子どもの説明には合わない。"}, {"text": "同じ作業を動的に繰り返す。", "explanation": "ここは〈機械的〉の意味。考えずに同じ手順を続けるのが機械的で、動的は変化していくようすなので、同じことを変えずに繰り返す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36701, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動的", "is_correct": true, "explanation": "「組織は動的で」の動的で、組織が状況に応じて変わることを表すので正解。"}, {"text": "上機嫌", "is_correct": false, "explanation": "上機嫌は人の気分の良さを表し、組織の性質には合わない。"}, {"text": "生意気", "is_correct": false, "explanation": "生意気は人の態度を指し、組織の性質の説明には使えない。"}, {"text": "健気", "is_correct": false, "explanation": "健気は人のひたむきさを表すので、組織の性質には合わない。"}], "explanations": {"動的": "「組織は動的で」の動的で、組織が状況に応じて変わることを表すので正解。", "上機嫌": "上機嫌は人の気分の良さを表し、組織の性質には合わない。", "生意気": "生意気は人の態度を指し、組織の性質の説明には使えない。", "健気": "健気は人のひたむきさを表すので、組織の性質には合わない。"}, "sentence_index": 6, "correct_answer": "動的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この石碑は動的で、千年前から一度も位置を変えていない。", "explanation": "ここは〈不変〉の意味。変わらないことを表すのが不変で、動的は変化していくようすなので、位置が動かない石碑の説明には合わない。"}, {"text": "湖の水位は動的で、ほとんど変わらない。", "explanation": "ここは〈安定〉の意味。揺れずに保たれるのが安定で、動的は変化していくようすなので、水位がほとんど変わらない文には合わない。"}, {"text": "工場の機械は動的なまま、夜明けまで一度も動かなかった。", "explanation": "ここは〈停止〉の意味。動きが止まっているのが停止で、動的は動いている状態を表すので、止まった機械には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36701, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市場は動的ので、一度立てた計画を見直す必要がある。", "corrected_sentence": "市場は動的なので、一度立てた計画を見直す必要がある。", "error_description": "「動的ので」が誤り。正しくは「動的なので」。形容動詞は理由を表す「ので」の前に「な」を置く必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "動的に", "is_correct": true, "explanation": "「表示が変わる」の前で動詞を修飾する連用形で、正解。"}, {"text": "動的な", "is_correct": false, "explanation": "連体形で、後ろに名詞が続くときに使う形なので、動詞「変わる」を修飾する位置には合わない。"}, {"text": "動的だ", "is_correct": false, "explanation": "終止形で文を言い切る形なので、「表示が変わる」にかかる修飾の位置には入らない。"}, {"text": "動的で", "is_correct": false, "explanation": "て形は前後をつなぐ形で、動詞「変わる」を修飾できないので文が成り立たない。"}], "correct_form": "動的に", "base_form": "動的だ", "form_label": "連用形", "sentence_index": 1, "explanations": {"動的に": "「表示が変わる」の前で動詞を修飾する連用形で、正解。", "動的な": "連体形で、後ろに名詞が続くときに使う形なので、動詞「変わる」を修飾する位置には合わない。", "動的だ": "終止形で文を言い切る形なので、「表示が変わる」にかかる修飾の位置には入らない。", "動的で": "て形は前後をつなぐ形で、動詞「変わる」を修飾できないので文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36701, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "需要に合わせて、料金は動的が変わる。", "corrected_sentence": "需要に合わせて、料金は動的に変わる。", "error_description": "「動的が変わる」が誤り。正しくは「動的に変わる」。形容動詞を動詞の前で使うには「に」が必要で、「が」は主語を示すので合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "動的に", "is_correct": true, "explanation": "「生態系を動的にとらえる」の連用形で、とらえ方を修飾するので正解。"}, {"text": "動的ではない", "is_correct": false, "explanation": "否定の形で、とらえ方を説明する文には合わない。"}, {"text": "動的だった", "is_correct": false, "explanation": "過去の断定の形で、今の見方を述べる文には合わない。"}, {"text": "動的になる", "is_correct": false, "explanation": "変化を表す形で、「とらえる」を修飾する位置には入らない。"}], "correct_form": "動的に", "base_form": "動的だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"動的に": "「生態系を動的にとらえる」の連用形で、とらえ方を修飾するので正解。", "動的ではない": "否定の形で、とらえ方を説明する文には合わない。", "動的だった": "過去の断定の形で、今の見方を述べる文には合わない。", "動的になる": "変化を表す形で、「とらえる」を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9625eb19-f03b-4b10-958a-e7948458bf84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36702, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「とる」の目的語で、バランスに直接つく。"}, {"text": "に", "is_correct": false, "explanation": "「バランスにとる」では「とる」の目的語にならず、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「バランスがとる」では「とる」の目的語がなくなり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、「バランスへとる」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "正解。「とる」の目的語で、バランスに直接つく。", "に": "「バランスにとる」では「とる」の目的語にならず、不自然。", "が": "「バランスがとる」では「とる」の目的語がなくなり、文が成り立たない。", "へ": "方向を示す「へ」で、「バランスへとる」では意味が通らない。"}, "error_tags": {"に": "格の誤り", "が": "主語の格", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36702, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「とる」の目的語で、バランスに直接つく。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」で、「バランスととりながら」の形は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、「バランスよりとりながら」では意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」で、「バランスからとりながら」は不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「とる」の目的語で、バランスに直接つく。", "と": "並列の「と」で、「バランスととりながら」の形は成り立たない。", "より": "比較の「より」で、「バランスよりとりながら」では意味が通らない。", "から": "起点の「から」で、「バランスからとりながら」は不自然。"}, "error_tags": {"と": "並列", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36702, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "つりあいをとること。ものがかたよらないようにすること。", "primary_collocate": null, "pronunciation": "ばらんす", "ipa": "baɾaɴsɯ", "syllable_count": 4, "sentences": [{"text": "食事は、肉と野菜のバランスを考えて作る。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "食事[しょくじ]は、肉[にく]と野菜[やさい]のバランスを考[かんが]えて作[つく]る。", "sentence_source": "generated"}, {"text": "仕事と休みのバランスをとることが大切だ。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "仕事[しごと]と休[やす]みのバランスをとることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "自転車に初めて乗ったとき、バランスをとるのが難しかった。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]に初[はじ]めて乗[の]ったとき、バランスをとるのが難[むずか]しかった。", "sentence_source": "generated"}, {"text": "体がかたむいて、バランスをくずして転んでしまった。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "体[からだ]がかたむいて、バランスをくずして転[ころ]んでしまった。", "sentence_source": "generated"}, {"text": "色のバランスが悪くて、部屋が落ち着かない。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "色[いろ]のバランスが悪[わる]くて、部屋[へや]が落[お]ち着[つ]かない。", "sentence_source": "generated"}, {"text": "勉強と遊びのバランスがよい子は、毎日楽しそうだ。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "勉強[べんきょう]と遊[あそ]びのバランスがよい子[こ]は、毎日[まいにち]楽[たの]しそうだ。", "sentence_source": "generated"}, {"text": "本棚の右だけが重いと、バランスが悪くてたおれそうだ。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の右[みぎ]だけが重[おも]いと、バランスが悪[わる]くてたおれそうだ。", "sentence_source": "generated"}, {"text": "彼女は片足でバランスをとりながら、ゆっくり歩いた。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は片足[かたあし]でバランスをとりながら、ゆっくり歩[ある]いた。", "sentence_source": "generated"}, {"text": "おかずの量のバランスがよくて、見た目もきれいなお弁当だ。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "おかずの量[りょう]のバランスがよくて、見[み]た目[め]もきれいなお弁当[べんとう]だ。", "sentence_source": "generated"}, {"text": "左右のバランスを見ながら、棚に皿を並べた。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "左右[さゆう]のバランスを見[み]ながら、棚[たな]に皿[さら]を並[なら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バランス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "かたよらないようにつりあいをとること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: たおれ (Zipf 1.74)']::text[], '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36702, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バランス", "is_correct": true, "explanation": "正解。肉と野菜の釣り合いを考える文で、この語だけが入る。"}, {"text": "スピード", "is_correct": false, "explanation": "速さの意味で、食材の釣り合いを表す語ではないので合わない。"}, {"text": "テンポ", "is_correct": false, "explanation": "物事の進む調子を表し、食材の組み合わせには使わないので合わない。"}, {"text": "ゴール", "is_correct": false, "explanation": "目標地点の意味で、食材の配分の話には当てはまらない。"}], "explanations": {"バランス": "正解。肉と野菜の釣り合いを考える文で、この語だけが入る。", "スピード": "速さの意味で、食材の釣り合いを表す語ではないので合わない。", "テンポ": "物事の進む調子を表し、食材の組み合わせには使わないので合わない。", "ゴール": "目標地点の意味で、食材の配分の話には当てはまらない。"}, "sentence_index": 0, "correct_answer": "バランス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は昼に、バランスを食べた。", "explanation": "ここは〈食品〉の意味。食べるのは食品で、釣り合いの状態は食べられない。"}, {"text": "彼女は本番でバランスを発揮した。", "explanation": "ここは〈実力〉の意味。発揮するのは実力や能力で、釣り合いの状態は発揮できない。"}, {"text": "このくじに当たるバランスを計算した。", "explanation": "ここは〈確率〉の意味。当たる見込みはバランスではなく確率と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36702, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バランス", "is_correct": true, "explanation": "正解。重さの偏りを表す文で、釣り合いの状態を指す語になる。"}, {"text": "ペース", "is_correct": false, "explanation": "速さや進み具合の意味で、重さの偏りには使わないので合わない。"}, {"text": "リズム", "is_correct": false, "explanation": "拍の規則性を表す語で、本棚の重さの話には当てはまらない。"}, {"text": "ボリューム", "is_correct": false, "explanation": "量や音量の意味で、重さの偏りを言う文には合わない。"}], "explanations": {"バランス": "正解。重さの偏りを表す文で、釣り合いの状態を指す語になる。", "ペース": "速さや進み具合の意味で、重さの偏りには使わないので合わない。", "リズム": "拍の規則性を表す語で、本棚の重さの話には当てはまらない。", "ボリューム": "量や音量の意味で、重さの偏りを言う文には合わない。"}, "sentence_index": 6, "correct_answer": "バランス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テストのバランスが上がった。", "explanation": "ここは〈成績〉の意味。釣り合いの状態は上がるものではないので、この言い方は使わない。"}, {"text": "テレビのバランスを休んだ。", "explanation": "ここは〈休止〉の意味。休むのは人や番組で、釣り合いの状態は休めない。"}, {"text": "列車のバランスが三分遅れた。", "explanation": "ここは〈時刻〉の意味。遅れるのは列車や時間で、釣り合いの状態は遅れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36702, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "綱の上で、体のバランスを立てながら進んだ。", "corrected_sentence": "綱の上で、体のバランスをとりながら進んだ。", "error_description": "「バランスをとる」が正しい。「立てる」はバランスとは合わない動詞で、釣り合いを保つ動作と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36702, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仕事と家庭のバランスが崩すと、体調を悪くしやすい。", "corrected_sentence": "仕事と家庭のバランスが崩れると、体調を悪くしやすい。", "error_description": "「崩す」は他動詞で、バランスが主語の文では自動詞の「崩れる」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36703, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「保つ」の目的語で、バランスに直接つく。"}, {"text": "に", "is_correct": false, "explanation": "「バランスに保つ」では「保つ」の目的語にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、「バランスへ保つ」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、「バランスより保っている」とは言わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「保つ」の目的語で、バランスに直接つく。", "に": "「バランスに保つ」では「保つ」の目的語にならず、不自然。", "へ": "方向を示す「へ」で、「バランスへ保つ」は意味が通らない。", "より": "比較の「より」で、「バランスより保っている」とは言わない。"}, "error_tags": {"に": "格の誤り", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36703, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。手段や根拠を示す「で」で、バランスによって値段が決まる、という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」で、「バランスを野菜の値段が決まる」とは続かない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」で、「バランスの野菜の値段が決まる」と文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」で、主語が二つ重なり不自然になる。"}], "correct_answer": "で", "explanations": {"で": "正解。手段や根拠を示す「で」で、バランスによって値段が決まる、という意味になる。", "を": "目的語の「を」で、「バランスを野菜の値段が決まる」とは続かない。", "の": "連体の「の」で、「バランスの野菜の値段が決まる」と文が成り立たない。", "が": "主語の「が」で、主語が二つ重なり不自然になる。"}, "error_tags": {"を": "目的語", "の": "連体", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36703, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の要素や力が、互いに打ち消し合ったり釣り合ったりして、安定した状態にあること。また、その状態。", "primary_collocate": null, "pronunciation": "ばらんす", "ipa": "baɾaɴsɯ", "syllable_count": 4, "sentences": [{"text": "生態系では、動物と植物のバランスが保たれている。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "生態系[せいたいけい]では、動物[どうぶつ]と植物[しょくぶつ]のバランスが保[たも]たれている。", "sentence_source": "generated"}, {"text": "二つの力が打ち消し合い、橋はバランスを保っている。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "二[ふた]つの力[ちから]が打[う]ち消[け]し合[あ]い、橋[はし]はバランスを保[たも]っている。", "sentence_source": "generated"}, {"text": "輸出と輸入のバランスがくずれると、経済に影響が出る。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "輸出[ゆしゅつ]と輸入[ゆにゅう]のバランスがくずれると、経済[けいざい]に影響[えいきょう]が出[で]る。", "sentence_source": "generated"}, {"text": "チームは攻撃と守りのバランスがよく、安定して勝っている。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "チームは攻撃[こうげき]と守[まも]りのバランスがよく、安定[あんてい]して勝[か]っている。", "sentence_source": "generated"}, {"text": "ホルモンのバランスが乱れると、体調をくずしやすい。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "ホルモンのバランスが乱[みだ]れると、体調[たいちょう]をくずしやすい。", "sentence_source": "generated"}, {"text": "税金と福祉のバランスをどうするかが、国会の議題だ。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "税金[ぜいきん]と福祉[ふくし]のバランスをどうするかが、国会[こっかい]の議題[ぎだい]だ。", "sentence_source": "generated"}, {"text": "天秤は、左右の重さのバランスが保たれて、真ん中で止まった。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "天秤[てんびん]は、左右[さゆう]の重[おも]さのバランスが保[たも]たれて、真[ま]ん中[なか]で止[と]まった。", "sentence_source": "generated"}, {"text": "需要と供給のバランスで、野菜の値段が決まる。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "需要[じゅよう]と供給[きょうきゅう]のバランスで、野菜[やさい]の値段[ねだん]が決[き]まる。", "sentence_source": "generated"}, {"text": "船は重い荷物を中央に積み、全体のバランスを整えた。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "船[ふね]は重[おも]い荷物[にもつ]を中央[ちゅうおう]に積[つ]み、全体[ぜんたい]のバランスを整[ととの]えた。", "sentence_source": "generated"}, {"text": "力のバランスがとれているからこそ、この建物は地震でもたおれない。", "target_word": "バランス", "complexity_tier": "T3", "furigana": "力[ちから]のバランスがとれているからこそ、この建物[たてもの]は地震[じしん]でもたおれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バランス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "複数の要素や力が釣り合って安定している状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: くずれる (Zipf 2.13)','sentence 9 above tier T2: contains vocabulary far above tier T2: たおれ (Zipf 1.74)']::text[], '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36703, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バランス", "is_correct": true, "explanation": "正解。二つの要素の安定した釣り合いを表し、ここに入る。"}, {"text": "スピード", "is_correct": false, "explanation": "速さの意味で、生き物どうしの関係を指す語ではないので合わない。"}, {"text": "テンポ", "is_correct": false, "explanation": "物事の進む調子を表し、生態系の釣り合いには使わない。"}, {"text": "ゴール", "is_correct": false, "explanation": "目標地点の意味で、生態系の状態には合わない。"}], "explanations": {"バランス": "正解。二つの要素の安定した釣り合いを表し、ここに入る。", "スピード": "速さの意味で、生き物どうしの関係を指す語ではないので合わない。", "テンポ": "物事の進む調子を表し、生態系の釣り合いには使わない。", "ゴール": "目標地点の意味で、生態系の状態には合わない。"}, "sentence_index": 0, "correct_answer": "バランス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "チームはバランスが高く、安定して勝っている。", "explanation": "ここは〈勝率〉の意味。釣り合いの状態は高い低いで比べる量ではないので、高いとは言わない。"}, {"text": "今日の試合はバランスを重ね、最後まで落ち着いていた。", "explanation": "ここは〈得点〉の意味。点を重ねるのは得点で、釣り合いの状態は重ねられない。"}, {"text": "夜になってバランスが下がった。", "explanation": "ここは〈気温〉の意味。気温のように数値で下がる量ではないので、下がるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36703, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バランス", "is_correct": true, "explanation": "正解。左右の釣り合いを表し、保たれる対象になる。"}, {"text": "グラフ", "is_correct": false, "explanation": "図や表の意味で、重さの釣り合いの状態には使わないので合わない。"}, {"text": "カーブ", "is_correct": false, "explanation": "曲がり具合を表す語で、重さの釣り合いには当てはまらない。"}, {"text": "リズム", "is_correct": false, "explanation": "拍の規則性を表す語で、重さの釣り合いの状態には合わない。"}], "explanations": {"バランス": "正解。左右の釣り合いを表し、保たれる対象になる。", "グラフ": "図や表の意味で、重さの釣り合いの状態には使わないので合わない。", "カーブ": "曲がり具合を表す語で、重さの釣り合いには当てはまらない。", "リズム": "拍の規則性を表す語で、重さの釣り合いの状態には合わない。"}, "sentence_index": 6, "correct_answer": "バランス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝からバランスが上がった。", "explanation": "ここは〈体温〉の意味。釣り合いの状態は温度のように上がるものではない。"}, {"text": "通帳を見て、バランスを引き出した。", "explanation": "ここは〈預金〉の意味。引き出すのは預金や現金で、釣り合いの状態は引き出せない。"}, {"text": "選手は厳しいバランスに耐えて、大会で勝った。", "explanation": "ここは〈試練〉の意味。耐えるのは試練や苦痛で、釣り合いの状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36703, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ホルモンのバランスを乱れると、体調が悪くなる。", "corrected_sentence": "ホルモンのバランスが乱れると、体調が悪くなる。", "error_description": "「乱れる」は自動詞なので、主語のバランスには「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36703, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "重い荷物の左右のバランスが保って、船は真ん中で止まった。", "corrected_sentence": "重い荷物の左右のバランスが保たれて、船は真ん中で止まった。", "error_description": "「保つ」は他動詞なので、バランスが主語のときは受け身の「保たれる」を使う。「保って」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
