INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36704, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "二つのものが、とても近い関係にあること。", "primary_collocate": null, "pronunciation": "みっせつ", "ipa": "misseʦɯ", "syllable_count": 4, "sentences": [{"text": "親と子の関係は、とても密接だ。", "target_word": "密接", "complexity_tier": "T3", "furigana": "親[おや]と子[こ]の関係[かんけい]は、とても密接[みっせつ]だ。", "sentence_source": "generated"}, {"text": "食生活と健康は密接に関係している。", "target_word": "密接", "complexity_tier": "T3", "furigana": "食生活[しょくせいかつ]と健康[けんこう]は密接[みっせつ]に関係[かんけい]している。", "sentence_source": "generated"}, {"text": "この二つの会社は、長年密接な関係を保っている。", "target_word": "密接", "complexity_tier": "T3", "furigana": "この二[ふた]つの会社[かいしゃ]は、長年[ながねん]密接[みっせつ]な関係[かんけい]を保[たも]っている。", "sentence_source": "generated"}, {"text": "言葉と文化は密接に結びついている。", "target_word": "密接", "complexity_tier": "T3", "furigana": "言葉[ことば]と文化[ぶんか]は密接[みっせつ]に結[むす]びついている。", "sentence_source": "generated"}, {"text": "警察は地元の住民と密接に連絡を取っている。", "target_word": "密接", "complexity_tier": "T3", "furigana": "警察[けいさつ]は地元[じもと]の住民[じゅうみん]と密接[みっせつ]に連絡[れんらく]を取[と]っている。", "sentence_source": "generated"}, {"text": "天気と農業の収穫量は密接な関係がある。", "target_word": "密接", "complexity_tier": "T3", "furigana": "天気[てんき]と農業[のうぎょう]の収穫量[しゅうかくりょう]は密接[みっせつ]な関係[かんけい]がある。", "sentence_source": "generated"}, {"text": "二つの町は、川を挟んで昔から密接な関係にあった。", "target_word": "密接", "complexity_tier": "T3", "furigana": "二[ふた]つの町[まち]は、川[かわ]を挟[はさ]んで昔[むかし]から密接[みっせつ]な関係[かんけい]にあった。", "sentence_source": "generated"}, {"text": "彼は先生と密接に連携しながら、研究を進めた。", "target_word": "密接", "complexity_tier": "T3", "furigana": "彼[かれ]は先生[せんせい]と密接[みっせつ]に連携[れんけい]しながら、研究[けんきゅう]を進[すす]めた。", "sentence_source": "generated"}, {"text": "歯の健康は全身の状態と密接につながっている。", "target_word": "密接", "complexity_tier": "T3", "furigana": "歯[は]の健康[けんこう]は全身[ぜんしん]の状態[じょうたい]と密接[みっせつ]につながっている。", "sentence_source": "generated"}, {"text": "両国は経済面で密接な協力を続けている。", "target_word": "密接", "complexity_tier": "T3", "furigana": "両国[りょうこく]は経済面[けいざいめん]で密接[みっせつ]な協力[きょうりょく]を続[つづ]けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "密接だ", "label": "断定形"}, {"form": "密接な", "label": "連体形"}, {"form": "密接に", "label": "連用形"}, {"form": "密接で", "label": "で形"}], "register": "neutral-written", "sense_fingerprint": "二つのものの関係や距離がとても近いさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36704, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密接", "is_correct": true, "explanation": "「密接」は二つのものの関係がとても近いことを表し、親と子の関係を説明するのに合う。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈」は話や時間がつまらないことを表すので、親子の関係の近さを言う文には合わない。"}, {"text": "豊富", "is_correct": false, "explanation": "「豊富」は量や種類が多いことを表すので、関係の性質を述べるこの文には合わない。"}, {"text": "盛大", "is_correct": false, "explanation": "「盛大」は行事などが大きく立派なことを表すので、親子の関係には使えない。"}], "explanations": {"密接": "「密接」は二つのものの関係がとても近いことを表し、親と子の関係を説明するのに合う。", "退屈": "「退屈」は話や時間がつまらないことを表すので、親子の関係の近さを言う文には合わない。", "豊富": "「豊富」は量や種類が多いことを表すので、関係の性質を述べるこの文には合わない。", "盛大": "「盛大」は行事などが大きく立派なことを表すので、親子の関係には使えない。"}, "sentence_index": 0, "correct_answer": "密接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前には店が密接に並び、いつもにぎやかだ。", "explanation": "ここは〈密集〉の意味。密接は関係の近さを表すので、店が集まって並ぶ様子には使わない。"}, {"text": "フィルムを台紙に密接に貼り付けた。", "explanation": "ここは〈密着〉の意味。密接は関係の近さを表すので、ものを隙間なく貼り付ける動作には合わない。"}, {"text": "ふたを密接に閉めて、空気が入らないようにした。", "explanation": "ここは〈密閉〉の意味。密接は関係の近さを表すので、容器を閉じて空気を遮る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36704, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密接", "is_correct": true, "explanation": "「密接な関係」は二つの町のつながりが強かったことを表し、この文に合う。"}, {"text": "斬新", "is_correct": false, "explanation": "「斬新」は考えや作品が新しいという意味で、町どうしの関係の説明には合わない。"}, {"text": "豪華", "is_correct": false, "explanation": "「豪華」は派手で物が多いことを表すので、町どうしの関係の近さを言う文には合わない。"}, {"text": "豪快", "is_correct": false, "explanation": "「豪快」は行動が大胆で勢いがあることを表すので、町どうしの関係には合わない。"}], "explanations": {"密接": "「密接な関係」は二つの町のつながりが強かったことを表し、この文に合う。", "斬新": "「斬新」は考えや作品が新しいという意味で、町どうしの関係の説明には合わない。", "豪華": "「豪華」は派手で物が多いことを表すので、町どうしの関係の近さを言う文には合わない。", "豪快": "「豪快」は行動が大胆で勢いがあることを表すので、町どうしの関係には合わない。"}, "sentence_index": 6, "correct_answer": "密接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週はスケジュールが密接で、休む日がない。", "explanation": "ここは〈過密〉の意味。密接は関係の近さを表すので、予定が詰まっている様子には使えない。"}, {"text": "その旅行は、計画を密接に立てて準備した。", "explanation": "ここは〈綿密〉の意味。密接は関係の近さを表すので、計画の細かさを言う場面には合わない。"}, {"text": "実験では、条件を密接に決めて記録した。", "explanation": "ここは〈厳密〉の意味。密接は関係の近さを表すので、条件を一つずつ正確に定める場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36704, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この二つの国は、昔から密接だ関係を保っている。", "corrected_sentence": "この二つの国は、昔から密接な関係を保っている。", "error_description": "「密接だ」は断定形で、名詞「関係」を修飾できない。正しくは連体形の「密接な」で、「密接な関係」と続ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "密接に", "is_correct": true, "explanation": "「関係している」を修飾する連用形。動詞の前に置いて、どのように関係しているかを表す。"}, {"text": "密接だ", "is_correct": false, "explanation": "断定形は文を言い切る形。ここでは後ろに動詞「関係している」が続くので使えない。"}, {"text": "密接な", "is_correct": false, "explanation": "連体形は後ろに名詞が続く形。「密接な関係」とすると「している」が続かず、文が成り立たない。"}, {"text": "密接の", "is_correct": false, "explanation": "「密接の」は連体の形として成り立たず、「関係している」の前で修飾する形にもならない。"}], "correct_form": "密接に", "base_form": "密接", "form_label": "連用形", "sentence_index": 1, "explanations": {"密接に": "「関係している」を修飾する連用形。動詞の前に置いて、どのように関係しているかを表す。", "密接だ": "断定形は文を言い切る形。ここでは後ろに動詞「関係している」が続くので使えない。", "密接な": "連体形は後ろに名詞が続く形。「密接な関係」とすると「している」が続かず、文が成り立たない。", "密接の": "「密接の」は連体の形として成り立たず、「関係している」の前で修飾する形にもならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36704, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "両国は経済面で密接と協力を続けている。", "corrected_sentence": "両国は経済面で密接に協力を続けている。", "error_description": "「密接」は「協力を続けている」を修飾する連用形で、後ろに「に」をつける。「と」は誤りで、「密接に」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "密接に", "is_correct": true, "explanation": "「連携しながら」を修飾する連用形。動詞の前に置いて、どのように連携したかを表す。"}, {"text": "密接だった", "is_correct": false, "explanation": "過去の断定形で、動詞を修飾する位置には使えず、「連携しながら」の前では文の流れが続かない。"}, {"text": "密接ではない", "is_correct": false, "explanation": "否定の形で、「連携しながら」を修飾する位置には使えず、文の途中で意味が成り立たない。"}, {"text": "密接です", "is_correct": false, "explanation": "丁寧な断定の形で、文末で言い切る形なので、「連携しながら」の前には置けない。"}], "correct_form": "密接に", "base_form": "密接", "form_label": "連用形", "sentence_index": 7, "explanations": {"密接に": "「連携しながら」を修飾する連用形。動詞の前に置いて、どのように連携したかを表す。", "密接だった": "過去の断定形で、動詞を修飾する位置には使えず、「連携しながら」の前では文の流れが続かない。", "密接ではない": "否定の形で、「連携しながら」を修飾する位置には使えず、文の途中で意味が成り立たない。", "密接です": "丁寧な断定の形で、文末で言い切る形なので、「連携しながら」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
