INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36705, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の間に関係が非常に近く、結びつきが強いこと。", "primary_collocate": null, "pronunciation": "みっせつ", "ipa": "misseʦɯ", "syllable_count": 4, "sentences": [{"text": "地域の祭りは、人々の暮らしと密接に結びついている。", "target_word": "密接", "complexity_tier": "T3", "furigana": "地域[ちいき]の祭[まつ]りは、人々[ひとびと]の暮[く]らしと密接[みっせつ]に結[むす]びついている。", "sentence_source": "generated"}, {"text": "睡眠の質は、毎日の気分と密接な関係がある。", "target_word": "密接", "complexity_tier": "T3", "furigana": "睡眠[すいみん]の質[しつ]は、毎日[まいにち]の気分[きぶん]と密接[みっせつ]な関係[かんけい]がある。", "sentence_source": "generated"}, {"text": "物価の上昇は、為替の動きと密接に関わっている。", "target_word": "密接", "complexity_tier": "T3", "furigana": "物価[ぶっか]の上昇[じょうしょう]は、為替[かわせ]の動[うご]きと密接[みっせつ]に関[かか]わっている。", "sentence_source": "generated"}, {"text": "彼は地元の商店街と密接なつながりを持っている。", "target_word": "密接", "complexity_tier": "T3", "furigana": "彼[かれ]は地元[じもと]の商店街[しょうてんがい]と密接[みっせつ]なつながりを持[も]っている。", "sentence_source": "generated"}, {"text": "環境問題と私たちの生活は密接に関係している。", "target_word": "密接", "complexity_tier": "T3", "furigana": "環境問題[かんきょうもんだい]と私[わたし]たちの生活[せいかつ]は密接[みっせつ]に関係[かんけい]している。", "sentence_source": "generated"}, {"text": "この病気は、生活習慣と密接な関係があるとされる。", "target_word": "密接", "complexity_tier": "T3", "furigana": "この病気[びょうき]は、生活習慣[せいかつしゅうかん]と密接[みっせつ]な関係[かんけい]があるとされる。", "sentence_source": "generated"}, {"text": "町の歴史と名物の料理は、密接に結びついている。", "target_word": "密接", "complexity_tier": "T3", "furigana": "町[まち]の歴史[れきし]と名物[めいぶつ]の料理[りょうり]は、密接[みっせつ]に結[むす]びついている。", "sentence_source": "generated"}, {"text": "研究チームと現場の医者が密接に協力して、新しい治療法を作った。", "target_word": "密接", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームと現場[げんば]の医者[いしゃ]が密接[みっせつ]に協力[きょうりょく]して、新[あたら]しい治療法[ちりょうほう]を作[つく]った。", "sentence_source": "generated"}, {"text": "二つの出来事は密接につながっているので、一緒に考えるべきだ。", "target_word": "密接", "complexity_tier": "T3", "furigana": "二[ふた]つの出来事[できごと]は密接[みっせつ]につながっているので、一緒[いっしょ]に考[かんが]えるべきだ。", "sentence_source": "generated"}, {"text": "学校と家庭が密接に連絡を取ると、子どもは安心する。", "target_word": "密接", "complexity_tier": "T3", "furigana": "学校[がっこう]と家庭[かてい]が密接[みっせつ]に連絡[れんらく]を取[と]ると、子[こ]どもは安心[あんしん]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "密接だ", "label": "断定形"}, {"form": "密接な", "label": "連体形"}, {"form": "密接に", "label": "連用形"}, {"form": "密接で", "label": "で形"}], "register": "neutral-written", "sense_fingerprint": "物事どうしの結びつきが非常に強いさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36705, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "密接", "is_correct": true, "explanation": "「密接に結びつく」は祭りと暮らしのつながりが強いことを表し、この文に合う。"}, {"text": "豊富", "is_correct": false, "explanation": "「豊富に結びつく」とは言えず、「豊富」は量が多い意味でつながりの強さを表さない。"}, {"text": "盛大", "is_correct": false, "explanation": "「盛大に結びつく」は不自然で、「盛大」は行事の規模が大きいことを表すので合わない。"}, {"text": "斬新", "is_correct": false, "explanation": "「斬新に結びつく」は言えず、「斬新」は新しい考えや形を表すので合わない。"}], "explanations": {"密接": "「密接に結びつく」は祭りと暮らしのつながりが強いことを表し、この文に合う。", "豊富": "「豊富に結びつく」とは言えず、「豊富」は量が多い意味でつながりの強さを表さない。", "盛大": "「盛大に結びつく」は不自然で、「盛大」は行事の規模が大きいことを表すので合わない。", "斬新": "「斬新に結びつく」は言えず、「斬新」は新しい考えや形を表すので合わない。"}, "sentence_index": 0, "correct_answer": "密接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商店街は、店が密接に並んでいて人通りが多い。", "explanation": "ここは〈密集〉の意味。密接は関係の近さを表すので、店が集まって並ぶ様子には使わない。"}, {"text": "この接着剤は、二枚の板を密接にくっつける。", "explanation": "ここは〈密着〉の意味。密接は関係の近さを表すので、板を隙間なく貼り合わせる働きには合わない。"}, {"text": "ドアを密接に閉じて、部屋の空気を逃がさないようにした。", "explanation": "ここは〈密閉〉の意味。密接は関係の近さを表すので、扉を閉じて空気を遮る場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36705, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密接", "is_correct": true, "explanation": "「密接に結びつく」は歴史と料理のつながりが強いことを表し、この文に合う。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈に結びつく」は不自然で、「退屈」は話や時間がつまらないことを表すので合わない。"}, {"text": "豪快", "is_correct": false, "explanation": "「豪快に結びつく」は言えず、「豪快」は行動が大胆なことを表すので合わない。"}, {"text": "淡白", "is_correct": false, "explanation": "「淡白に結びつく」は不自然で、「淡白」は味や性格があっさりしていることを表すので合わない。"}], "explanations": {"密接": "「密接に結びつく」は歴史と料理のつながりが強いことを表し、この文に合う。", "退屈": "「退屈に結びつく」は不自然で、「退屈」は話や時間がつまらないことを表すので合わない。", "豪快": "「豪快に結びつく」は言えず、「豪快」は行動が大胆なことを表すので合わない。", "淡白": "「淡白に結びつく」は不自然で、「淡白」は味や性格があっさりしていることを表すので合わない。"}, "sentence_index": 6, "correct_answer": "密接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みは予定が密接に詰まっていて、休む間がない。", "explanation": "ここは〈過密〉の意味。密接は関係の近さを表すので、予定が詰まっている様子には使えない。"}, {"text": "旅行の日程を、密接に決めた。", "explanation": "ここは〈綿密〉の意味。密接は関係の近さを表すので、日程を細かく定める場面には合わない。"}, {"text": "条件を、密接に定めて記録した。", "explanation": "ここは〈厳密〉の意味。密接は関係の近さを表すので、条件を正確に定める場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36705, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "運動と健康は、密接と関係がある。", "corrected_sentence": "運動と健康は、密接に関係がある。", "error_description": "「密接」は「関係がある」を修飾する連用形で、後ろに「に」をつける。「と」は誤りで、「密接に」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "密接な", "is_correct": true, "explanation": "「関係がある」の前に置いて名詞「関係」を修飾する連体形。「毎日の気分と密接な関係」という名詞句になる。"}, {"text": "密接だ", "is_correct": false, "explanation": "断定形は文を言い切る形で、名詞「関係」の前には置けない。"}, {"text": "密接さ", "is_correct": false, "explanation": "「密接さ」は名詞の形で、名詞「関係」の前に続けると「密接さ関係」となり文が成り立たない。"}, {"text": "密接の", "is_correct": false, "explanation": "「密接の」は連体の形として成り立たず、名詞「関係」を修飾できない。"}], "correct_form": "密接な", "base_form": "密接", "form_label": "連体形", "sentence_index": 1, "explanations": {"密接な": "「関係がある」の前に置いて名詞「関係」を修飾する連体形。「毎日の気分と密接な関係」という名詞句になる。", "密接だ": "断定形は文を言い切る形で、名詞「関係」の前には置けない。", "密接さ": "「密接さ」は名詞の形で、名詞「関係」の前に続けると「密接さ関係」となり文が成り立たない。", "密接の": "「密接の」は連体の形として成り立たず、名詞「関係」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36705, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父と母は、子育てで密接だ協力を続けてきた。", "corrected_sentence": "父と母は、子育てで密接な協力を続けてきた。", "error_description": "「密接」は名詞「協力」を修飾するので連体形の「密接な」が必要。「密接だ」は断定形で、名詞の前では使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "密接に", "is_correct": true, "explanation": "「協力して」を修飾する連用形。動詞の前で、どのように協力したかを表す。"}, {"text": "密接である", "is_correct": false, "explanation": "「である」は文を言い切る形で、「協力して」の前に置くと文の流れが切れ、動詞を修飾できない。"}, {"text": "密接だった", "is_correct": false, "explanation": "過去の断定形で文を言い切るため、「協力して」へつながらず、動詞「協力する」を修飾できない。"}, {"text": "密接ではない", "is_correct": false, "explanation": "否定の形で文を終えてしまうため、「協力して」へ続けて動作の様子を表すことができない。"}], "correct_form": "密接に", "base_form": "密接", "form_label": "連用形", "sentence_index": 7, "explanations": {"密接に": "「協力して」を修飾する連用形。動詞の前で、どのように協力したかを表す。", "密接である": "「である」は文を言い切る形で、「協力して」の前に置くと文の流れが切れ、動詞を修飾できない。", "密接だった": "過去の断定形で文を言い切るため、「協力して」へつながらず、動詞「協力する」を修飾できない。", "密接ではない": "否定の形で文を終えてしまうため、「協力して」へ続けて動作の様子を表すことができない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36706, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関係", "is_correct": true, "explanation": "つながりがないという意味で、「関連」の反対語。"}, {"text": "独立", "is_correct": false, "explanation": "独立は他に頼らず立つことなので、つながりの反対語とは言えない。"}, {"text": "製造", "is_correct": false, "explanation": "製造は物を作ることなので、関係の有無とは関係がない。"}, {"text": "集中", "is_correct": false, "explanation": "集中は一点に注意を向けることなので、つながりの反対にはならない。"}], "correct_answer": "無関係", "explanations": {"無関係": "つながりがないという意味で、「関連」の反対語。", "独立": "独立は他に頼らず立つことなので、つながりの反対語とは言えない。", "製造": "製造は物を作ることなので、関係の有無とは関係がない。", "集中": "集中は一点に注意を向けることなので、つながりの反対にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36706, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「関連がなく」の「が」。関連が存在しないことを表す主語。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「関連をなく」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「関連のなく」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「関連へなく」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「関連がなく」の「が」。関連が存在しないことを表す主語。", "を": "「を」は目的語を示す。「関連をなく」では文が成り立たない。", "の": "連体修飾の「の」。「関連のなく」は不自然。", "へ": "方向を表す「へ」。「関連へなく」は意味が通らない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関係", "is_correct": true, "explanation": "関わりがないという意味で、「関連」の反対語。"}, {"text": "販売", "is_correct": false, "explanation": "販売は商品を売ることなので、つながりの反対語ではない。"}, {"text": "分析", "is_correct": false, "explanation": "分析は細かく調べることなので、関係の反対とは言えない。"}, {"text": "記録", "is_correct": false, "explanation": "記録は残すことなので、関わりの有無とは関係がない。"}], "correct_answer": "無関係", "explanations": {"無関係": "関わりがないという意味で、「関連」の反対語。", "販売": "販売は商品を売ることなので、つながりの反対語ではない。", "分析": "分析は細かく調べることなので、関係の反対とは言えない。", "記録": "記録は残すことなので、関わりの有無とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36706, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものと、他のものがつながっていること。", "primary_collocate": null, "pronunciation": "かんれん", "ipa": "kaɴɾeɴ", "syllable_count": 4, "sentences": [{"text": "この二つの事件は関連があると、警察は考えています。", "target_word": "関連", "complexity_tier": "T3", "furigana": "この二[ふた]つの事件[じけん]は関連[かんれん]があると、警察[けいさつ]は考[かんが]えています。", "sentence_source": "generated"}, {"text": "本のテーマに関連して、作者の生い立ちも紹介されています。", "target_word": "関連", "complexity_tier": "T3", "furigana": "本[ほん]のテーマに関連[かんれん]して、作者[さくしゃ]の生[お]い立[た]ちも紹介[しょうかい]されています。", "sentence_source": "generated"}, {"text": "健康に関連する記事を、毎日読んでいます。", "target_word": "関連", "complexity_tier": "T3", "furigana": "健康[けんこう]に関連[かんれん]する記事[きじ]を、毎日[まいにち]読[よ]んでいます。", "sentence_source": "generated"}, {"text": "睡眠と食事は深く関連しています。", "target_word": "関連", "complexity_tier": "T3", "furigana": "睡眠[すいみん]と食事[しょくじ]は深[ふか]く関連[かんれん]しています。", "sentence_source": "generated"}, {"text": "関連する資料は、すべて机の上に置いてあります。", "target_word": "関連", "complexity_tier": "T3", "furigana": "関連[かんれん]する資料[しりょう]は、すべて机[つくえ]の上[うえ]に置[お]いてあります。", "sentence_source": "generated"}, {"text": "この仕事に関連した本を、図書館で借りました。", "target_word": "関連", "complexity_tier": "T3", "furigana": "この仕事[しごと]に関連[かんれん]した本[ほん]を、図書館[としょかん]で借[か]りました。", "sentence_source": "generated"}, {"text": "天気と野菜の値段には関連があるそうです。", "target_word": "関連", "complexity_tier": "T3", "furigana": "天気[てんき]と野菜[やさい]の値段[ねだん]には関連[かんれん]があるそうです。", "sentence_source": "generated"}, {"text": "二つの話に関連がなく、何を言いたいのかわかりませんでした。", "target_word": "関連", "complexity_tier": "T3", "furigana": "二[ふた]つの話[はなし]に関連[かんれん]がなく、何[なに]を言[い]いたいのかわかりませんでした。", "sentence_source": "generated"}, {"text": "地震に関連したニュースが、朝から続いています。", "target_word": "関連", "complexity_tier": "T3", "furigana": "地震[じしん]に関連[かんれん]したニュースが、朝[あさ]から続[つづ]いています。", "sentence_source": "generated"}, {"text": "関連のある言葉をまとめて、ノートに書きました。", "target_word": "関連", "complexity_tier": "T3", "furigana": "関連[かんれん]のある言葉[ことば]をまとめて、ノートに書[か]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "関連", "label": "基本形"}, {"form": "関連する", "label": "サ変動詞の終止形"}, {"form": "関連した", "label": "過去形"}, {"form": "関連して", "label": "て形"}], "register": "丁寧", "sense_fingerprint": "ある物事が別の物事とつながりを持っていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36706, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "関連", "is_correct": true, "explanation": "「この二つの事件は」に続けて、つながりを表す「関連」が入るので正解。"}, {"text": "拒否", "is_correct": false, "explanation": "拒否は受け入れないことなので、事件同士のつながりを表す意味にはならない。"}, {"text": "合計", "is_correct": false, "explanation": "合計は数を足すことなので、事件の関係を示す言葉としては不自然。"}, {"text": "水分", "is_correct": false, "explanation": "水分は液体の成分なので、事件のつながりとは合わない。"}], "explanations": {"関連": "「この二つの事件は」に続けて、つながりを表す「関連」が入るので正解。", "拒否": "拒否は受け入れないことなので、事件同士のつながりを表す意味にはならない。", "合計": "合計は数を足すことなので、事件の関係を示す言葉としては不自然。", "水分": "水分は液体の成分なので、事件のつながりとは合わない。"}, "sentence_index": 0, "correct_answer": "関連"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は学生時代からの大切な関連です。", "explanation": "ここは〈友人〉の意味。関連は物事同士のつながりを指すので、人には使わない。"}, {"text": "役所で住民票の関連を済ませました。", "explanation": "ここは〈手続き〉の意味。関連は物事のつながりを指すので、書類の手続きには使わない。"}, {"text": "先輩に関連を取りました。", "explanation": "ここは〈連絡〉の意味。関連は物事のつながりを指すので、人と連絡を取る意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36706, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "関連", "is_correct": true, "explanation": "「〜には関連がある」の形で、つながりを表す「関連」が入るので正解。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことなので、値段の関係を表す文には合わない。"}, {"text": "欠席", "is_correct": false, "explanation": "欠席は出席しないことなので、値段の関係には使えない。"}, {"text": "応募", "is_correct": false, "explanation": "応募は申し込むことなので、値段とのつながりを表さない。"}], "explanations": {"関連": "「〜には関連がある」の形で、つながりを表す「関連」が入るので正解。", "散歩": "散歩は歩くことなので、値段の関係を表す文には合わない。", "欠席": "欠席は出席しないことなので、値段の関係には使えない。", "応募": "応募は申し込むことなので、値段とのつながりを表さない。"}, "sentence_index": 6, "correct_answer": "関連"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女とは付き合って三年の関連です。", "explanation": "ここは〈恋人どうしの仲〉の意味。関連は物事同士のつながりを指すので、恋人の間柄には使わない。"}, {"text": "叔母は私の遠い関連です。", "explanation": "ここは〈親戚〉の意味。関連は物事のつながりを指すので、家族や親族には使わない。"}, {"text": "レストランの席を、電話で関連しました。", "explanation": "ここは〈予約〉の意味。関連はつながりを表すので、席を取る意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36706, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その記事は経済ニュースを関連しています。", "corrected_sentence": "その記事は経済ニュースに関連しています。", "error_description": "「経済ニュースを関連」は誤り。「関連する」は「〜に関連する」と使うので、助詞は「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36706, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この件には事故との関連をあります。", "corrected_sentence": "この件には事故との関連があります。", "error_description": "「関連をあります」は誤り。「ある」の主語は「が」で示すので、「関連があります」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36707, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関係", "is_correct": true, "explanation": "つながりがないという意味で、「関連」の反対語。"}, {"text": "独立", "is_correct": false, "explanation": "独立は他に頼らず立つことなので、関連の反対語ではない。"}, {"text": "製造", "is_correct": false, "explanation": "製造は物を作ることなので、関わりの有無とは関係ない。"}, {"text": "集中", "is_correct": false, "explanation": "集中は一点に注意を向けることなので、関連の反対にはならない。"}], "correct_answer": "無関係", "explanations": {"無関係": "つながりがないという意味で、「関連」の反対語。", "独立": "独立は他に頼らず立つことなので、関連の反対語ではない。", "製造": "製造は物を作ることなので、関わりの有無とは関係ない。", "集中": "集中は一点に注意を向けることなので、関連の反対にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36707, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「関連がある」の「が」。あるものを示す主語。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「関連をあるかどうか」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「関連へあるかどうか」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」。「関連からあるかどうか」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「関連がある」の「が」。あるものを示す主語。", "を": "「を」は目的語。「関連をあるかどうか」は不自然。", "へ": "方向を表す「へ」。「関連へあるかどうか」は意味が通らない。", "から": "起点を表す「から」。「関連からあるかどうか」は文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関係", "is_correct": true, "explanation": "関わりがないという意味で、「関連」の反対語。"}, {"text": "販売", "is_correct": false, "explanation": "販売は商品を売ることなので、つながりの反対語ではない。"}, {"text": "分析", "is_correct": false, "explanation": "分析は細かく調べることなので、関係の反対とは言えない。"}, {"text": "記録", "is_correct": false, "explanation": "記録は残すことなので、関わりの有無とは関係がない。"}], "correct_answer": "無関係", "explanations": {"無関係": "関わりがないという意味で、「関連」の反対語。", "販売": "販売は商品を売ることなので、つながりの反対語ではない。", "分析": "分析は細かく調べることなので、関係の反対とは言えない。", "記録": "記録は残すことなので、関わりの有無とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36707, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つ以上の物事が互いに関わり合っていること。また、関係があること。", "primary_collocate": null, "pronunciation": "かんれん", "ipa": "kaɴɾeɴ", "syllable_count": 4, "sentences": [{"text": "病気と生活習慣は互いに関連しています。", "target_word": "関連", "complexity_tier": "T3", "furigana": "病気[びょうき]と生活習慣[せいかつしゅうかん]は互[たが]いに関連[かんれん]しています。", "sentence_source": "generated"}, {"text": "質問が研究と関連していなかったので、答えられませんでした。", "target_word": "関連", "complexity_tier": "T3", "furigana": "質問[しつもん]が研究[けんきゅう]と関連[かんれん]していなかったので、答[こた]えられませんでした。", "sentence_source": "generated"}, {"text": "環境の問題は、経済とも関連が深いです。", "target_word": "関連", "complexity_tier": "T3", "furigana": "環境[かんきょう]の問題[もんだい]は、経済[けいざい]とも関連[かんれん]が深[ふか]いです。", "sentence_source": "generated"}, {"text": "関連のない話を始めたので、会議が長くなりました。", "target_word": "関連", "complexity_tier": "T3", "furigana": "関連[かんれん]のない話[はなし]を始[はじ]めたので、会議[かいぎ]が長[なが]くなりました。", "sentence_source": "generated"}, {"text": "色と気持ちの関連を調べる研究があります。", "target_word": "関連", "complexity_tier": "T3", "furigana": "色[いろ]と気持[きも]ちの関連[かんれん]を調[しら]べる研究[けんきゅう]があります。", "sentence_source": "generated"}, {"text": "彼の転職は、家族の事情と関連があるようです。", "target_word": "関連", "complexity_tier": "T3", "furigana": "彼[かれ]の転職[てんしょく]は、家族[かぞく]の事情[じじょう]と関連[かんれん]があるようです。", "sentence_source": "generated"}, {"text": "この言葉は音楽に関連して使われることが多いです。", "target_word": "関連", "complexity_tier": "T3", "furigana": "この言葉[ことば]は音楽[おんがく]に関連[かんれん]して使[つか]われることが多[おお]いです。", "sentence_source": "generated"}, {"text": "二つの会社に関連があるかどうか、調べています。", "target_word": "関連", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]に関連[かんれん]があるかどうか、調[しら]べています。", "sentence_source": "generated"}, {"text": "関連する法律が変わったため、ルールも新しくなりました。", "target_word": "関連", "complexity_tier": "T3", "furigana": "関連[かんれん]する法律[ほうりつ]が変[か]わったため、ルールも新[あたら]しくなりました。", "sentence_source": "generated"}, {"text": "運動不足は、多くの病気と関連があると言われています。", "target_word": "関連", "complexity_tier": "T3", "furigana": "運動不足[うんどうぶそく]は、多[おお]くの病気[びょうき]と関連[かんれん]があると言[い]われています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "関連", "label": "基本形"}, {"form": "関連する", "label": "サ変動詞の終止形"}, {"form": "関連した", "label": "過去形"}, {"form": "関連して", "label": "て形"}], "register": "丁寧", "sense_fingerprint": "二つ以上の物事が互いに影響し合うような関係にあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7105bb1-e226-4133-ac5e-7c362d45bd96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36707, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "関連", "is_correct": true, "explanation": "「互いに」に続けて、影響し合う関係を表す「関連」が入るので正解。"}, {"text": "合計", "is_correct": false, "explanation": "合計は数を足すことなので、互いに影響し合う関係を表さない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物などを頼むことなので、関係を表す語とは合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことなので、互いの関係を表す文には入らない。"}], "explanations": {"関連": "「互いに」に続けて、影響し合う関係を表す「関連」が入るので正解。", "合計": "合計は数を足すことなので、互いに影響し合う関係を表さない。", "注文": "注文は品物などを頼むことなので、関係を表す語とは合わない。", "散歩": "散歩は歩くことなので、互いの関係を表す文には入らない。"}, "sentence_index": 0, "correct_answer": "関連"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テストの答案に、関連の点数をつけました。", "explanation": "ここは〈採点〉の意味。関連は物事のつながりを表すので、答案に点数をつける意味にはならない。"}, {"text": "宅配便は、荷物の届け先と関連して到着しました。", "explanation": "ここは〈配達〉の意味。関連は関わりを表すので、荷物を相手に届ける意味にはならない。"}, {"text": "新しい友人と、みんなに関連させました。", "explanation": "ここは〈紹介〉の意味。関連させるは関係づける意味で、人を引き合わせる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36707, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "関連", "is_correct": true, "explanation": "「音楽に」に続けて「関連して」となる、つながりを表す「関連」が入るので正解。"}, {"text": "欠席", "is_correct": false, "explanation": "欠席は出席しないことなので、言葉の使われ方とは合わない。"}, {"text": "応募", "is_correct": false, "explanation": "応募は申し込むことなので、音楽との関わりを表さない。"}, {"text": "外出", "is_correct": false, "explanation": "外出は外へ出ることなので、言葉の使い方を表す語ではない。"}], "explanations": {"関連": "「音楽に」に続けて「関連して」となる、つながりを表す「関連」が入るので正解。", "欠席": "欠席は出席しないことなので、言葉の使われ方とは合わない。", "応募": "応募は申し込むことなので、音楽との関わりを表さない。", "外出": "外出は外へ出ることなので、言葉の使い方を表す語ではない。"}, "sentence_index": 6, "correct_answer": "関連"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の日、大きな声で選手と関連しました。", "explanation": "ここは〈応援〉の意味。関連は関わりを表すので、選手を励む意味にはならない。"}, {"text": "担当の先生と関連して、名前を書きました。", "explanation": "ここは〈指名〉の意味。関連は関わりを表すので、人を選び出す意味にはならない。"}, {"text": "旅行の荷物を、空港で関連しました。", "explanation": "ここは〈預ける〉の意味。関連はつながりを表すので、荷物を預ける意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36707, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事件に関連いて、新しい発表がありました。", "corrected_sentence": "事件に関連して、新しい発表がありました。", "error_description": "「関連いて」は誤り。「関連する」のて形は「関連して」で、「いて」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36707, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい法律が、この制度と関連しいます。", "corrected_sentence": "新しい法律が、この制度と関連しています。", "error_description": "「関連しいます」は誤り。「関連しています」の「て」が抜けている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4f6a415-d03d-46c8-933b-35673ed32ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36708, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「興味を持つ」の目的語を示す形で、弟が虫に関心を持つ意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「興味が持つ」とすると興味を主語にしてしまい、弟が興味を持つ文にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「興味へ持つ」は方向を示す形で、「興味を持つ」の目的語の関係にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「興味で持つ」は手段を示すことになり、「興味を持つ」の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「興味を持つ」の目的語を示す形で、弟が虫に関心を持つ意味になる。", "が": "「興味が持つ」とすると興味を主語にしてしまい、弟が興味を持つ文にならない。", "へ": "「興味へ持つ」は方向を示す形で、「興味を持つ」の目的語の関係にならず不自然。", "で": "「興味で持つ」は手段を示すことになり、「興味を持つ」の意味が通らない。"}, "error_tags": {}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関心", "is_correct": true, "explanation": "関心がないことを表し、興味の対義語として辞書に並ぶ。"}, {"text": "不安", "is_correct": false, "explanation": "不安は心配の気持ちで、興味の対義語ではない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は朝起きられないことで、関心の有無とは関係しない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、興味と反対の意味関係にない。"}], "correct_answer": "無関心", "explanations": {"無関心": "関心がないことを表し、興味の対義語として辞書に並ぶ。", "不安": "不安は心配の気持ちで、興味の対義語ではない。", "寝坊": "寝坊は朝起きられないことで、関心の有無とは関係しない。", "夕焼け": "夕焼けは空の現象で、興味と反対の意味関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36708, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「興味を持つ」の目的語を示す形で、日本語への関心を表す文になる。"}, {"text": "に", "is_correct": false, "explanation": "「興味に持つ」とは言わず、「に」は相手や対象を示すが「持つ」の目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「興味と持つ」は並列を示すことになり、「持つ」の目的語の関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「興味より持つ」は比較の意味になり、「興味を持つ」の文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「興味を持つ」の目的語を示す形で、日本語への関心を表す文になる。", "に": "「興味に持つ」とは言わず、「に」は相手や対象を示すが「持つ」の目的語にはならない。", "と": "「興味と持つ」は並列を示すことになり、「持つ」の目的語の関係が成り立たない。", "より": "「興味より持つ」は比較の意味になり、「興味を持つ」の文の意味が通らない。"}, "error_tags": {}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関心", "is_correct": true, "explanation": "関心がないことを表し、興味の対義語として辞書に並ぶ。"}, {"text": "請求書", "is_correct": false, "explanation": "請求書は代金を求める書類で、関心の有無とは反対の関係にない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まることで、興味と対になる意味関係にない。"}, {"text": "寝不足", "is_correct": false, "explanation": "寝不足は睡眠が足りない状態で、興味の対義語ではない。"}], "correct_answer": "無関心", "explanations": {"無関心": "関心がないことを表し、興味の対義語として辞書に並ぶ。", "請求書": "請求書は代金を求める書類で、関心の有無とは反対の関係にない。", "停電": "停電は電気が止まることで、興味と対になる意味関係にない。", "寝不足": "寝不足は睡眠が足りない状態で、興味の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36708, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを知りたい、見てみたいと思う気持ちのことです。", "primary_collocate": null, "pronunciation": "きょうみ", "ipa": "kʲoːmi", "syllable_count": 3, "sentences": [{"text": "私は日本の歴史に興味があります。", "target_word": "興味", "complexity_tier": "T3", "furigana": "私[わたし]は日本[にほん]の歴史[れきし]に興味[きょうみ]があります。", "sentence_source": "generated"}, {"text": "弟は虫に興味を持って、毎日図鑑を見ています。", "target_word": "興味", "complexity_tier": "T3", "furigana": "弟[おとうと]は虫[むし]に興味[きょうみ]を持[も]って、毎日[まいにち]図鑑[ずかん]を見[み]ています。", "sentence_source": "generated"}, {"text": "興味がない映画なので、見に行きませんでした。", "target_word": "興味", "complexity_tier": "T3", "furigana": "興味[きょうみ]がない映画[えいが]なので、見[み]に行[い]きませんでした。", "sentence_source": "generated"}, {"text": "先生の話がおもしろくて、科学に興味がわきました。", "target_word": "興味", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]がおもしろくて、科学[かがく]に興味[きょうみ]がわきました。", "sentence_source": "generated"}, {"text": "娘は料理に興味があるので、一緒に作っています。", "target_word": "興味", "complexity_tier": "T3", "furigana": "娘[むすめ]は料理[りょうり]に興味[きょうみ]があるので、一緒[いっしょ]に作[つく]っています。", "sentence_source": "generated"}, {"text": "彼は音楽に興味を示し、ギターを習い始めました。", "target_word": "興味", "complexity_tier": "T3", "furigana": "彼[かれ]は音楽[おんがく]に興味[きょうみ]を示[しめ]し、ギターを習[なら]い始[はじ]めました。", "sentence_source": "generated"}, {"text": "子どもの興味に合わせて、本を選びました。", "target_word": "興味", "complexity_tier": "T3", "furigana": "子[こ]どもの興味[きょうみ]に合[あ]わせて、本[ほん]を選[えら]びました。", "sentence_source": "generated"}, {"text": "日本語に興味を持ったのは、アニメを見たからです。", "target_word": "興味", "complexity_tier": "T3", "furigana": "日本語[にほんご]に興味[きょうみ]を持[も]ったのは、アニメを見[み]たからです。", "sentence_source": "generated"}, {"text": "この町のお祭りに興味があって、写真を撮りに来ました。", "target_word": "興味", "complexity_tier": "T3", "furigana": "この町[まち]のお祭[まつ]りに興味[きょうみ]があって、写真[しゃしん]を撮[と]りに来[き]ました。", "sentence_source": "generated"}, {"text": "興味がなくなったので、そのゲームをやめました。", "target_word": "興味", "complexity_tier": "T3", "furigana": "興味[きょうみ]がなくなったので、そのゲームをやめました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "興味", "label": "基本形"}, {"form": "興味が", "label": "主語を表す形"}, {"form": "興味を", "label": "目的語を表す形"}], "register": "neutral", "sense_fingerprint": "何かを知りたい、見てみたいと思う気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36708, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "興味", "is_correct": true, "explanation": "「歴史に興味がある」の形で、対象への関心を表すので文が成り立つ。"}, {"text": "天気", "is_correct": false, "explanation": "天気は「歴史に〜がある」の対象にならず、文として成り立たない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は歴史の中に「ある」ものではなく、この空所に入らない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは歴史の一部ではなく、「歴史にある」と言えないので合わない。"}], "explanations": {"興味": "「歴史に興味がある」の形で、対象への関心を表すので文が成り立つ。", "天気": "天気は「歴史に〜がある」の対象にならず、文として成り立たない。", "寝坊": "寝坊は歴史の中に「ある」ものではなく、この空所に入らない。", "夕焼け": "夕焼けは歴史の一部ではなく、「歴史にある」と言えないので合わない。"}, "sentence_index": 0, "correct_answer": "興味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この借り入れは、返済が遅れると興味が増える。", "explanation": "ここは〈利息〉の意味。興味は物事を知りたい気持ちのことで、お金の利子は指さない。"}, {"text": "彼は仲間の興味を一人で負い、店を閉めた。", "explanation": "ここは〈責任〉の意味。興味は関心の気持ちで、負うべきものとしては使わない。"}, {"text": "祖母は、興味を込めて手紙を書いてくれた。", "explanation": "ここは〈心〉の意味。「心を込める」の「心」にあたり、「興味を込める」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36708, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "興味", "is_correct": true, "explanation": "子どもの関心に合わせる意味になり、「興味に合わせて」で文が成り立つ。"}, {"text": "地震", "is_correct": false, "explanation": "「子どもの地震に合わせて」は意味をなさず、空所に入らない。"}, {"text": "雷雨", "is_correct": false, "explanation": "「子どもの雷雨に合わせて」は意味をなさず、空所に入らない。"}, {"text": "大雪", "is_correct": false, "explanation": "「子どもの大雪に合わせて」は意味をなさず、空所に入らない。"}], "explanations": {"興味": "子どもの関心に合わせる意味になり、「興味に合わせて」で文が成り立つ。", "地震": "「子どもの地震に合わせて」は意味をなさず、空所に入らない。", "雷雨": "「子どもの雷雨に合わせて」は意味をなさず、空所に入らない。", "大雪": "「子どもの大雪に合わせて」は意味をなさず、空所に入らない。"}, "sentence_index": 6, "correct_answer": "興味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は味の興味がよく、遠くからも客が来る。", "explanation": "ここは〈評判〉の意味。興味は関心の気持ちで、料理の評価は表さない。"}, {"text": "この口座は、毎月の興味が元本に加わって増える。", "explanation": "ここは〈利息〉の意味。興味は関心の気持ちで、口座の利子は指さない。"}, {"text": "その失敗の興味を負って、社長は辞任した。", "explanation": "ここは〈責任〉の意味。興味は物事への関心で、負うべきものとしては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36708, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は日本の文化に興味をあります。", "corrected_sentence": "私は日本の文化に興味があります。", "error_description": "「興味」は「が」で「ある」を続ける。「を」は誤りで、「興味がある」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36708, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの興味を合わせて、絵本を選びました。", "corrected_sentence": "子どもの興味に合わせて、絵本を選びました。", "error_description": "「合わせる」は「に」を取る。「興味を合わせて」は「を」が誤りで、「興味に合わせて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36709, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「興味を引く」の目的語を示す形で、学者たちの関心を引いた意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「興味に引く」は「引く」の対象として成り立たず、興味を引く形にならない。"}, {"text": "で", "is_correct": false, "explanation": "「興味で引く」は手段を示すことになり、「興味を引く」の目的語の関係にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「興味へ引く」は方向を示す形で、「興味を引く」の文の意味にならない。"}], "correct_answer": "を", "explanations": {"を": "「興味を引く」の目的語を示す形で、学者たちの関心を引いた意味になる。", "に": "「興味に引く」は「引く」の対象として成り立たず、興味を引く形にならない。", "で": "「興味で引く」は手段を示すことになり、「興味を引く」の目的語の関係にならず不自然。", "へ": "「興味へ引く」は方向を示す形で、「興味を引く」の文の意味にならない。"}, "error_tags": {}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関心", "is_correct": true, "explanation": "関心がないことを表し、興味の対義語として辞書に並ぶ。"}, {"text": "雷雨", "is_correct": false, "explanation": "雷雨は天気の現象で、興味と反対の意味関係にない。"}, {"text": "義務", "is_correct": false, "explanation": "義務は果たすべきことで、興味の対義語ではない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、興味と反対の意味関係にない。"}], "correct_answer": "無関心", "explanations": {"無関心": "関心がないことを表し、興味の対義語として辞書に並ぶ。", "雷雨": "雷雨は天気の現象で、興味と反対の意味関係にない。", "義務": "義務は果たすべきことで、興味の対義語ではない。", "夕焼け": "夕焼けは空の現象で、興味と反対の意味関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36709, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「興味が深まる」の主語を示す形で、環境問題への関心が深まった意味になる。"}, {"text": "と", "is_correct": false, "explanation": "「興味と深まる」は並列を示すことになり、「深まった」の主語の関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「興味より深まる」は比較の意味になり、「深まった」の主語を示せず文が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「興味の」は連体修飾になり、「深まった」の主語を示すことにはならない。"}], "correct_answer": "が", "explanations": {"が": "「興味が深まる」の主語を示す形で、環境問題への関心が深まった意味になる。", "と": "「興味と深まる」は並列を示すことになり、「深まった」の主語の関係が成り立たない。", "より": "「興味より深まる」は比較の意味になり、「深まった」の主語を示せず文が通らない。", "の": "「興味の」は連体修飾になり、「深まった」の主語を示すことにはならない。"}, "error_tags": {}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無関心", "is_correct": true, "explanation": "関心がないことを表し、興味の対義語として辞書に並ぶ。"}, {"text": "大雪", "is_correct": false, "explanation": "大雪は天気の現象で、興味と反対の意味関係にない。"}, {"text": "請求書", "is_correct": false, "explanation": "請求書は代金を求める書類で、関心の有無とは反対の関係にない。"}, {"text": "地震", "is_correct": false, "explanation": "地震は自然現象で、興味と反対の意味関係にない。"}], "correct_answer": "無関心", "explanations": {"無関心": "関心がないことを表し、興味の対義語として辞書に並ぶ。", "大雪": "大雪は天気の現象で、興味と反対の意味関係にない。", "請求書": "請求書は代金を求める書類で、関心の有無とは反対の関係にない。", "地震": "地震は自然現象で、興味と反対の意味関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36709, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事に対して特別な関心や好奇心を持ち、それについてもっと知りたい、または関わりたいと思う心の動き。", "primary_collocate": null, "pronunciation": "きょうみ", "ipa": "kʲoːmi", "syllable_count": 3, "sentences": [{"text": "彼は昔から、宇宙の成り立ちに強い興味を抱いている。", "target_word": "興味", "complexity_tier": "T3", "furigana": "彼[かれ]は昔[むかし]から、宇宙[うちゅう]の成[な]り立[た]ちに強[つよ]い興味[きょうみ]を抱[いだ]いている。", "sentence_source": "generated"}, {"text": "この研究は、多くの学者の興味を引いた。", "target_word": "興味", "complexity_tier": "T3", "furigana": "この研究[けんきゅう]は、多[おお]くの学者[がくしゃ]の興味[きょうみ]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "彼女は言語学に興味を持ち、大学で専攻することにした。", "target_word": "興味", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は言語学[げんごがく]に興味[きょうみ]を持[も]ち、大学[だいがく]で専攻[せんこう]することにした。", "sentence_source": "generated"}, {"text": "新しい技術に対する消費者の興味は、年々高まっている。", "target_word": "興味", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]に対[たい]する消費者[しょうひしゃ]の興味[きょうみ]は、年々[ねんねん]高[たか]まっている。", "sentence_source": "generated"}, {"text": "興味のある分野を選ぶと、勉強が長続きしやすい。", "target_word": "興味", "complexity_tier": "T3", "furigana": "興味[きょうみ]のある分野[ぶんや]を選[えら]ぶと、勉強[べんきょう]が長続[ながつづ]きしやすい。", "sentence_source": "generated"}, {"text": "彼はスポーツには興味が薄く、読書ばかりしている。", "target_word": "興味", "complexity_tier": "T3", "furigana": "彼[かれ]はスポーツには興味[きょうみ]が薄[うす]く、読書[どくしょ]ばかりしている。", "sentence_source": "generated"}, {"text": "好奇心の強い子は、さまざまな物事に興味を向ける。", "target_word": "興味", "complexity_tier": "T3", "furigana": "好奇心[こうきしん]の強[つよ]い子[こ]は、さまざまな物事[ものごと]に興味[きょうみ]を向[む]ける。", "sentence_source": "generated"}, {"text": "講演を聞いて、環境問題への興味がいっそう深まった。", "target_word": "興味", "complexity_tier": "T3", "furigana": "講演[こうえん]を聞[き]いて、環境問題[かんきょうもんだい]への興味[きょうみ]がいっそう深[ふか]まった。", "sentence_source": "generated"}, {"text": "面接官は、応募者の興味や関心について質問した。", "target_word": "興味", "complexity_tier": "T3", "furigana": "面接官[めんせつかん]は、応募者[おうぼしゃ]の興味[きょうみ]や関心[かんしん]について質問[しつもん]した。", "sentence_source": "generated"}, {"text": "興味を失った客は、すぐに店から出ていった。", "target_word": "興味", "complexity_tier": "T3", "furigana": "興味[きょうみ]を失[うしな]った客[きゃく]は、すぐに店[みせ]から出[で]ていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "興味", "label": "基本形"}, {"form": "興味を", "label": "目的語を表す形"}, {"form": "興味の", "label": "連体形"}], "register": "formal", "sense_fingerprint": "特定の物事への関心や好奇心という心の動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081c94d7-8af4-46b1-9d3d-bdb2c1d8524b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36709, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "興味", "is_correct": true, "explanation": "「強い興味を抱く」で、特定の物事への関心を表すので文が成り立つ。"}, {"text": "台風", "is_correct": false, "explanation": "台風は「抱く」の対象にならず、「強い台風を抱いている」は成り立たない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは「抱く」ものではなく、この空所に入らない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は「強い寝坊を抱く」とは言えず、文として成り立たない。"}], "explanations": {"興味": "「強い興味を抱く」で、特定の物事への関心を表すので文が成り立つ。", "台風": "台風は「抱く」の対象にならず、「強い台風を抱いている」は成り立たない。", "夕焼け": "夕焼けは「抱く」ものではなく、この空所に入らない。", "寝坊": "寝坊は「強い寝坊を抱く」とは言えず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "興味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この定期預金は、一年たつと興味が元本に加わる。", "explanation": "ここは〈利息〉の意味。興味は物事への関心の心の動きで、預金の利子は指さない。"}, {"text": "彼のピアノは興味が正確で、どの音も外さない。", "explanation": "ここは〈腕前〉の意味。興味は関心の気持ちで、演奏の正確さは表さない。"}, {"text": "危険な場所では、興味を払って行動すべきだ。", "explanation": "ここは〈注意〉の意味。興味は関心を向けることで、用心する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36709, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "興味", "is_correct": true, "explanation": "「物事に興味を向ける」で、関心を向ける意味になり文が成り立つ。"}, {"text": "停電", "is_correct": false, "explanation": "停電は「物事に向ける」ものではなく、この文に入らない。"}, {"text": "雪崩", "is_correct": false, "explanation": "雪崩は「物事に向ける」ものではなく、文が成り立たない。"}, {"text": "寝不足", "is_correct": false, "explanation": "寝不足は「向ける」対象にならず、「寝不足を向ける」は不自然で合わない。"}], "explanations": {"興味": "「物事に興味を向ける」で、関心を向ける意味になり文が成り立つ。", "停電": "停電は「物事に向ける」ものではなく、この文に入らない。", "雪崩": "雪崩は「物事に向ける」ものではなく、文が成り立たない。", "寝不足": "寝不足は「向ける」対象にならず、「寝不足を向ける」は不自然で合わない。"}, "sentence_index": 6, "correct_answer": "興味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は町の興味がよく、いつも行列ができる。", "explanation": "ここは〈評判〉の意味。興味は関心の気持ちで、店の世間での評価は表さない。"}, {"text": "この貯金は、五年たつと興味が元本の二割に達する。", "explanation": "ここは〈利息〉の意味。興味は関心の気持ちで、貯金の利子は指さない。"}, {"text": "大きな損害の興味を負うのは、経営者の役目だ。", "explanation": "ここは〈責任〉の意味。興味は物事への関心で、損害を負う対象としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36709, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は昔から、宇宙の仕組みに強い興味に抱いている。", "corrected_sentence": "彼は昔から、宇宙の仕組みに強い興味を抱いている。", "error_description": "「抱く」は「を」を取る。「興味に抱いて」は「に」が誤りで、「興味を抱いて」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36709, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "好奇心の強い子は、さまざまな物事に興味が示す。", "corrected_sentence": "好奇心の強い子は、さまざまな物事に興味を示す。", "error_description": "「示す」は「を」を取る。「興味が示す」は「が」が誤りで、「興味を示す」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018cfc59-165b-41bc-9f6a-0e85c5709bab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36710, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「このミラーは大きい」とミラーを主題にして大きさを述べる、正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "「ミラーと大きいので」は並列の形になり、大きさの説明が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ミラーへ大きいので」は方向を示すが、大きさを述べる文にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「ミラーから大きいので」は起点を示す形で、大きさを述べる主題にならない。"}], "correct_answer": "は", "explanations": {"は": "「このミラーは大きい」とミラーを主題にして大きさを述べる、正しい助詞。", "と": "「ミラーと大きいので」は並列の形になり、大きさの説明が成り立たない。", "へ": "「ミラーへ大きいので」は方向を示すが、大きさを述べる文にはならない。", "から": "「ミラーから大きいので」は起点を示す形で、大きさを述べる主題にならない。"}, "error_tags": {"と": "並列", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36710, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「試着室のミラーで」は道具・手段を表し、鏡を使って確認した意味になる正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「ミラーを、新しい服を」と目的語が二つ重なり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ミラーに新しい服を確認した」では確認の手段を示せず、不自然。"}, {"text": "より", "is_correct": false, "explanation": "「ミラーより新しい服を確認した」は比較の形になり、確認の手段を示せない。"}], "correct_answer": "で", "explanations": {"で": "「試着室のミラーで」は道具・手段を表し、鏡を使って確認した意味になる正しい助詞。", "を": "「ミラーを、新しい服を」と目的語が二つ重なり、文が成り立たない。", "に": "「ミラーに新しい服を確認した」では確認の手段を示せず、不自然。", "より": "「ミラーより新しい服を確認した」は比較の形になり、確認の手段を示せない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36710, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かがみの こと。", "primary_collocate": null, "pronunciation": "みらー", "ipa": "miɾaː", "syllable_count": 3, "sentences": [{"text": "出かける前に、ミラーを見て髪を直しました。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "出[で]かける前[まえ]に、ミラーを見[み]て髪[かみ]を直[なお]しました。", "sentence_source": "generated"}, {"text": "このミラーは大きいので、全身がうつります。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "このミラーは大[おお]きいので、全身[ぜんしん]がうつります。", "sentence_source": "generated"}, {"text": "洗面所のミラーが曇って、顔がよく見えません。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "洗面所[せんめんじょ]のミラーが曇[くも]って、顔[かお]がよく見[み]えません。", "sentence_source": "generated"}, {"text": "彼女はバッグから小さなミラーを出して、口紅をぬった。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はバッグから小[ちい]さなミラーを出[だ]して、口紅[くちべに]をぬった。", "sentence_source": "generated"}, {"text": "ミラーの前で、笑顔の練習をしました。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "ミラーの前[まえ]で、笑顔[えがお]の練習[れんしゅう]をしました。", "sentence_source": "generated"}, {"text": "うっかり落として、ミラーが割れてしまいました。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "うっかり落[お]として、ミラーが割[わ]れてしまいました。", "sentence_source": "generated"}, {"text": "玄関にミラーを置くと、部屋が広く見えます。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "玄関[げんかん]にミラーを置[お]くと、部屋[へや]が広[ひろ]く見[み]えます。", "sentence_source": "generated"}, {"text": "試着室のミラーで、新しい服を確認した。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "試着室[しちゃくしつ]のミラーで、新[あたら]しい服[ふく]を確認[かくにん]した。", "sentence_source": "generated"}, {"text": "ミラーにうつった自分の顔は、とても疲れていた。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "ミラーにうつった自分[じぶん]の顔[かお]は、とても疲[つか]れていた。", "sentence_source": "generated"}, {"text": "妹はミラーを持ち歩いて、何度も前髪を確かめる。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "妹[いもうと]はミラーを持[も]ち歩[ある]いて、何度[なんど]も前髪[まえがみ]を確[たし]かめる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ミラー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ミラー=身だしなみや姿を見るための一般的な鏡(洗面所・試着室・手鏡)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36710, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ミラー", "is_correct": true, "explanation": "身だしなみを確かめる鏡のこと。髪を直すときに見る対象として合う。"}, {"text": "靴下", "is_correct": false, "explanation": "足に履く衣類で、見て髪を直す対象にはならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、見て髪を直す対象として成り立たない。"}, {"text": "掃除機", "is_correct": false, "explanation": "ゴミを吸う家電で、髪を直すときに見る対象にはならない。"}], "explanations": {"ミラー": "身だしなみを確かめる鏡のこと。髪を直すときに見る対象として合う。", "靴下": "足に履く衣類で、見て髪を直す対象にはならない。", "冷蔵庫": "食品を冷やす家電で、見て髪を直す対象として成り立たない。", "掃除機": "ゴミを吸う家電で、髪を直すときに見る対象にはならない。"}, "sentence_index": 0, "correct_answer": "ミラー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、ミラーの向こうに富士山が見える。", "explanation": "ここは〈窓〉の意味。ミラーは光を映す鏡で、向こう側は見通せないので合わない。"}, {"text": "お風呂上がりに、ミラーで体を拭いた。", "explanation": "ここは〈タオル〉の意味。ミラーは姿を映す道具で、体を拭く用途はないので合わない。"}, {"text": "スマホのミラーに、友達からのメッセージが届いた。", "explanation": "ここは〈画面〉の意味。ミラーは映すための鏡で、情報を表示したり届けたりはしないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36710, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ミラー", "is_correct": true, "explanation": "姿や部屋を映して広く見せる鏡のこと。玄関に置く対象として合う。"}, {"text": "教科書", "is_correct": false, "explanation": "学習用の本で、置いても部屋を広く見せる効果はない。"}, {"text": "洗剤", "is_correct": false, "explanation": "掃除に使う液体で、置いても部屋が広く見えることにはならない。"}, {"text": "雑誌", "is_correct": false, "explanation": "読むための印刷物で、置いて部屋を広く見せる効果はない。"}], "explanations": {"ミラー": "姿や部屋を映して広く見せる鏡のこと。玄関に置く対象として合う。", "教科書": "学習用の本で、置いても部屋を広く見せる効果はない。", "洗剤": "掃除に使う液体で、置いても部屋が広く見えることにはならない。", "雑誌": "読むための印刷物で、置いて部屋を広く見せる効果はない。"}, "sentence_index": 6, "correct_answer": "ミラー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹はミラーを持ち歩いて、何度も道を確かめる。", "explanation": "ここは〈地図〉の意味。ミラーは姿を映すもので、道の位置は確かめられないので合わない。"}, {"text": "妹はミラーを持ち歩いて、何度も時間を確かめる。", "explanation": "ここは〈時計〉の意味。ミラーは時刻を示さないので、時間を確かめる道具にはならない。"}, {"text": "妹はミラーを持ち歩いて、何度も景色を撮る。", "explanation": "ここは〈カメラ〉の意味。ミラーでは景色を撮れないので、撮るという動作と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36710, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝ぐせが気になって、玄関のミラーに見ながら髪を直しました。", "corrected_sentence": "寝ぐせが気になって、玄関のミラーを見ながら髪を直しました。", "error_description": "誤: ミラーに見ながら、正: ミラーを見ながら。見る対象は「を」で示す。「に」では見る対象にならず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36710, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は玄関のミラーを前で、前髪を直していた。", "corrected_sentence": "妹は玄関のミラーの前で、前髪を直していた。", "error_description": "誤: ミラーを前で、正: ミラーの前で。「前」は場所を表す名詞なので、ミラーとの関係は「の」で結ぶ。「を」は動作の対象にしか使えず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36711, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ミラーを見る」で見る対象を示す正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「ミラーに見ると」では見る対象にならず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「ミラーと見ると」は並列となり、見る動作が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「ミラーの見ると」は名詞修飾になり、「見ると」の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「ミラーを見る」で見る対象を示す正しい助詞。", "に": "「ミラーに見ると」では見る対象にならず、不自然。", "と": "「ミラーと見ると」は並列となり、見る動作が成り立たない。", "の": "「ミラーの見ると」は名詞修飾になり、「見ると」の対象を示せない。"}, "error_tags": {"に": "対象", "と": "並列", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36711, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ミラーを使って」で使う対象を示す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「小さなミラーが使って」ではミラーが主語になり、使う対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「ミラーより使って」は比較となり、使う対象の意味にならない。"}, {"text": "から", "is_correct": false, "explanation": "「ミラーから使って」は起点の意味になり、道具として使う文にならない。"}], "correct_answer": "を", "explanations": {"を": "「ミラーを使って」で使う対象を示す正しい助詞。", "が": "「小さなミラーが使って」ではミラーが主語になり、使う対象を示せない。", "より": "「ミラーより使って」は比較となり、使う対象の意味にならない。", "から": "「ミラーから使って」は起点の意味になり、道具として使う文にならない。"}, "error_tags": {"が": "主語", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36711, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "鏡。特に、自動車のバックミラーなど、物を映して見るためのもの。", "primary_collocate": null, "pronunciation": "みらー", "ipa": "miɾaː", "syllable_count": 3, "sentences": [{"text": "運転する前に、ミラーの角度を調整します。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "運転[うんてん]する前[まえ]に、ミラーの角度[かくど]を調整[ちょうせい]します。", "sentence_source": "generated"}, {"text": "ミラーを見ると、後ろに大きいトラックがいた。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "ミラーを見[み]ると、後[うし]ろに大[おお]きいトラックがいた。", "sentence_source": "generated"}, {"text": "雨の日はミラーに水がついて、後ろが見えにくい。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]はミラーに水[みず]がついて、後[うし]ろが見[み]えにくい。", "sentence_source": "generated"}, {"text": "狭い道では、ミラーを折りたたんで通ります。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "狭[せま]い道[みち]では、ミラーを折[お]りたたんで通[とお]ります。", "sentence_source": "generated"}, {"text": "交差点のミラーで、向こうから来る車を確認した。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "交差点[こうさてん]のミラーで、向[む]こうから来[く]る車[くるま]を確認[かくにん]した。", "sentence_source": "generated"}, {"text": "ミラーが壊れたまま運転するのは危険です。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "ミラーが壊[こわ]れたまま運転[うんてん]するのは危険[きけん]です。", "sentence_source": "generated"}, {"text": "望遠鏡のミラーは、星の光を集める大切な部品だ。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "望遠鏡[ぼうえんきょう]のミラーは、星[ほし]の光[ひかり]を集[あつ]める大切[たいせつ]な部品[ぶひん]だ。", "sentence_source": "generated"}, {"text": "歯医者さんは小さなミラーを使って、奥の歯を調べた。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "歯医者[はいしゃ]さんは小[ちい]さなミラーを使[つか]って、奥[おく]の歯[は]を調[しら]べた。", "sentence_source": "generated"}, {"text": "自転車にミラーをつけたら、後ろの車がよく分かる。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]にミラーをつけたら、後[うし]ろの車[くるま]がよく分[わ]かる。", "sentence_source": "generated"}, {"text": "見通しの悪いカーブには、大きなミラーが立っている。", "target_word": "ミラー", "complexity_tier": "T3", "furigana": "見通[みとお]しの悪[わる]いカーブには、大[おお]きなミラーが立[た]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ミラー", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ミラー=車・道路・器具などで、見えない所を映して確かめるための鏡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36711, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ミラー", "is_correct": true, "explanation": "車の後ろや横を映すミラーのこと。運転前に角度を調整する対象として合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "料理に使う甘味で、角度を調整する対象にはならない。"}, {"text": "財布", "is_correct": false, "explanation": "お金を入れる袋で、角度を調整するという話とは関係がない。"}, {"text": "牛乳", "is_correct": false, "explanation": "飲み物で、角度を調整する対象ではない。"}], "explanations": {"ミラー": "車の後ろや横を映すミラーのこと。運転前に角度を調整する対象として合う。", "砂糖": "料理に使う甘味で、角度を調整する対象にはならない。", "財布": "お金を入れる袋で、角度を調整するという話とは関係がない。", "牛乳": "飲み物で、角度を調整する対象ではない。"}, "sentence_index": 0, "correct_answer": "ミラー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので、部屋のミラーを閉めた。", "explanation": "ここは〈窓〉の意味。ミラーは開け閉めするものではないので、閉めるという動作と合わない。"}, {"text": "地図アプリのミラーに、現在地が表示された。", "explanation": "ここは〈画面〉の意味。ミラーは映すための鏡で、現在地を表示する役割はないので合わない。"}, {"text": "寒い朝は、ミラーを首に巻いて出かけた。", "explanation": "ここは〈マフラー〉の意味。ミラーは映す道具で、首に巻いて防寒する物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36711, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ミラー", "is_correct": true, "explanation": "車の死角を映して、見えない所を確かめる鏡のこと。発進前に確認する対象として合う。"}, {"text": "靴下", "is_correct": false, "explanation": "足に履く衣類で、車の死角を確かめる道具にはならない。"}, {"text": "雑誌", "is_correct": false, "explanation": "印刷された読み物で、車の死角を映す道具ではない。"}, {"text": "洗剤", "is_correct": false, "explanation": "汚れを落とす液体で、死角を映して確かめる道具ではない。"}], "explanations": {"ミラー": "車の死角を映して、見えない所を確かめる鏡のこと。発進前に確認する対象として合う。", "靴下": "足に履く衣類で、車の死角を確かめる道具にはならない。", "雑誌": "印刷された読み物で、車の死角を映す道具ではない。", "洗剤": "汚れを落とす液体で、死角を映して確かめる道具ではない。"}, "sentence_index": 6, "correct_answer": "ミラー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "見通しの悪いカーブには、大きなミラーを点けている。", "explanation": "ここは〈照明〉の意味。ミラーは光を出す器具ではないので、点けるという動作と合わない。"}, {"text": "見通しの悪いカーブでは、大きなミラーを広げて道を確かめる。", "explanation": "ここは〈地図〉の意味。ミラーは広げて道を調べるものではないので合わない。"}, {"text": "見通しの悪いカーブでは、大きなミラーを振って音を鳴らす。", "explanation": "ここは〈ベル〉の意味。ミラーは音を出す道具ではないので、振って鳴らす用途には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36711, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "運転する前に、ミラーを角度を合わせておくと、後ろの車がよく見える。", "corrected_sentence": "運転する前に、ミラーの角度を合わせておくと、後ろの車がよく見える。", "error_description": "誤: ミラーを角度、正: ミラーの角度。「角度」はミラーの属性なので「の」で結ぶ。「を」が二つになり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36711, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自転車のミラーに直したら、後ろの車がよく見えた。", "corrected_sentence": "自転車のミラーを直したら、後ろの車がよく見えた。", "error_description": "誤: ミラーに直す、正: ミラーを直す。「直す」は直す対象に「を」をとる。「に直す」は別のものに変えるという意味になり、この文の意味に合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36712, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ニューロン」の後に続いて、あります（存在する）の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、存在を述べる文の「ニューロン」には続かない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す助詞で、「脳にある」という存在の文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「ニューロン」の後に続いて、あります（存在する）の主語を示す。", "を": "「ある」は目的語を取らないので、「を」は合わない。", "へ": "方向を表す助詞で、存在を述べる文の「ニューロン」には続かない。", "から": "起点を表す助詞で、「脳にある」という存在の文には合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36712, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ニューロン」が主語で、つながる動作をする。"}, {"text": "を", "is_correct": false, "explanation": "「つながる」は目的語を取らないので、「を」は合わない。"}, {"text": "の", "is_correct": false, "explanation": "所属を表す助詞で、「つながる」の主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「つながる」の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「ニューロン」が主語で、つながる動作をする。", "を": "「つながる」は目的語を取らないので、「を」は合わない。", "の": "所属を表す助詞で、「つながる」の主語にはならない。", "より": "比較の助詞で、「つながる」の主語を示せない。"}, "error_tags": {"を": "目的語", "の": "所属", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36712, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体の小さな部分で、情報を伝える働きをするものです。", "primary_collocate": null, "pronunciation": "にゅーろん", "ipa": "ɲɯːɾoɴ", "syllable_count": 4, "sentences": [{"text": "ニューロンは、体の中で情報を伝える小さな細胞です。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "ニューロンは、体[からだ]の中[なか]で情報[じょうほう]を伝[つた]える小[ちい]さな細胞[さいぼう]です。", "sentence_source": "generated"}, {"text": "脳には、たくさんのニューロンがあります。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "脳[のう]には、たくさんのニューロンがあります。", "sentence_source": "generated"}, {"text": "ニューロンのおかげで、熱いものにさわるとすぐ手を引っこめられる。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "ニューロンのおかげで、熱[あつ]いものにさわるとすぐ手[て]を引[ひ]っこめられる。", "sentence_source": "generated"}, {"text": "先生は、ニューロンの形を黒板に絵でかいて見せた。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ニューロンの形[かたち]を黒板[こくばん]に絵[え]でかいて見[み]せた。", "sentence_source": "generated"}, {"text": "ニューロンが情報を送るので、足を動かすことができる。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "ニューロンが情報[じょうほう]を送[おく]るので、足[あし]を動[うご]かすことができる。", "sentence_source": "generated"}, {"text": "人の脳には、ニューロンが約八百六十億個あるといわれる。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "人[ひと]の脳[のう]には、ニューロンが約[やく]八百六十億個[はっぴゃくろくじゅうおくこ]あるといわれる。", "sentence_source": "generated"}, {"text": "昨日の理科の授業で、ニューロンのしくみを習った。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "昨日[きのう]の理科[りか]の授業[じゅぎょう]で、ニューロンのしくみを習[なら]った。", "sentence_source": "generated"}, {"text": "ニューロンがつながると、新しいことをおぼえやすくなる。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "ニューロンがつながると、新[あたら]しいことをおぼえやすくなる。", "sentence_source": "generated"}, {"text": "目で見た情報は、ニューロンを通って脳に届く。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "目[め]で見[み]た情報[じょうほう]は、ニューロンを通[とお]って脳[のう]に届[とど]く。", "sentence_source": "generated"}, {"text": "ニューロンが弱ると、体にうまく指令が届かなくなる。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "ニューロンが弱[よわ]ると、体[からだ]にうまく指令[しれい]が届[とど]かなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ニューロン", "label": "基本形"}, {"form": "ニューロンが", "label": "が格"}, {"form": "ニューロンの", "label": "の格"}], "register": "neutral", "sense_fingerprint": "体の中で情報を伝える小さな細胞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36712, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ニューロン", "is_correct": true, "explanation": "体の中で情報を伝える小さな細胞を指すので、空欄に入る正解。"}, {"text": "心臓", "is_correct": false, "explanation": "血液を送り出す臓器で、小さな細胞ではない。「小さな細胞」の説明に合わない。"}, {"text": "血液", "is_correct": false, "explanation": "体内を流れる液体の組織で、細胞ではない。情報を伝える働きとも結びつかない。"}, {"text": "筋肉", "is_correct": false, "explanation": "体を動かす組織で、情報を伝えて指令を出す細胞の説明とは合わない。"}], "explanations": {"ニューロン": "体の中で情報を伝える小さな細胞を指すので、空欄に入る正解。", "心臓": "血液を送り出す臓器で、小さな細胞ではない。「小さな細胞」の説明に合わない。", "血液": "体内を流れる液体の組織で、細胞ではない。情報を伝える働きとも結びつかない。", "筋肉": "体を動かす組織で、情報を伝えて指令を出す細胞の説明とは合わない。"}, "sentence_index": 0, "correct_answer": "ニューロン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "牛乳を温めすぎると、ニューロンが増えやすくなる。", "explanation": "ここは〈細菌〉の意味。ニューロンは体内の神経細胞で、牛乳の中で増えるものではない。"}, {"text": "夜中に回線が切れて、ニューロンが使えなくなった。", "explanation": "ここは〈通信の経路〉の意味。ニューロンは体内の神経細胞で、通信の経路を指す言葉ではない。"}, {"text": "古い機械の部品が傷んだので、ニューロンを交換した。", "explanation": "ここは〈パーツ〉の意味。ニューロンは体の細胞で、機械の取り替え用の品を指す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36712, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ニューロン", "is_correct": true, "explanation": "神経系の仕組みを指すので、理科の授業で習う対象として正解。"}, {"text": "俳句", "is_correct": false, "explanation": "文学の一種で、理科の授業で仕組みを習う対象ではない。"}, {"text": "水泳", "is_correct": false, "explanation": "運動の一種で、「しくみ」を習う対象として成り立たない。"}, {"text": "漢字", "is_correct": false, "explanation": "国語で習う文字で、理科の授業の内容としては合わない。"}], "explanations": {"ニューロン": "神経系の仕組みを指すので、理科の授業で習う対象として正解。", "俳句": "文学の一種で、理科の授業で仕組みを習う対象ではない。", "水泳": "運動の一種で、「しくみ」を習う対象として成り立たない。", "漢字": "国語で習う文字で、理科の授業の内容としては合わない。"}, "sentence_index": 6, "correct_answer": "ニューロン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ニューロンは体の中枢で、すべての指令を出している。", "explanation": "ここは〈脳・脊髄〉の意味。ニューロンは一つの細胞で、脳や脊髄のような大きな組織ではない。"}, {"text": "ニューロンが破れて、血が外に出てしまった。", "explanation": "ここは〈血管〉の意味。血管は血を通す管で、ニューロンは血を通すものではない。"}, {"text": "家の電線が古くなったので、ニューロンを張り直した。", "explanation": "ここは〈電気を通す導線〉の意味。ニューロンは体の細胞で、電気を通す導線を指す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36712, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ニューロンを情報を送るので、指を動かせる。", "corrected_sentence": "ニューロンが情報を送るので、指を動かせる。", "error_description": "「送る」の主語を表す助詞は「が」。「を」にすると、目的語が二つ並んで文が崩れる。正しくは「ニューロンが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36712, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ニューロンを弱ると、手に力が入りにくくなる。", "corrected_sentence": "ニューロンが弱ると、手に力が入りにくくなる。", "error_description": "「弱る」は目的語を取らない自動詞なので、主語には「が」を使う。「を」は不自然。正しくは「ニューロンが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36713, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「ニューロン」を主題として示す助詞で、定義文の書き出しに合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、主題にはならない。送るの対象を示すと文が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を続けるだけで、文の主題や主語を示さない。「脳のニューロンの、」では述語に続かず文が成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、定義の主題を示せない。"}], "correct_answer": "は", "explanations": {"は": "「ニューロン」を主題として示す助詞で、定義文の書き出しに合う。", "を": "目的語を示す助詞で、主題にはならない。送るの対象を示すと文が崩れる。", "の": "「の」は名詞を続けるだけで、文の主題や主語を示さない。「脳のニューロンの、」では述語に続かず文が成立しない。", "より": "比較の助詞で、定義の主題を示せない。"}, "error_tags": {"を": "目的語", "より": "比較", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36713, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ニューロンの働き」と所属を示す助詞として自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「ニューロンが働き」では所属の関係にならず、「働き」の前に続かない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示す。「ニューロンに働き」では所属を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「ニューロンで働き」では所属の関係にならない。"}], "correct_answer": "の", "explanations": {"の": "「ニューロンの働き」と所属を示す助詞として自然に続く。", "が": "「が」は主語を示す。「ニューロンが働き」では所属の関係にならず、「働き」の前に続かない。", "に": "「に」は位置や相手を示す。「ニューロンに働き」では所属を表せない。", "で": "「で」は手段や場所を示す。「ニューロンで働き」では所属の関係にならない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36713, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "神経細胞のこと。脳や体のすみずみにあって、電気の信号で情報をやりとりし、考える・動く・感じるなどの働きをになう。", "primary_collocate": null, "pronunciation": "にゅーろん", "ipa": "ɲɯːɾoɴ", "syllable_count": 4, "sentences": [{"text": "ニューロンとは、電気の信号で情報をやりとりする神経細胞のことだ。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "ニューロンとは、電気[でんき]の信号[しんごう]で情報[じょうほう]をやりとりする神経細胞[しんけいさいぼう]のことだ。", "sentence_source": "generated"}, {"text": "脳のニューロンは、電気の信号を次の細胞へ送る。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "脳[のう]のニューロンは、電気[でんき]の信号[しんごう]を次[つぎ]の細胞[さいぼう]へ送[おく]る。", "sentence_source": "generated"}, {"text": "研究者は、ニューロンの活動を顕微鏡で観察した。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]は、ニューロンの活動[かつどう]を顕微鏡[けんびきょう]で観察[かんさつ]した。", "sentence_source": "generated"}, {"text": "ニューロンは体のすみずみにあり、感じる働きをになっている。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "ニューロンは体[からだ]のすみずみにあり、感[かん]じる働[はたら]きをになっている。", "sentence_source": "generated"}, {"text": "けがで一部のニューロンがこわれると、手足が動かしにくくなる。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "けがで一部[いちぶ]のニューロンがこわれると、手足[てあし]が動[うご]かしにくくなる。", "sentence_source": "generated"}, {"text": "ニューロンどうしのつながりが増えると、考える力も育つ。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "ニューロンどうしのつながりが増[ふ]えると、考[かんが]える力[ちから]も育[そだ]つ。", "sentence_source": "generated"}, {"text": "医者は、神経の病気はニューロンがこわれることで起こると説明した。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "医者[いしゃ]は、神経[しんけい]の病気[びょうき]はニューロンがこわれることで起[お]こると説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この本は、ニューロンの働きを絵でわかりやすく説明している。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "この本[ほん]は、ニューロンの働[はたら]きを絵[え]でわかりやすく説明[せつめい]している。", "sentence_source": "generated"}, {"text": "眠っている間も、ニューロンは電気の信号を出し続けている。", "target_word": "ニューロン", "complexity_tier": "T4", "furigana": "眠[ねむ]っている間[あいだ]も、ニューロンは電気[でんき]の信号[しんごう]を出[だ]し続[つづ]けている。", "sentence_source": "generated"}, {"text": "痛みを感じるのは、ニューロンが信号を脳に伝えるからだ。", "target_word": "ニューロン", "complexity_tier": "T3", "furigana": "痛[いた]みを感[かん]じるのは、ニューロンが信号[しんごう]を脳[のう]に伝[つた]えるからだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ニューロン", "label": "基本形"}, {"form": "ニューロンは", "label": "は格"}, {"form": "ニューロンを", "label": "を格"}], "register": "neutral", "sense_fingerprint": "電気の信号で情報をやりとりする神経細胞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36713, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ニューロン", "is_correct": true, "explanation": "電気の信号で情報をやりとりする神経細胞を指すので、定義文の主語として正解。"}, {"text": "骨格", "is_correct": false, "explanation": "体を支える骨の組み合わせで、神経細胞ではない。"}, {"text": "血液", "is_correct": false, "explanation": "体内を流れる液体の組織で、電気の信号で情報を伝える細胞ではない。"}, {"text": "筋肉", "is_correct": false, "explanation": "体を動かす組織で、情報をやりとりする神経細胞とは別物。"}], "explanations": {"ニューロン": "電気の信号で情報をやりとりする神経細胞を指すので、定義文の主語として正解。", "骨格": "体を支える骨の組み合わせで、神経細胞ではない。", "血液": "体内を流れる液体の組織で、電気の信号で情報を伝える細胞ではない。", "筋肉": "体を動かす組織で、情報をやりとりする神経細胞とは別物。"}, "sentence_index": 0, "correct_answer": "ニューロン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事な試験の前で、ニューロンがピリピリしている。", "explanation": "ここは〈神経〉の「気持ちが張りつめる」意味。ニューロンは細胞の名前なので、気持ちには使わない。"}, {"text": "リモコンの電池が切れたので、ニューロンを入れ替えた。", "explanation": "ここは〈バッテリー〉の意味。ニューロンは体の細胞で、機器の動力源を指す言葉ではない。"}, {"text": "ニューロンが破れて、血が外に出てしまった。", "explanation": "ここは〈血管〉の意味。血管は血を通す管で、ニューロンは血を通すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36713, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ニューロン", "is_correct": true, "explanation": "神経の病気の原因として説明される神経細胞なので、正解。"}, {"text": "天気", "is_correct": false, "explanation": "気象の状態で、「こわれる」という説明とは合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい感覚で、病気の原因として「こわれる」ものではない。"}, {"text": "試験", "is_correct": false, "explanation": "学習の評価の機会で、体の中で「こわれる」ものではない。"}], "explanations": {"ニューロン": "神経の病気の原因として説明される神経細胞なので、正解。", "天気": "気象の状態で、「こわれる」という説明とは合わない。", "眠気": "眠たい感覚で、病気の原因として「こわれる」ものではない。", "試験": "学習の評価の機会で、体の中で「こわれる」ものではない。"}, "sentence_index": 6, "correct_answer": "ニューロン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ニューロンは体の中枢で、すべての指令を出している。", "explanation": "ここは〈脳・脊髄〉の意味。ニューロンは一つの細胞で、脳や脊髄のような大きな組織ではない。"}, {"text": "ニューロンは血液を送る大切な器官だ。", "explanation": "ここは〈臓器〉の意味。ニューロンは神経細胞で、体の働きを担う臓器とは別物だ。"}, {"text": "家の電線が古くなったので、ニューロンを張り直した。", "explanation": "ここは〈電気を通す導線〉の意味。ニューロンは体の細胞で、電気を通す導線を指す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36713, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ニューロンを電気の信号を次の細胞へ送るしくみだ。", "corrected_sentence": "ニューロンが電気の信号を次の細胞へ送るしくみだ。", "error_description": "「送る」の主語は「が」で表す。「を」にすると目的語が重なり、文が崩れる。正しくは「ニューロンが」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36713, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ニューロンを弱ると、手足の感覚が鈍くなる。", "corrected_sentence": "ニューロンが弱ると、手足の感覚が鈍くなる。", "error_description": "「弱る」は目的語を取らない自動詞なので、主語には「が」を使う。「を」は不自然。正しくは「ニューロンが」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36714, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「自閉から抜け出す」の「から」は、閉じこもった状態を出発点として表す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「自閉で抜け出す」とは言えず合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点や対象を表すので、「自閉に抜け出す」とは言えず合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「抜け出す」は出発点を取るので「自閉へ抜け出す」とは言わない。"}], "correct_answer": "から", "explanations": {"から": "「自閉から抜け出す」の「から」は、閉じこもった状態を出発点として表す。", "で": "「で」は場所や手段を表すので、「自閉で抜け出す」とは言えず合わない。", "に": "「に」は到着点や対象を表すので、「自閉に抜け出す」とは言えず合わない。", "へ": "「へ」は方向を表すが、「抜け出す」は出発点を取るので「自閉へ抜け出す」とは言わない。"}, "error_tags": {"で": "場所・手段", "に": "帰着・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36714, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「自閉の状態」の「の」は、「自閉」が「状態」を修飾する連体修飾を作る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すので、「自閉が状態」とは続かず合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すが、「自閉を状態」では名詞どうしがつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「自閉で状態」とは続かず合わない。"}], "correct_answer": "の", "explanations": {"の": "「自閉の状態」の「の」は、「自閉」が「状態」を修飾する連体修飾を作る。", "が": "「が」は主語を表すので、「自閉が状態」とは続かず合わない。", "を": "「を」は目的語を表すが、「自閉を状態」では名詞どうしがつながらない。", "で": "「で」は場所や手段を表すので、「自閉で状態」とは続かず合わない。"}, "error_tags": {"が": "主格", "を": "対象", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36714, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の気持ちや考えを、ほかの人とあまり話さないこと。", "primary_collocate": null, "pronunciation": "じへい", "ipa": "dʑihei", "syllable_count": 3, "sentences": [{"text": "彼は転校してから、自閉の日々が続いた。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "彼[かれ]は転校[てんこう]してから、自閉[じへい]の日々[ひび]が続[つづ]いた。", "sentence_source": "generated"}, {"text": "長い自閉から抜け出し、友人に電話をかけた。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "長[なが]い自閉[じへい]から抜[ぬ]け出[だ]し、友人[ゆうじん]に電話[でんわ]をかけた。", "sentence_source": "generated"}, {"text": "自閉が続くと、周りの人は心配になる。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "自閉[じへい]が続[つづ]くと、周[まわ]りの人[ひと]は心配[しんぱい]になる。", "sentence_source": "generated"}, {"text": "彼女は悲しみのあまり、自閉に陥ってしまった。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は悲[かな]しみのあまり、自閉[じへい]に陥[おちい]ってしまった。", "sentence_source": "generated"}, {"text": "先生は彼が自閉になった理由を無理に聞かなかった。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "[先生|せんせい]は[彼|かれ]が[自閉|じへい]になった[理由|りゆう]を[無理|むり]に[聞|き]かなかった。", "sentence_source": "generated"}, {"text": "彼の自閉は、いじめがきっかけで始まった。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "彼[かれ]の自閉[じへい]は、いじめがきっかけで始[はじ]まった。", "sentence_source": "generated"}, {"text": "自閉から抜け出すには、安心して話せる相手が必要だ。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "[自閉|じへい]から[抜|ぬ]け[出|だ]すには、[安心|あんしん]して[話|はな]せる[相手|あいて]が[必要|ひつよう]だ。", "sentence_source": "generated"}, {"text": "兄は仕事を失ってから、家族とも話さない自閉の状態にあった。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "兄[あに]は仕事[しごと]を失[うしな]ってから、家族[かぞく]とも話[はな]さない自閉[じへい]の状態[じょうたい]にあった。", "sentence_source": "generated"}, {"text": "自閉から少しずつ抜け出して、彼は再び笑うようになった。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "自閉[じへい]から少[すこ]しずつ抜[ぬ]け出[だ]して、彼[かれ]は再[ふたた]び笑[わら]うようになった。", "sentence_source": "generated"}, {"text": "長い自閉を経て、彼女はようやく自分の気持ちを話し始めた。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "長[なが]い自閉[じへい]を経[へ]て、彼女[かのじょ]はようやく自分[じぶん]の気持[きも]ちを話[はな]し始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自閉", "label": "名詞形"}, {"form": "自閉の", "label": "連体形"}, {"form": "自閉から", "label": "格助詞つき形"}], "register": "neutral-written", "sense_fingerprint": "気持ちや考えを人に話さず、閉じこもること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36714, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自閉", "is_correct": true, "explanation": "「自閉の日々」は人と話さず閉じこもって過ごした日々を表し、この文に合う。"}, {"text": "自信", "is_correct": false, "explanation": "「自信の日々」は意味が通らず、人と話さない状態の説明にはならない。"}, {"text": "自覚", "is_correct": false, "explanation": "「自覚の日々」は不自然で、閉じこもって話さない状態を表さないので合わない。"}, {"text": "自重", "is_correct": false, "explanation": "「自重の日々」は不自然で、慎んで行動する意味は人と話さない状態を表さない。"}], "explanations": {"自閉": "「自閉の日々」は人と話さず閉じこもって過ごした日々を表し、この文に合う。", "自信": "「自信の日々」は意味が通らず、人と話さない状態の説明にはならない。", "自覚": "「自覚の日々」は不自然で、閉じこもって話さない状態を表さないので合わない。", "自重": "「自重の日々」は不自然で、慎んで行動する意味は人と話さない状態を表さない。"}, "sentence_index": 0, "correct_answer": "自閉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "感染が広がったので、週末の外出は自閉することにした。", "explanation": "ここは〈自粛〉の意味。自閉は気持ちを閉ざす意味なので、外出を控える場面には合わない。"}, {"text": "店は客が来ないので自閉した。", "explanation": "ここは〈閉店〉の意味。自閉は気持ちを閉ざす意味なので、店が営業をやめる場面には合わない。"}, {"text": "会議中、彼は自閉を守っていた。", "explanation": "ここは〈沈黙〉の意味。沈黙は「守る」と結びつくが、自閉は人との関わりを避ける状態なので「守る」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36714, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自閉", "is_correct": true, "explanation": "「自閉から抜け出す」は閉じこもった状態から出ることを表し、この文に合う。"}, {"text": "自炊", "is_correct": false, "explanation": "「自炊から抜け出す」は意味が通らず、閉じこもりの状態を指さない。"}, {"text": "自治", "is_correct": false, "explanation": "「自治から抜け出す」は不自然で、人と話さない状態には当てはまらない。"}, {"text": "自習", "is_correct": false, "explanation": "「自習から抜け出す」は言えず、気持ちを話さない状態の説明にはならない。"}], "explanations": {"自閉": "「自閉から抜け出す」は閉じこもった状態から出ることを表し、この文に合う。", "自炊": "「自炊から抜け出す」は意味が通らず、閉じこもりの状態を指さない。", "自治": "「自治から抜け出す」は不自然で、人と話さない状態には当てはまらない。", "自習": "「自習から抜け出す」は言えず、気持ちを話さない状態の説明にはならない。"}, "sentence_index": 6, "correct_answer": "自閉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体調がよくないので、激しい運動を自閉した。", "explanation": "ここは〈自重〉の意味。自閉は気持ちを閉ざす意味なので、激しい運動を控える場面には合わない。"}, {"text": "寒いので、窓を自閉した。", "explanation": "ここは〈閉める〉の意味。自閉は気持ちを閉ざす意味なので、窓を閉じる動作には合わない。"}, {"text": "会議の資料を、彼は自閉した。", "explanation": "ここは〈提出〉の意味。自閉は気持ちを閉ざす意味なので、資料を出す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36714, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は学校を辞めてから、自閉に日々が続いた。", "corrected_sentence": "彼は学校を辞めてから、自閉の日々が続いた。", "error_description": "「自閉」は名詞「日々」を修飾するので連体修飾の「の」が必要。「に」は誤りで、「自閉の日々」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36714, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長い自閉に抜け出すには、信頼できる友人が必要だ。", "corrected_sentence": "長い自閉から抜け出すには、信頼できる友人が必要だ。", "error_description": "「抜け出す」は出発点を「から」で表す。「に」は誤りで、「自閉から抜け出す」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
