INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36715, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "他人との関わりやコミュニケーションを避け、自分の内側にこもる傾向があること。また、そのような状態。", "primary_collocate": null, "pronunciation": "じへい", "ipa": "dʑihei", "syllable_count": 3, "sentences": [{"text": "自閉の傾向が強まると、人との会話を避けるようになる。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "自閉[じへい]の傾向[けいこう]が強[つよ]まると、人[ひと]との会話[かいわ]を避[さ]けるようになる。", "sentence_source": "generated"}, {"text": "長い入院生活で、彼は自閉の状態になった。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "長[なが]い入院生活[にゅういんせいかつ]で、彼[かれ]は自閉[じへい]の状態[じょうたい]になった。", "sentence_source": "generated"}, {"text": "周りの理解が、自閉の状態から抜け出す助けになる。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "[周|まわ]りの[理解|りかい]が、[自閉|じへい]の[状態|じょうたい]から[抜|ぬ]け[出|だ]す[助|たす]けになる。", "sentence_source": "generated"}, {"text": "自閉の殻を破るのは、簡単なことではない。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "自閉[じへい]の殻[から]を破[やぶ]るのは、簡単[かんたん]なことではない。", "sentence_source": "generated"}, {"text": "彼女の自閉は、人間関係に疲れたことから生じた。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の自閉[じへい]は、人間関係[にんげんかんけい]に疲[つか]れたことから生[しょう]じた。", "sentence_source": "generated"}, {"text": "自閉が深まると、メールの返事さえ書けなくなる。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "自閉[じへい]が深[ふか]まると、メールの返事[へんじ]さえ書[か]けなくなる。", "sentence_source": "generated"}, {"text": "ネットだけの生活が、若者の自閉を強めているという指摘がある。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "ネットだけの生活[せいかつ]が、若者[わかもの]の自閉[じへい]を強[つよ]めているという指摘[してき]がある。", "sentence_source": "generated"}, {"text": "先生は、生徒の自閉のサインを見逃さないようにしている。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の自閉[じへい]のサインを見逃[みのが]さないようにしている。", "sentence_source": "generated"}, {"text": "自閉の状態が長引いたので、家族が相談窓口を訪ねた。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "自閉[じへい]の状態[じょうたい]が長引[ながび]いたので、家族[かぞく]が相談窓口[そうだんまどぐち]を訪[たず]ねた。", "sentence_source": "generated"}, {"text": "自閉の期間を過ぎて、彼は人前で話せるようになった。", "target_word": "自閉", "complexity_tier": "T3", "furigana": "自閉[じへい]の期間[きかん]を過[す]ぎて、彼[かれ]は人前[ひとまえ]で話[はな]せるようになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自閉", "label": "名詞形"}, {"form": "自閉の", "label": "連体形"}, {"form": "自閉が", "label": "格助詞つき形"}], "register": "neutral-written", "sense_fingerprint": "人との関わりを避けて内にこもる傾向や状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bffff8f7-34bc-4ee6-b9ae-720d65edf148') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36715, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自閉", "is_correct": true, "explanation": "「自閉の傾向」は人との関わりを避けて内にこもる傾向を表し、この文に合う。"}, {"text": "自炊", "is_correct": false, "explanation": "「自炊の傾向」は意味が通らず、人との会話を避ける傾向とは関係しない。"}, {"text": "自習", "is_correct": false, "explanation": "「自習の傾向」は不自然で、人との関わりを避ける傾向を表さない。"}, {"text": "自治", "is_correct": false, "explanation": "「自治の傾向」は言えず、人と会話を避けるという性質を表さない。"}], "explanations": {"自閉": "「自閉の傾向」は人との関わりを避けて内にこもる傾向を表し、この文に合う。", "自炊": "「自炊の傾向」は意味が通らず、人との会話を避ける傾向とは関係しない。", "自習": "「自習の傾向」は不自然で、人との関わりを避ける傾向を表さない。", "自治": "「自治の傾向」は言えず、人と会話を避けるという性質を表さない。"}, "sentence_index": 0, "correct_answer": "自閉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一人暮らしを始めて、毎日の食事を自閉している。", "explanation": "ここは〈自炊〉の意味。自閉は気持ちを閉ざす意味なので、自分で料理をする場面には合わない。"}, {"text": "授業中、彼は自閉を守っていた。", "explanation": "ここは〈沈黙〉の意味。沈黙は「守る」と結びつくが、自閉は人との関わりを避ける状態なので「守る」とは合わない。"}, {"text": "庭で育てた米を、自閉している。", "explanation": "ここは〈自給〉の意味。自閉は気持ちを閉ざす意味なので、自分で作った米を賄う場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36715, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自閉", "is_correct": true, "explanation": "「自閉を強める」は人との関わりを避ける傾向を強めるという意味で、この文に合う。"}, {"text": "自給", "is_correct": false, "explanation": "「自給を強める」は言えず、人との関わりを避ける傾向とは関係しない。"}, {"text": "自戒", "is_correct": false, "explanation": "「自戒を強める」は不自然で、人との関わりを避ける傾向を表さない。"}, {"text": "自主", "is_correct": false, "explanation": "「自主を強める」は言えず、人と関わらなくなる傾向を表さない。"}], "explanations": {"自閉": "「自閉を強める」は人との関わりを避ける傾向を強めるという意味で、この文に合う。", "自給": "「自給を強める」は言えず、人との関わりを避ける傾向とは関係しない。", "自戒": "「自戒を強める」は不自然で、人との関わりを避ける傾向を表さない。", "自主": "「自主を強める」は言えず、人と関わらなくなる傾向を表さない。"}, "sentence_index": 6, "correct_answer": "自閉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "怪我をしないよう、激しい練習を自閉した。", "explanation": "ここは〈自重〉の意味。自閉は気持ちを閉ざす意味なので、行動を控える場面には合わない。"}, {"text": "夜の山小屋は、自閉に包まれていた。", "explanation": "ここは〈静寂〉の意味。自閉は人の気持ちの状態を表すので、場所の静けさには使わない。"}, {"text": "屋根の雪を、彼は自閉した。", "explanation": "ここは〈除雪〉の意味。自閉は気持ちを閉ざす意味なので、雪を取り除く場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36715, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの自閉に傾向が強まると、家族は不安になる。", "corrected_sentence": "子どもの自閉の傾向が強まると、家族は不安になる。", "error_description": "「自閉」は名詞「傾向」を修飾するので連体修飾の「の」が必要。「に」は誤りで、「自閉の傾向」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36715, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近、若者の自閉を強まっているという指摘がある。", "corrected_sentence": "最近、若者の自閉が強まっているという指摘がある。", "error_description": "「強まる」は自動詞なので主語に「が」を使う。「を」は誤りで、「自閉が強まっている」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cb405c9-2d9f-4d67-9616-623314a1f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36716, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。主語を示す「が」で、「スペクトラムができる」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」になり、「できる」の形に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、「スペクトラムへできる」とは言わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、「スペクトラムよりできる」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。主語を示す「が」で、「スペクトラムができる」の形になる。", "を": "目的語の「を」になり、「できる」の形に合わない。", "へ": "方向を示す「へ」で、「スペクトラムへできる」とは言わない。", "より": "比較の「より」で、「スペクトラムよりできる」は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
