INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36716, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "色の帯が連なったものを言います。", "primary_collocate": null, "pronunciation": "すぺくとらむ", "ipa": "sɯpekɯtoɾamɯ", "syllable_count": 6, "sentences": [{"text": "窓のガラスに光が当たって、壁に赤から紫までのスペクトラムが映った。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "窓[まど]のガラスに光[ひかり]が当[あ]たって、壁[かべ]に赤[あか]から紫[むらさき]までのスペクトラムが映[うつ]った。", "sentence_source": "generated"}, {"text": "プリズムに光を通すと、きれいなスペクトラムができる。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "プリズムに光[ひかり]を通[とお]すと、きれいなスペクトラムができる。", "sentence_source": "generated"}, {"text": "理科の授業で、太陽の光のスペクトラムを調べた。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、太陽[たいよう]の光[ひかり]のスペクトラムを調[しら]べた。", "sentence_source": "generated"}, {"text": "スペクトラムでは、赤の隣にだいだい色が並んでいる。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "スペクトラムでは、赤[あか]の隣[となり]にだいだい色[いろ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "白い光は、スペクトラムに分けると何色にも分かれる。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "白[しろ]い光[ひかり]は、スペクトラムに分[わ]けると何色[なにいろ]にも分[わ]かれる。", "sentence_source": "generated"}, {"text": "先生は黒板に、色のスペクトラムを七つの帯で描いた。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に、色[いろ]のスペクトラムを七[なな]つの帯[おび]で描[えが]いた。", "sentence_source": "generated"}, {"text": "紙に絵の具で、青から黄色へ変わるスペクトラムを描いた。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "紙[かみ]に絵[え]の具[ぐ]で、青[あお]から黄色[きいろ]へ変[か]わるスペクトラムを描[えが]いた。", "sentence_source": "generated"}, {"text": "水のしぶきに光が当たって、小さなスペクトラムができた。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "水[みず]のしぶきに光[ひかり]が当[あ]たって、小[ちい]さなスペクトラムができた。", "sentence_source": "generated"}, {"text": "スペクトラムの色は、境目がなく、少しずつ変わっていく。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "スペクトラムの色[いろ]は、境目[さかいめ]がなく、少[すこ]しずつ変[か]わっていく。", "sentence_source": "generated"}, {"text": "博物館では、ガラスを使ってスペクトラムを作る実験ができる。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、ガラスを使[つか]ってスペクトラムを作[つく]る実験[じっけん]ができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スペクトラム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "光が分かれてできる、連なった色の帯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36716, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スペクトラム", "is_correct": true, "explanation": "正解。光が分かれてできる色の帯で、映る対象になる。"}, {"text": "輪郭", "is_correct": false, "explanation": "形の外側の線を指し、色の帯が映る文には合わない。"}, {"text": "凹凸", "is_correct": false, "explanation": "表面のでこぼこを表し、色の見え方には当てはまらない。"}, {"text": "ゆがみ", "is_correct": false, "explanation": "形のずれを表し、色が連なって映る様子とは合わない。"}], "explanations": {"スペクトラム": "正解。光が分かれてできる色の帯で、映る対象になる。", "輪郭": "形の外側の線を指し、色の帯が映る文には合わない。", "凹凸": "表面のでこぼこを表し、色の見え方には当てはまらない。", "ゆがみ": "形のずれを表し、色が連なって映る様子とは合わない。"}, "sentence_index": 0, "correct_answer": "スペクトラム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓辺で、スペクトラムが光を七色に分けた。", "explanation": "ここは〈プリズム〉の意味。光を分けるのはプリズムで、色の帯のスペクトラムは分ける道具ではない。"}, {"text": "彼女はスペクトラムがおしゃれで、会うたびに驚かされる。", "explanation": "ここは〈髪型〉の意味。スペクトラムは光の色の帯で、髪型の見た目は指さない。"}, {"text": "布に水玉のスペクトラムが入っている。", "explanation": "ここは〈模様〉の意味。水玉のような図柄は色の帯とは呼ばない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36716, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スペクトラム", "is_correct": true, "explanation": "正解。青から黄色へ連なる色の帯で、描く対象になる。"}, {"text": "残像", "is_correct": false, "explanation": "目を閉じても残る像を指し、描く対象にはならない。"}, {"text": "屈折", "is_correct": false, "explanation": "光が曲がる現象の意味で、絵に描く対象には合わない。"}, {"text": "反射", "is_correct": false, "explanation": "光がはね返る現象の意味で、色の連なりを描く対象ではない。"}], "explanations": {"スペクトラム": "正解。青から黄色へ連なる色の帯で、描く対象になる。", "残像": "目を閉じても残る像を指し、描く対象にはならない。", "屈折": "光が曲がる現象の意味で、絵に描く対象には合わない。", "反射": "光がはね返る現象の意味で、色の連なりを描く対象ではない。"}, "sentence_index": 6, "correct_answer": "スペクトラム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方、台所で、スペクトラムを瓶に詰めた。", "explanation": "ここは〈ジャム〉の意味。瓶に詰めるのは食べ物で、色の帯は詰められない。"}, {"text": "壁のスペクトラムを飲み干した。", "explanation": "ここは〈飲み物〉の意味。飲み干すのは液体で、色の帯は飲めない。"}, {"text": "夏祭りでスペクトラムを打ち上げた。", "explanation": "ここは〈花火〉の意味。打ち上げるのは花火で、スペクトラムは打ち上げられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36716, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝の窓辺に光が差して、小さなスペクトラムをできた。", "corrected_sentence": "朝の窓辺に光が差して、小さなスペクトラムができた。", "error_description": "「できる」は自動詞なので、主語のスペクトラムには「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36716, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "プリズムは白い光を、きれいなスペクトラムに消した。", "corrected_sentence": "プリズムは白い光を、きれいなスペクトラムに分けた。", "error_description": "「消す」では光を色の帯にする意味にならない。光を分けて帯を作るには「分ける」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
