INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36717, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。主語を示す「が」で、「スペクトラムが幅広い」と述べる形になる。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」で、「スペクトラムと幅広く」は続かない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」で、「スペクトラムの幅広く」は文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」で、「スペクトラムから幅広く」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "正解。主語を示す「が」で、「スペクトラムが幅広い」と述べる形になる。", "と": "並列の「と」で、「スペクトラムと幅広く」は続かない。", "の": "連体の「の」で、「スペクトラムの幅広く」は文が成り立たない。", "から": "起点の「から」で、「スペクトラムから幅広く」は意味が通らない。"}, "error_tags": {"と": "並列", "の": "連体", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36717, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "電磁波の波長の違いによって現れる、色の連続した帯。転じて、さまざまな要素が連続的に分布する範囲。", "primary_collocate": null, "pronunciation": "すぺくとらむ", "ipa": "sɯpekɯtoɾamɯ", "syllable_count": 6, "sentences": [{"text": "電磁波は、波長の長さによってスペクトラムに分けられる。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "電磁波[でんじは]は、波長[はちょう]の長[なが]さによってスペクトラムに分[わ]けられる。", "sentence_source": "generated"}, {"text": "目に見える光は、電波の広いスペクトラムの一部にすぎない。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "目[め]に見[み]える光[ひかり]は、電波[でんぱ]の広[ひろ]いスペクトラムの一部[いちぶ]にすぎない。", "sentence_source": "generated"}, {"text": "自閉症は、症状の重さが人によってちがうスペクトラムだと考えられている。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "自閉[じへい]症[しょう]は、症状[しょうじょう]の重[おも]さが人[ひと]によってちがうスペクトラムだと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "政治的な考え方は、右から左まで幅広いスペクトラムをなしている。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "政治的[せいじてき]な考[かんが]え方[かた]は、右[みぎ]から左[ひだり]まで幅広[はばひろ]いスペクトラムをなしている。", "sentence_source": "generated"}, {"text": "科学者は、星の光のスペクトラムから、その星の成分を調べる。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]は、星[ほし]の光[ひかり]のスペクトラムから、その星[ほし]の成分[せいぶん]を調[しら]べる。", "sentence_source": "generated"}, {"text": "アンケートでは、とても満足からまったく不満までのスペクトラムで意見を集めた。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "アンケートでは、とても満足[まんぞく]からまったく不満[ふまん]までのスペクトラムで意見[いけん]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "赤外線は、光のスペクトラムのなかで赤の外側にある。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "赤外線[せきがいせん]は、光[ひかり]のスペクトラムのなかで赤[あか]の外側[そとがわ]にある。", "sentence_source": "generated"}, {"text": "この店の客は、年齢のスペクトラムが幅広く、子どもから高齢者までいる。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "この店[みせ]の客[きゃく]は、年齢[ねんれい]のスペクトラムが幅広[はばひろ]く、子[こ]どもから高齢者[こうれいしゃ]までいる。", "sentence_source": "generated"}, {"text": "虹の七色は、連続したスペクトラムを人が七つに分けたものだ。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "虹[にじ]の七色[ななしょく]は、連続[れんぞく]したスペクトラムを人[ひと]が七[なな]つに分[わ]けたものだ。", "sentence_source": "generated"}, {"text": "音にも周波数のスペクトラムがあり、機械でグラフにして調べられる。", "target_word": "スペクトラム", "complexity_tier": "T3", "furigana": "音[おと]にも周波数[しゅうはすう]のスペクトラムがあり、機械[きかい]でグラフにして調[しら]べられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スペクトラム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "波長の違いで分かれる連続した帯。転じて、要素が連続的に分布する範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36717, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スペクトラム", "is_correct": true, "explanation": "正解。波長によって分けられる連なった範囲で、ここに入る。"}, {"text": "プリズム", "is_correct": false, "explanation": "光を分ける道具で、分けられる対象にはならないので合わない。"}, {"text": "レンズ", "is_correct": false, "explanation": "光を集めたり曲げたりする道具で、分けられる対象にはならない。"}, {"text": "フィルター", "is_correct": false, "explanation": "特定の光を通す器具で、分けられる対象にはならない。"}], "explanations": {"スペクトラム": "正解。波長によって分けられる連なった範囲で、ここに入る。", "プリズム": "光を分ける道具で、分けられる対象にはならないので合わない。", "レンズ": "光を集めたり曲げたりする道具で、分けられる対象にはならない。", "フィルター": "特定の光を通す器具で、分けられる対象にはならない。"}, "sentence_index": 0, "correct_answer": "スペクトラム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "チームは大会で、ついにスペクトラムに立った。", "explanation": "ここは〈頂点〉の意味。スペクトラムは一点ではなく範囲を表すので、頂点の代わりにはならない。"}, {"text": "このバスのスペクトラムは三十人だ。", "explanation": "ここは〈定員〉の意味。人数の上限を数で表す語で、範囲の広がりを指すスペクトラムは使わない。"}, {"text": "テストのスペクトラムを計算した。", "explanation": "ここは〈平均〉の意味。計算で求める数値を指す語で、範囲の広がりとは別のもの。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36717, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スペクトラム", "is_correct": true, "explanation": "正解。光が連なった範囲で、赤外線の位置を示す語になる。"}, {"text": "レーザー", "is_correct": false, "explanation": "一方向にそろった光を出す装置で、位置の範囲を表す語にはならない。"}, {"text": "フレーム", "is_correct": false, "explanation": "枠や骨組みの意味で、光の範囲には使わないので合わない。"}, {"text": "アングル", "is_correct": false, "explanation": "撮る角度を表す語で、光の連なりには当てはまらない。"}], "explanations": {"スペクトラム": "正解。光が連なった範囲で、赤外線の位置を示す語になる。", "レーザー": "一方向にそろった光を出す装置で、位置の範囲を表す語にはならない。", "フレーム": "枠や骨組みの意味で、光の範囲には使わないので合わない。", "アングル": "撮る角度を表す語で、光の連なりには当てはまらない。"}, "sentence_index": 6, "correct_answer": "スペクトラム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜更けに、スペクトラムが鍋を焦がした。", "explanation": "ここは〈焦げ〉の意味。焦がすのは食べ物で、範囲を表すスペクトラムは焦がせない。"}, {"text": "スピーカーのスペクトラムを上げた。", "explanation": "ここは〈音量〉の意味。上げるのは音の大きさで、光の連なりは上げられない。"}, {"text": "少しずつスペクトラムを踏んで、練習を進めた。", "explanation": "ここは〈段階〉の意味。段階は踏むもので、範囲を表すスペクトラムは踏めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36717, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新製品について、満足から不満までのスペクトラムを意見を集めた。", "corrected_sentence": "新製品について、満足から不満までのスペクトラムで意見を集めた。", "error_description": "「集める」の手段・範囲を表す「で」が正しい。「を」を二つ続けると目的語が重なり、誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36717, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店の客は、年齢のスペクトラムが広めて、若者から高齢者まで集まっている。", "corrected_sentence": "この店の客は、年齢のスペクトラムが広くて、若者から高齢者まで集まっている。", "error_description": "「広める」は他動詞なので、主語のスペクトラムには形容詞「広い」を使う。「広くて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36718, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「選ぶ」の目的語を示す。一つの個体を選ぶので正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。個体が選ぶ側ではないので、この文では意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示す。選ぶ対象そのものには「に」を使わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。選ぶという動作の対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "「選ぶ」の目的語を示す。一つの個体を選ぶので正解。", "が": "主語を示す。個体が選ぶ側ではないので、この文では意味が通らない。", "に": "相手や場所を示す。選ぶ対象そのものには「に」を使わない。", "へ": "方向を示す。選ぶという動作の対象には使えない。"}, "error_tags": {"が": "主語", "に": "相手・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
