INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36718, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "一人ひとりの生き物や物を、ひとつのかたまりとして見たときの言い方。", "primary_collocate": null, "pronunciation": "こたい", "ipa": "kotai", "syllable_count": 3, "sentences": [{"text": "同じ種類の貝でも、一つ一つの個体を見ると模様が少しずつ違います。", "target_word": "個体", "complexity_tier": "T3", "furigana": "同[おな]じ種類[しゅるい]の貝[かい]でも、一[ひと]つ一[ひと]つの個体[こたい]を見[み]ると模様[もよう]が少[すこ]しずつ違[ちが]います。", "sentence_source": "generated"}, {"text": "実験では、まず一つの個体を選んで、体の大きさを測りました。", "target_word": "個体", "complexity_tier": "T3", "furigana": "実験[じっけん]では、まず一[ひと]つの個体[こたい]を選[えら]んで、体[からだ]の大[おお]きさを測[はか]りました。", "sentence_source": "generated"}, {"text": "群れの中の個体はそれぞれ違う顔をしているので、研究者は名前をつけて区別します。", "target_word": "個体", "complexity_tier": "T3", "furigana": "群[む]れの中[なか]の個体[こたい]はそれぞれ違[ちが]う顔[かお]をしているので、研究者[けんきゅうしゃ]は名前[なまえ]をつけて区別[くべつ]します。", "sentence_source": "generated"}, {"text": "このロボットは、個体によって動きが少し違うので、調整が必要です。", "target_word": "個体", "complexity_tier": "T3", "furigana": "このロボットは、個体[こたい]によって動[うご]きが少[すこ]し違[ちが]うので、調整[ちょうせい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "木をたくさん植えたが、弱い個体は冬を越せずに枯れてしまった。", "target_word": "個体", "complexity_tier": "T3", "furigana": "木[き]をたくさん植[う]えたが、弱[よわ]い個体[こたい]は冬[ふゆ]を越[こ]せずに枯[か]れてしまった。", "sentence_source": "generated"}, {"text": "この研究所では、飼育している個体すべてに番号をつけて記録しています。", "target_word": "個体", "complexity_tier": "T3", "furigana": "この研究所[けんきゅうじょ]では、飼育[しいく]している個体[こたい]すべてに番号[ばんごう]をつけて記録[きろく]しています。", "sentence_source": "generated"}, {"text": "全体の数ではなく、個体の特徴に注目して観察してください。", "target_word": "個体", "complexity_tier": "T3", "furigana": "全体[ぜんたい]の数[かず]ではなく、個体[こたい]の特徴[とくちょう]に注目[ちゅうもく]して観察[かんさつ]してください。", "sentence_source": "generated"}, {"text": "魚の群れから、大きな個体だけを網で捕まえました。", "target_word": "個体", "complexity_tier": "T3", "furigana": "魚[さかな]の群[む]れから、大[おお]きな個体[こたい]だけを網[あみ]で捕[つか]まえました。", "sentence_source": "generated"}, {"text": "小さな虫でも、一つの個体として数えれば一匹です。", "target_word": "個体", "complexity_tier": "T3", "furigana": "小[ちい]さな虫[むし]でも、一[ひと]つの個体[こたい]として数[かぞ]えれば一匹[いっぴき]です。", "sentence_source": "generated"}, {"text": "集団を理解するときも、まず一つの個体をよく知ることが大切です。", "target_word": "個体", "complexity_tier": "T3", "furigana": "集団[しゅうだん]を理解[りかい]するときも、まず一[ひと]つの個体[こたい]をよく知[し]ることが大切[たいせつ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "個体", "label": "基本形"}], "register": "中立", "sense_fingerprint": "全体や集団の中の、生き物や物の一つ一つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36718, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "個体", "is_correct": true, "explanation": "一つ一つの貝を指す語で、この空所に入る。"}, {"text": "全体", "is_correct": false, "explanation": "「一つ一つの」と並ばない。全体は個々を含むまとまりなので、個々の模様を見る文に合わない。"}, {"text": "総数", "is_correct": false, "explanation": "数の合計を表すので、「一つ一つの」を受けて模様を見る対象にはならない。"}, {"text": "群れ", "is_correct": false, "explanation": "まとまった集まりを指すので、一つ一つの貝という単位に当てはまらない。"}], "explanations": {"個体": "一つ一つの貝を指す語で、この空所に入る。", "全体": "「一つ一つの」と並ばない。全体は個々を含むまとまりなので、個々の模様を見る文に合わない。", "総数": "数の合計を表すので、「一つ一つの」を受けて模様を見る対象にはならない。", "群れ": "まとまった集まりを指すので、一つ一つの貝という単位に当てはまらない。"}, "sentence_index": 0, "correct_answer": "個体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水を冷やすと個体になり、氷ができる。", "explanation": "ここは〈固体〉（固まった状態）の意味。個体は一つの生き物や物を数える語で、物質の状態は表せない。"}, {"text": "この個体は会員が三十人いて、毎月活動している。", "explanation": "ここは〈団体〉（会員でつくる組織）の意味。個体は一つの生き物や物を指すので、複数の会員を持つ組織には合わない。"}, {"text": "彼女は個体が強く、どこにいてもすぐ目立つ。", "explanation": "ここは〈個性〉（人柄や特徴）の意味。個体は一つの単位を指す語で、人の性格の強さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36718, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "個体", "is_correct": true, "explanation": "「全体」と対比される、一つ一つの単位を指す語。ここで正解。"}, {"text": "数字", "is_correct": false, "explanation": "数を書いた記号で、「全体の数ではなく」と対比する観察対象にはならない。"}, {"text": "季節", "is_correct": false, "explanation": "「全体の数」との対比にならず、観察する特徴の対象として不自然。"}, {"text": "名前", "is_correct": false, "explanation": "呼び名を表すので、観察する特徴の対象にはならない。"}], "explanations": {"個体": "「全体」と対比される、一つ一つの単位を指す語。ここで正解。", "数字": "数を書いた記号で、「全体の数ではなく」と対比する観察対象にはならない。", "季節": "「全体の数」との対比にならず、観察する特徴の対象として不自然。", "名前": "呼び名を表すので、観察する特徴の対象にはならない。"}, "sentence_index": 6, "correct_answer": "個体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店では、お客様の個体情報を大切に守っています。", "explanation": "ここは〈個人情報〉（個人に関する情報）の意味。個体は一つの生き物や物を指す語で、人に関する情報には使わない。"}, {"text": "学校では、個体で給食を食べることが決まっている。", "explanation": "ここは〈個別〉（一人ずつ別々に）の意味。個体は生き物や物を数える名詞で、「個体で給食を食べる」のように副詞的には使えない。"}, {"text": "この蝋は冷えると個体になる。", "explanation": "ここは〈固体〉（固まった状態）の意味。個体は一つの生き物や物を数える語で、物質の状態は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36718, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は、群れの個体が一頭ずつ数えて、記録しました。", "corrected_sentence": "研究者は、群れの個体を一頭ずつ数えて、記録しました。", "error_description": "誤りは「個体が」。「数える」は数える対象を「を」で示すので、正しくは「個体を」。「個体が」だと個体が数える側になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36718, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、一頭ずつ個体に記録を取っています。", "corrected_sentence": "研究者は、一頭ずつ個体の記録を取っています。", "error_description": "誤りは「個体に」。「個体の記録」と「の」で結ぶのが正しく、「に」は相手や方向を示すので「記録を取る」と結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36719, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36719, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「足に」の「に」。輪をつける場所を示すので正解。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す。足で輪をつけるという意味になり不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「足を」と「輪を」が重なり、不自然な文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。足が輪をつける側になり、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「足に」の「に」。輪をつける場所を示すので正解。", "で": "手段を示す。足で輪をつけるという意味になり不自然。", "を": "目的語を示す。「足を」と「輪を」が重なり、不自然な文になる。", "が": "主語を示す。足が輪をつける側になり、意味が通らない。"}, "error_tags": {"で": "手段", "を": "目的語（重複）", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36719, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生物学的に一つのまとまりとして数えられる対象。特に、同じ種類の中で区別される一つの生き物。", "primary_collocate": null, "pronunciation": "こたい", "ipa": "kotai", "syllable_count": 3, "sentences": [{"text": "この島には、数十の個体しか残っていません。", "target_word": "個体", "complexity_tier": "T3", "furigana": "この島[しま]には、数十[すうじゅう]の個体[こたい]しか残[のこ]っていません。", "sentence_source": "generated"}, {"text": "研究者は、首の傷を目印にして、一頭ずつ個体を見分けています。", "target_word": "個体", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、首[くび]の傷[きず]を目印[めじるし]にして、一頭[いっとう]ずつ個体[こたい]を見分[みわ]けています。", "sentence_source": "generated"}, {"text": "同じ種類でも、成長した個体は子どもより体がずっと大きいです。", "target_word": "個体", "complexity_tier": "T3", "furigana": "同[おな]じ種類[しゅるい]でも、成長[せいちょう]した個体[こたい]は子[こ]どもより体[からだ]がずっと大[おお]きいです。", "sentence_source": "generated"}, {"text": "この鳥は個体によって鳴き声が違うので、声だけで仲間を見分けられる。", "target_word": "個体", "complexity_tier": "T3", "furigana": "この鳥[とり]は個体[こたい]によって鳴[な]き声[ごえ]が違[ちが]うので、声[こえ]だけで仲間[なかま]を見分[みわ]けられる。", "sentence_source": "generated"}, {"text": "病気にかかった個体は、群れから離して育てます。", "target_word": "個体", "complexity_tier": "T3", "furigana": "病気[びょうき]にかかった個体[こたい]は、群[む]れから離[はな]して育[そだ]てます。", "sentence_source": "generated"}, {"text": "絶滅の危機にある種では、生き残った個体を一匹ずつ守っている。", "target_word": "個体", "complexity_tier": "T3", "furigana": "絶滅[ぜつめつ]の危機[きき]にある種[しゅ]では、生[い]き残[のこ]った個体[こたい]を一匹[いっぴき]ずつ守[まも]っている。", "sentence_source": "generated"}, {"text": "観察したシカの個体は、子を守るために天敵に立ち向かった。", "target_word": "個体", "complexity_tier": "T3", "furigana": "観察[かんさつ]したシカの個体[こたい]は、子[こ]を守[まも]るために天敵[てんてき]に立[た]ち向[む]かった。", "sentence_source": "generated"}, {"text": "調査で捕まえた個体には、足に小さな輪をつけて、放しました。", "target_word": "個体", "complexity_tier": "T3", "furigana": "調査[ちょうさ]で捕[つか]まえた個体[こたい]には、足[あし]に小[ちい]さな輪[わ]をつけて、放[はな]しました。", "sentence_source": "generated"}, {"text": "若い個体は経験が少ないため、えさを探すのが下手だ。", "target_word": "個体", "complexity_tier": "T3", "furigana": "若[わか]い個体[こたい]は経験[けいけん]が少[すく]ないため、えさを探[さが]すのが下手[へた]だ。", "sentence_source": "generated"}, {"text": "親から遺伝子を受け継いだ新しい個体が、卵からかえった。", "target_word": "個体", "complexity_tier": "T3", "furigana": "親[おや]から遺伝子[いでんし]を受[う]け継[つ]いだ新[あたら]しい個体[こたい]が、卵[たまご]からかえった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "個体", "label": "基本形"}], "register": "中立", "sense_fingerprint": "同じ種の中で区別される、生物の一匹・一頭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '920eb11e-36fd-435d-a5dc-a83487d94a28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36719, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "個体", "is_correct": true, "explanation": "島に残る生き物を数える語で、この空所に入る。"}, {"text": "段階", "is_correct": false, "explanation": "過程の区切りを表すので、残っている生き物の数を述べる文には入らない。"}, {"text": "年", "is_correct": false, "explanation": "時間の単位で、島に残っている対象にはならない。"}, {"text": "価値", "is_correct": false, "explanation": "値打ちを表すので、残っている生き物の数を述べる文に合わない。"}], "explanations": {"個体": "島に残る生き物を数える語で、この空所に入る。", "段階": "過程の区切りを表すので、残っている生き物の数を述べる文には入らない。", "年": "時間の単位で、島に残っている対象にはならない。", "価値": "値打ちを表すので、残っている生き物の数を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "個体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は個体で事業を始めた。", "explanation": "ここは〈個人〉（一人で、個人として）の意味。個体は一つの生き物や物を指す語なので、事業を一人で行う言い方には使わない。"}, {"text": "このロケットは個体の燃料を使っている。", "explanation": "ここは〈固体〉（固まった状態の）の意味。個体は生き物や物を数える語なので、燃料の状態を表す言い方には合わない。"}, {"text": "この犬は個体がはっきりしていて、ほかの犬と区別しやすい。", "explanation": "ここは〈個性〉（ほかと違う特徴）の意味。個体は一つの単位を指す語で、特徴のはっきりさを表す言い方ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36719, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "個体", "is_correct": true, "explanation": "立ち向かう行動の主体になる、一頭一頭の生き物を指す語。ここで正解。"}, {"text": "角", "is_correct": false, "explanation": "体の部位で、立ち向かう行動の主語にはならない。"}, {"text": "鳴き声", "is_correct": false, "explanation": "声を表すので、子を守って立ち向かう行動の主体にはならない。"}, {"text": "足", "is_correct": false, "explanation": "体の部位で、子を守る行動の主語にはならない。"}], "explanations": {"個体": "立ち向かう行動の主体になる、一頭一頭の生き物を指す語。ここで正解。", "角": "体の部位で、立ち向かう行動の主語にはならない。", "鳴き声": "声を表すので、子を守って立ち向かう行動の主体にはならない。", "足": "体の部位で、子を守る行動の主語にはならない。"}, "sentence_index": 6, "correct_answer": "個体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三十人の大学生が、個体で旅行を申し込んだ。", "explanation": "ここは〈団体〉（複数人でまとまった集まり）の意味。個体は一つの生き物や物を指すので、人の集まりが一緒に行動する文には合わない。"}, {"text": "このチームは、個体で練習して連携を高めている。", "explanation": "ここは〈個別〉（一人ずつ別々に）の意味。個体は生き物や物を数える名詞で、「個体で練習する」のように副詞的には使えない。"}, {"text": "先生は生徒ごとに個体指導を行っている。", "explanation": "ここは〈個別〉（一人ずつ別々に）の意味。個体は名詞で、指導の仕方を表す語ではないので「個体指導」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36719, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者は、絶滅が心配される個体が一頭ずつ数えている。", "corrected_sentence": "研究者は、絶滅が心配される個体を一頭ずつ数えている。", "error_description": "誤りは「個体が」。「数える」は数える対象を「を」で示すので、正しくは「個体を」。「個体が」だと個体が数える側になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36719, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、絶滅寸前の個体に守るため、一頭ずつ保護している。", "corrected_sentence": "研究者は、絶滅寸前の個体を守るため、一頭ずつ保護している。", "error_description": "誤りは「個体に」。「守る」は守る対象を「を」で示すので、正しくは「個体を」。「に」は相手や方向を示すので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '263c51b8-3f5c-4b62-8ec3-215d45785e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
