INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36720, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かが起こること。", "primary_collocate": null, "pronunciation": "はっせい", "ipa": "hasseː", "syllable_count": 4, "sentences": [{"text": "事故が発生した。", "target_word": "発生した", "complexity_tier": "T1", "furigana": "事故[じこ]が発生[はっせい]した。", "sentence_source": "generated"}, {"text": "トラブルが発生しました。", "target_word": "発生しました", "complexity_tier": "T2", "furigana": "トラブルが発生[はっせい]しました。", "sentence_source": "generated"}, {"text": "火事の発生を知らせる音が鳴った。", "target_word": "発生", "complexity_tier": "T3", "furigana": "火事[かじ]の発生[はっせい]を知[し]らせる音[おと]が鳴[な]った。", "sentence_source": "generated"}, {"text": "問題が発生しないように、事前に確認しておきます。", "target_word": "発生しない", "complexity_tier": "T4", "furigana": "問題[もんだい]が発生[はっせい]しないように、事前[じぜん]に確認[かくにん]しておきます。", "sentence_source": "generated"}, {"text": "停電が発生しています。", "target_word": "発生して", "complexity_tier": "T3", "furigana": "停電[ていでん]が発生[はっせい]しています。", "sentence_source": "generated"}, {"text": "もしエラーが発生したら、すぐに連絡してください。", "target_word": "発生したら", "complexity_tier": "T4", "furigana": "もしエラーが発生[はっせい]したら、すぐに連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "事故が発生した場所を地図で調べる。", "target_word": "発生した", "complexity_tier": "T3", "furigana": "事故[じこ]が発生[はっせい]した場所[ばしょ]を地図[ちず]で調[しら]べる。", "sentence_source": "generated"}, {"text": "事件の発生から三時間後、警察が現場に到着した。", "target_word": "発生", "complexity_tier": "T4", "furigana": "事件[じけん]の発生[はっせい]から三時間後[さんじかんご]、警察[けいさつ]が現場[げんば]に到着[とうちゃく]した。", "sentence_source": "generated"}, {"text": "予想外の事態が発生した際の対応を、全員で確認しておく必要がある。", "target_word": "発生した", "complexity_tier": "T5", "furigana": "予想外[よそうがい]の事態[じたい]が発生[はっせい]した際[さい]の対応[たいおう]を、全員[ぜんいん]で確認[かくにん]しておく必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "地震の発生は夜の十時ごろでした。", "target_word": "発生", "complexity_tier": "T3", "furigana": "地震[じしん]の発生[はっせい]は夜[よる]の十時[じゅうじ]ごろでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発生する", "label": "活用"}, {"form": "発生した", "label": "活用"}, {"form": "発生させる", "label": "活用"}, {"form": "発生源", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 出来事が起こること、生じること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 火事 (Zipf 3.95), 知らせる (Zipf 3.57), 鳴っ (Zipf 3.81)']::text[], '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36720, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発生した", "is_correct": true, "explanation": "事故が起こったという意味で、文意に合います。"}, {"text": "卒業した", "is_correct": false, "explanation": "形は合うが、事故に卒業という意味は合わない。"}, {"text": "出席した", "is_correct": false, "explanation": "形は合うが、事故が出席するという意味は合わない。"}, {"text": "勉強した", "is_correct": false, "explanation": "形は合うが、事故が勉強するという意味は合わない。"}], "explanations": {"発生した": "事故が起こったという意味で、文意に合います。", "卒業した": "形は合うが、事故に卒業という意味は合わない。", "出席した": "形は合うが、事故が出席するという意味は合わない。", "勉強した": "形は合うが、事故が勉強するという意味は合わない。"}, "sentence_index": 0, "correct_answer": "発生した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は昨日、新しい友だちを発生しました。", "explanation": "「発生」は人を作る意味ではなく、物事が起こる意味なので誤用です。"}, {"text": "毎日、公園で犬を発生しています。", "explanation": "「散歩させる」の意味で誤用している。「発生」は物事が起こること。"}, {"text": "先生は黒板に字を発生した。", "explanation": "「書く」の意味で誤用している。「発生」は書く動作を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36720, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発生した", "is_correct": true, "explanation": "「発生した場所」で、起こった場所という意味になる。"}, {"text": "卒業した", "is_correct": false, "explanation": "形は合うが、事故が卒業するとは言えない。"}, {"text": "出席した", "is_correct": false, "explanation": "形は合うが、事故が出席するとは言えない。"}, {"text": "勉強した", "is_correct": false, "explanation": "形は合うが、事故が勉強するとは言えない。"}], "explanations": {"発生した": "「発生した場所」で、起こった場所という意味になる。", "卒業した": "形は合うが、事故が卒業するとは言えない。", "出席した": "形は合うが、事故が出席するとは言えない。", "勉強した": "形は合うが、事故が勉強するとは言えない。"}, "sentence_index": 6, "correct_answer": "発生した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私の発生は赤くて重いです。", "explanation": "「発生」は物の性質を表さず、起こることを意味するので誤用です。"}, {"text": "昨日、駅で友だちに発生しました。", "explanation": "「発生」は人に会う意味ではないので誤用です。"}, {"text": "この発生は冷たくておいしいです。", "explanation": "食べ物のように使っているが、「発生」は物ではなく出来事を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36720, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅の近くで火事に発生した。", "corrected_sentence": "駅の近くで火事が発生した。", "error_description": "発生する主体は「火事が」で示すので、「に」は誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36720, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅前に新しい店が発生した。", "corrected_sentence": "駅前に新しい店ができた。", "error_description": "店ができる場合には「発生」ではなく「できる」を使うので、語の選択が誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36721, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「発生が増える」で、増える主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「増える」は自動詞なので「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「発生に増えます」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、ここでは文法的に合わない。"}], "correct_answer": "が", "explanations": {"が": "「発生が増える」で、増える主体を示す。", "を": "「増える」は自動詞なので「を」は合わない。", "に": "「発生に増えます」は文として成り立たない。", "へ": "「へ」は方向を表し、ここでは文法的に合わない。"}, "error_tags": {"を": "transitivity", "に": "particle_mismatch", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消滅", "is_correct": true, "explanation": "現れ起こることの反対で、なくなることを表す。"}, {"text": "発見", "is_correct": false, "explanation": "見つけることで、「発生」の反対ではない。"}, {"text": "報告", "is_correct": false, "explanation": "知らせることで、「発生」の反対ではない。"}, {"text": "拡大", "is_correct": false, "explanation": "大きくなることで、「発生」の反対ではない。"}], "correct_answer": "消滅", "explanations": {"消滅": "現れ起こることの反対で、なくなることを表す。", "発見": "見つけることで、「発生」の反対ではない。", "報告": "知らせることで、「発生」の反対ではない。", "拡大": "大きくなることで、「発生」の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36721, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「工場から発生する」で、発生の起点を示す。"}, {"text": "を", "is_correct": false, "explanation": "「工場を発生する」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「工場と発生する」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「工場へ発生する」は方向が合わず成り立たない。"}], "correct_answer": "から", "explanations": {"から": "「工場から発生する」で、発生の起点を示す。", "を": "「工場を発生する」は文として成り立たない。", "と": "「工場と発生する」は文として成り立たない。", "へ": "「工場へ発生する」は方向が合わず成り立たない。"}, "error_tags": {"を": "transitivity", "と": "particle_mismatch", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消滅", "is_correct": true, "explanation": "台風が生じることの反対で、なくなることを表す。"}, {"text": "予測", "is_correct": false, "explanation": "前もって見通すことで、「発生」の反対ではない。"}, {"text": "確認", "is_correct": false, "explanation": "確かめることで、「発生」の反対ではない。"}, {"text": "増加", "is_correct": false, "explanation": "数が増えることで、「発生」の反対ではない。"}], "correct_answer": "消滅", "explanations": {"消滅": "台風が生じることの反対で、なくなることを表す。", "予測": "前もって見通すことで、「発生」の反対ではない。", "確認": "確かめることで、「発生」の反対ではない。", "増加": "数が増えることで、「発生」の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36721, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事が現れたり、起こったりすること。", "primary_collocate": null, "pronunciation": "はっせい", "ipa": "hasseː", "syllable_count": 4, "sentences": [{"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "発生", "complexity_tier": "T6", "furigana": "再生可能[さいせいかのう]エネルギーの導入[どうにゅう]加速[かそく]にもかかわらず、製造[せいぞう]プロセスの性質上[せいしつじょう]、炭素[たんそ]発生[はっせい]をゼロ化[か]し得[え]ない領域[りょういき]において、CCUSは極[きわ]めて重要[じゅうよう]な役割[やくわり]を担[にな]う。", "sentence_source": "mined"}, {"text": "夏は虫の発生が増えます。", "target_word": "発生", "complexity_tier": "T2", "furigana": "夏[なつ]は虫[むし]の発生[はっせい]が増[ふ]えます。", "sentence_source": "generated"}, {"text": "雨が続くと、カビが発生しやすくなります。", "target_word": "発生し", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]くと、カビが発生[はっせい]しやすくなります。", "sentence_source": "generated"}, {"text": "霧が発生した。", "target_word": "発生した", "complexity_tier": "T1", "furigana": "霧[きり]が発生[はっせい]した。", "sentence_source": "generated"}, {"text": "地震が発生した場合は、すぐに机の下に隠れてください。", "target_word": "発生した", "complexity_tier": "T4", "furigana": "地震[じしん]が発生[はっせい]した場合[ばあい]は、すぐに机[つくえ]の下[した]に隠[かく]れてください。", "sentence_source": "generated"}, {"text": "新しい問題が発生して、会議が長引いた。", "target_word": "発生して", "complexity_tier": "T3", "furigana": "新[あたら]しい問題[もんだい]が発生[はっせい]して、会議[かいぎ]が長引[ながび]いた。", "sentence_source": "generated"}, {"text": "発生の原因を調べます。", "target_word": "発生", "complexity_tier": "T2", "furigana": "発生[はっせい]の原因[げんいん]を調[しら]べます。", "sentence_source": "generated"}, {"text": "工場から発生するガスを減らす取り組みが進んでいる。", "target_word": "発生する", "complexity_tier": "T4", "furigana": "工場[こうじょう]から発生[はっせい]するガスを減[へ]らす取[と]り組[く]みが進[すす]んでいる。", "sentence_source": "generated"}, {"text": "大雨によって川の水があふれ、各地で土砂崩れが発生したと報じられた。", "target_word": "発生した", "complexity_tier": "T5", "furigana": "大雨[おおあめ]によって川[かわ]の水[みず]があふれ、各地[かくち]で土砂崩[どしゃくず]れが発生[はっせい]したと報[ほう]じられた。", "sentence_source": "generated"}, {"text": "台風が発生したというニュースを見た。", "target_word": "発生した", "complexity_tier": "T3", "furigana": "台風[たいふう]が発生[はっせい]したというニュースを見[み]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発生する", "label": "活用"}, {"form": "発生した", "label": "活用"}, {"form": "発生させる", "label": "活用"}, {"form": "発生源", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が新たに現れ起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 大雨 (Zipf 3.96), あふれ (Zipf 3.89), 土砂崩れ (Zipf 3.16)']::text[], '91f81af3-0e78-4da0-b675-62ce9dc0b7db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
